import React, { memo } from 'react'
import dynamic from 'next/dynamic';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { useSelector } from 'react-redux';
import { IReduxState } from 'types/reduxStateTypes';
import { StyledModal } from 'components/shared/CustomPropertyModal/styles';
import styled from 'styled-components';
import { Button, useFeatureFlag } from 'uxcam-frontend-components';
import { tokenRefreshManager } from 'services/tokenRefreshManager';

// dashboard-builder's App bundles a lottie player that touches `document` at module scope,
// so it must never load during SSR
const DashboardTemplate = dynamic(
  () => import('dashboard-builder/dist/cjs/App').then((mod) => mod.DashboardTemplate),
  { ssr: false }
);

interface IProps {
  readonly edge: {
    readonly node: {
      readonly id: string;
    } | null | undefined;
  } | null | undefined;
}

const ModalContentWrapper = styled.div`
  h2 {
    font-weight: 500;
    margin-bottom: 16px !important;
  }

  button{
    height: 32px;
    min-width: 132px !important;
  }

  .modal-footer{
    margin-top: 32px !important;
  }

`


const DashboardTemplates = () => {
  const { showDashboardTemplate, setShowDashboardTemplate, currentAction } = useNoCodeEventsContext()
  const [showCreateModal, setShowCreateModal] = React.useState(false)
  const {
    currentAppReducer,
  } = useSelector((state: IReduxState) => state);

  const { _id: appId } = currentAppReducer;
  const [dashboardId, setDashboardId] = React.useState<string | null>(null);
  const [dashboardName, setDashboardName] = React.useState<string | null>(null);

  const newScreenFilter = useFeatureFlag('new-screens-filter')
  const conversionEnabled = useFeatureFlag( 'conversion-report' )

  const env = process.env.APP_ENV || 'develop';

  const templateId = React.useMemo(() => {
    if(currentAction?.type === 'sdk_event') return 'coded_event_insights'

    return 'smart_event_insights'
  }, [currentAction?.type])


  const templateProperties = React.useMemo(() => {
    if(currentAction?.type === 'sdk_event') return {
      "$CODED_EVENT$": currentAction?.name,
    }

    return {
      "$SMART_EVENT$": currentAction?.name,
    }
  }, [currentAction?.name, currentAction?.type])

  const handleOnCreateDashboard = React.useCallback((dashboard: IProps) => {
    setDashboardId(dashboard?.edge?.node?.id || null)
    setShowDashboardTemplate(false)
    setShowCreateModal(true)
  }, [setShowDashboardTemplate])

  const handleWidgetAddition = React.useCallback(( dashId: string, dashName: string ) => {
    setDashboardId(dashId || null)
    setDashboardName(dashName || null)
    setShowDashboardTemplate(false)
    setShowCreateModal(true)
  }, [setShowDashboardTemplate])

  if (showCreateModal) return (
    <StyledModal
      centered
      visible={showCreateModal}
      onCancel={() => setShowCreateModal(false)}
      footer={null}
      closable={false}
    >
      <ModalContentWrapper>
        <h2>Your event analysis is ready</h2>
        <p>
        {
          dashboardName ? 
          <>
          Reports added to the dashboard <strong>{dashboardName}</strong>.
          </>
          : 
          <>
          Dashboard <strong>{currentAction?.name}</strong> Analysis has been created.
          </>
        }
        {' '}
        Dive in to discover trends and patterns in user behavior.
        </p>
        <div className="modal-footer">
          <Button variant='ghost' onClick={() => setShowCreateModal(false)}>
            Cancel
          </Button>
          <Button variant='primary' onClick={() => window.open(`/app/${appId}/customDashboard/${dashboardId}`, '_blank')}>
            View analysis
          </Button>
        </div>
      </ModalContentWrapper>
    </StyledModal>
  )

  if (!showDashboardTemplate) return null

  return (
    <DashboardTemplate
      env={env}
      templateId={templateId}
      templateProperties={templateProperties}
      appId={appId as string}
      onClose={() => setShowDashboardTemplate(false)}
      onDashboardCreate={handleOnCreateDashboard}
      onWidgetAddition={handleWidgetAddition}
      noCodeEnabled
      conversionEnabled={ conversionEnabled }
      newScreenFilter={ newScreenFilter}
      onBeforeRequest={ tokenRefreshManager.refreshIfNeeded }
    />
  )
}

export default memo(DashboardTemplates)