/* eslint-disable jsx-a11y/anchor-is-valid */
import React, { memo, useCallback, useEffect, useMemo, useState } from 'react';
import { Menu } from 'antd';
import { useRouter } from 'next/router';
import { RootStateOrAny, useDispatch, useSelector } from 'react-redux';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { useFeatureFlag } from 'uxcam-frontend-components';
import {
  AppFlowIcon,
  DashboardIcon,
  EventsIcon,
  FunnelsIcon,
  IssuesIcon,
  LockIcon,
  OverviewIcon,
  RetentionIcon,
  ScreensIcon,
  SessionsIcon,
  UsersIcon,
  WebHeatmapIcon,
  WebScreenIcon,
} from 'public/static/redesign/sidebar';

import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import LottieIcon from 'components/common/LottieIcon';
import Link from 'next/link';
import { useIsAppType } from 'hooks/useIsAppType';
import { setActivityFilterSegment } from 'redux/actions/megaFilter';
import { defaultActivityFilterSegment } from 'components/shared/GlobalFilter/components/FilterDisplayBar/ActivityFilter/constants';
import { mappedPageType } from 'Utils/helpers/commonUtils';
import {
  lockedFeaturePages,
  pageList,
  sideBarSubMenuKeys,
  MenuKey,
  menuKeyToParentTypeMap,
  LottieMap,
  LottieCollapseMap,
} from './variables';
import useSidebarUtils from '../hooks/useSidebarUtils';
import {
  ExpandIconWrapper,
  IconContainer,
  NewPill,
  SubMenuGlobalStyle,
} from './styles';
import {
  MenuIconProps,
  MenuItem,
  NewSideBarMenuProps,
  RenderTitleInfo,
} from './types';

function getItem(
  label: React.ReactNode,
  key: string,
  dataAttributes?: Record<string, string> | null,
  icon?: React.ReactNode,
  children?: MenuItem[],
  disabled?: boolean,
  type?: string
): MenuItem {
  return {
    key,
    icon,
    children,
    label,
    disabled,
    type,
    dataAttributes,
  } as MenuItem;
}

const MenuLabel: React.FC<RenderTitleInfo> = (props) => {
  const { title, badgeTitle } = props;

  return (
    <ExpandIconWrapper>
      {title}
      {badgeTitle && <NewPill>{badgeTitle}</NewPill>}
    </ExpandIconWrapper>
  );
};


const MenuIcon: React.FC<MenuIconProps> = memo((props) => {
  const { children, isLocked, isNew, id: idRaw, collapsed, isSubmenu } = props;
  const {
    urlReducer: { parentType },
  } = useSelector((state: RootStateOrAny) => state);
  
  const isWebSDK = useIsAppType( 'web' )
  
  const isActive = useMemo(
    () => menuKeyToParentTypeMap[idRaw] === parentType,
    [idRaw, parentType]
  );
  const { getRouteQuery, getRouteUrl } = useSidebarUtils();

  const id:string = useMemo(() => idRaw === MenuKey.screensAnalytics && isWebSDK ? 'heatmapsListWeb' : idRaw ,[isWebSDK, idRaw] )

  return (
      <IconContainer isLocked={isLocked || false} isNew={isNew}>
        <Link
        href={getRouteQuery(idRaw as string)}
        as={getRouteUrl(idRaw as string)}
        >
      {!isSubmenu && (
        <>
          {isActive ? (
            <LottieIcon
              animationData={collapsed ? LottieCollapseMap[id] : LottieMap[id]}
              active={isActive}
              dependencies={[collapsed]}
            />
          ) : (
            children
          )}
          {isLocked && (
            <span className="locked">
              <LockIcon />
            </span>
          )}
        </>
      )}
    </Link>
    </IconContainer>
  );
});

const NewSideBarMenu: React.FC<NewSideBarMenuProps> = (props) => {
  const { collapsedMenu } = props;

  const router = useRouter();
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext();
  const { getRouteQuery, getRouteUrl } = useSidebarUtils();
  const webHeatmapsEnabled = useFeatureFlag('web-heatmaps');

  const [openKeys, setOpenKeys] = useState<string[]>([]);

  const {
    urlReducer: { parentType, issueType },
    appFilter,
    currentAppReducer: { _id: appId, hasAccess, isIntegrated },
    currentOrgReducer: { orgId },
  } = useSelector((state: RootStateOrAny) => state);
  const dispatch = useDispatch()

  const {
    eventsFeatureAllowed,
    screensFeatureAllowed,
    appFlowsFeatureAllowed,
    funnelsFeatureAllowed,
    issuesFeatureAllowed,
    retentionFeatureAllowed,
  } = useRestrictionContext() as unknown as {
    eventsFeatureAllowed: boolean;
    screensFeatureAllowed: boolean;
    appFlowsFeatureAllowed: boolean;
    funnelsFeatureAllowed: boolean;
    issuesFeatureAllowed: boolean;
    retentionFeatureAllowed: boolean;
  };

  const disabled = useMemo(
    () =>
      appId === undefined ||
      parentType === 'plan-downgrade' ||
      !hasAccess ||
      !orgId,
    [appId, hasAccess, orgId, parentType]
  );

  const isAIDisabled = useCallback( ( key: string ) => {
    if ( key === MenuKey.sessions ) {
      return false
    }
    return true
  }, [] )
  const isWebOrg = useIsAppType( 'web' );

  const isWebDisabled = useCallback((key: string) => {
    if (!isWebOrg) {
      return key === MenuKey.webHeatmaps;
    }

    switch (key) {
      case MenuKey.dashboard:
      case MenuKey.overview:
      case MenuKey.users:
      case MenuKey.events:
      case MenuKey.divider:
      case MenuKey.sessions:
      case MenuKey.aiSessions:
      case MenuKey.retention:
      case MenuKey.webHeatmaps:
      case MenuKey.screensAnalytics:
      case MenuKey.screens:
      case MenuKey.funnels: {
        return false
      }
      case MenuKey.appFlows:
        return false
      case MenuKey.issues:
        return true
      default: {
        return true
      }
    }

  }, [isWebOrg])

  const selectedKeys = useMemo(() => {
    if (parentType === 'issues') {
      return [issueType];
    }
    if (parentType === 'nocodeEventsList' && noCodeEventsFeatureFlag) {
      return ['eventsList'];
    }
    return [parentType];
  }, [parentType, issueType, noCodeEventsFeatureFlag]);

  const openKeysSets = useMemo(() => {
    if (Object.keys(pageList).indexOf(parentType) > -1) {
      return [pageList[parentType as keyof typeof pageList]];
    }
    return [parentType];
  }, [parentType]);

  useEffect(() => {
    if (!collapsedMenu) {
      setOpenKeys(openKeysSets);
    }
  }, [openKeysSets, collapsedMenu]);

  const onOpenChange = (keys: string[]) => {
    const latestOpenKey = keys.find(
      (key: string) => openKeys.indexOf(key) === -1
    );
    if (sideBarSubMenuKeys.indexOf(latestOpenKey as string) === -1) {
      setOpenKeys(keys);
    } else {
      setOpenKeys(latestOpenKey ? [latestOpenKey] : []);
    }
    if (!keys.length) setOpenKeys(['']);
  };

  const getScreensMenuItems = useCallback(() => {

    if (isWebOrg && !webHeatmapsEnabled) {
      return getItem(
        <MenuLabel title="Heatmaps" />,
        MenuKey.webHeatmaps,
        { 'data-intercom-target': 'Heatmap' },
        <WebHeatmapIcon />,
        undefined,
        true,
      );
    }

    if (isWebOrg && webHeatmapsEnabled) {
      return getItem(
        <MenuLabel title="Screens" />,
        MenuKey.screens,
        { 'data-intercom-target': 'Sidebar Screens' },
        <WebScreenIcon />,
        [
          getItem('Analytics', MenuKey.screensAnalytics, {
            'data-intercom-target': 'Sidebar Screen Analytics',
          }),
          getItem('Heatmaps', MenuKey.webHeatmaps, {
            'data-intercom-target': 'Sidebar Web Heatmaps',
          }),
        ]
      );
    }

    return getItem(
      <MenuLabel title="Screens" />,
      MenuKey.screens,
      { 'data-intercom-target': 'Sidebar Heatmaps V2' },
      <ScreensIcon />
    );
  }, [isWebOrg, webHeatmapsEnabled]);

  const items: MenuItem[] = useMemo(() => {
    const screensMenuItem = getScreensMenuItems();

    return [
      getItem(
        <MenuLabel title="Overview" />,
        MenuKey.overview,
        { 'data-intercom-target': 'Sidebar Overview' },
        <OverviewIcon />
      ),
      getItem(
        <MenuLabel title="Dashboards" />,
        MenuKey.dashboard,
        { 'data-intercom-target': 'Sidebar Dashboards' },
        <DashboardIcon />
      ),
      getItem(
        <MenuLabel title="Retention" />,
        MenuKey.retention,
        { 'data-intercom-target': 'Sidebar Retention' },
        <RetentionIcon />
      ),
      getItem(
        <MenuLabel title="Funnels" />,
        MenuKey.funnels,
        { 'data-intercom-target': 'Sidebar Funnels' },
        <FunnelsIcon />
      ),
      getItem(
        <MenuLabel title={isWebOrg ? "Flows" : "App flows"} />,
        MenuKey.appFlows,
        { 'data-intercom-target': 'Sidebar App Flows' },
        <AppFlowIcon />,
        [
          getItem('Screen flow', MenuKey.screenFlow, {
            'data-intercom-target': 'Sidebar Screen Flow 2',
          }),
          getItem('Screen burst', MenuKey.screenBurst, {
            'data-intercom-target': 'Sidebar Screen Burst',
          }),
        ]
      ),
      getItem(
        'Divider',
        MenuKey.divider,
        null,
        null,
        undefined,
        undefined,
        'divider'
      ),
      getItem(
        <MenuLabel title="Sessions" />,
        MenuKey.sessions,
        { 'data-intercom-target': 'Sidebar Sessions' },
        <SessionsIcon />,
        [
          getItem('List', MenuKey.sessionsList, {
            'data-intercom-target': 'Session List',
          }),
          getItem('Analytics', MenuKey.sessionAnalytics, {
            'data-intercom-target': 'Session Analytics',
          }),
        ]
      ),
      getItem(
        <MenuLabel title="Sessions" />,
        MenuKey.aiSessions,
        { 'data-intercom-target': 'Sidebar AI Sessions' },
        <SessionsIcon />,
        [
          getItem('List', MenuKey.aiSessionsList, {
            'data-intercom-target': 'AI Session List',
          } ),
          getItem('Analytics', MenuKey.aiSessionAnalytics, {
            'data-intercom-target': 'AI Session Analytics',
          } ),
        ]
      ),
      getItem(
        <MenuLabel title="Users" />,
        MenuKey.users,
        { 'data-intercom-target': 'Sidebar Users' },
        <UsersIcon />
      ),

      getItem(
        <MenuLabel title="Events" />,
        MenuKey.events,
        { 'data-intercom-target': 'Sidebar Events' },
        <EventsIcon />,
        [
          getItem('List', MenuKey.eventsList, {
            'data-intercom-target': 'Sidebar Event List',
          }),
          getItem('Analytics', MenuKey.eventAnalytics, {
            'data-intercom-target': 'Sidebar Event Analytics',
          }),
        ]
      ),
      ...(screensMenuItem ? [screensMenuItem] : []),
      getItem(
        <MenuLabel title="Issues" />,
        MenuKey.issues,
        { 'data-intercom-target': 'Sidebar Issues' },
        <IssuesIcon />,
        [
          getItem('Crashes', MenuKey.crashes, {
            'data-intercom-target': 'Sidebar Crashes',
          }),
          getItem('UI Freeze', MenuKey.uiFreeze, {
            'data-intercom-target': 'Sidebar UI Freezes',
          }),
          getItem('Exceptions', MenuKey.exceptions, {
            'data-intercom-target': 'Sidebar Exceptions',
          }),
        ]
      ),
    ];
  }, [isWebOrg, getScreensMenuItems]);

  const findMenuItem = (key: string) => {
    const menuItem = items.find((item) => {
      if (item?.children && item.children.length > 0) {
        return item.children.find((child) => child.key === key);
      }
      return item.key === key;
    });
    return menuItem;
  };

  const findSubMenuFirstKey = useCallback((key: string) => {
    const firstChildKey = items.find((item) => item.key === key)?.children?.[0]
      .key;
    return firstChildKey;
  }, [items]);

  const handleSubMenuRouteChange = useCallback(
    (key: string, issueKey?: string) => {
      if (issueKey) {
        const routeQuery = getRouteQuery(key, issueKey);
        const routeUrl = getRouteUrl(issueKey);
        router.push(routeQuery, routeUrl);
        return;
      }
      if (key === 'usersList' && !appFilter[mappedPageType[key]]?.segment.length && !appFilter[mappedPageType[key]]?.activityFilterList.length) {
        // * No any filter
        dispatch(setActivityFilterSegment([defaultActivityFilterSegment], "user"));
      }
      const routeQuery = getRouteQuery(key);
      const routeUrl = getRouteUrl(key);
      router.push(routeQuery, routeUrl);
    },
    [appFilter, dispatch, getRouteQuery, getRouteUrl, router]
  );

  const onMenuTitleClick = useCallback(
    ({ key }: { key: string }) => {
      const menuItemKey = findSubMenuFirstKey(key as string) as string;
      if (key === 'issuesCrashesException') {
        handleSubMenuRouteChange('issues', menuItemKey);
        return;
      }
      handleSubMenuRouteChange(menuItemKey);
    },
    [findSubMenuFirstKey, handleSubMenuRouteChange]
  );

  const handleMenuClick = ({
    key,
    keyPath,
  }: {
    key: string;
    keyPath: React.Key[];
  }) => {
    const menuItem = findMenuItem(key as string);
    if (menuItem && menuItem.children && menuItem.children.length > 0) {
      const menuItemKey = keyPath[0] as string;
      if (menuItem.key === 'issuesCrashesException') {
        handleSubMenuRouteChange('issues', menuItemKey);
        return;
      }
      handleSubMenuRouteChange(menuItemKey);
    } else {
      handleSubMenuRouteChange(key);
    }
  };

  const isLockedFeature = useCallback(
    (key: string) => {
      if (lockedFeaturePages.includes(key)) {
        switch (key) {
          case 'retention':
            return !retentionFeatureAllowed;
          case 'eventsListAnalytics':
            return !eventsFeatureAllowed;
          case 'heatmapsList':
            return !screensFeatureAllowed;
          case 'screenFlowBurst':
            return !appFlowsFeatureAllowed;
          case 'funnels':
            return !funnelsFeatureAllowed;
          case 'issuesCrashesException':
            return !issuesFeatureAllowed;
          default:
            return false;
        }
      }
      return false;
    },
    [
      appFlowsFeatureAllowed,
      eventsFeatureAllowed,
      funnelsFeatureAllowed,
      issuesFeatureAllowed,
      retentionFeatureAllowed,
      screensFeatureAllowed,
    ]
  );

  const renderMenuItem = useCallback(
    (item: MenuItem, isSubmenu = false) => {
      const { icon, children, type, label, key, disabled: itemDisabled } = item;
      if (type === 'divider') {
        return <Menu.Divider key={item.key} />;
      }

      const isItemDisabled = disabled || itemDisabled;

      if (children && children.length > 0) {
        const renderedSubMenu = children.map((subItem) =>
          renderMenuItem(subItem, true)
        );


        return (
          <Menu.SubMenu
            key={key}
            icon={
              <MenuIcon
                id={key as string}
                isNew={null}
                isLocked={isLockedFeature(key as string)}
                collapsed={collapsedMenu}
              >
                {icon}
              </MenuIcon>
            }
            title={label}
            disabled={disabled}
            popupClassName="collapsed-submenu-popup"
            onTitleClick={onMenuTitleClick}
            // eslint-disable-next-line react/jsx-props-no-spreading
            {...item.dataAttributes}
          >
            {collapsedMenu && (
              <Menu.Item
                className="collapsed-submenu-title"
                key={`${key} ${label}`}
              >
                {label}
              </Menu.Item>
            )}
            {renderedSubMenu}
          </Menu.SubMenu>
        );
      }

      return (
        <Menu.Item
          key={key}
          icon={
            <MenuIcon
              id={key as string}
              collapsed={collapsedMenu}
              isNew={null}
              isSubmenu={isSubmenu}
              isLocked={isLockedFeature(key as string)}
            >
              {icon}
            </MenuIcon>
          }
          // eslint-disable-next-line react/jsx-props-no-spreading
          {...item.dataAttributes}
          disabled={isItemDisabled}
        >
          {
            isItemDisabled ? (
              <a href='#disabled'>{label}</a>
            ) : (
              <Link
                href={getRouteQuery(key as string)}
                as={getRouteUrl(key as string)}
                passHref
                legacyBehavior
              >
                <a href="#!">{label}</a>
              </Link>
            )
          }
        </Menu.Item>
      );
    },
    [
      collapsedMenu,
      disabled,
      getRouteQuery,
      getRouteUrl,
      isLockedFeature,
      onMenuTitleClick,
    ]
  );

  const renderMenuItems = useMemo(
    () => items
      .filter(item => !isWebDisabled(item.key as string))
      .filter( item => isAIDisabled( item.key as string ) )
      .map((indx) => renderMenuItem(indx, false)),
    [items, isWebDisabled, isAIDisabled, renderMenuItem]
  );
  return (
    <>
      <SubMenuGlobalStyle collapsed={collapsedMenu} />
      <Menu
        mode="inline"
        theme="dark"
        openKeys={openKeys}
        defaultSelectedKeys={['overview']}
        selectedKeys={selectedKeys}
        inlineCollapsed={collapsedMenu}
        disabled={!isIntegrated}
        onOpenChange={onOpenChange}
        onClick={handleMenuClick}
      >
        {renderMenuItems}
      </Menu>
    </>
  );
};

export default NewSideBarMenu;
