/* eslint-disable no-underscore-dangle */
import React, { memo, useCallback, useEffect, useMemo, useRef } from 'react';
import { Modal, Form } from 'antd';
import Rollbar from 'rollbar';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import IconBin from 'public/static/icon-bin.svg';
import IconDuplicateSmall from 'public/static/icon-duplicate-small.svg';
import ButtonNew from 'components/common/ButtonNew';
import { RootStateOrAny, useDispatch, useSelector } from 'react-redux';
import { useMutation, useQueryClient } from 'react-query';
import useMessage from 'hooks/useMessage';
import {
  createScreenSmartEvent,
  editScreenSmartEvent,
} from 'components/features/sessions/hooks/useNocodeEvents';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';
import { ISessionTimeline } from 'types/sessionTypes';
import {
  gesturesValueToStringType,
  gesturesViewTypeIntToString,
} from 'components/features/heatmaps/constants';
import { rollbar } from 'components/common/rollbar';
import { trackPageViews } from 'redux/actions/trackingReport';
import axios from 'axios';
import { ICreateSmartEventResponse, IScreenEventFormValues } from 'types/screenEvents';
import { setScreenTimeLineEvents } from 'redux/actions/video';
import { getFilterPropertyRemoteData } from 'redux/actions/filter';
import { getDateMonthDay } from 'Utils/DateConversion/dateConversionUtils';
import {  Buttons, Label, Title } from '../commonStyles';

import {
  ButtonsWrapper,
  EventWrapper,
  GlobalStyles,
  InputArea,
  InputLabel,
  InputText,
  LabelRight,
  LabelWrapper,
  Scrollable,
  SubTitle,
} from '../../styles';
import { addScreenEventToSessionDetail, editSmartEventToSessionDetail } from '../helpers';

export const gesturesViewTypeIntToStringAdjusted =
  gesturesViewTypeIntToString as { [key: number]: string };
export const gesturesValueToStringTypeAdjusted = gesturesValueToStringType as {
  [key: number]: string;
};


const ManageScreenEventModal: React.FC = () => {
  const {
    screenEventModalOpen,
    setScreenEventModalOpen,
    currentScreen,
    currentAction,
    deleteScreenEventPopupOpen,
    setCurrentScreen,
    setCurrentAction,
    setDeleteScreenEventPopupOpen,
    setDuplicateEventModalOpen,
    duplicateEventModalOpen,
  } = useNoCodeEventsContext();
  const {
    sessionDetail,
    setSessionDetail,
    sessionQueriesToInvalidate,
    setSessionQueriesToInvalidate,
    sessionNocodeEvents,
    setSessionNocodeEvents,
  } = useSessionTimeLine() as unknown as ISessionTimeline;
  const { device } = sessionDetail || {};
  const [form] = Form.useForm();

  const { message } = useMessage();
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const { resetFields, setFieldsValue, setFields } = form;

  const editable = useMemo(() => currentAction?.id && currentAction?.type === "smart_screenvisit_event", [currentAction?.id, currentAction?.type])
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const displayedScreenName = useMemo(() => currentAction?.props?.activityName || currentScreen?.activityName, [currentAction?.props?.activityName, currentScreen?.activityName])
  
  const { currentAppReducer, currentOrgReducer, urlReducer, screenTimelineReducer: { selectedEventField }, screenRenamedList, appFilter: {
    dateSegment
  }, } = useSelector(
    (state: RootStateOrAny) => state
  );

  const parentType = urlReducer?.parentType;

  const isManagementPage = useMemo(() => parentType === 'settings', [parentType]);

  const { _id: appId } = currentAppReducer || {};
  const orgId = currentOrgReducer?.orgId;

  const renamedScreenName = useMemo(() => screenRenamedList[displayedScreenName || ''] || displayedScreenName, [displayedScreenName, screenRenamedList]);

  const getPayload = useCallback(
    () => ({
      attribute: 'nce_name',
      filter: [],
      search: '',
      dropdownLimit: 501,
      date_range: dateSegment,
    }),
    [dateSegment]
  );
  
  const { mutate: createScreenEvent, isLoading: createIsLoading } = useMutation(
    createScreenSmartEvent
  );

  const { mutate: editScreenEvent, isLoading: editIsLoading } =
    useMutation(editScreenSmartEvent);
  const isLoading = createIsLoading || editIsLoading;

  const handleClose: () => void = useCallback(
    () => !isLoading && setScreenEventModalOpen(false),
    [setScreenEventModalOpen, isLoading]
  );
  const handleDeleteEvent = useCallback(() => {
    if (editable) {
      setScreenEventModalOpen(false);
      setDeleteScreenEventPopupOpen(true);
    }
  }, [editable, setDeleteScreenEventPopupOpen, setScreenEventModalOpen]);

  const handleDuplicateEvent = useCallback(() => {
    if (editable) {
      setScreenEventModalOpen(false);
      setDuplicateEventModalOpen(true);
    }
  }, [editable, setDuplicateEventModalOpen, setScreenEventModalOpen]);

  const makeInvalidations = useCallback(() => {
    const sessionId = urlReducer?.sessionid;
    if (sessionId) {
      setSessionQueriesToInvalidate([...sessionQueriesToInvalidate, sessionId]);
    }
    dispatch(getFilterPropertyRemoteData(getPayload(), false, true));
    queryClient.invalidateQueries({ queryKey: ['sessionNocodeEvents'] });
    queryClient.invalidateQueries({ queryKey: ['manage-nocode-list'] });
  }, [urlReducer?.sessionid, dispatch, getPayload, queryClient, setSessionQueriesToInvalidate, sessionQueriesToInvalidate]);

  const handleCreateEvent = useCallback(
    (values: IScreenEventFormValues) => {
      if (
        appId &&
        orgId &&
        device?.platform &&
        currentScreen?.activityName &&
        device?.sdkVersion
      ) {
        const { event_name: eventName, event_description: eventDescription } =
          values;
          createScreenEvent(
          {
            name: eventName?.trim(),
            description: eventDescription,
            appid: appId,
            orgid: orgId,
            platform: device?.platform,
            screen_name: [currentScreen.activityName],
            sdk_version: device?.sdkVersion,
            category: ['nocode'],
            previous_screen_name: [], // empty for now, will implement later
            next_screen_name: [], // empty for now, will implement later
            custom_property: {
              access: "Yes"
            }
          },
          {
            onSuccess: (res) => {
              makeInvalidations();
              const id = (res as ICreateSmartEventResponse)?.data?.data?.nceId;

              if (setSessionNocodeEvents && sessionNocodeEvents) {
                setSessionNocodeEvents([...sessionNocodeEvents, {
                  event_name: eventName?.trim(),
                  count: 1,
                }])
              }

              const newSelectedEventField = [...selectedEventField, {
                name: eventName?.trim(),
                count: 1,
              }]
    
              dispatch(setScreenTimeLineEvents(newSelectedEventField))

              if (id && sessionDetail && currentScreen) {
                const newNocodeObj = {
                  id,
                  name: eventName?.trim(),
                  description: eventDescription,
                  time: currentScreen?.time,
                  params: {
                    screenName: currentScreen?.activityName,
                  },
                  type: 'smart_screenvisit_event'
                };
                const newSessionDetail = addScreenEventToSessionDetail(sessionDetail, currentScreen, newNocodeObj);
                setSessionDetail(newSessionDetail);
              }

              message({
                content: 'Smart event has been created successfully.',
                type: 'success',
              });
              dispatch(
                trackPageViews(null, {
                  eventName: 'wa_create_nocode_event',
                  track_type: 'event',
                  eventProperty: {
                    event_id: id,
                    event_name: eventName?.trim(),
                    screen_name: renamedScreenName,
                    original_screen_name: currentScreen?.activityName,
                    session_id: urlReducer?.sessionid,
                    type_of_event: 'screenvisit',
                  },
                })
              );
              handleClose();
            },
            onError: (error) => {
              if (axios.isAxiosError(error)) {
                const errorObj =
                  error?.request?.response &&
                  JSON.parse(error.request.response)['error'];
                if (
                  errorObj?.status === 409 &&
                  errorObj?.message === 'Duplicate name.'
                ) {
                  setFields([
                    {
                      name: 'event_name',
                      errors: ['Smart event with that name already exists'],
                    },
                  ]);
                  return;
                }
              }
              message({
                content: `Something went wrong while creating an event. Please try again.`,
                type: 'error',
              });
              rollbar.error(
                error as Rollbar.LogArgument[],
                'Error while creating an event'
              );
            },
          }
        );
      } else {
        message({
          content: 'Something went wrong while creating an event',
          type: 'error',
        });
        rollbar.error(
          [
            appId &&
              orgId &&
              device?.platform &&
              currentScreen?.activityName &&
              device?.sdkVersion,
          ],
          'Error with values when creating event'
        );
        message({
          content: 'Something went wrong while creating an event',
          type: 'error',
        });
      }
    },
    [appId, orgId, device?.platform, device?.sdkVersion, currentScreen, createScreenEvent, makeInvalidations, setSessionNocodeEvents, sessionNocodeEvents, selectedEventField, dispatch, sessionDetail, message, renamedScreenName, urlReducer?.sessionid, handleClose, setSessionDetail, setFields]
  );

  const handleEditEvent = useCallback(
    (values: IScreenEventFormValues) => {
      const { event_name: eventName, event_description: eventDescription } = values;
      if (editable) {
        const id = currentAction?.id
        editScreenEvent(
          {
            appid: appId,
            description: eventDescription || '',
            name: eventName?.trim() || '',
            nce_id: id as unknown as number,
          },
          {
            onSuccess: () => {
              if (setSessionNocodeEvents && sessionNocodeEvents) {
                setSessionNocodeEvents(sessionNocodeEvents.map(event => {
                  if (event.event_name === currentAction?.name) {
                    return {
                      ...event,
                      event_name: eventName?.trim(),
                    }
                  }
                  return event;
                }))
              }
              if (id && sessionDetail && currentScreen && currentAction) {
                const newNocodeObj = {
                  ...currentAction,
                  id: id as unknown as number,
                  name: eventName?.trim(),
                  description: eventDescription,
                  params: {
                    screenName: currentScreen?.activityName,
                  }
                }
                setSessionDetail(editSmartEventToSessionDetail(sessionDetail, newNocodeObj))
              }

              const newSelectedEventField = selectedEventField.map((event: { name: string }) => (
                event.name === currentAction?.name ? {
                  ...event,
                  name: eventName?.trim(),
                } : event
              ))
    
              dispatch(setScreenTimeLineEvents(newSelectedEventField));
              makeInvalidations();

              message({
                content: 'Smart event has been updated successfully.',
                type: 'success'
              });

              dispatch(
                trackPageViews(null, {
                  eventName: 'wa_modify_smart_event',
                  track_type: 'event',
                  eventProperty: {
                    event_id: id,
                    type_of_event: 'screenvisit',
                    event_name: eventName?.trim(),
                    screen_name: renamedScreenName,
                    original_screen_name: currentScreen?.activityName,
                    session_id: urlReducer?.sessionid,
                  },
                })
              );
              handleClose();
            },
            onError: (error) => {
              if (axios.isAxiosError(error)) {
                const errorObj =
                  error?.request?.response &&
                  JSON.parse(error.request.response)['error'];
                if (
                  errorObj?.status === 409 &&
                  errorObj?.message === 'Duplicate name.'
                ) {
                  setFields([
                    {
                      name: 'event_name',
                      errors: ['Smart event with that name already exists'],
                    },
                  ]);
                  return;
                }
              }
              message({
                content: `Something went wrong while editing an event. Please try again.`,
                type: 'error',
              });
              rollbar.error(
                error as Rollbar.LogArgument[],
                'Error while editing an event'
              );
            },
          }
        );
      }
    },
    [editable, currentAction, editScreenEvent, appId, setSessionNocodeEvents, sessionNocodeEvents, sessionDetail, currentScreen, selectedEventField, dispatch, makeInvalidations, message, renamedScreenName, urlReducer?.sessionid, handleClose, setSessionDetail, setFields]
  );

  const handleFormOnFinish = useCallback(
    (values: IScreenEventFormValues) => {
      if (!editable) return handleCreateEvent(values);
      return handleEditEvent(values);
    },
    [editable, handleCreateEvent, handleEditEvent]
  );

  const clearForm = useCallback(() => {
    resetFields();
    if (!deleteScreenEventPopupOpen && !screenEventModalOpen) {
      setCurrentAction(undefined)
      setCurrentScreen(undefined);
    }
  }, [resetFields, deleteScreenEventPopupOpen, screenEventModalOpen, setCurrentAction, setCurrentScreen]);

  useEffect(() => {
    if (editable) {
      setFieldsValue({
        'event_name': currentAction?.name,
        'event_description': currentAction?.description || ''
      });
    }
  }, [setFieldsValue, editable, currentAction?.name, currentAction?.description]);

  useEffect(() => {
    if (!screenEventModalOpen && !duplicateEventModalOpen) {
      timerRef.current = setTimeout(clearForm, 500);
    }
    return () => clearTimeout(timerRef?.current);
  }, [clearForm, duplicateEventModalOpen, screenEventModalOpen]);

  useEffect(() => {
    if (screenEventModalOpen) {
      dispatch(trackPageViews(null, {
      	eventName: editable ? 'wa_activity_open_modify_event_dialog' : 'wa_activity_open_create_event_dialog',
      	track_type: 'event',
      	eventProperty: {
      		session_id: sessionDetail?._id,
          type_of_event: 'screenvisit',
          screen_name: renamedScreenName,
          original_screen_name: displayedScreenName,
      	}
      }))
    }
  }, [currentScreen, editable, sessionDetail, urlReducer, dispatch, screenEventModalOpen, renamedScreenName, displayedScreenName]);

  return (
    <>
      <GlobalStyles />
      <Modal
        visible={screenEventModalOpen}
        footer={null}
        onCancel={handleClose}
        closable={false}
        className="ant-modal-manage-nocode-event"
        wrapClassName="ant-modal-manage-nocode-event-wrapper"
        destroyOnClose
        width={570}
      >
        <Form
          form={form}
          name="manage-no-code-screen-event"
          onFinish={handleFormOnFinish}
        >
          <Title>
            {editable
              ? 'Edit smart event - screen visit'
              : 'Create smart event - screen visit'}
          </Title>
          <SubTitle>
            Create and manage events without a single line of code. Click <a href='https://help.uxcam.com/hc/en-us/articles/24753425542297-What-are-smart-events' target="_blank" rel="noreferrer">here</a> to know more.
          </SubTitle>
          <Scrollable>
            <InputLabel>
              <b>Event name</b>
            </InputLabel>
            <Form.Item
              name="event_name"
              rules={[
                { required: true, message: 'Please provide an event name' },
                {
                  max: 50,
                  message:
                    'The event name is too long. Please make it shorter.',
                },
              ]}
              shouldUpdate
            >
              <InputText placeholder="Add event name" disabled={isLoading || !!editable } />
            </Form.Item>
            <InputLabel>
              <b>Description</b>
            </InputLabel>
            <Form.Item
              name="event_description"
              className="text-area"
              rules={[
                {
                  max: 500,
                  message:
                    'The description is too long. Please make it shorter.',
                },
              ]}
            >
              <InputArea placeholder="Add description" disabled={isLoading} />
            </Form.Item>
            <EventWrapper isEditable={editable as boolean}>
              <LabelWrapper>
                <Label>
                  <b>Screen name:</b>
                </Label>
                <LabelRight isUneditable>
                  <span>{renamedScreenName}</span>
                </LabelRight>
              </LabelWrapper>
              <LabelWrapper>
                <Label>
                  <b>Original screen name:</b>
                </Label>
                <LabelRight isUneditable>
                  <span>{displayedScreenName}</span>
                </LabelRight>
              </LabelWrapper>
              {
                editable && currentAction?.eventType && (
                  <LabelWrapper>
                  <Label>
                    <b>Event type:</b>
                  </Label>
                  <LabelRight isUneditable>
                    <span>{currentAction?.eventType}</span>
                  </LabelRight>
                </LabelWrapper>
                )
              }
                {
                editable && currentAction?.createdByName && (
                  <LabelWrapper>
                  <Label>
                    <b>Created by:</b>
                  </Label>
                  <LabelRight isUneditable>
                    <span>{currentAction?.createdByName}</span>
                  </LabelRight>
                </LabelWrapper>
                )
              }
               {
                editable && currentAction?.createdOn && (
                <LabelWrapper>
                  <Label>
                    <b>Created on:</b>
                  </Label>
                  <LabelRight isUneditable>
                    <span>{getDateMonthDay(currentAction?.createdOn)}</span>
                  </LabelRight>
                </LabelWrapper>
                )
              }
            </EventWrapper>
          </Scrollable>
          <Form.Item>
            <ButtonsWrapper>
              <Buttons>
                {editable && (
                  <>
                  {
                    isManagementPage && (
                      <ButtonNew
                        width="default"
                        variant="ghost"
                        size="big"
                        onClick={handleDuplicateEvent}
                        type="button"
                        style={{
                          color: '#5D97FF',
                          fontSize: '12px',
                          lineHeight: '24px',
                          paddingRight: '12px',
                        }}
                        loading={editIsLoading}
                        disabled={createIsLoading}
                      >
                        <IconDuplicateSmall />
                        Duplicate event
                      </ButtonNew>
                    )
                  }
                  <ButtonNew
                    width="default"
                    variant="ghost"
                    size="big"
                    onClick={handleDeleteEvent}
                    type="button"
                    style={{
                      color: '#DC4F44',
                      fontSize: '12px',
                      lineHeight: '24px',
                      paddingRight: '12px',
                    }}
                    loading={editIsLoading}
                    disabled={createIsLoading}
                  >
                    <IconBin />
                    Delete event
                  </ButtonNew>
                  </>
                )}
              </Buttons>
              <Buttons>
                <ButtonNew
                  width="medium"
                  variant="ghost"
                  onClick={handleClose}
                  disabled={isLoading}
                  type="button"
                >
                  Cancel
                </ButtonNew>
                <ButtonNew
                  width="medium"
                  type="submit"
                  loading={createIsLoading}
                  disabled={editIsLoading}
                >
                  {editable ? 'Save' : 'Create event'}
                </ButtonNew>
              </Buttons>
            </ButtonsWrapper>
          </Form.Item>
        </Form>
      </Modal>
    </>
  );
};

export default memo(ManageScreenEventModal);
