// Represents a chunk in the stream - either content or a tool call
export type StreamChunk =
	| { type: 'content'; content: string }
	| { type: 'tool_call'; toolCall: IToolCall }

interface IChatComponent {
	messages: IMessage[]
	loading?: boolean
	hidden?: boolean
	setInput: React.Dispatch<React.SetStateAction<string>>
	toolCalls?: IToolCall[]
	streamChunks?: StreamChunk[]
	chatSessionId?: string
	onPromptSelect?: (promptText: string, placeholderPosition?: number, secondaryPlaceholder?: string) => void
}

export interface IDocument {
	title: string
	url: string
}

export interface TLastChat {
	chat_id: string
	messages: IMessage[]
	pagination?: TPagination
}

