export const ChatComponent = React.memo(({
	messages,
	loading = false,
	hidden = false,
	setInput,
	toolCalls = [],
	streamChunks = [],
	chatSessionId,
	onPromptSelect,
}: IChatComponent) => {
	const dateRef = React.useRef<string>(null)
	const bubblesRef = React.useRef<HTMLDivElement>(null)

	// Build content sections from streamChunks for inline rendering
	// Groups consecutive content chunks together, keeps tool calls separate
	const renderStreamContent = React.useMemo(() => {
		if (streamChunks.length === 0) return null

		const elements: React.ReactNode[] = []
		let currentContent = ''
		let contentIndex = 0

		streamChunks.forEach((chunk) => {
			if (chunk.type === 'content') {
				currentContent += chunk.content
			} else if (chunk.type === 'tool_call') {
				// If we have accumulated content, render it first
				if (currentContent) {
					elements.push(
						<ChatBubble
							key={`content-${contentIndex}`}
							message={{
								id: `streaming-${contentIndex}`,
								role: "assistant",
								content: currentContent
							}}
							showCopyButton={false}
						/>
					)
					contentIndex += 1
					currentContent = ''
				}
				// Render the tool call
				elements.push(
					<ToolCallProgress
						key={`tool-${chunk.toolCall.id}`}
						toolCalls={[chunk.toolCall]}
						visible
					/>
				)
			}
		})

		// Render any remaining content
		if (currentContent) {
			elements.push(
				<ChatBubble
					key={`content-${contentIndex}`}
					message={{
						id: `streaming-${contentIndex}`,
						role: "assistant",
						content: currentContent
					}}
					showCopyButton={false}
				/>
			)
		}

		return elements
	}, [streamChunks])

	// Check if we have any content in streamChunks
	const hasStreamContent = streamChunks.some(chunk => chunk.type === 'content')
	const hasToolCalls = streamChunks.some(chunk => chunk.type === 'tool_call') || toolCalls.length > 0

	return (
		<ChatBubbles data-hidden={hidden} ref={bubblesRef} data-element="chat-bubbles">
			{messages?.map((message, index) => {
				if (message.role === 'shared_chat_end') {
					return (
						<SharedChatEndDivider key={message.id}>
							<SharedChatEndTitle>
								<SharedChatEndIcon />
								<span><strong>End of shared chat.</strong> New messages use your filters.</span>
							</SharedChatEndTitle>
							<SharedChatEndSubtext>
								Include details when referencing the conversation above.
							</SharedChatEndSubtext>
						</SharedChatEndDivider>
					);
				}

				const isUser = message.role === 'user';
				let showCopyButton = true;
				let customCopyContent = '';

				if (!isUser) {
					// Check if next message is also from AI
					const nextMessage = messages[index + 1];
					const isNextMessageAI = nextMessage && nextMessage.role !== 'user' && nextMessage.role !== 'shared_chat_end';

					if (isNextMessageAI) {
						showCopyButton = false;
					} else if (loading && !hasStreamContent && index === messages.length - 1) {
						// If loading and no streamed content yet, and this is the last message, hide button
						showCopyButton = false;
					} else if (loading && hasStreamContent && index === messages.length - 1) {
						// If loading and there IS streamed content, hide button on this completed message
						showCopyButton = false;
					}

					// Calculate custom copy content (concatenate previous continuous AI messages)
					if (showCopyButton) {
						const parts = [];
						if (message.content !== 'function_call' && message.content !== 'function_response') {
							parts.unshift(message.content);
						}

						let prevIndex = index - 1;
						while (prevIndex >= 0) {
							const prevMsg = messages[prevIndex];
							if (prevMsg.role === 'user') break;
							if (prevMsg.content !== 'function_call' && prevMsg.content !== 'function_response') {
								parts.unshift(prevMsg.content);
							}
							prevIndex -= 1;
						}
						customCopyContent = parts.join('\n\n');
					}
				}

				return (
					<ChatBubble
						key={message.id}
						message={message}
						dateRef={dateRef}
						showCopyButton={showCopyButton}
						customCopyContent={customCopyContent}
						chatSessionId={chatSessionId}
					/>
				);
			})}
			{!messages?.length && !hasStreamContent && (
				<EmptyChatScreen setInput={setInput} onPromptSelect={onPromptSelect} />
			)}
			{loading && !hasStreamContent && !hasToolCalls && (
				<ResponseLoader />
			)}
			{loading && streamChunks.length > 0 && renderStreamContent}
		</ChatBubbles>
	)
})

const addStreamError = (
	queryClient: QueryClient,
	appID: string,
	error: Error,
	currentVersion: TARA_API_VERSION,
	debugMode: boolean,
	persona: string,
	extraContext?: Record<string, unknown>,
) => {
	const errorMessage: IMessage = {
		id: new Date().toISOString(),
		role: 'assistant',
		content: 'An error occurred while generating the response. Please try again.',
		timestamp: new Date().toISOString(),
		isError: true,
	}

	rollbar.error(
		`AI STREAM - ${error?.message || 'An error occurred while generating the response. Please try again.'}`,
		error,
		{
			errorCode: (error as any)?.code,
			errorName: error?.name,
			appID,
			apiVersion: currentVersion,
			debugMode,
			statusCode: (error as any)?.response?.status,
			endpoint: (error as any)?.config?.url,
			...extraContext,
		}
	);

	// Update query cache with error message
		queryClient.setQueryData(taraApiFactory.getQueryKey(currentVersion, 'chat_thread', debugMode, appID, persona), (prevData: unknown) => {
		const typedData = prevData as TLastChat
		const oldMessages = typedData?.messages || []
		const newMessages = [...oldMessages, errorMessage]
		return { ...typedData, messages: newMessages }
	})

	return errorMessage
}

// Delay in ms before showing subsequent tool calls
const TOOL_CALL_STAGGER_DELAY = 1000

interface IProps {
	streamedMessage: string
	setStreamedMessage: React.Dispatch<React.SetStateAction<string>>
	chatThreadId: string | undefined
	setChatThreadId: React.Dispatch<React.SetStateAction<string | undefined>>
	isSharedClaim?: boolean
	onDismissClaim?: () => void
	onLoadingChange?: (loading: boolean) => void
}

const ChatTab = ({ streamedMessage, setStreamedMessage, chatThreadId, setChatThreadId, isSharedClaim, onDismissClaim, onLoadingChange }: IProps) => {
	const [input, setInput] = React.useState('')
	const [loading, setLoading] = React.useState(false)

	React.useEffect(() => {
		onLoadingChange?.(loading)
	}, [loading, onLoadingChange])
	const [toolCalls, setToolCalls] = React.useState<IToolCall[]>([])
	const [streamChunks, setStreamChunks] = React.useState<StreamChunk[]>([])
	const [showSuggestionsPopup, setShowSuggestionsPopup] = React.useState(false)
	const [cursorToFirstToken, setCursorToFirstToken] = React.useState(false)
	const [secondaryPlaceholder, setSecondaryPlaceholder] = React.useState<string | undefined>(undefined)
	const autoSendPendingRef = React.useRef(false)
	const taraPromptProcessedRef = React.useRef(false)
	const isTaraEmailInsightRef = React.useRef(false)
	const [isFetchingOlderMessages, setIsFetchingOlderMessages] = React.useState(false)
	const paginationRef = React.useRef<TPagination | null>(null)
	const chatMainRef = React.useRef<HTMLDivElement>(null)
	const router = useRouter()
	const { currentVersion, currentPersona, isReady } = useTaraAPIVersion()
	const { isLoggedInFromAdmin } = useIsLoggedInAdmin()

	// Get current persona and session ID
	const streamRef = React.useRef<EventSource | null>(null)
	// Track tool call count for staggered display
	const toolCallCountRef = React.useRef(0)
	// Store pending timeouts for cleanup
	const pendingToolCallTimeoutsRef = React.useRef<ReturnType<typeof setTimeout>[]>([])

	const { setTempDocumentsMap, setSessionAliasMap } = useAIAssistantContext()
	const { debugMode } = useAISidebarContext()
	const { activeChatId, setActiveChatId, activeChatPersona, setActiveChatPersona, isPendingNewChat, finalizePendingChat, refetchChats, isLoadingPeek, isLoadingChats, chats, totalChats, createNewChat, selectChat, hasReachedChatLimit, setShowChatLimitModal } = useChatManagement()
	const dispatch = useDispatch()
	const queryClient = useQueryClient()
	const {
		currentAppReducer: { _id: appID },
		currentOrgReducer: { orgId },
		urlReducer: { sessionpage, sessionid, parentType },
		appFilter,
        profileReducer: { _id: userID },
	} = useSelector((state: IReduxState) => state)
	const {
		session: {
			segment: appFilterSegment,
		},
		dateSegment: appFilterDateSegment,
	} = appFilter

	const { sessionMeta: aiMeta } = useSessionMeta('AI CHAT TAB - error getting session meta')
	const statsBoxDataPayload = React.useMemo(() => ({
		appid: appID,
		filters: appFilterSegment,
		date_range: appFilterDateSegment
	}), [appID, appFilterDateSegment, appFilterSegment])

	const isAISessionsPage = parentType === 'aiSessionsList'
	const { data: statBoxesData } = useStatsBoxData(statsBoxDataPayload, { enabled: isAISessionsPage })

	// Query key changes based on activeChatId for multi-chat support
	const effectivePersona = activeChatPersona || currentPersona
	const chatQueryKey = React.useMemo(() => {
		const key = activeChatId
			? [...taraApiFactory.getQueryKey(currentVersion, 'chat_thread', debugMode, appID, effectivePersona), activeChatId]
			: taraApiFactory.getQueryKey(currentVersion, 'chat_thread', debugMode, appID, effectivePersona)
		return key
	}, [currentVersion, debugMode, appID, effectivePersona, activeChatId])

	const queryEnabled = !!appID && isReady && !isPendingNewChat && !!activeChatId

	const { data, isLoading: isFetching } = useQuery({
		queryKey: chatQueryKey,
		queryFn: () => {
			return getChatThread(
				appID as string,
				currentVersion,
				effectivePersona,
				debugMode,
				activeChatId || undefined,
			)
		},
		enabled: queryEnabled,
		staleTime: 1000 * 60 * 5,
		onSuccess: (response) => {
			if (response?.session_id) {
				setChatThreadId(response.session_id)
			}
		},
		onError: (err: Error) => {
			// Suppressing 404 (Needs further investigation) -  A 404 here means peek/list referenced a thread that no longer exists in Tara.
			// Expected, not actionable — skip error reporting to avoid alert noise.
			if ((err as { response?: { status?: number } })?.response?.status === 404) return
			addStreamError(queryClient, appID as string, err, currentVersion, debugMode, currentPersona)
		},
	})

	// Sync session alias map from chat thread data (works for both fresh fetches and cached data)
	React.useEffect(() => {
		setSessionAliasMap(data?.session_alias_map || null)
	}, [data?.session_alias_map, setSessionAliasMap])

	// Reset streaming state and sync chatThreadId when switching chats
	React.useEffect(() => {
		setStreamedMessage('')
		setToolCalls([])
		setStreamChunks([])
		setLoading(false)
		setInput('')
		setShowSuggestionsPopup(false)
		setIsFetchingOlderMessages(false)
		paginationRef.current = null
		if (streamRef.current) {
			streamRef.current.close()
			streamRef.current = null
		}
		setChatThreadId(activeChatId || undefined)
	}, [activeChatId])
	
	const [userScrolledUp, setUserScrolledUp] = React.useState(false);
	const [hasTriggered, setHasTriggered] = React.useState(false);

	const handleUserScroll = React.useCallback((e: WheelEvent | TouchEvent) => {
		if (!chatMainRef.current) return;

		let isScrollingUp = false;
		let isScrollingDown = false;
		if (e instanceof WheelEvent) {
			isScrollingUp = e.deltaY < 0;
			isScrollingDown = e.deltaY > 0;
		} else if (e instanceof TouchEvent && e.touches.length > 0) {
			isScrollingUp = true;
		}

		if (isScrollingUp) {
			setUserScrolledUp(true);
		}

		const { scrollTop, scrollHeight, clientHeight } = chatMainRef.current;
		const isNearBottom = scrollHeight - scrollTop - clientHeight < 100;
		if (isScrollingDown && isNearBottom) {
			setUserScrolledUp(false);
		}
	}, []);

	const fetchOlderMessages = React.useCallback(async () => {
		const pagination = paginationRef.current
		if (!pagination?.next_page || isFetchingOlderMessages) return

		setIsFetchingOlderMessages(true)
		const scrollContainer = chatMainRef.current
		const prevScrollHeight = scrollContainer?.scrollHeight ?? 0

		try {
			const olderData = await getChatThread(
				appID as string,
				currentVersion,
				effectivePersona,
				debugMode,
				activeChatId || undefined,
				pagination.next_page,
			)

			queryClient.setQueryData(chatQueryKey, (prevData: unknown) => {
				if (!prevData) return prevData
				const typedData = prevData as TLastChat
				const existingMessages = typedData.messages || []
				const olderMessages = olderData.messages || []
				const existingIds = new Set(existingMessages.map(m => m.id))
				const uniqueOlder = olderMessages.filter(m => !existingIds.has(m.id))
				return {
					...typedData,
					messages: [...uniqueOlder, ...existingMessages],
					pagination: olderData.pagination,
				}
			})

			requestAnimationFrame(() => {
				if (scrollContainer) {
					const heightDelta = scrollContainer.scrollHeight - prevScrollHeight
					scrollContainer.scrollTop = heightDelta
				}
			})
		} catch (error) {
			console.error('Failed to fetch older messages:', error)
		} finally {
			setIsFetchingOlderMessages(false)
		}
	}, [appID, currentVersion, effectivePersona, debugMode, activeChatId, queryClient, chatQueryKey, isFetchingOlderMessages])

	const handleScroll = React.useCallback(() => {
		if (!chatMainRef.current) return;

		const { scrollTop, scrollHeight, clientHeight } = chatMainRef.current;
		const distanceFromBottom = scrollHeight - scrollTop - clientHeight;

		const triggerDistance = distanceFromBottom > clientHeight * 2
		if (triggerDistance) {
			if (!hasTriggered) {
				dispatch(
					trackPageViews(null, {
						eventName: 'wa_sessions_tara_scroll_response',
						track_type: 'event',
						eventProperty: {
							height_triggered: triggerDistance,
						},
					})
				)
				setHasTriggered(true);
			}
		} else {
			setHasTriggered(false);
		}

		// Load older messages when scrolled near top
		if (scrollTop < 100 && !isFetchingOlderMessages && paginationRef.current?.next_page) {
			fetchOlderMessages()
		}
	}, [hasTriggered, dispatch, isFetchingOlderMessages, fetchOlderMessages]);

	// Attach wheel/touch listeners
	React.useEffect(() => {
		const element = chatMainRef.current;
		if (!element) return;

		element.addEventListener('wheel', handleUserScroll, { passive: true });
		element.addEventListener('touchmove', handleUserScroll, { passive: true });

		// eslint-disable-next-line consistent-return
		return () => {
			element.removeEventListener('wheel', handleUserScroll);
			element.removeEventListener('touchmove', handleUserScroll);
		};
	}, [handleUserScroll]);


	const scrollToBottom = React.useCallback((instant = false) => {
		if (!chatMainRef.current) return;

		const element = chatMainRef.current;
		element.scrollTo({
			top: element.scrollHeight,
			behavior: instant ? 'auto' : 'smooth'
		});
	}, []);

	const sendMessage = React.useCallback(async () => {
		if (!input.trim()) return;
		if (hasReachedChatLimit && !activeChatId) {
			setShowChatLimitModal(true)
			return;
		}
		setUserScrolledUp(false);
		setShowSuggestionsPopup(false);
		setTimeout(() => scrollToBottom(), 50);
		
		// Strip curly braces from placeholders before sending
		// This handles the case where user selects a prompt and sends immediately without editing
		const messageContent = input.replace(/\{([^}]+)\}/g, '$1')
		
		const newMessage: IMessage = {
			id: crypto.randomUUID(),
			role: 'user',
			content: messageContent,
			timestamp: new Date().toISOString(),
			readable_filters: aiMeta?.descriptions,
			sessions_analyzed_by_ai: aiMeta?.total_sessions,
		}
		queryClient.setQueryData(chatQueryKey, (prevData: unknown) => {
			if (prevData) {
				const typedData = prevData as TLastChat
				const oldMessages = typedData?.messages || []
				const newMessages = [...oldMessages, newMessage]
				return { ...typedData, messages: newMessages }
			}
			return { messages: [newMessage], session_id: chatThreadId }
		})
		setInput('')
		setLoading(true)
		setStreamedMessage('')
		setToolCalls([])
		setStreamChunks([])
		// Reset tool call counter and clear any pending timeouts
		toolCallCountRef.current = 0
		pendingToolCallTimeoutsRef.current.forEach(clearTimeout)
		pendingToolCallTimeoutsRef.current = []
		dispatch(
			trackPageViews(null, {
				eventName: 'wa_sessions_tara_submit_prompt',
				track_type: 'event',
				eventProperty: {
					prompt_text: input,
					context_length: aiMeta?.total_sessions,
					filters_applied: appFilterSegment || [],
				},
			})
		)

		try {

			const start = performance.now();
            const isNewEmailInsight = isTaraEmailInsightRef.current && isPendingNewChat
            // EventSource bypasses axiosInstance, so proactively refresh the token here
            // to avoid hitting the stream endpoint with an expired token (403).
            await tokenRefreshManager.refreshIfNeeded()
            const stream = taraApiFactory.createStream(currentVersion, {
                    input: messageContent,
                    appID: appID as string,
                    userID,
                    sessionid,
                    sessionpage: sessionpage as number,
                    aiMeta: aiMeta as TSessionMetaResponse,
                    statBoxesData,
                    appFilterSegment,
                    appFilterDateSegment,
                    chatThreadId: isPendingNewChat ? undefined : chatThreadId,
                    persona: effectivePersona,
                    ...(isNewEmailInsight && {
                        requestSource: 'email_insight',
                        title: 'Tara email insights',
                    }),
            }, debugMode)
            if (isNewEmailInsight) {
                isTaraEmailInsightRef.current = false
            }

			streamRef.current = stream

			// For new chats, delay list invalidation to give BE time to generate the chat name
			if (isPendingNewChat) {
				setTimeout(() => {
					finalizePendingChat()
				}, 1000)
			}

			let totalCost = 0
			let answerCost = 0
			let queryExpansionCost = 0
			let documents: IDocument[] = []
			let incomingConversationHistory: IMessage[] = []
			let accumulatedContent = '' // Local variable to accumulate streamed content
			let streamCompletedSuccessfully = false

			stream.onmessage = (event) => {
				let jsonStr = event.data
				if (jsonStr.startsWith('data: ')) {
					jsonStr = jsonStr.substring(6)
				}
                let parsedData: any;
                try{
 			    	parsedData = JSON.parse(jsonStr)
                }catch(error){
					// Attempt to sanitize corrupted SSE data where "data:" prefix leaks mid-content
					const sanitized = jsonStr.replace(/data:\s*/g, '')
					try {
						parsedData = JSON.parse(sanitized)
					} catch {
						return
					}
                }
				switch (parsedData.type) {
					case 'content':
						accumulatedContent += parsedData.content
						// Mark all existing tool calls as loaded when content arrives
						setToolCalls((prev) => prev.map((tc) => ({ ...tc, status: 'loaded' as const })))
						setStreamChunks((prev) => {
							// Mark any previous tool call chunks as loaded when content starts streaming
							const updatedPrev = prev.map((chunk) => {
								if (chunk.type === 'tool_call' && chunk.toolCall.status === 'loading') {
									return { ...chunk, toolCall: { ...chunk.toolCall, status: 'loaded' as const } }
								}
								return chunk
							})
							// Check if last chunk is content - if so, append to it
							const lastChunk = updatedPrev[updatedPrev.length - 1]
							if (lastChunk && lastChunk.type === 'content') {
								return [
									...updatedPrev.slice(0, -1),
									{ type: 'content', content: lastChunk.content + parsedData.content }
								]
							}
							// Otherwise add new content chunk
							return [...updatedPrev, { type: 'content', content: parsedData.content }]
						})
						setStreamedMessage((prev) => prev + parsedData.content)
						break
					case 'function_call': {
						// Handle tool call progress - add new tool call or update existing
						const toolData = parsedData.tool
						if (toolData?.name && toolData?.data?.progress_message) {
							const newToolCall: IToolCall = {
								id: toolData.id || `tool-${Date.now()}`,
								name: toolData.name as ToolName,
								progress_message: toolData.data.progress_message,
								status: 'loading',
								timestamp: Date.now(),
							}

							// Function to add the tool call to state
							const addToolCallToState = () => {
								// Mark previous tool calls as loaded
								setToolCalls((prev) => {
									const updatedPrev = prev.map((tc) => ({ ...tc, status: 'loaded' as const }))
									return [...updatedPrev, newToolCall]
								})
								// Add tool call to stream chunks for inline rendering
								setStreamChunks((prev) => {
									// Mark any previous tool call chunks as loaded
									const updatedPrev = prev.map((chunk) => {
										if (chunk.type === 'tool_call') {
											return { ...chunk, toolCall: { ...chunk.toolCall, status: 'loaded' as const } }
										}
										return chunk
									})
									return [...updatedPrev, { type: 'tool_call', toolCall: newToolCall }]
								})
							}

							// First tool call shows immediately, subsequent ones have cumulative staggered delays
							// 1st: immediate, 2nd: 600ms, 3rd: 1200ms, 4th: 1800ms, etc.
							const currentCount = toolCallCountRef.current
							toolCallCountRef.current += 1

							if (currentCount === 0) {
								// First tool call - show immediately
								addToolCallToState()
							} else {
								// Subsequent tool calls - cumulative delay to space them out
								const delay = TOOL_CALL_STAGGER_DELAY * currentCount
								const timeoutId = setTimeout(() => {
									addToolCallToState()
								}, delay)
								pendingToolCallTimeoutsRef.current.push(timeoutId)
							}
						} else {
							console.log('[TARA] Tool call missing required fields:', {
								hasName: !!toolData?.name,
								hasProgressMessage: !!toolData?.data?.progress_message
							})
						}
						break
					}
					case 'documents':
						documents = parsedData.documents
						setTempDocumentsMap(documents)
						break
					case 'end': {
						// PROD: conversation_history is provided in the end event
						// UAT: conversation_history is NOT provided, build it from streamed data
						if (parsedData?.conversation_history && parsedData.conversation_history.length > 0) {
							incomingConversationHistory = parsedData.conversation_history
						} else {
							const userMessage: IMessage = {
								id: crypto.randomUUID(),
								role: 'user',
								content: messageContent,
								timestamp: new Date().toISOString(),
								readable_filters: aiMeta?.descriptions,
								sessions_analyzed_by_ai: aiMeta?.total_sessions,
							}

							const taraMessage: IMessage = {
								id: crypto.randomUUID(),
								role: 'tara',
								content: accumulatedContent,
								timestamp: new Date().toISOString(),
								...(parsedData?.token_usage && { token_usage: parsedData.token_usage }),
								...(parsedData?.model_used && { model_used: parsedData.model_used }),
								...(parsedData?.model_requested && { model_requested: parsedData.model_requested }),
							}

							incomingConversationHistory = [userMessage, taraMessage]
						}

						// Handle tool_calls if present (for debug mode)
						if (debugMode && parsedData?.tool_calls?.length > 0) {
							const toolCallMessages: IMessage[] = parsedData.tool_calls.map((toolCall: any, index: number) => ({
								id: `tool-${Date.now()}-${index}`,
								role: 'tara' as const,
								content: toolCall.content,
								timestamp: new Date().toISOString(),
								tool: toolCall.tool
							}))

							// Insert tool calls before the final tara response
							if (incomingConversationHistory.length >= 2) {
								// Insert tool calls between user message and final tara response
								const userMessage = incomingConversationHistory[0]
								const taraResponse = incomingConversationHistory[incomingConversationHistory.length - 1]
								incomingConversationHistory = [userMessage, ...toolCallMessages, taraResponse]
							} else if (incomingConversationHistory.length === 1) {
								// Only final response, append tool calls before it
								incomingConversationHistory = [...toolCallMessages, ...incomingConversationHistory]
							}
						}

						if (incomingConversationHistory.length >= 1) {
							// Find the user message (should be the first non-tool message)
							const userMessageIdx = incomingConversationHistory.findIndex(msg => msg.role === 'user')
							if (userMessageIdx !== -1) {
								incomingConversationHistory[userMessageIdx] = {
									...incomingConversationHistory[userMessageIdx],
									readable_filters: aiMeta?.descriptions,
									sessions_analyzed_by_ai: aiMeta?.total_sessions,
								}
							}
                            // * ensure id and timestamp are not null
                            incomingConversationHistory = incomingConversationHistory.map((message) => ({
                                ...message,
                                content: message.content.replace(/\\n\\n/g, '\n\n').replace(/\\n/g, '\n'),
                                id: message.id || crypto.randomUUID(),
                                timestamp: message.timestamp || new Date().toISOString(),
                            }))

							// Add invocation_id to Tara's message (needed for feedback API)
							if (parsedData?.invocation_id) {
								for (let i = incomingConversationHistory.length - 1; i >= 0; i -= 1) {
									if (incomingConversationHistory[i].role === 'tara') {
										incomingConversationHistory[i] = {
											...incomingConversationHistory[i],
											invocation_id: parsedData.invocation_id
										}
										break
									}
								}
							}

							// Store session_alias_map in context (thread-level, not per-message)
							const hasAliasMap = parsedData?.session_alias_map && Object.keys(parsedData.session_alias_map).length > 0
							if (hasAliasMap) {
								setSessionAliasMap(parsedData.session_alias_map)
							}

                            // Store session_id from stream response
                            if (parsedData?.session_id) {
                                setChatThreadId(parsedData.session_id)
                                // Set active chat and pre-seed cache for new query key
                                if (!activeChatId) {
                                    const newChatQueryKey = [
                                        ...taraApiFactory.getQueryKey(currentVersion, 'chat_thread', debugMode, appID, effectivePersona),
                                        parsedData.session_id,
                                    ]
                                    queryClient.setQueryData(newChatQueryKey, {
                                        messages: incomingConversationHistory,
                                        session_id: parsedData.session_id,
                                        ...(hasAliasMap && { session_alias_map: parsedData.session_alias_map }),
                                    })
                                    setActiveChatId(parsedData.session_id)
                                    setActiveChatPersona(effectivePersona)
                                }
                            }
						}

						// Increase credit count
						queryClient.setQueryData<TAIUsageOverview>( `ai_usage_overview_${orgId}`, ( prev ) => {
							if (!prev || isLoggedInFromAdmin) return prev as TAIUsageOverview

							return {
								...prev,
								consumed_tara_credit_by_chat: prev.consumed_tara_credit_by_chat + 1,
								consumed_tara_credit: prev.consumed_tara_credit + 1,
							} as TAIUsageOverview
						})
						streamCompletedSuccessfully = true

						setTimeout(() => {
							refetchChats()
						}, 1000)

						break;
					}
					case 'cost': {
						totalCost = parsedData.cost
						answerCost = parsedData.details.answer_cost
						queryExpansionCost = parsedData.details.query_expansion_cost
						const lastMessage = incomingConversationHistory.splice(-1, 1)[0]
						incomingConversationHistory.push({
							...lastMessage,
							document_map: documents,
							cost: totalCost,
							answer_cost: answerCost,
							query_expansion_cost: queryExpansionCost,
						})
						break
					}
					case 'error':
					case 'request_error': {
						const errorMessage = parsedData.error || parsedData.message || 'AI Stream error'
						const statusCode = parsedData.statusCode ? ` (${parsedData.statusCode})` : ''
						addStreamError(
							queryClient,
							appID as string,
							new Error(`${errorMessage}${statusCode}`),
							currentVersion,
							debugMode,
							currentPersona
						)
						queryClient.invalidateQueries(`ai_usage_overview_${orgId}`)
						stream.close()
						setLoading(false)
						setStreamedMessage('')
						setToolCalls([])
						setStreamChunks([])
						// Reset tool call counter and clear pending timeouts
						toolCallCountRef.current = 0
						pendingToolCallTimeoutsRef.current.forEach(clearTimeout)
						pendingToolCallTimeoutsRef.current = []
						break
					}
					default:
						break
				}
			}

			stream.onerror = (event) => {
				const readyStateMap = { 0: 'CONNECTING', 1: 'OPEN', 2: 'CLOSED' };
				const readyStateText = readyStateMap[stream.readyState as 0 | 1 | 2] || 'UNKNOWN';
				const hasHistory = incomingConversationHistory.length > 0;
				const hasStreamedContent = accumulatedContent.length > 0;

				// EventSource fires onerror on every server-side close, including after a clean 'end' event.
				// streamCompletedSuccessfully is the canonical signal; readyState/history are defense-in-depth.
				const shouldReportError = !streamCompletedSuccessfully || (stream.readyState !== 2 && stream.readyState !== 0) || !hasHistory;

				if (shouldReportError) {
					// Low-cardinality title so Rollbar can group occurrences; per-request detail goes in context.
					const reason = !hasHistory && !hasStreamedContent
						? 'no data received'
						: 'connection lost mid-conversation';
					const errorContext = {
						readyState: stream.readyState,
						readyStateText,
						hasConversationHistory: hasHistory,
						hasStreamedContent,
						streamedMessageLength: accumulatedContent.length,
						conversationHistoryLength: incomingConversationHistory.length,
						url: stream.url,
						messageLength: input?.length || 0,
					};
					console.error('AI STREAM ERROR:', errorContext, event);
					addStreamError(
						queryClient,
						appID as string,
						new Error(`Stream ${readyStateText.toLowerCase()} — ${reason}`),
						currentVersion,
						debugMode,
						currentPersona,
						errorContext,
					)
					queryClient.invalidateQueries(`ai_usage_overview_${orgId}`)
				} else {
					queryClient.setQueryData(chatQueryKey, (prevData: unknown) => {
						if (prevData) {
							const typedData = prevData as TLastChat
							const oldMessages = typedData?.messages || []
							const newMessages = [...oldMessages.slice(0, -1), ...incomingConversationHistory]
							return { ...typedData, messages: newMessages }
						}
						return null

					})

					const end = performance.now();
					const formattedDuration = ((end - start || 0) / 1000).toFixed(2);
					dispatch(
						trackPageViews(null, {
							eventName: 'wa_sessions_tara_response',
							track_type: 'event',
							eventProperty: {
								time_to_load: formattedDuration,
							},
						})
					)
				}

				queryClient.invalidateQueries(`ai_usage_overview_${orgId}`)
				setLoading(false)
				setToolCalls([])
				setStreamChunks([])
				setTempDocumentsMap(null)
				streamRef.current = null
				// Reset tool call counter and clear pending timeouts
				toolCallCountRef.current = 0
				pendingToolCallTimeoutsRef.current.forEach(clearTimeout)
				pendingToolCallTimeoutsRef.current = []
				stream.close()
			}
		} catch (error: unknown) {
			addStreamError(queryClient, appID as string, error as Error, currentVersion, debugMode, currentPersona)
			queryClient.invalidateQueries(`ai_usage_overview_${orgId}`)
			setLoading(false)
			setToolCalls([])
			setStreamChunks([])
			setTempDocumentsMap(null)
			streamRef.current = null
			// Reset tool call counter and clear pending timeouts
			toolCallCountRef.current = 0
			pendingToolCallTimeoutsRef.current.forEach(clearTimeout)
			pendingToolCallTimeoutsRef.current = []
		}
	}, [input, aiMeta, queryClient, currentVersion, currentPersona, activeChatPersona, appID, dispatch, orgId, appFilterSegment, userID, sessionid, sessionpage, statBoxesData, appFilterDateSegment, chatThreadId, setTempDocumentsMap, setSessionAliasMap, debugMode, scrollToBottom, isLoggedInFromAdmin, isPendingNewChat, setActiveChatId, finalizePendingChat, refetchChats, chatQueryKey])

	const handleStop = React.useCallback(() => {
		if (streamRef.current) {
			streamRef.current.close()
			streamRef.current = null
		}

		dispatch(
			trackPageViews(null, {
				eventName: 'wa_ai_stop_response',
				track_type: 'event',
			})
		)

		const stoppedIndicator: IMessage = {
			id: crypto.randomUUID(),
			role: 'assistant',
			content: 'Response stopped by user',
			timestamp: new Date().toISOString(),
			isError: false,
			isStoppedByUser: true,
		}

		queryClient.setQueryData(chatQueryKey, (prevData: unknown) => {
			if (prevData) {
				const typedData = prevData as TLastChat
				const oldMessages = typedData?.messages || []

				if (streamedMessage) {
					const partialResponseMessage: IMessage = {
						id: crypto.randomUUID(),
						role: 'assistant',
						content: streamedMessage,
						timestamp: new Date().toISOString(),
					}
					const newMessages = [...oldMessages, partialResponseMessage, stoppedIndicator]
					return { ...typedData, messages: newMessages }
				}

				const newMessages = [...oldMessages, stoppedIndicator]
				return { ...typedData, messages: newMessages }
			}
			return prevData
		})

		queryClient.invalidateQueries(`ai_usage_overview_${orgId}`)
		setLoading(false)
		setStreamedMessage('')
		setToolCalls([])
		setStreamChunks([])
		setTempDocumentsMap(null)
		// Reset tool call counter and clear pending timeouts
		toolCallCountRef.current = 0
		pendingToolCallTimeoutsRef.current.forEach(clearTimeout)
		pendingToolCallTimeoutsRef.current = []
	}, [streamedMessage, queryClient, currentVersion, currentPersona, debugMode, appID, setTempDocumentsMap, setSessionAliasMap, orgId, dispatch, aiMeta, chatQueryKey])

	const handleInputChange = React.useCallback((value: string) => {
		setInput(value)
	}, [])

	const handleKeyDown = React.useCallback((e: React.KeyboardEvent<HTMLDivElement>) => {
		if (e.key === 'Enter' && !e.shiftKey && input.trim() && !isFetching) {
			e.preventDefault()
			sendMessage()
		}
	}, [sendMessage, input, isFetching])

	const handleSuggestionsClick = React.useCallback(() => {
		setShowSuggestionsPopup((prev) => !prev)
	}, [])

	const handleSuggestionsClose = React.useCallback(() => {
		setShowSuggestionsPopup(false)
	}, [])

	const handlePromptSelect = React.useCallback((promptText: string, _placeholderPosition?: number, secondaryPlaceholderText?: string) => {
		setInput(promptText)
		// Signal to place cursor at the first token
		setCursorToFirstToken(true)
		// Store secondary placeholder for use in TokenizedInput
		setSecondaryPlaceholder(secondaryPlaceholderText)
	}, [])

	const handleCursorPlaced = React.useCallback(() => {
		setCursorToFirstToken(false)
	}, [])

	const hasMessages = React.useMemo(() => {
		return data?.messages && data.messages.length > 0
	}, [data?.messages])

	// Close suggestions popup when switching to a chat without messages
	React.useEffect(() => {
		if (!hasMessages) {
			setShowSuggestionsPopup(false)
		}
	}, [hasMessages])

	React.useEffect(() => {
		if (data?.messages?.length && !isFetching) {
			const scrollUntilBottom = (attempts = 0) => {
				if (!chatMainRef.current || attempts > 10) return;

				const { scrollTop, scrollHeight, clientHeight } = chatMainRef.current;
				const isAtBottom = scrollHeight - scrollTop - clientHeight < 10;

				if (!isAtBottom) {
					scrollToBottom(true);
					setTimeout(() => scrollUntilBottom(attempts + 1), 100);
				}
			};

			setTimeout(() => scrollUntilBottom(), 50);
		}
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [isFetching, activeChatId]);

	React.useEffect(() => {
		if (!userScrolledUp && streamChunks.length > 0) {
			scrollToBottom();
		}
	}, [streamChunks, userScrolledUp, scrollToBottom]);

	React.useEffect(() => {
		if (data?.pagination) {
			paginationRef.current = data.pagination
		}
	}, [data?.pagination])

    React.useEffect(() => {
        // Reset session ID when app changes
        setChatThreadId(undefined)
    }, [appID])

    React.useEffect(() => {
        // When version or persona switches, invalidate queries to refetch /chat_thread
        setStreamedMessage('')
        queryClient.invalidateQueries(taraApiFactory.getQueryKey(currentVersion, 'chat_thread', debugMode, appID, currentPersona))
    }, [currentVersion, currentPersona, queryClient, appID, debugMode])

	React.useEffect(() => {
		const { taraPrompt } = router.query
		if (taraPrompt && typeof taraPrompt === 'string' && isReady && !taraPromptProcessedRef.current && appID) {
			taraPromptProcessedRef.current = true

			const url = new URL(window.location.href)
			url.searchParams.delete('taraPrompt')
			window.history.replaceState(window.history.state, '', url.pathname + url.search)

			let decodedContent: string
			try {
				decodedContent = decodeURIComponent(taraPrompt)
			} catch {
				decodedContent = taraPrompt
			}

			peekEmailInsightChat(appID as string, currentVersion)
				.then((peekData) => {
					if (peekData?.session_id) {
						selectChat(peekData.session_id, peekData.persona || currentPersona)
					} else if (totalChats >= 149 && chats.length > 0) {
						selectChat(chats[0].session_id, chats[0].persona || currentPersona)
					} else {
						isTaraEmailInsightRef.current = true
						createNewChat('Email insights')
					}
				})
				.catch(() => {
					if (totalChats >= 149 && chats.length > 0) {
						selectChat(chats[0].session_id, chats[0].persona || currentPersona)
					} else {
						isTaraEmailInsightRef.current = true
						createNewChat('Email insights')
					}
				})
				.finally(() => {
					// Defer setting input so it runs after the chat-switch effect clears input
					setTimeout(() => {
						setInput(decodedContent)
						autoSendPendingRef.current = true
					}, 0)
				})
		}
	}, [router, isReady, createNewChat, appID, currentVersion, selectChat, currentPersona, totalChats, chats])

	React.useEffect(() => {
		if (autoSendPendingRef.current && input.trim() && !isFetching && !loading && isReady && data) {
			autoSendPendingRef.current = false
			sendMessage()
		}
	}, [input, isFetching, loading, isReady, sendMessage, data])

	React.useEffect(() => {
		if (isSharedClaim && data?.shared_info?.shared_by) {
			dispatch(
				trackPageViews(null, {
					eventName: 'wa_tara_open_shared_chat',
					track_type: 'event',
				})
			)
		}
	}, [isSharedClaim, data?.shared_info?.shared_by, dispatch])

	return (
		<>
		<ChatWrapper>
			<ChatMainWrapper>
				<ChatMain ref={chatMainRef} onScroll={handleScroll} $suggestionsOpen={showSuggestionsPopup}>
					{isFetchingOlderMessages && (
						<OlderMessagesLoader>
							<Spinner data-size='sm' />
						</OlderMessagesLoader>
					)}
					{(isFetching || isLoadingPeek || !isReady) && (
						<SpinnerWrapper>
							<Spinner data-size='m' />
						</SpinnerWrapper>
					)}
					<ChatComponent
						messages={data?.messages as IMessage[]}
						loading={loading}
						streamChunks={streamChunks}
						hidden={isFetching || isLoadingPeek || !isReady}
						setInput={setInput}
						toolCalls={toolCalls}
						chatSessionId={chatThreadId}
						onPromptSelect={handlePromptSelect}
					/>
				</ChatMain>
				{hasMessages && (
					<PromptLibraryPopup
						isOpen={showSuggestionsPopup}
						onClose={handleSuggestionsClose}
						onPromptSelect={handlePromptSelect}
					/>
				)}
			</ChatMainWrapper>
			<ChatBottom>
				<ChatInput
					value={input}
					onChange={handleInputChange}
					onKeyDown={handleKeyDown}
					onSend={sendMessage}
					disabled={isFetching || loading || !isReady}
					loading={loading || !isReady}
					onStop={handleStop}
					onSuggestionsClick={handleSuggestionsClick}
					showSuggestionsButton={hasMessages}
					suggestionsActive={showSuggestionsPopup}
					cursorToFirstToken={cursorToFirstToken}
					onCursorPlaced={handleCursorPlaced}
					secondaryPlaceholder={secondaryPlaceholder}
				/>
			</ChatBottom>
		</ChatWrapper>
		<SharedChatClaimModal
			visible={!!isSharedClaim && !!data?.shared_info?.shared_by}
			senderName={data?.shared_info?.shared_by}
			onClose={() => onDismissClaim?.()}
		/>
	</>
	)
}

export default ChatTab
