/* eslint-disable no-underscore-dangle */
import React, {
  memo,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { Modal, Form, Tooltip, Radio, RadioChangeEvent } from 'antd';
import Rollbar from 'rollbar';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import IconBin from 'public/static/icon-bin.svg';
import IconDuplicateSmall from 'public/static/icon-duplicate-small.svg';
import ButtonNew from 'components/common/ButtonNew';
import { useDispatch, useSelector } from 'react-redux';
import { IReduxState } from 'types/reduxStateTypes';
import { useMutation, useQueryClient } from 'react-query';
import useMessage from 'hooks/useMessage';
import {
  createNocodeEvent,
  editNocodeEvent,
} from 'components/features/sessions/hooks/useNocodeEvents';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import InfoAccordion from 'components/common/InfoAccordion';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';
import { ISessionTimeline, TGestureName } from 'types/sessionTypes';
import { getDateMonthYear } from 'Utils/DateConversion/dateConversionUtils';
import {
  gesturesTypesWithValue,
  gesturesValueToStringType,
  gesturesViewTypeIntToString,
} from 'components/features/heatmaps/constants';
import { rollbar } from 'components/common/rollbar';
import { trackPageViews } from 'redux/actions/trackingReport';
import { ICreateNocodeResponse } from 'types/nocodeEvents';
import axios from 'axios';
import { setScreenTimeLineEvents } from 'redux/actions/video';
import { useRouter } from 'next/router';
import { getFilterPropertyRemoteData } from 'redux/actions/filter';
import { Buttons, Label, Title } from '../commonStyles';

import {
  editNocodeEventToSessionDetail,
  addNocodeEventToSessionDetail,
  checkForAnyValue,
  accordionText,
  showTooltip,
} from '../helpers';

import {
  ButtonsWrapper,
  EventWrapper,
  GlobalStyles,
  InputArea,
  InputLabel,
  InputText,
  LabelRight,
  LabelWrapper,
  Scrollable,
  SubTitle,
} from '../../styles';

interface IFormValues {
  'event-name': string;
  'event-description': string;
}
export const gesturesViewTypeIntToStringAdjusted =
  gesturesViewTypeIntToString as { [key: number]: string };
export const gesturesValueToStringTypeAdjusted = gesturesValueToStringType as {
  [key: number]: string;
};

const ManageNoCodeEventPopup: React.FC = () => {
  const {
    managePopupOpen,
    setManagePopupOpen,
    setCurrentAction,
    currentAction,
    currentScreen,
    deletePopupOpen,
    setCurrentScreen,
    setDeletePopupOpen,
    setDuplicateEventModalOpen,
    duplicateEventModalOpen,

  } = useNoCodeEventsContext();
  const {
    sessionDetail,
    setSessionDetail,
    sessionNocodeEvents,
    sessionQueriesToInvalidate,
    setSessionNocodeEvents,
    setSessionQueriesToInvalidate,
  } = useSessionTimeLine() as unknown as ISessionTimeline;
  const { device } = sessionDetail || {};
  const [form] = Form.useForm();

  const [isScreenAny, setIsScreenAny] = useState<boolean>(false);
  const [isViewNameAny, setIsViewNameAny] = useState<boolean>(false);
  const [isElementIdAny, setIsElementIdAny] = useState<boolean>(false);

  const radioNameMap = useMemo(
    () => ({
      elementId: setIsElementIdAny,
      viewName: setIsViewNameAny,
      screenName: setIsScreenAny,
    }),
    []
  );

  const smartRule = useMemo(
    () => currentAction?.props?.rule,
    [currentAction?.props?.rule]
  );

  const onRadioChange = useCallback(
    (
      e: RadioChangeEvent,
      radioName: 'screenName' | 'viewName' | 'elementId'
    ) => {
      const isAny = e.target.value === 'any';

      if (radioName in radioNameMap) {
        const setStateFunction = radioNameMap[radioName];
        setStateFunction(Boolean(isAny));
      }
    },
    [radioNameMap]
  );

  const labelArray = useMemo(
    () => [
      {
        name: 'screenName',
        value: isScreenAny,
      },
      {
        name: 'viewName',
        value: isViewNameAny,
      },
      {
        name: 'elementId',
        value: isElementIdAny,
      },
    ],
    [isElementIdAny, isScreenAny, isViewNameAny]
  );

  const mappedLabelArray = useMemo(
    () => labelArray.filter((label) => label.value === true),
    [labelArray]
  );
  const mappedNames = useMemo(
    () => mappedLabelArray.map((label) => label.name),
    [mappedLabelArray]
  );

  const disableSwitch = useCallback(
    (switchName: string) => {
      if (mappedLabelArray.length === 2 && !mappedNames.includes(switchName))
        return true;
      return false;
    },
    [mappedLabelArray, mappedNames]
  );

  const { message } = useMessage();
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const { resetFields, setFieldsValue, setFields } = form;
  const editable = useMemo(
    () => currentAction?.type === 'smart_gesture_event',
    [currentAction?.type]
  );
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const router = useRouter();

  const {
    currentAppReducer,
    currentOrgReducer,
    screenTimelineReducer: { selectedEventField },
    appFilter: {
      event: { segment },
      dateSegment,
    },
    urlReducer,
  } = useSelector((state: IReduxState) => state);
  const { _id: appId } = currentAppReducer;
  const orgId = currentOrgReducer?.orgId;

  const parentType = urlReducer?.parentType;

  const isManagementPage = useMemo(() => parentType === 'settings', [parentType]);

  const getPayload = useCallback(
    () => ({
      attribute: 'nce_name',
      filter: [],
      appid: appId as string,
      search: '',
      dropdownLimit: 501,
      date_range: dateSegment,
    }),
    [appId, dateSegment]
  );

  const { mutate: createEvent, isLoading: createIsLoading } =
    useMutation(createNocodeEvent);
  const { mutate: editEvent, isLoading: editIsLoading } =
    useMutation(editNocodeEvent);
  const isLoading = createIsLoading || editIsLoading;

  const handleClose: () => void = useCallback(
    () => !isLoading && setManagePopupOpen(false),
    [setManagePopupOpen, isLoading]
  );
  const handleDeleteEvent = useCallback(() => {
    if (editable) {
      setManagePopupOpen(false);
      setDeletePopupOpen(true);
    }
  }, [editable, setDeletePopupOpen, setManagePopupOpen]);

  const makeInvalidations = useCallback(() => {
    const sessionId = urlReducer?.sessionid;
    if (sessionId) {
      setSessionQueriesToInvalidate([...sessionQueriesToInvalidate, sessionId]);
    }
    queryClient.invalidateQueries({ queryKey: ['manage-nocode-list'] });
    queryClient.invalidateQueries({ queryKey: ['nocodeEventList'] });
    queryClient.invalidateQueries({ queryKey: ['nocodeEventNamesWithCount'] });
    queryClient.invalidateQueries({ queryKey: ['sessionNocodeEvents'] });
  }, [
    sessionQueriesToInvalidate,
    urlReducer,
    queryClient,
    setSessionQueriesToInvalidate,
  ]);

  const gestureTypeStr = useMemo(() => {
    if (currentAction?.type === 'gesture') {
      return currentAction?.name || 'not defined';
    }

    return currentAction?.props?.gestureType || 'not defined';
  }, [
    currentAction?.name,
    currentAction?.props?.gestureType,
    currentAction?.type,
  ]);

  const handleDuplicateEvent = useCallback(() => {
    if (editable) {
      setManagePopupOpen(false);
      setDuplicateEventModalOpen(true);
    }
  }, [editable, setDuplicateEventModalOpen, setManagePopupOpen]);

  const handleCreateEvent = useCallback(
    (values: IFormValues) => {
      if (
        appId &&
        currentAction?.name &&
        orgId &&
        device?.platform &&
        currentScreen?.activityName &&
        device?.sdkVersion
      ) {
        createEvent(
          {
            name: values['event-name']?.trim(),
            description: values['event-description'],
            appid: appId,
            element_id: isElementIdAny
              ? ['__any__']
              : [currentAction?.props?.idString] || [null],
            gesture_type: [
              gesturesTypesWithValue[currentAction.name as TGestureName],
            ],
            orgid: orgId,
            platform: device?.platform,
            screen_name: isScreenAny
              ? ['__any__']
              : [currentScreen.activityName],
            sdk_version: device?.sdkVersion,
            view_type: [currentAction?.props?.viewTypeId] || [null],
            view_name: isViewNameAny
              ? ['__any__']
              : [currentAction?.props?.viewName] || [null],
            category: ['nocode'],
          },
          {
            onSuccess: (res) => {
              makeInvalidations();
              dispatch(getFilterPropertyRemoteData(getPayload(), false, true));

              const nceId = (res as ICreateNocodeResponse)?.data?.data?.nceId;

              const newSelectedEventField = [
                ...selectedEventField,
                {
                  name: values['event-name']?.trim(),
                  count: 1,
                },
              ];

              dispatch(setScreenTimeLineEvents(newSelectedEventField));

              if (nceId && sessionDetail && currentScreen && currentAction) {
                const newNocodeObj = {
                  nceId,
                  name: values['event-name']?.trim(),
                  description: values['event-description'],
                  rule: {
                    viewName: isViewNameAny
                      ? '__any__'
                      : currentAction?.props?.viewName || 'undefined',
                    activityName: isScreenAny
                      ? '__any__'
                      : currentScreen?.activityName,
                    idString: isElementIdAny
                      ? '__any__'
                      : currentAction?.props?.idString || 'undefined',
                  },
                };
                setSessionDetail(
                  addNocodeEventToSessionDetail(
                    sessionDetail,
                    currentAction,
                    newNocodeObj
                  )
                );
              }
              if (setSessionNocodeEvents && sessionNocodeEvents) {
                setSessionNocodeEvents([
                  ...sessionNocodeEvents,
                  {
                    event_name: values['event-name']?.trim(),
                    count: 1,
                  },
                ]);
              }

              message({
                content: 'Smart event has been created successfully.',
                type: 'success',
              });
              dispatch(
                trackPageViews(null, {
                  eventName: 'wa_create_nocode_event',
                  track_type: 'event',
                  eventProperty: {
                    event_id: nceId,
                    event_name: values['event-name']?.trim(),
                    screen_name: isScreenAny
                      ? '__any__'
                      : currentScreen?.activityName,
                    view_name: isViewNameAny
                      ? '__any__'
                      : currentAction?.props?.viewNameUpdated ||
                        currentAction?.props?.viewName,
                    view_type: currentAction?.props?.viewType,
                    element_id: isElementIdAny
                      ? '__any__'
                      : currentAction?.props?.idString,
                    gesture_type: currentAction?.props?.gestureType,
                    gesture_name: currentAction?.name,
                    session_id: urlReducer?.sessionid,
                    type_of_event: 'gesture',
                  },
                })
              );
              handleClose();
            },
            onError: (error) => {
              if (axios.isAxiosError(error)) {
                const errorObj =
                  error?.request?.response &&
                  JSON.parse(error.request.response)['error'];
                if (
                  errorObj?.status === 409 &&
                  errorObj?.message === 'Duplicate name.'
                ) {
                  setFields([
                    {
                      name: 'event-name',
                      errors: ['Smart event with that name already exists'],
                    },
                  ]);
                  return;
                }
              }
              message({
                content: `Something went wrong while creating an event. Please try again.`,
                type: 'error',
              });
              rollbar.error(
                error as Rollbar.LogArgument[],
                'Error while creating an event'
              );
            },
          }
        );
      } else {
        message({
          content: 'Something went wrong while creating an event',
          type: 'error',
        });
        rollbar.error(
          [
            appId &&
              currentAction?.name &&
              orgId &&
              device?.platform &&
              currentScreen?.activityName &&
              device?.sdkVersion &&
              currentAction?.props?.viewTypeId &&
              currentAction?.props?.viewType,
          ],
          'Error with values when creating event'
        );
        message({
          content: 'Something went wrong while creating an event',
          type: 'error',
        });
      }
    },
    [
      appId,
      currentAction,
      orgId,
      device?.platform,
      device?.sdkVersion,
      currentScreen,
      createEvent,
      isElementIdAny,
      isScreenAny,
      isViewNameAny,
      makeInvalidations,
      dispatch,
      getPayload,
      selectedEventField,
      sessionDetail,
      setSessionNocodeEvents,
      sessionNocodeEvents,
      message,
      urlReducer?.sessionid,
      handleClose,
      setSessionDetail,
      setFields,
    ]
  );

  const handleEditEvent = useCallback(
    (values: IFormValues) => {
      if (editable) {
        const id = currentAction?.id;
        editEvent(
          {
            appid: appId,
            description: values['event-description'] || '',
            name: values['event-name']?.trim() || '',
            nce_id: id as unknown as number,
          },
          {
            onSuccess: () => {
              if (setSessionNocodeEvents && sessionNocodeEvents) {
                setSessionNocodeEvents(
                  sessionNocodeEvents.map((event) => {
                    if (event.event_name === currentAction?.name) {
                      return {
                        ...event,
                        event_name: values['event-name']?.trim(),
                      };
                    }
                    return event;
                  })
                );
              }

              if (id && sessionDetail && currentScreen && currentAction) {
                const newNocodeObj = {
                  nceId: id as unknown as number,
                  name: values['event-name']?.trim(),
                  description: values['event-description'],
                };
                setSessionDetail(
                  editNocodeEventToSessionDetail(sessionDetail, newNocodeObj)
                );
              }

              const newSelectedEventField = selectedEventField.map((event) =>
                event.name === currentAction?.name
                  ? {
                      ...event,
                      name: values['event-name']?.trim(),
                    }
                  : event
              );

              dispatch(setScreenTimeLineEvents(newSelectedEventField));

              if (
                urlReducer?.parentType === 'nocodeEventsList' &&
                urlReducer?.sessionid
              ) {
                const newSegment = currentAction?.name
                  ? JSON.parse(
                      JSON.stringify(segment).replaceAll(
                        currentAction.name,
                        values['event-name']?.trim()
                      )
                    )
                  : segment;
                const url = `/app/${appId}/smart-events/list/${urlReducer?.eventpage}/${urlReducer?.sessionid}/${urlReducer?.eventid}/${urlReducer?.starttime}#autoplay`;
                router.push(
                  `/integration?parentType=nocodeEventsList&appId=${appId}&sessionid=${urlReducer?.sessionid}&eventpage=${urlReducer?.eventpage}&eventid=${urlReducer?.eventid}&starttime=${urlReducer?.starttime}`,
                  urlSegmentEncoder(url, newSegment)
                );
              }
              makeInvalidations();
              dispatch(getFilterPropertyRemoteData(getPayload(), false, true));

              message({
                content: 'Smart event has been updated successfully.',
                type: 'success',
              });

              dispatch(
                trackPageViews(null, {
                  eventName: 'wa_modify_nocode_event',
                  track_type: 'event',
                  eventProperty: {
                    event_id: currentAction?.id,
                    screen_name: checkForAnyValue(
                      'activityName',
                      currentScreen?.activityName ||
                        currentAction?.screenName ||
                        'undefined',
                      smartRule
                    ).value,
                    view_name: checkForAnyValue(
                      'viewName',
                      currentAction?.props?.viewName || 'undefined',
                      smartRule
                    ).value,
                    view_type: currentAction?.props?.viewType || '',
                    element_id: checkForAnyValue(
                      'idString',
                      currentAction?.props?.idString || 'undefined',
                      smartRule
                    ).value,
                    gesture_type: currentAction?.props?.gestureType,
                    event_name_old: currentAction?.name,
                    event_name_new: values['event-name']?.trim(),
                    modified_description:
                      currentAction?.description?.trim() !==
                      values['event-description'].trim(),
                    type_of_event: 'gesture',
                  },
                })
              );

              handleClose();
            },
            onError: (error) => {
              if (axios.isAxiosError(error)) {
                const errorObj =
                  error?.request?.response &&
                  JSON.parse(error.request.response)['error'];
                if (
                  errorObj?.status === 409 &&
                  errorObj?.message === 'Duplicate name.'
                ) {
                  setFields([
                    {
                      name: 'event-name',
                      errors: ['Smart event with that name already exists'],
                    },
                  ]);
                  return;
                }
              }
              message({
                content: `Something went wrong while editing an event. Please try again.`,
                type: 'error',
              });
              rollbar.error(
                error as Rollbar.LogArgument[],
                'Error while editing an event'
              );
            },
          }
        );
      }
    },
    [
      editable,
      currentAction,
      editEvent,
      appId,
      setSessionNocodeEvents,
      sessionNocodeEvents,
      sessionDetail,
      currentScreen,
      selectedEventField,
      dispatch,
      urlReducer?.parentType,
      urlReducer?.sessionid,
      urlReducer?.eventpage,
      urlReducer?.eventid,
      urlReducer?.starttime,
      makeInvalidations,
      getPayload,
      message,
      smartRule,
      handleClose,
      setSessionDetail,
      segment,
      router,
      setFields,
    ]
  );

  const handleFormOnFinish = useCallback(
    (values: IFormValues) => {
      if (!editable) return handleCreateEvent(values);
      return handleEditEvent(values);
    },
    [editable, handleCreateEvent, handleEditEvent]
  );

  const clearForm = useCallback(() => {
    resetFields();
    if (!deletePopupOpen && !managePopupOpen) {
      setCurrentAction(undefined);
      setCurrentScreen(undefined);
    }
  }, [
    resetFields,
    deletePopupOpen,
    managePopupOpen,
    setCurrentAction,
    setCurrentScreen,
  ]);

  useEffect(() => {
    if (editable) {
      setFieldsValue({
        'event-name': currentAction?.name,
        'event-description': currentAction?.description || '',
      });
    }
  }, [currentAction, setFieldsValue, managePopupOpen, editable]);

  useEffect(() => {
    if (!managePopupOpen && !duplicateEventModalOpen) {
      timerRef.current = setTimeout(clearForm, 500);
    }
    return () => clearTimeout(timerRef?.current);
  }, [clearForm, duplicateEventModalOpen, managePopupOpen]);

  useEffect(() => {
    if (managePopupOpen) {
      dispatch(
        trackPageViews(null, {
          eventName: editable
            ? 'wa_activity_open_modify_event_dialog'
            : 'wa_activity_open_create_event_dialog',
          track_type: 'event',
          eventProperty: {
            screen_name: checkForAnyValue(
              'activityName',
              currentScreen?.activityName ||
                currentAction?.screenName ||
                'undefined',
              smartRule
            ).value,
            view_name: checkForAnyValue(
              'viewName',
              currentAction?.props?.viewName || 'undefined',
              smartRule
            ).value,
            view_type: currentAction?.props?.viewType || '',
            element_id: checkForAnyValue(
              'idString',
              currentAction?.props?.idString || 'undefined',
              smartRule
            ).value,
            gesture_type:
              currentAction?.props?.gestureType || currentAction?.name,
            event_id: currentAction?.id,
            event_name: currentAction?.name,
            session_id: sessionDetail?._id,
            type_of_event: 'gesture',
          },
        })
      );
    }
  }, [
    managePopupOpen,
    currentScreen,
    currentAction,
    editable,
    sessionDetail,
    urlReducer,
    dispatch,
    smartRule,
  ]);

  useEffect(() => {
    if (!editable && managePopupOpen) {
      setIsElementIdAny(false);
      setIsScreenAny(false);
      setIsViewNameAny(false);
    }
  }, [editable, managePopupOpen]);

  return (
    <>
      <GlobalStyles />
      <Modal
        visible={managePopupOpen}
        footer={null}
        onCancel={handleClose}
        closable={false}
        className="ant-modal-manage-nocode-event"
        wrapClassName="ant-modal-manage-nocode-event-wrapper"
        destroyOnClose
        width={570}
      >
        <Form
          form={form}
          name="manage-no-code-event"
          onFinish={handleFormOnFinish}
        >
          <Title>
            {editable ? 'Edit smart event' : 'Create smart event'} 
          </Title>
          <SubTitle>
            Create and manage events without a single line of code. Click <a href='https://help.uxcam.com/hc/en-us/articles/24753425542297-What-are-smart-events' target="_blank" rel="noreferrer"> here</a> to know more.
          </SubTitle>
          <Scrollable>
            <InputLabel>
              <b>Event name</b>
            </InputLabel>
            <Form.Item
              name="event-name"
              rules={[
                { required: true, message: 'Please provide an event name' },
                {
                  max: 50,
                  message:
                    'The event name is too long. Please make it shorter.',
                },
              ]}
              shouldUpdate
            >
              <InputText placeholder="Add event name" disabled={isLoading || !!editable} />
            </Form.Item>
            <InputLabel>
              <b>Description</b>
            </InputLabel>
            <Form.Item
              name="event-description"
              className="text-area"
              rules={[
                {
                  max: 500,
                  message:
                    'The description is too long. Please make it shorter.',
                },
              ]}
            >
              <InputArea placeholder="Add description" disabled={isLoading} />
            </Form.Item>
            <EventWrapper isEditable={editable}>
              {!editable && (
                <>
                  <InputLabel>
                    <b>Event properties</b>
                  </InputLabel>
                  <InfoAccordion
                    title={accordionText.title}
                    description={accordionText.description}
                  />
                </>
              )}
              <LabelWrapper>
                <Label>
                  <b>Screen name:</b>
                </Label>
                <LabelRight>
                  {!editable ? (
                    <Radio.Group
                      onChange={(e) => onRadioChange(e, 'screenName')}
                      defaultValue={
                        currentScreen?.activityName || currentAction?.screenName
                      }
                      disabled={disableSwitch('screenName')}
                    >
                      <Tooltip
                        overlay={
                          disableSwitch('screenName') &&
                          'You can set a maximum of 2 attributes to “All”.'
                        }
                        placement="bottom"
                      >
                        <Radio value="any">All</Radio>
                      </Tooltip>
                      <Radio
                        value={
                          currentScreen?.activityName ||
                          currentAction?.screenName
                        }
                      >
                        <Tooltip
                          overlay={
                            showTooltip(
                              currentScreen?.activityName ||
                                currentAction?.screenName
                            ) &&
                            (currentScreen?.activityName ||
                              currentAction?.screenName)
                          }
                          placement="top"
                        >
                          {
                            checkForAnyValue(
                              'activityName',
                              currentScreen?.activityName ||
                                currentAction?.screenName ||
                                'undefined',
                              smartRule
                            ).jsx
                          }
                        </Tooltip>
                      </Radio>
                    </Radio.Group>
                  ) : (
                    <span>
                      <Tooltip
                        overlay={
                          showTooltip(currentAction?.props?.viewName) &&
                          currentAction?.props?.viewName
                        }
                        placement="top"
                      >
                        {
                          checkForAnyValue(
                            'activityName',
                            currentScreen?.activityName ||
                              currentAction?.screenName ||
                              'undefined',
                            smartRule
                          ).jsx
                        }
                      </Tooltip>
                    </span>
                  )}
                </LabelRight>
              </LabelWrapper>
              {
                editable && currentAction?.eventType && (
                <LabelWrapper>
                  <Label>
                    <b>Event type:</b>
                  </Label>
                  <LabelRight isUneditable>
                    <span>{currentAction?.eventType}</span>
                  </LabelRight>
                </LabelWrapper>
                )
              }
              <LabelWrapper>
                <Label>
                  <b>Gesture type:</b>
                </Label>
                <LabelRight isUneditable>
                  <span>{gestureTypeStr}</span>
                </LabelRight>
              </LabelWrapper>
              <LabelWrapper>
                <Label>
                  <b>UI element type:</b>
                </Label>
                <LabelRight isUneditable>
                  <span>
                    {currentAction?.props?.viewType || <i>Undefined</i>}
                  </span>
                </LabelRight>
              </LabelWrapper>
              <LabelWrapper>
                <Label>
                  <b>UI element name:</b>
                </Label>
                <LabelRight>
                  {!editable ? (
                    <Radio.Group
                      onChange={(e) => onRadioChange(e, 'viewName')}
                      defaultValue={
                        currentAction?.props?.viewName || 'not defined'
                      }
                      disabled={disableSwitch('viewName')}
                    >
                      <Tooltip
                        overlay={
                          disableSwitch('viewName') &&
                          'You can set a maximum of 2 attributes to “All”.'
                        }
                        placement="bottom"
                      >
                        <Radio value="any">All</Radio>
                      </Tooltip>
                      <Radio
                        value={currentAction?.props?.viewName || 'not defined'}
                      >
                        <Tooltip
                          overlay={
                            showTooltip(currentAction?.props?.viewName) &&
                            currentAction?.props?.viewName
                          }
                          placement="top"
                        >
                          {
                            checkForAnyValue(
                              'viewName',
                              currentAction?.props?.viewName || 'undefined',
                              smartRule
                            ).jsx
                          }
                        </Tooltip>
                      </Radio>
                    </Radio.Group>
                  ) : (
                    <span>
                      <Tooltip
                        overlay={
                          showTooltip(currentAction?.props?.viewName) &&
                          currentAction?.props?.viewName
                        }
                        placement="top"
                      >
                        {
                          checkForAnyValue(
                            'viewName',
                            currentAction?.props?.viewName || 'undefined',
                            smartRule
                          ).jsx
                        }
                      </Tooltip>
                    </span>
                  )}
                </LabelRight>
              </LabelWrapper>
              <LabelWrapper>
                <Label>
                  <b>UI element ID:</b>
                </Label>
                <LabelRight>
                  {!editable ? (
                    <Radio.Group
                      onChange={(e) => onRadioChange(e, 'elementId')}
                      defaultValue={
                        currentAction?.props?.idString || 'not defined'
                      }
                      disabled={disableSwitch('elementId')}
                    >
                      <Tooltip
                        overlay={
                          disableSwitch('elementId') &&
                          'You can set a maximum of 2 attributes to “All”.'
                        }
                        placement="bottom"
                      >
                        <Radio value="any">All</Radio>
                      </Tooltip>
                      <Radio
                        value={currentAction?.props?.idString || 'not defined'}
                      >
                        <Tooltip
                          overlay={
                            showTooltip(currentAction?.props?.idString) &&
                            currentAction?.props?.idString
                          }
                          placement="top"
                        >
                          {
                            checkForAnyValue(
                              'idString',
                              currentAction?.props?.idString || 'undefined',
                              smartRule
                            ).jsx
                          }
                        </Tooltip>
                      </Radio>
                    </Radio.Group>
                  ) : (
                    <span>
                      <Tooltip
                        overlay={
                          showTooltip(currentAction?.props?.idString) &&
                          currentAction?.props?.idString
                        }
                        placement="top"
                      >
                        {
                          checkForAnyValue(
                            'idString',
                            currentAction?.props?.idString || 'undefined',
                            smartRule
                          ).jsx
                        }
                      </Tooltip>
                    </span>
                  )}
                </LabelRight>
              </LabelWrapper>
              {
                editable && currentAction?.createdByName && (
                <LabelWrapper>
                  <Label>
                    <b>Created by:</b>
                  </Label>
                  <LabelRight isUneditable>
                    <span>{currentAction?.createdByName}</span>
                  </LabelRight>
                </LabelWrapper>
                )
              }
              {
                editable && currentAction?.createdOn && (
                <LabelWrapper>
                  <Label>
                    <b>Created on:</b>
                  </Label>
                  <LabelRight isUneditable>
                    <span>{getDateMonthYear(currentAction?.createdOn)}</span>
                  </LabelRight>
                </LabelWrapper>
                )
              }
            </EventWrapper>
          </Scrollable>
          <Form.Item>
            <ButtonsWrapper>
              <Buttons>
                {editable && (
                  <>
                  {
                    isManagementPage && (
                      <ButtonNew
                        width="default"
                        variant="ghost"
                        size="big"
                        onClick={handleDuplicateEvent}
                        type="button"
                        style={{
                          color: '#5D97FF',
                          fontSize: '12px',
                          lineHeight: '24px',
                          paddingRight: '12px',
                        }}
                        loading={editIsLoading}
                        disabled={createIsLoading}
                      >
                        <IconDuplicateSmall />
                        Duplicate event
                      </ButtonNew>
                    )
                  }
                  <ButtonNew
                    width="default"
                    variant="ghost"
                    size="big"
                    onClick={handleDeleteEvent}
                    type="button"
                    style={{
                      color: '#DC4F44',
                      fontSize: '12px',
                      lineHeight: '24px',
                      paddingRight: '12px',
                    }}
                    loading={editIsLoading}
                    disabled={createIsLoading}
                  >
                    <IconBin />
                    Delete event
                  </ButtonNew>
                  </>
                )}
              </Buttons>
              <Buttons>
                <ButtonNew
                  width="medium"
                  variant="ghost"
                  onClick={handleClose}
                  disabled={isLoading}
                  type="button"
                >
                  Cancel
                </ButtonNew>
                <ButtonNew
                  width="medium"
                  type="submit"
                  loading={createIsLoading}
                  disabled={editIsLoading}
                >
                  {editable ? 'Save' : 'Create event'}
                </ButtonNew>
              </Buttons>
            </ButtonsWrapper>
          </Form.Item>
        </Form>
      </Modal>
    </>
  );
};

export default memo(ManageNoCodeEventPopup);
