import React from 'react'
import styled, { createGlobalStyle } from 'styled-components'
import { Modal } from 'antd'
import { theme } from 'theme'

const GlobalStyles = createGlobalStyle`
	.shared-chat-claim-modal {
		.ant-modal-content {
			border-radius: 8px;
			box-shadow: 0px 8px 32px rgba(0, 0, 0, 0.12);
			.ant-modal-body {
				padding: 32px;
			}
		}
	}
`

const ContentWrapper = styled.div`
	display: flex;
	flex-direction: column;
	gap: 32px;
	align-items: flex-end;
`

const TextSection = styled.div`
	display: flex;
	flex-direction: column;
	gap: 12px;
	width: 100%;
`

const Title = styled.h2`
	font-family: Roboto;
	font-weight: 500;
	font-size: 18px;
	line-height: normal;
	color: ${theme.colors.surface500.toString()};
	margin: 0;
`

const Description = styled.p`
	font-family: Roboto;
	font-weight: 400;
	font-size: 12px;
	line-height: 24px;
	color: ${theme.colors.surface400.toString()};
	margin: 0;
`

const Footer = styled.div`
	display: flex;
	justify-content: flex-end;
	width: 100%;
`

const ViewChatButton = styled.button`
	padding: 8px 30px;
	border-radius: 6px;
	border: none;
	font-family: Roboto;
	font-size: 14px;
	font-weight: 500;
	cursor: pointer;
	color: ${theme.colors.primary500.toString()};
	background: white;

	&:hover {
		background: ${theme.colors.primary10.toString()};
	}
`

interface ISharedChatClaimModalProps {
	visible: boolean
	senderName?: string
	onClose: () => void
}

const SharedChatClaimModal: React.FC<ISharedChatClaimModalProps> = ({
	visible,
	senderName,
	onClose,
}) => {
	const title = senderName
		? `${senderName} shared a chat with you`
		: 'A chat was shared with you'

	return (
		<>
			<GlobalStyles />
			<Modal
				visible={visible}
				closable={false}
				footer={null}
				className="shared-chat-claim-modal"
				centered
				width={470}
				destroyOnClose
			>
				<ContentWrapper>
					<TextSection>
						<Title>{title}</Title>
						<Description>
							This is your own copy of the conversation. Any questions you ask or changes you make won&apos;t affect the original chat.
						</Description>
					</TextSection>
					<Footer>
						<ViewChatButton onClick={onClose}>View chat</ViewChatButton>
					</Footer>
				</ContentWrapper>
			</Modal>
		</>
	)
}

export default SharedChatClaimModal
