import React from 'react';

import dynamic from 'next/dynamic';
import { Button, Menu, Tooltip } from 'antd';
import { useRouter } from 'next/router';
import { RootStateOrAny, useSelector } from 'react-redux';

import { BugFeedbackIcon, DocumentIcon, GuideIcon, HelpIcon, ProductFeedbackIcon, ProfileIcon, RightExpandIcon } from 'public/static/redesign/sidebar';
import GuideBigIcon from 'public/static/sidebarmenu/guide-big.svg';

import LottieIcon from 'components/common/LottieIcon';
import { GuideLottie } from 'public/static/lottie-icons/animations';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { useIsAppType } from 'hooks/useIsAppType';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import useSidebarUtils from '../hooks/useSidebarUtils';

import { BottomMenuWrapper, LinkStyled } from './styles';
import { BottomMenuProps, MenuItem } from './types';
import { UXCamHelpDocs, UXCamProductUpdates } from './variables';
import CommonPopover from '../../NewAppMenu/CommonPopover';
import CheckListPercentage from '../CheckListPercentage';
import IntercomButton from './IntercomButton';

const NewOrganizationSetting = dynamic(
  import(
    'components/IntegratePages/layout/dashboardMenu/NewOrganizationSetting/index'
  ),
  {
    loading: () => <div />,
  }
);

function getItem(
  label: React.ReactNode,
  key: string,
  icon?: React.ReactNode,
  popupClassName?: string
): MenuItem {
  return {
    key,
    icon,
    label,
    popupClassName,
  } as MenuItem;
}

const BottomMenu: React.FC<BottomMenuProps> = (props) => {
  const {
    organizationIndex,
    navigateToTeam,
    navigateToSubscription,
    navigateToAccountSetting,
    urlRoutePageName,
    dispatchPortalLink,
    collapsed,
    logout,
    planHatPortalAccessData,
  } = props;

  const router = useRouter();

  const {
    urlReducer: { parentType },
    currentAppReducer: { isIntegrated },
  } = useSelector((state: RootStateOrAny) => state);

  const { getRouteQuery, getRouteUrl, handleIntercom } = useSidebarUtils();
  const { aiSessionFeatureAllowed: isAISessionEnabled } = (useRestrictionContext() || {}) as { aiSessionFeatureAllowed: boolean };
  const isWebApp = useIsAppType( 'web' );

  const items: MenuItem[] = [
    ...(isAISessionEnabled && !isWebApp ? [getItem('Guide', 'guide', <GuideBigIcon />)] : [getItem('Talk to us', 'talkToUs', <ProfileIcon />)]),
    getItem('Documentation', 'documentation', <DocumentIcon />),
    getItem('Product updates', 'productUpdates', <ProductFeedbackIcon />)
  ];

  const handleGuideClick = (key: string) => {
    if (isWebApp) return;
    if (key === 'guide') {
      const routeQuery = getRouteQuery(key);
      const routeUrl = getRouteUrl(key);
      router.push(routeQuery, routeUrl);
    }
  };

  const handleMenuClick = ({ key }: { key: string }) => {
    if (key === 'talkToUs') {
      handleIntercom();
      return;
    }

    if (key === 'documentation') {
      window.open(UXCamHelpDocs, '_blank');
      return;
    }

    if (key === 'guide') {
      handleGuideClick('guide');
      return;
    }

    window.open(UXCamProductUpdates, '_blank');
  };

  return (
    <BottomMenuWrapper collapsed={collapsed}>
      {
        isWebApp ? (
          <Tooltip title="Bugs & feedback" placement='right'>
            <LinkStyled
              rel='noreferrer'
              target='_blank'
              href='https://uxcamcom.atlassian.net/servicedesk/customer/portal/10'
            >
              <Button
                icon={<BugFeedbackIcon />}
              >
                {collapsed ? null : 'Bugs & feedback'}
              </Button>
            </LinkStyled>
          </Tooltip>
        ) : null
      }
      {isIntegrated && !isWebApp && !isAISessionEnabled ? (
        <Tooltip title="Guide" placement='right'>
          <Button
            className={parentType === 'guide' ? 'selected' : ''}
            icon={parentType === 'guide' ?  <LottieIcon animationData={GuideLottie} active={parentType === 'guide'} />
            : <GuideIcon />}
            onClick={() => handleGuideClick('guide')}
          >
            {collapsed ? null : 'Guide'}
            {collapsed ? null : <CheckListPercentage/>}
          </Button>
        </Tooltip>
      ) : null}
      <CommonPopover
        paddingSize="small"
        placement="rightTop"
        collapsed={collapsed}
        content={
          <Menu
            mode="vertical"
            theme="dark"
            inlineCollapsed={false}
            items={items}
            triggerSubMenuAction="click"
            onClick={handleMenuClick}
            className="popover-menu-list"
          />
        }
        trigger={collapsed ? 'hover' : 'click'}
      >
        <Button icon={<HelpIcon />}>
          {collapsed ? null : 'Support'}
          <RightExpandIcon />
        </Button>
      </CommonPopover>
      {isAISessionEnabled && <IntercomButton collapsed={collapsed} />}
      <NewOrganizationSetting
        navigateToTeam={navigateToTeam}
        navigateToSubscription={navigateToSubscription}
        logout={logout}
        collapsed={collapsed}
        urlRouteTo={urlRoutePageName}
        orgIndex={organizationIndex}
        navigateToAccountSetting={navigateToAccountSetting}
        planhatPortalLink={dispatchPortalLink}
        planHatPortalAccessData={planHatPortalAccessData}
      />
    </BottomMenuWrapper>
  );
};

export default BottomMenu;
