import { findIndex } from 'lodash';
import accessManagementApi from 'services/accessManagementApi';
import {
  ACCESS_CHECK_PLAN_STATUS,
  ACCESS_APP_LIST,
  ACCESS_USER_LIST,
} from 'types';

export const accessManagement = (data, type) => ({
  type,
  data,
});
export const checkPlanStatus = (orgId) => async (dispatch, getState) => {
  let isOwner = false;
  const orgList = [...getState().applicationReducer];
  const indexOfOrgObj = findIndex(orgList, { orgId });
  if (indexOfOrgObj > -1) isOwner = orgList[indexOfOrgObj].isOwner;
  return (
    isOwner &&
    accessManagementApi
      .checkPlanStatus(orgId)
      .then((res) => {
        dispatch(accessManagement(res.data, ACCESS_CHECK_PLAN_STATUS));
        return res.data;
      })
      .catch(
        (error) =>
          error?.response &&
          dispatch(
            accessManagement(error.response.data, ACCESS_CHECK_PLAN_STATUS)
          )
      )
  );
};
export const getApps = (orgId) => async (dispatch) =>
  accessManagementApi
    .getApps(orgId)
    .then((res) => {
      dispatch(accessManagement(res.data, ACCESS_APP_LIST));
      return res.data;
    })
    .catch((error) => error.response);
export const getUsers = (orgId) => async (dispatch) =>
  accessManagementApi
    .getUsers(orgId)
    .then((res) => {
      dispatch(accessManagement(res.data, ACCESS_USER_LIST));
      return res.data;
    })
    .catch((error) => error.response);
export const manageAppAccess = (orgId) => async () =>
  accessManagementApi
    .manageAppAccess(orgId)
    .then((res) => res)
    .catch((error) => error);
export const manageUserAccess = (orgId) => async () =>
  accessManagementApi
    .manageUserAccess(orgId)
    .then((res) => res)
    .catch((error) => error.response);
