import React, { useCallback } from 'react'
import styled from 'styled-components'
import PromptLibrary from '../PromptLibrary'

const Wrapper = styled.div`
	display: flex;
	flex-direction: column;
	height: 100%;
	width: 100%;
	background-color: #fff;
	justify-content: center;
	align-items: center;
	padding: 0;
`

interface IProps {
	setInput: React.Dispatch<React.SetStateAction<string>>
	onPromptSelect?: (promptText: string, placeholderPosition?: number, secondaryPlaceholder?: string) => void
}

const EmptyChatScreen = ({ setInput, onPromptSelect }: IProps) => {
	const handlePromptSelect = useCallback((promptText: string, placeholderPosition?: number, secondaryPlaceholder?: string) => {
		if (onPromptSelect) {
			onPromptSelect(promptText, placeholderPosition, secondaryPlaceholder)
		} else {
			setInput(promptText)
		}
	}, [setInput, onPromptSelect])
	return (
		<Wrapper>
			<PromptLibrary onPromptSelect={handlePromptSelect} />
		</Wrapper>
	)
}

export default EmptyChatScreen
