/**
 * Feedback API Service
 *
 * This service handles AI response feedback submission.
 */

import taraApiFactory, { TARA_API_VERSION } from 'components/common/AIAssistant/utils';
import { axiosInstance } from './globalInstance';

export type FeedbackType = 'positive' | 'negative' | null;

export interface FeedbackReason {
  id: string;
  label: string;
}

export interface FeedbackPayload {
  feedback_type: 'positive' | 'negative' | null;
  why_bad_response: string | null;
  improvement_suggestion: string | null;
  app_id: string;
  session_id: string;
  invocation_id: string;
}

export interface FeedbackResponseData {
  id: string;
  feedback_type: 'positive' | 'negative';
  why_bad_response: string | null;
  improvement_suggestion: string | null;
  uxcamuserid: string;
  user_email: string;
  app_id: string;
  session_id: string;
  tara_version: string;
  invocation_id: string;
  user_type: string;
  created_at: string;
  updated_at: string;
}

export interface FeedbackResponse {
  success: boolean;
  message: string;
  feedback: FeedbackResponseData;
}

// Predefined reasons for negative feedback
export const NEGATIVE_FEEDBACK_REASONS: FeedbackReason[] = [
  { id: 'incorrect_examples', label: 'Incorrect examples provided' },
  { id: 'didnt_answer', label: 'Didn’t answer my question' },
  { id: 'inaccurate', label: 'Inaccurate information/response' },
  { id: 'technical_error', label: 'Technical error or processing issue' },
  { id: 'vague_generic', label: 'Too vague or generic' },
  { id: 'too_slow', label: 'Response took too long' },
  { id: 'exposed_sensitive_data', label: 'Exposed sensitive data' },
  { id: 'other', label: 'Other' },
];

/**
 * Submit feedback for an AI response
 */
export const submitFeedback = async (
  payload: FeedbackPayload,
  environment: TARA_API_VERSION = TARA_API_VERSION.PROD
): Promise<FeedbackResponse> => {
  const baseURL = taraApiFactory.getBaseURL(environment);

  const response = await axiosInstance.post<FeedbackResponse>(
    `${baseURL}/feedback`,
    payload,
    {
      withCredentials: true,
    }
  );

  return response.data;
};
