interface IMessageDocument {
	url: string
	title: string
}

export interface IMessage {
	id: string
	role: 'user' | 'assistant' | 'tara' | 'user_stopped' | 'shared_chat_end'
	content: string
	timestamp?: string
	debug_id?: string
	cost?: number
	answer_cost?: number
	query_expansion_cost?: number
	document_map?: IMessageDocument[]
	invocation_id?: string
	meta?: string
	isError?: boolean
	isStoppedByUser?: boolean
	readable_filters?: string[]
	sessions_analyzed_by_ai?: number
	token_usage?: {
		prompt: number
		completion: number
		total: number
		cached: number
	}
	model_used?: string
	model_requested?: string
	tool?: {
		name: string
		data: unknown
	}
	feedback_type?: 'positive' | 'negative' | null
}

export interface IBatch {
	id: string
	name: string
}

export interface IChat {
	session_id: string
	app_id: string
	persona: string
	created_at: string
	updated_at: string
	title: string | null
	is_pinned: boolean
	search_snippet: string | null
}

export interface IChatListResponse {
	sessions: IChat[]
	total_count: number
}

