const AIAssistantContent = () => {
	const { toggleExpansion, isExpanded } = useAISidebarContext();
	const { toggleSidebar, chats } = useChatManagement()
	const { aiSessionFeatureAllowed: isTaraEnabled } = useRestrictionContext() as unknown as { aiSessionFeatureAllowed: boolean }
	const { currentOrgReducer, currentAppReducer: { _id: appID } } = useSelector( ( state: IReduxState ) => state )
	const isTaraProPackage = currentOrgReducer?.isTaraProPackage ?? false
	const dispatch = useDispatch()
	const [streamedMessage, setStreamedMessage] = React.useState<string>('')
	const [chatThreadId, setChatThreadId] = React.useState<string | undefined>(undefined)
	const [showShareModal, setShowShareModal] = React.useState(false)
	const [isChatLoading, setIsChatLoading] = React.useState(false)
	const isStreaming = isChatLoading

	const { isSharedClaim, dismissClaim } = useShareChatClaim()

	const activeChatTitle = React.useMemo(() => {
		if (!chatThreadId || !chats) return 'New Chat'
		const activeChat = chats.find(c => c.session_id === chatThreadId)
		return activeChat?.title || 'New Chat'
	}, [chatThreadId, chats])

	const handleToggleSidebar = () => {
		dispatch(
			trackPageViews(null, {
				eventName: 'wa_tara_view_menu',
				track_type: 'event',
			})
		)
		toggleSidebar()
	}

	const handleShareClick = () => {
		dispatch(
			trackPageViews(null, {
				eventName: 'wa_tara_share_chat',
				track_type: 'event',
				eventProperty: { source: 'chat' },
			})
		)
		setShowShareModal(true)
	}

	const handleToggleExpansion = () => {
		dispatch(
			trackPageViews(null, {
				eventName: isExpanded ? 'wa_ai_collapse_chat' : 'wa_ai_expand_chat',
				track_type: 'event',
			})
		)
		toggleExpansion()
	}

	return (
		<StylesProvider>
			<Wrapper>
				<ControlsContainer>
					<LogoWrapper>
						<Tooltip title="Expand Menu" align={{offset: [0, 4]}} placement='topLeft'>
							<HamburgerButton onClick={handleToggleSidebar} type="button" disabled={isStreaming} style={isStreaming ? { opacity: 0.4, pointerEvents: 'none' } : undefined}>
								<HamburgerIcon />
							</HamburgerButton>
						</Tooltip>
						<TaraLogo />
						{ isTaraProPackage ? <IconPro /> : <IconLite /> }
					</LogoWrapper>
					<ControlRight>
						{!isProd && <APIVersionToggle />}
						<Tooltip
							title={isExpanded ? "Collapse" : "Expand"}
							align={{offset: [0, 4]}}
						>
							<ControlButton
								onClick={handleToggleExpansion}
							>
								{isExpanded ?
									<CollapseIcon />
								: <ExpandIcon />}
							</ControlButton>
						</Tooltip>
						{chatThreadId && (
							<Tooltip placement='bottomLeft' title="Share chat" align={{offset: [0, 4]}}>
								<ControlButton onClick={handleShareClick} disabled={isStreaming} style={isStreaming ? { opacity: 0.4, pointerEvents: 'none' } : undefined}>
									<ShareIcon />
								</ControlButton>
							</Tooltip>
						)}
					</ControlRight>
				</ControlsContainer>
				{ isTaraEnabled && (
					<SessionWatchStatus />
				) }
				<Content>
					<ChatTab
						streamedMessage={ streamedMessage }
						setStreamedMessage={setStreamedMessage}
						chatThreadId={ chatThreadId }
						setChatThreadId={ setChatThreadId }
						isSharedClaim={isSharedClaim}
						onDismissClaim={dismissClaim}
						onLoadingChange={setIsChatLoading}
					/>
				</Content>
				<ChatSidebar />
				<ShareChatModal
					visible={showShareModal}
					onCancel={() => setShowShareModal(false)}
					chatTitle={activeChatTitle}
					sessionId={chatThreadId}
					appId={appID as string}
				/>
				</Wrapper>
		</StylesProvider>
	)
}

const AIAssistant = () => {
	return (
        <TaraAPIVersionProvider>
			<ChatManagementProvider>
				<FeedbackModalProvider>
					<AIAssistantContent />
					<NegativeFeedbackModal />
				</FeedbackModalProvider>
			</ChatManagementProvider>
        </TaraAPIVersionProvider>
	)
}

export default React.memo( AIAssistant )