import { axiosInstance } from 'services/globalInstance'
import { IEnvironmentPersonasResponse } from './types'
import taraApiFactory, { TARA_API_VERSION } from './utils'

export const fetchPersonasByEnvironment = async (version: TARA_API_VERSION): Promise<IEnvironmentPersonasResponse> => {
  const baseURL = taraApiFactory.getBaseURL(version)

  const response = await axiosInstance.get(`${baseURL}/personas`, {
    withCredentials: true,
  })
  return response.data
}
