import React, { useState, memo } from 'react'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import { useSelector } from 'react-redux'
import useAppFilter from 'components/shared/GlobalFilter/components/useAppFilter'
import { isEqual } from 'lodash'

import { useRouter } from 'next/router'

const HandleLockedFeatures = () => {
	const { advancedFiltersAllowed, notAllowedFiltersApplied, filterOptionsWithoutNotAllowedCategories, setFiltersLockedModal } = useRestrictionContext()
	const { callListApi, segmentType, pageType } = useAppFilter()
	const { appFilter } = useSelector( ( state ) => state )
	const [ lockedFiltersRemoved, setLockedFiltersRemoved ] = useState( false )
	const oldAppFilter = React.useRef( appFilter )
	const router = useRouter()

	React.useEffect( () => {
		if ( !isEqual( oldAppFilter.current, appFilter ) && lockedFiltersRemoved ) {
			setLockedFiltersRemoved( false )
			oldAppFilter.current = appFilter
		} 
	}, [ appFilter, lockedFiltersRemoved ] )

	if ( advancedFiltersAllowed || lockedFiltersRemoved || !appFilter || !pageType || !router ) return null
	
	if ( notAllowedFiltersApplied  ) {
		const currentSegment = appFilter[ segmentType ]
		const allowedOptions = Object.values( filterOptionsWithoutNotAllowedCategories ).flat().map( option => option.attribute)
		let newSegment = JSON.parse( JSON.stringify( currentSegment.segment ) )
		newSegment = newSegment.filter( el => allowedOptions.includes( el.attribute ) )

		const params = new URLSearchParams( router.asPath.split( '?' )[ 1 ] )
		const paramsArr = Array.from( params )

		paramsArr.forEach( ( elem ) => { 
			if ( elem[ 0 ] === "event_name" ) {
				if ( JSON.parse( elem[ 1 ] )[ "v" ].some( val => !allowedOptions.includes( val ) ) ) {
					params.delete( elem[ 0 ] )
				}
			} else if ( !allowedOptions.includes( elem[ 0 ] ) ) {
					params.delete( elem[ 0 ] )
				}
		} )

		const newURL = new URL( window.location )
		newURL.search = params.toString()

		router.replace( {
			query: {
				...router.query,
				url: newURL.pathname + newURL.search,
			},
		}, newURL.pathname + newURL.search )
		callListApi( newSegment )
		setLockedFiltersRemoved( true )
		setFiltersLockedModal( true )
	}

	return null
}

export default memo( HandleLockedFeatures )
