import React from 'react'
import { UFCModal } from 'uxcam-frontend-components'
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'
import styled from 'styled-components'
import { Footer, StyledButton, SubTitle, Title } from '../common'

const StyledTitle = styled( Title )`
	margin-bottom: 8px;
`

const SessionBatchError = () => {
	const { setErrorModalVisible, setBatchModalVisible, errorModalVisible } = useAISessionWatchlist()

	const handleClose = () => {
		setErrorModalVisible( false )
	}

	const handleRetry = () => {
		setErrorModalVisible( false )
		setBatchModalVisible( true )
	}

	const footer = (
		<Footer>
			<StyledButton
				type="button"
				variant="ghost"
				size="large"
				onClick={ handleClose }
			>
				Close
			</StyledButton>
			<StyledButton
				type="button"
				variant="primary"
				size="large"
				onClick={ handleRetry }
			>
				Try again
			</StyledButton>
		</Footer>
	)

	return (
		<UFCModal
			visible={ errorModalVisible }
			footer={ footer }
			closable={ false }
			className='duration-modal'
			style={{top: 0}}
		>
			<StyledTitle>
				Something went wrong
			</StyledTitle>
			<SubTitle>
				We couldn’t process your request. Please try again, and if the problem continues, contact support.
			</SubTitle>
		</UFCModal>
	)
}

export default SessionBatchError