export const addNocodeEventToSessionDetail = (
  sessionDetail: ISessionDetail,
  currentAction: IAction,
  nocode: ICreateNocodeLocal
) => {
  const isScreenAny = nocode?.rule?.activityName === '__any__';
  const isViewNameAny = nocode?.rule?.viewName === '__any__';
  const isElementIdAny = nocode?.rule?.idString === '__any__';

  let creationRule: boolean;
  const newData = sessionDetail.screenTimeline?.activities?.map((screen) => ({
    ...screen,
    actions: screen?.actions?.flatMap((action) => {
      creationRule =
        action.name === currentAction.name &&
        (isElementIdAny
          ? true
          : action?.properties?.idString === currentAction?.props?.idString) &&
        (isViewNameAny
          ? true
          : action?.properties?.viewName === currentAction?.props?.viewName) &&
        (isScreenAny
          ? true
          : currentAction.screenName === screen?.activityName);
      if (creationRule) {
        const newAction = {
          ...action,
          type: 'smart_gesture_event',
          id: nocode?.nceId.toString(),
          name: nocode?.name,
          description: nocode?.description,
          params: {
            ...action.properties,
            gestureType: action?.name,
            rule: nocode?.rule,
            viewName: action?.properties?.viewName || null,
            viewType: action?.properties?.viewType || 'Unknown view type',
            idString: action?.properties?.idString || null,
          },
        };
        delete newAction?.params?.viewClass;
        delete newAction?.properties;
        delete newAction?.isRage;
        delete newAction?.isResponsiveGesture;

        return [action, newAction];
      }
      return action;
    }),
  }));

  return {
    ...sessionDetail,
    screenTimeline: {
      ...sessionDetail.screenTimeline,
      activities: newData as unknown as IActivity[],
    },
  };
};

export const editNocodeEventToSessionDetail = (
  sessionDetail: ISessionDetail,
  nocode: ICreateNocodeLocal
) => {
  const newData = sessionDetail.screenTimeline?.activities?.map((screen) => ({
    ...screen,
    actions: screen?.actions?.map((action) => {
      if ((action?.id as unknown as number) === nocode?.nceId) {
        return {
          ...action,
          name: nocode?.name,
          description: nocode?.description,
        };
      }
      return action;
    }),
  }));

  return {
    ...sessionDetail,
    screenTimeline: {
      ...sessionDetail.screenTimeline,
      activities: newData as unknown as IActivity[],
    },
  };
};

