export const renderAnyOrUndefined = (value: string | undefined) => {
  if (value !== 'undefined' && value === '__any__') {
    return <i>Includes all</i>;
  }

  if (value === undefined || value === null) {
    return <i>Undefined</i>;
  }

  const showTooltip = value?.length > 42;

  return (
    <Tooltip overlay={showTooltip && value} placement="top">
      <TableData>{value}</TableData>
    </Tooltip>
  );
};

export const checkForAnyValue = (
  object: 'viewName' | 'activityName' | 'idString',
  value: string,
  smartRule?: IRule
) => {
  if (value === '__any__') {
    return {
      jsx: <i>Includes all</i>,
      value: '__any__',
    };
  }

  if (value === 'undefined') {
    return {
      jsx: <i>Undefined</i>,
      value: 'undefined',
    };
  }

  if (smartRule && Object.keys(smartRule) && smartRule[object] === '__any__') {
    return {
      jsx: <i>Includes all</i>,
      value: '__any__',
    };
  }

  return {
    jsx: value,
    value,
  };
};

