export const addScreenEventToSessionDetail = (
  sessionDetail: ISessionDetail,
  currentScreen: ISessionScreen,
  smartEvent: ICreateSmartEventLocal
) => {
  const newData = sessionDetail.screenTimeline?.activities?.map((screen) => {
    if (screen?.activityName === currentScreen?.activityName) {
      const updatedActions = [
        {
          ...smartEvent,
          type: 'smart_screenvisit_event',
          id: smartEvent?.id.toString(),
          name: smartEvent?.name,
          description: smartEvent?.description,
          time: screen?.time,
          params: {
            ...smartEvent?.params,
            screenName: smartEvent?.params?.screenName,
          },
        },
        ...(screen?.actions || []),
      ];
      // Return the updated screen object
      return {
        ...screen,
        actions: updatedActions,
      };
    }
    return screen;
  });
  return {
    ...sessionDetail,
    screenTimeline: {
      ...sessionDetail.screenTimeline,
      activities: newData as unknown as IActivity[],
    },
  };
};

