import { useEffect, useRef, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { useQueryClient } from 'react-query';
import HeatmapApi from 'components/features/heatmaps/apis';
import { screenListCache } from 'Utils/helpers/screenListCache';
import { formattedFilters } from 'Utils/ScreenPageFilter';
import { screenColumnAttributes } from 'components/features/heatmaps/constants';
import { useIsAppType } from './useIsAppType';

export const useScreenListPrefetch = () => {
  const queryClient = useQueryClient();
  const isWebApp = useIsAppType('web');
  const {
    urlReducer: { appId, parentType },
    appFilter: {
      dateSegment,
      heatmap: { segment = [] },
    },
    currentApp,
  } = useSelector(({ urlReducer, appFilter, currentAppReducer }) => ({
    urlReducer,
    appFilter,
    currentApp: currentAppReducer,
  }));

  // Use screenListCache.generateKey to ensure cache key matches exactly
  const cacheKey = useMemo(() => {
    if (!appId || !dateSegment) return null;

    let orderBy = [{
      sortName: screenColumnAttributes.visitCount || 'count',
      sortOrder: 'desc',
    }];

    try {
      const storedSort = localStorage.getItem('screenSortBy');
      if (storedSort && storedSort !== 'undefined') {
        const parsedSort = JSON.parse(storedSort);
        if (parsedSort && parsedSort.length > 0) {
          orderBy = [{
            sortName: screenColumnAttributes[parsedSort[0].id] || parsedSort[0].id,
            sortOrder: parsedSort[0].desc ? 'desc' : 'asc',
          }];
        }
      }
    } catch (e) {
      // ignore
    }

    const reqBody = {
      appid: appId,
      date_range: dateSegment,
      filters: formattedFilters(segment) || [],
      orderBy,
    };

    // Use the same key generation logic as the cache
    return screenListCache.generateKey(reqBody);
  }, [appId, dateSegment, segment]);

  const lastPrefetchedKey = useRef(null);
  const lastAppId = useRef(null);
  const hasPrefetchedOnce = useRef(false);

  useEffect(() => {
    if (!appId || !cacheKey || !dateSegment || isWebApp || !currentApp?.appType) return;

    // Reset when appId changes
    if (lastAppId.current !== appId) {
      lastPrefetchedKey.current = null;
      hasPrefetchedOnce.current = false;
      lastAppId.current = appId;
    }

    let orderBy = [{
      sortName: screenColumnAttributes.visitCount || 'count',
      sortOrder: 'desc',
    }];

    try {
      const storedSort = localStorage.getItem('screenSortBy');
      if (storedSort && storedSort !== 'undefined') {
        const parsedSort = JSON.parse(storedSort);
        if (parsedSort && parsedSort.length > 0) {
          orderBy = [{
            sortName: screenColumnAttributes[parsedSort[0].id] || parsedSort[0].id,
            sortOrder: parsedSort[0].desc ? 'desc' : 'asc',
          }];
        }
      }
    } catch (e) {
      // ignore
    }

    const reqBody = {
      appid: appId,
      date_range: dateSegment,
      filters: formattedFilters(segment) || [],
      orderBy,
    };

    // Check if we already have valid cached data
    const cached = screenListCache.get(reqBody);

    // If we have valid cache and already prefetched this combination, skip
    if (cached && lastPrefetchedKey.current === cacheKey) return;

    // After initial prefetch, only run again if:
    // 1. We're on the heatmaps page, OR
    // 2. Cache has expired (cached is null)
    if (hasPrefetchedOnce.current && parentType !== 'heatmapsList' && cached) return;

    // If cache is still valid, mark as prefetched and skip API call
    if (cached) {
      lastPrefetchedKey.current = cacheKey;
      hasPrefetchedOnce.current = true;
      return;
    }

    const prefetchScreenList = async () => {
      try {
        await screenListCache.getOrFetch(reqBody, async () => {
          const startTime = Date.now();
          const data = await HeatmapApi.getScreenList(reqBody);
          const duration = Date.now() - startTime;
          queryClient.setQueryData(['screen-table-list', reqBody], data);
          return { data, duration };
        });
        lastPrefetchedKey.current = cacheKey;
        hasPrefetchedOnce.current = true;
      } catch (error) {
        // silent fail
      }
    };

    const timeoutId = setTimeout(prefetchScreenList, 1000);

    // eslint-disable-next-line consistent-return
    return () => clearTimeout(timeoutId);
  }, [currentApp, isWebApp, appId, cacheKey, parentType, queryClient, dateSegment, segment]);
};
