import { useState, useEffect, useCallback, useRef } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { IReduxState } from 'types/reduxStateTypes'
import { changedUrl } from 'redux/actions/common'
import { useChatManagement } from '../../Contexts/ChatManagementContext'
import { useTaraAPIVersion } from '../../Contexts/APIVersionContext'
import { TARA_API_VERSION } from '../utils'

interface UseShareChatClaimReturn {
	isSharedClaim: boolean
	dismissClaim: () => void
}

const useShareChatClaim = (): UseShareChatClaimReturn => {
	const [isSharedClaim, setIsSharedClaim] = useState(false)
	const processedRef = useRef(false)
	const dispatch = useDispatch()

	const { selectChat, deferSelectChat } = useChatManagement()
	const { currentPersona, currentVersion, setEnvironment, fetchPersonasForEnvironment } = useTaraAPIVersion()

	const { urlReducer } = useSelector((state: IReduxState) => state)

	const sharedSessionId = urlReducer?.sharedSessionId
	const envParam = urlReducer?.env

	const dismissClaim = useCallback(() => {
		setIsSharedClaim(false)
	}, [])

	useEffect(() => {
		if (processedRef.current) return
		if (!sharedSessionId) return
		processedRef.current = true

		const ENV_PARAM_TO_VERSION: Record<string, { version: TARA_API_VERSION; environmentId: string }> = {
			uat: { version: TARA_API_VERSION.UAT, environmentId: 'uat' },
			stg: { version: TARA_API_VERSION.STAGING, environmentId: 'staging' },
			experience: { version: TARA_API_VERSION.EXPERIENCE, environmentId: 'experience' },
			cx: { version: TARA_API_VERSION.CX, environmentId: 'cx' },
			bizops: { version: TARA_API_VERSION.BIZOPS, environmentId: 'bizops' },
			research: { version: TARA_API_VERSION.RESEARCH, environmentId: 'research' },
		}
		const target = envParam ? ENV_PARAM_TO_VERSION[envParam] : null
		const targetVersion = target?.version ?? TARA_API_VERSION.PROD
		const targetEnvironmentId = target?.environmentId ?? 'production'

		// Strip share params from URL and Redux
		const url = new URL(window.location.href)
		url.searchParams.delete('sharedSessionId')
		url.searchParams.delete('env')
		window.history.replaceState({}, '', url.toString())

		const { sharedSessionId: _s, env: _e, ...cleanedUrlReducer } = urlReducer || {}
		dispatch(changedUrl(cleanedUrlReducer))

		setIsSharedClaim(true)

		if (currentVersion === targetVersion) {
			selectChat(sharedSessionId, currentPersona)
		} else {
			deferSelectChat(sharedSessionId, currentPersona)
			fetchPersonasForEnvironment(targetEnvironmentId)
			setEnvironment(targetEnvironmentId)
		}
	}, [sharedSessionId, envParam, currentPersona, currentVersion, selectChat, deferSelectChat, setEnvironment, fetchPersonasForEnvironment])

	return { isSharedClaim, dismissClaim }
}

export default useShareChatClaim
