import React, { createContext, useContext, useMemo, useState, useEffect, useCallback } from 'react'
import { useQuery, useQueryClient } from 'react-query'
import { TARA_API_VERSION } from '../AIAssistant/utils'
import { fetchPersonasByEnvironment } from '../AIAssistant/personasApi'
import { IEnvironment, IEnvironmentPersonasResponse, IPersona } from '../AIAssistant/types'
import { rollbar } from '../rollbar'

export const DEFAULT_PERSONA_VALUE = 'tara_flat'
export const DEFAULT_PERSONA_LABEL = 'Flat'

const DEFAULT_PERSONAS: IPersona[] = [
	{ value: DEFAULT_PERSONA_VALUE, label: DEFAULT_PERSONA_LABEL }
]

const BASE_ENVIRONMENTS: Omit<IEnvironment, 'personas' | 'default_persona'>[] = [
	{ id: 'production', label: 'PROD' },
	{ id: 'uat', label: 'UAT' },
	{ id: 'staging', label: 'STG' },
	{ id: 'experience', label: 'Experience' },
	{ id: 'cx', label: 'CX' },
	{ id: 'bizops', label: 'BizOps' },
	{ id: 'research', label: 'Research' },
]

const ENV_ID_TO_VERSION: Record<string, TARA_API_VERSION> = {
	production: TARA_API_VERSION.PROD,
	uat: TARA_API_VERSION.UAT,
	staging: TARA_API_VERSION.STAGING,
	experience: TARA_API_VERSION.EXPERIENCE,
	cx: TARA_API_VERSION.CX,
	bizops: TARA_API_VERSION.BIZOPS,
	research: TARA_API_VERSION.RESEARCH,
}

interface IAPIVersionContext {
	currentVersion: TARA_API_VERSION
	currentEnvironment: IEnvironment | null
	currentPersona: string
	environments: IEnvironment[]
	isLoading: boolean
	isReady: boolean
	setEnvironment: (environmentId: string, persona?: string) => void
	setPersona: (personaValue: string) => void
	fetchPersonasForEnvironment: (environmentId: string) => void
	isLoadingEnvironment: (environmentId: string) => boolean
}

const TaraAPIVersionContext = createContext<IAPIVersionContext>({
	currentVersion: TARA_API_VERSION.PROD,
	currentEnvironment: null,
	currentPersona: DEFAULT_PERSONA_VALUE,
	environments: [],
	isLoading: false,
	isReady: true,
	// eslint-disable-next-line @typescript-eslint/no-empty-function
	setEnvironment: () => {},
	// eslint-disable-next-line @typescript-eslint/no-empty-function
	setPersona: () => {},
	// eslint-disable-next-line @typescript-eslint/no-empty-function
	fetchPersonasForEnvironment: () => {},
	isLoadingEnvironment: () => false,
})

interface IProps {
	children: React.ReactNode
}

export const TaraAPIVersionProvider: React.FC<IProps> = ({ children }) => {
	const queryClient = useQueryClient()
	const cachedProdPersonas = queryClient.getQueryData<IEnvironmentPersonasResponse>(['tara-personas', 'production'])
	const [environmentPersonas, setEnvironmentPersonas] = useState<Record<string, { personas: IPersona[], default_persona: string }>>(() => {
		if (cachedProdPersonas?.personas?.length) {
			return { production: { personas: cachedProdPersonas.personas, default_persona: cachedProdPersonas.default_persona } }
		}
		return {} as Record<string, { personas: IPersona[], default_persona: string }>
	})
	const [currentEnvironmentId, setCurrentEnvironmentId] = useState<string>('production')
	const [currentPersona, setCurrentPersonaState] = useState<string | null>(() => {
		if (cachedProdPersonas?.personas?.length) {
			return cachedProdPersonas.default_persona || cachedProdPersonas.personas[0]?.value || DEFAULT_PERSONA_VALUE
		}
		return null
	})
	const [fetchingEnvironments, setFetchingEnvironments] = useState<Set<string>>(new Set())

	const { isLoading: isProdLoading } = useQuery(
		['tara-personas', 'production'],
		() => fetchPersonasByEnvironment(TARA_API_VERSION.PROD),
		{
			onSuccess: (data) => {
				if (data?.personas?.length) {
					setEnvironmentPersonas(prev => ({
						...prev,
						production: {
							personas: data.personas,
							default_persona: data.default_persona
						}
					}))
					if (currentPersona === null) {
						setCurrentPersonaState(data.default_persona || data.personas[0]?.value || DEFAULT_PERSONA_VALUE)
					}
				} else {
					setEnvironmentPersonas(prev => ({
						...prev,
						production: { personas: DEFAULT_PERSONAS, default_persona: DEFAULT_PERSONA_VALUE }
					}))
					if (currentPersona === null) {
						setCurrentPersonaState(DEFAULT_PERSONA_VALUE)
					}
				}
			},
			onError: (error) => {
				rollbar.error('AI personas failed to fetch', error as Error, { environment: 'production' })
				setEnvironmentPersonas(prev => ({
					...prev,
					production: { personas: DEFAULT_PERSONAS, default_persona: DEFAULT_PERSONA_VALUE }
				}))
				if (currentPersona === null) {
					setCurrentPersonaState(DEFAULT_PERSONA_VALUE)
				}
			},
			refetchOnWindowFocus: false,
			retry: 1,
			staleTime: 1000 * 60 * 30,
		}
	)

	const fetchPersonasForEnvironment = useCallback((environmentId: string) => {
		if (environmentPersonas[environmentId] || fetchingEnvironments.has(environmentId)) {
			return
		}

		const version = ENV_ID_TO_VERSION[environmentId]
		if (!version) return

		setFetchingEnvironments(prev => new Set(prev).add(environmentId))

		queryClient.fetchQuery(
			['tara-personas', environmentId],
			() => fetchPersonasByEnvironment(version),
			{
				staleTime: 1000 * 60 * 30,
				retry: 1,
			}
		).then((data) => {
			if (data?.personas?.length) {
				setEnvironmentPersonas(prev => ({
					...prev,
					[environmentId]: {
						personas: data.personas,
						default_persona: data.default_persona
					}
				}))
			} else {
				setEnvironmentPersonas(prev => ({
					...prev,
					[environmentId]: { personas: DEFAULT_PERSONAS, default_persona: DEFAULT_PERSONA_VALUE }
				}))
			}
		}).catch((error) => {
			rollbar.error('AI personas failed to fetch', error as Error, { environment: environmentId })
			setEnvironmentPersonas(prev => ({
				...prev,
				[environmentId]: { personas: DEFAULT_PERSONAS, default_persona: DEFAULT_PERSONA_VALUE }
			}))
		}).finally(() => {
			setFetchingEnvironments(prev => {
				const next = new Set(prev)
				next.delete(environmentId)
				return next
			})
		})
	}, [environmentPersonas, fetchingEnvironments, queryClient])

	const isLoadingEnvironment = useCallback((environmentId: string) => {
		return fetchingEnvironments.has(environmentId)
	}, [fetchingEnvironments])

	const environments: IEnvironment[] = useMemo(() => {
		return BASE_ENVIRONMENTS.map(env => ({
			...env,
			personas: environmentPersonas[env.id]?.personas || [],
			default_persona: environmentPersonas[env.id]?.default_persona || DEFAULT_PERSONA_VALUE
		}))
	}, [environmentPersonas])

	const isReady = !isProdLoading

	const currentEnvironment = useMemo(() => {
		return environments.find((env) => env.id === currentEnvironmentId) || environments[0]
	}, [environments, currentEnvironmentId])

	const currentVersion = useMemo(() => {
		return ENV_ID_TO_VERSION[currentEnvironmentId] || TARA_API_VERSION.PROD
	}, [currentEnvironmentId])

	useEffect(() => {
		if (currentEnvironment && currentPersona !== null && currentEnvironment.personas.length > 0) {
			const availablePersonas = currentEnvironment.personas.map((p) => p.value)
			if (!availablePersonas.includes(currentPersona)) {
				const fallbackPersona = currentEnvironment.default_persona || currentEnvironment.personas[0]?.value || DEFAULT_PERSONA_VALUE
				setCurrentPersonaState(fallbackPersona)
			}
		}
	}, [currentEnvironment, currentPersona])

	const setEnvironment = useCallback((environmentId: string, persona?: string) => {
		const envData = environmentPersonas[environmentId]
		let newPersona: string
		if (persona) {
			newPersona = persona
		} else if (currentPersona && envData?.personas?.some(p => p.value === currentPersona)) {
			newPersona = currentPersona
		} else {
			newPersona = envData?.default_persona || envData?.personas?.[0]?.value || DEFAULT_PERSONA_VALUE
		}

		setCurrentEnvironmentId(environmentId)
		setCurrentPersonaState(newPersona)
	}, [environmentPersonas, currentPersona])

	const setPersona = useCallback((personaValue: string) => {
		setCurrentPersonaState(personaValue)
	}, [])

	const value: IAPIVersionContext = useMemo(() => ({
		currentVersion,
		currentEnvironment,
		currentPersona: currentPersona || DEFAULT_PERSONA_VALUE,
		environments,
		isLoading: isProdLoading,
		isReady,
		setEnvironment,
		setPersona,
		fetchPersonasForEnvironment,
		isLoadingEnvironment,
	}), [currentVersion, currentEnvironment, currentPersona, environments, isProdLoading, isReady, setEnvironment, setPersona, fetchPersonasForEnvironment, isLoadingEnvironment])

	return (
		<TaraAPIVersionContext.Provider value={value}>
			{children}
		</TaraAPIVersionContext.Provider>
	)
}

export const useTaraAPIVersion = () => useContext(TaraAPIVersionContext)
