import { AxiosResponse } from 'axios';
import { axiosInstance } from 'services/globalInstance';

import {
  ICreateNocodePayload,
  ICreateNocodeResponse,
  IGetNocodeEventManageListPayload,
  IGetNocodeEventManageListResponse,
  IDeleteNocodeEventPayload,
  IDeleteNocodeEventResponse,
  IEditNocodeEventPayload,
  IEditNocodeEventResponse,
} from 'types/nocodeEvents';
import {
  ICreateSmartEventPayload,
  IEditScreenEventPayload,
  IEditScreenEventResponse,
  ICreateSmartEventResponse,
} from 'types/screenEvents';

export const createNocodeEvent = async (
  payload: ICreateNocodePayload
): Promise<AxiosResponse<ICreateNocodeResponse>> =>
  axiosInstance.post(`${process.env.PYTHON_API_URL}/no_code_event/create`, payload, {
    withCredentials: true,
  });

export const getNocodeEventManageList = async (
  payload: IGetNocodeEventManageListPayload
): Promise<AxiosResponse<IGetNocodeEventManageListResponse>> =>
  axiosInstance.post(
    `${process.env.PYTHON_API_URL}/no_code_event/management`,
    payload,
    {
      withCredentials: true,
    }
  );

export const deleteNocodeEvent = async ({
  appId,
  nceId,
}: IDeleteNocodeEventPayload): Promise<
  AxiosResponse<IDeleteNocodeEventResponse>
> =>
  axiosInstance.delete(
    `${process.env.PYTHON_API_URL}/no_code_event/delete/${appId}/${nceId}`,
    {
      withCredentials: true,
    }
  );

export const editNocodeEvent = async (
  payload: IEditNocodeEventPayload
): Promise<AxiosResponse<IEditNocodeEventResponse>> =>
  axiosInstance.post(`${process.env.PYTHON_API_URL}/no_code_event/update`, payload, {
    withCredentials: true,
  });

