import { useQuery } from 'react-query';
import DebugApi, { DebugCostResponse } from 'services/debugApi';
import { useTaraAPIVersion } from 'components/common/Contexts/APIVersionContext';

interface UseCostDetailsParams {
  invocationId?: string;
  appId?: string;
  enabled: boolean;
}

export const useCostDetails = ({ invocationId, appId, enabled }: UseCostDetailsParams) => {
  const { currentVersion } = useTaraAPIVersion();

  return useQuery<DebugCostResponse>(
    ['debugCost', invocationId, appId, currentVersion],
    () => DebugApi.getCostDetails(invocationId!, appId!, currentVersion),
    {
      enabled: enabled && !!invocationId && !!appId,
      staleTime: Infinity, // Cache indefinitely since cost data doesn't change
      cacheTime: Infinity, // Keep in cache indefinitely
      retry: false,
    }
  );
};
