import React, { createContext, useContext, useState, useCallback, useMemo, useRef } from 'react'
import { useQueryClient, useQuery } from 'react-query'
import { useSelector, useDispatch } from 'react-redux'
import { trackPageViews } from 'redux/actions/trackingReport'
import { IReduxState } from 'types/reduxStateTypes'
import { useTaraAPIVersion } from './APIVersionContext'
import { useAISidebarContext } from './AISidebarContext'
import { IChat } from '../AIAssistant'
import taraApiFactory from '../AIAssistant/utils'
import {
	getChats,
	peekChat,
	renameChat as renameChatAPI,
} from '../AIAssistant/queries'

interface IChatManagementContext {
	activeChatId: string | null
	setActiveChatId: (chatId: string | null) => void
	activeChatPersona: string | null
	setActiveChatPersona: (persona: string | null) => void
	isSidebarOpen: boolean
	toggleSidebar: () => void
	closeSidebar: () => void
	chats: IChat[]
	totalChats: number
	isLoadingChats: boolean
	createNewChat: (source?: string) => void
	renameChat: (chatId: string, newName: string, persona?: string) => Promise<boolean>
	selectChat: (chatId: string, persona: string) => void
	deferSelectChat: (chatId: string, persona: string) => void
	isPendingNewChat: boolean
	finalizePendingChat: () => void
	refetchChats: () => void
	isLoadingPeek: boolean
	hasReachedChatLimit: boolean
	showChatLimitModal: boolean
	setShowChatLimitModal: (show: boolean) => void
}

const ChatManagementContext = createContext<IChatManagementContext | null>(null)

export const useChatManagement = () => {
	const context = useContext(ChatManagementContext)
	if (!context) {
		throw new Error('useChatManagement must be used within a ChatManagementProvider')
	}
	return context
}

export const MAX_CHATS = 150

export const ChatManagementProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
	const [activeChatId, setActiveChatId] = useState<string | null>(null)
	const [activeChatPersona, setActiveChatPersona] = useState<string | null>(null)
	const [isSidebarOpen, setIsSidebarOpen] = useState(false)
	const [isPendingNewChat, setIsPendingNewChat] = useState(false)
	const deferredSelectionRef = useRef<{ chatId: string; persona: string } | null>(null)
	const skipNextResetRef = useRef(false)
	const [showChatLimitModal, setShowChatLimitModal] = useState(false)

	const queryClient = useQueryClient()
	const { currentVersion, currentPersona } = useTaraAPIVersion()
	const { debugMode } = useAISidebarContext()
	const {
		currentAppReducer: { _id: appID },
	} = useSelector((state: IReduxState) => state)
	const dispatch = useDispatch()

	const chatListQueryKey = taraApiFactory.getQueryKey(currentVersion, 'chat_list', false, appID)

	const { data: chatListData, isLoading: isLoadingChats, refetch: refetchChatList } = useQuery({
		queryKey: chatListQueryKey,
		queryFn: () => getChats(appID as string, currentVersion),
		enabled: !!appID,
	})

	const chats = chatListData?.sessions ?? []
	const totalChats = chatListData?.total_count ?? 0

	// Peek: fetch the latest chat the user interacted with (multi-chat only)
	const peekQueryKey = taraApiFactory.getQueryKey(currentVersion, 'chat_peek', debugMode, appID)
	const { data: peekData, isLoading: isLoadingPeek } = useQuery({
		queryKey: peekQueryKey,
		queryFn: () => peekChat(appID as string, currentVersion),
		enabled: !!appID && !activeChatId && !isPendingNewChat,
		staleTime: 1000 * 60 * 5,
	})

	const refetchChats = useCallback(() => {
		refetchChatList()
		queryClient.removeQueries(peekQueryKey)
	}, [refetchChatList, queryClient, peekQueryKey])

	// Auto-select: peek data > first chat from list
	React.useEffect(() => {
		if (!activeChatId && !isPendingNewChat) {
			if (peekData?.session_id) {
				setActiveChatId(peekData.session_id)
				setActiveChatPersona(peekData.persona || currentPersona)
				// Pre-seed chat thread cache to avoid a redundant fetch
				const threadQueryKey = [
					...taraApiFactory.getQueryKey(currentVersion, 'chat_thread', debugMode, appID, peekData.persona || currentPersona),
					peekData.session_id,
				]
				queryClient.setQueryData(threadQueryKey, peekData)
			} else if (!isLoadingPeek && chats.length > 0) {
				setActiveChatId(chats[0].session_id)
				setActiveChatPersona(chats[0].persona)
			}
		}
	}, [activeChatId, isPendingNewChat, peekData, isLoadingPeek, chats, currentPersona, currentVersion, debugMode, appID, queryClient])

	const toggleSidebar = useCallback(() => {
		setIsSidebarOpen(prev => !prev)
	}, [])

	const closeSidebar = useCallback(() => {
		setIsSidebarOpen(false)
	}, [])

	const hasReachedChatLimit = totalChats >= MAX_CHATS

	const createNewChat = useCallback((source?: string) => {
		if (source) {
			dispatch(trackPageViews(null, { eventName: 'wa_tara_new_chat', track_type: 'event', eventProperty: { source } }))
		}
		setIsPendingNewChat(true)
		setActiveChatId(null)
		setActiveChatPersona(null)

		queryClient.setQueryData(
			taraApiFactory.getQueryKey(currentVersion, 'chat_thread', debugMode, appID, currentPersona),
			{ messages: [], session_id: undefined }
		)
	}, [queryClient, currentVersion, debugMode, appID, currentPersona, dispatch])

	const selectChat = useCallback((chatId: string, persona: string) => {
		setIsPendingNewChat(false)
		setActiveChatId(chatId)
		setActiveChatPersona(persona)
		closeSidebar()
	}, [closeSidebar])

	const deferSelectChat = useCallback((chatId: string, persona: string) => {
		deferredSelectionRef.current = { chatId, persona }
	}, [])

	const finalizePendingChat = useCallback(() => {
		queryClient.invalidateQueries(chatListQueryKey)
		queryClient.removeQueries(peekQueryKey)
	}, [queryClient, chatListQueryKey, peekQueryKey])

	// Clear pending flag once the new chat has an active ID (set by stream 'end' handler)
	React.useEffect(() => {
		if (activeChatId && isPendingNewChat) {
			setIsPendingNewChat(false)
		}
	}, [activeChatId, isPendingNewChat])

	const handleRenameChat = useCallback(async (chatId: string, newName: string, persona?: string): Promise<boolean> => {
		if (!appID) return false

		try {
			await renameChatAPI(chatId, appID, newName, currentVersion, persona || currentPersona)
			await queryClient.invalidateQueries(chatListQueryKey)
			return true
		} catch {
			return false
		}
	}, [appID, currentVersion, currentPersona, queryClient, chatListQueryKey])

	// Reset state when app or version changes (skip initial mount)
	const isInitialMount = React.useRef(true)
	React.useEffect(() => {
		const deferred = deferredSelectionRef.current
		deferredSelectionRef.current = null

		if (deferred) {
			skipNextResetRef.current = true
			setActiveChatId(deferred.chatId)
			setActiveChatPersona(deferred.persona)
			setIsPendingNewChat(false)
			setIsSidebarOpen(false)
		} else if (skipNextResetRef.current) {
			skipNextResetRef.current = false
		} else {
			if (isInitialMount.current) {
				isInitialMount.current = false
				return
			}
			setActiveChatId(null)
			setActiveChatPersona(null)
			setIsPendingNewChat(false)
			setIsSidebarOpen(false)
		}
	}, [appID, currentVersion])

	const value = useMemo(() => ({
		activeChatId,
		setActiveChatId,
		activeChatPersona,
		setActiveChatPersona,
		isSidebarOpen,
		toggleSidebar,
		closeSidebar,
		chats,
		totalChats,
		isLoadingChats,
		createNewChat,
		renameChat: handleRenameChat,
		selectChat,
		deferSelectChat,
		isPendingNewChat,
		finalizePendingChat,
		refetchChats,
		isLoadingPeek,
		hasReachedChatLimit,
		showChatLimitModal,
		setShowChatLimitModal,
	}), [
		activeChatId,
		setActiveChatId,
		activeChatPersona,
		setActiveChatPersona,
		isSidebarOpen,
		toggleSidebar,
		closeSidebar,
		chats,
		totalChats,
		isLoadingChats,
		createNewChat,
		handleRenameChat,
		selectChat,
		deferSelectChat,
		isPendingNewChat,
		finalizePendingChat,
		refetchChats,
		isLoadingPeek,
		hasReachedChatLimit,
		showChatLimitModal,
	])

	return (
		<ChatManagementContext.Provider value={value}>
			{children}
		</ChatManagementContext.Provider>
	)
}
