import React from 'react'
import styled from 'styled-components'
import ChevronRightIcon from 'public/static/ai/icon-chevron-right.svg'
import { UseCase } from './promptLibraryData'
import { UseCaseIcon } from './UseCaseIcons'

const Card = styled.button`
	display: flex;
	align-items: center;
	gap: 2px;
	padding: 8px;
	background: #EFF5FFB2;
	border-radius: 4px;
	border: none;
	cursor: pointer;
	width: 100%;
	text-align: left;
	transition: background-color 0.15s ease;

	&:hover {
		background: #DFEAFF99;
	}
`

const Content = styled.div`
	display: flex;
	flex: 1;
	gap: 10px;
	align-items: flex-start;
	min-width: 0;
`

const IconWrapper = styled.div`
	flex-shrink: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	
	svg rect {
		fill: white;
	}
`

const TextContent = styled.div`
	display: flex;
	flex-direction: column;
	gap: 1px;
	flex: 1;
	min-width: 0;
`

const Title = styled.span`
	font-family: 'Roboto', sans-serif;
	font-weight: 500;
	font-size: 12px;
	line-height: 20px;
	color: #161E35;
`

const Description = styled.span`
	font-family: 'Roboto', sans-serif;
	font-weight: 400;
	font-size: 12px;
	line-height: 20px;
	color: #737886;
`

const ChevronWrapper = styled.div`
	flex-shrink: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 24px;
	height: 24px;
`

interface UseCaseCardProps {
	useCase: UseCase
	onClick: (useCase: UseCase) => void
}

const UseCaseCard = ({ useCase, onClick }: UseCaseCardProps) => {
	const handleClick = () => {
		onClick(useCase)
	}

	return (
		<Card onClick={handleClick}>
			<Content>
				<IconWrapper>
					<UseCaseIcon type={useCase.icon} />
				</IconWrapper>
				<TextContent>
					<Title>{useCase.title}</Title>
					<Description>{useCase.description}</Description>
				</TextContent>
			</Content>
			<ChevronWrapper>
				<ChevronRightIcon />
			</ChevronWrapper>
		</Card>
	)
}

export default UseCaseCard
