/* eslint-disable @typescript-eslint/ban-ts-comment */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { isDateOlderThanMonths } from 'Utils/DateUtils';
import { useAISessionItems } from 'components/features/aiSessions/hooks/useSessionItems';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { useAISessionTableHelper } from 'components/features/aiSessions/SessionDetailsAndVideo/SessionTable/utils';
import { useStatsBoxData } from 'components/common/Analytics/NewOverviewBoxes/hooks/useStatisticBoxes';
import { useIsAppType } from 'hooks/useIsAppType';
import { goToPage } from 'components/shared/Pagination';
import { formatTime } from 'components/shared/Sessions/Video/utils';
import { useSessionVideoContext, useSessionVideoControlls } from 'components/shared/Sessions/Context';
import { useSessionTableHelper } from 'components/features/sessions/SessionDetailsAndVideo/SessionTable/utils';
import { PLAYLIST_STATUS, useAISessionUtils } from '../../../shared/GlobalFilter/components/aiSessionFilter/AISessionUtilsContext';
import { DropdownSession, PlaylistType, Session } from './types';
import { getUserName, getTimeDuration, trackNextPrevNavigation, trackPlaylistDropdownClick, trackAISessionSelect, trackPlaylistSessionSelect } from './utils';
import BaseSessionDropdown from './BaseSessionDropdown';
import { useAIUserSessions } from './service';

interface RestrictionContext {
    monthsOfVideosAccessible?: number;
}

const getDropdownTitle = (isContinueWatching:boolean)=>{
    return isContinueWatching ? "Continue watching from session list:"
    : "Sessions from session list:"
}
const SessionListDropdown: React.FC = () => {
    const {
        urlReducer: { sessionid, sessionpage = 1, appId, secondarysessionid,autoplay,notetab, starttime,eventid, parentType},
        appFilter: { session: { segment: sessionSegment }, dateSegment },
        currentOrgReducer: { planLimit },
    } = useSelector((state: any) => state);
    const dispatch = useDispatch();
    const { mutate:mutateAIUserSession  } = useAIUserSessions()
    const { isPlaying, timeRef } = useSessionVideoContext()
    const { nextSessionCallbackRef, playAllRef } = useSessionVideoControlls()
    const { trackUserTimeEvent } = useSessionTableHelper({expanded: true})
    const restrictionContext = useRestrictionContext() as RestrictionContext | null;
    const { utils, setUtils, setActiveSessionList } = useAISessionUtils();
    const sessionpageNumber = Number(sessionpage);
    const aiSessionsListReqBody = useMemo(() => {
        try {
            return JSON.parse(localStorage.getItem('aiSessionsListReqBody') || '{}');
        } catch {
            return {};
        }
    }, []);

  const isWebApp = useIsAppType( 'web' );

    const getInitial = useCallback(() => ({
        appid: appId,
        // filters: [ ...sessionSegment, ...[ { ...dateSegment } ] ],
        filters: sessionSegment,
        date_range: dateSegment,
        orderBy: aiSessionsListReqBody.orderBy,
        page: sessionpageNumber || 1,
        session_per_page: 50,
        webApp: isWebApp,
        navigationType: 'initial' // Add navigation type to track direction
    }), [appId, sessionSegment, dateSegment, aiSessionsListReqBody.orderBy, sessionpageNumber, isWebApp]);
    
    const [payloadConfiguration, setPayloadConfiguration] = useState(getInitial)

    const getPostBody = useCallback(() => {
        const { navigationType, ...rest } = payloadConfiguration;
        return rest
    }, [payloadConfiguration]);

    useEffect(() => {
        try {
            localStorage.setItem('aiSessionsListReqBody', JSON.stringify(getPostBody()));
        } catch (err) {
            // silent fail
        }
    }, [getPostBody]);

    const { data: dataBody, isLoading, isFetching } = useAISessionItems(
        getPostBody()
        , {
        enabled: !!aiSessionsListReqBody,
    });

    const dataWithSessionLocked = useMemo(() => {
        if (!dataBody) return undefined;
        const { data } = dataBody;
        return {
            ...dataBody,
            data: {
                ...data,
                data: {
                    ...data.data,
                    body: data.data?.body?.map((item: Session) => ({
                        ...item,
                        sessionLocked:
                            restrictionContext?.monthsOfVideosAccessible &&
                            isDateOlderThanMonths(item.sessionUploadedDateTime, restrictionContext.monthsOfVideosAccessible) &&
                            planLimit?.videoRetentionTime !== planLimit?.videoPlaybackAccessibleTime
                    }))
                }
            }
        };
    }, [dataBody, restrictionContext?.monthsOfVideosAccessible, planLimit]);

    const payload = useMemo(() => ({
        appid: appId,
        filters: [...sessionSegment],
        date_range: { ...dateSegment }
    }), [appId, sessionSegment, dateSegment]);

    const { data: statBoxesData, isLoading: isStatsDataLoading } = useStatsBoxData(payload);

    const sessions: DropdownSession[] = useMemo(() => {
        const body = dataWithSessionLocked?.data?.data?.body || [];
        return body.map((item: Session, index: number) => ({
            dataIndex: index,
            index: (index + 1) + ((sessionpageNumber - 1) * 50),
            id: item.sessionid,
            name: getUserName(item.userProperty),
            location: item.country || 'Unknown',
            duration: formatTime(item.sessionDuration).toString(),
            date: getTimeDuration(item.deviceLocalDateTime, item.userTimezone)[0],
            status: 'playing',
            isAIAnalyzed: item.sessionanalyzedbyai || false,
            hasVideo: item.video || false,
        }));
    }, [dataWithSessionLocked, sessionpageNumber]);

    const totalSessionsCount = useMemo(() => {
        if (isStatsDataLoading) return '';
        return statBoxesData?.boxes['Sessions']?.count?.value_this_period_string || '';
    }, [statBoxesData, isStatsDataLoading]);

    const { handleRowClick: handleRowClickRaw } = useAISessionTableHelper({ expanded: true });
    const handleSessionReplayStoppedTrackEvent = useCallback((userSessionId: string) => {
        if(isPlaying) {
            trackUserTimeEvent(userSessionId, timeRef?.current);
        }
    }, [trackUserTimeEvent, isPlaying, timeRef]);

    const handleRowClick = useCallback(
        (sessionId: string, currentIndex?: number, previousIndex?: number, skipTracking = false, autoPlay = false) => {
            const sessionData = dataWithSessionLocked?.data?.data?.body?.find((item:Session)=>item.sessionid === sessionId)
            setUtils(prev => ({ ...prev, activePlaylist: PLAYLIST_STATUS.SESSION_PLAYLIST }));
            
            if (!skipTracking) {
                if (currentIndex && previousIndex) {
                    dispatch(trackPlaylistSessionSelect({
                        parentType,
                        playlistType: PlaylistType.SESSION,
                        sessionsPosition: previousIndex,
                        selectedSessionPosition: currentIndex
                    }))
                }
                if (sessionData) {
                    dispatch(trackAISessionSelect({
                        sessionId: sessionid,
                        aiAnalyzed: sessionData.sessionanalyzedbyai,
                        containsVideo: sessionData.video,
                        duration: sessionData.sessionDuration, 
                        gestureCount: sessionData.totalGesture,
                        parentType, 
                        sessionSelectedFrom: 'session_playlist',
                        filtersApplied: sessionSegment,
                        isRageTap: sessionData.isRageTap,
                        isUiFreeze: sessionData.isuifreeze,
                        isCrashed: sessionData.crashed
                    }))
                }
            }
            
            mutateAIUserSession({
                appid: appId,
                uxcamuserid: sessionData?.userProperty?.uxcamuserid,
                recordedon: sessionData?.recordedon,
                session_per_page: 101,
                usersessionrun: sessionData?.userSessionRun,
                webApp: isWebApp
            })
            handleSessionReplayStoppedTrackEvent(secondarysessionid)
            handleRowClickRaw({ button: 0 }, sessionId, false, false, autoPlay);
        },
        [dataWithSessionLocked?.data?.data?.body, setUtils, mutateAIUserSession, appId, isWebApp, handleSessionReplayStoppedTrackEvent, secondarysessionid, handleRowClickRaw, dispatch, parentType, sessionid, sessionSegment]
    );

    const handleNextPrevClick = (direction: 'next' | 'prev') => {
        if (!dataWithSessionLocked?.data?.data?.pagination) return;

        const currentSession = sessions.find(s => s.id === sessionid);
        if (!currentSession) return;

        const potentialNewIndex = direction === 'next' 
            ? currentSession.dataIndex + 1
            : currentSession.dataIndex - 1;

        const {pagination} = dataWithSessionLocked.data.data;
        const currentPage = pagination.current;
        const totalPages = pagination.pages;

        const isNavigatingToNextPage = potentialNewIndex >= sessions.length && direction === 'next';
        const isNavigatingToPrevPage = potentialNewIndex < 0 && direction === 'prev';
        
        dispatch(trackNextPrevNavigation({
            currentOrder: currentSession.index,
            total: statBoxesData?.boxes['Sessions']?.count?.value_this_period_number || 0,
            playlistType: PlaylistType.SESSION,
            direction: direction === 'next' ? 'next session' : 'previous session',
            parentType
        }))

        if(isNavigatingToNextPage) {
            // * Check if there are more pages available before fetching next page
            if (currentPage < totalPages) {
                setPayloadConfiguration(prev => ({
                    ...prev,
                    page: prev.page + 1,
                    navigationType: 'next'
                }));
            }
            return;
        }
        if(isNavigatingToPrevPage) {
            // * Check if we're not already on the first page before fetching previous page
            if (currentPage > 1) {
                setPayloadConfiguration(prev => ({
                    ...prev,
                    page: Math.max(prev.page - 1, 1),
                    navigationType: 'prev'
                }));
            }
            return;
        }

        // If we're staying on the same page, clamp the index and navigate to that session
        const newIndex = direction === 'next' 
            ? Math.min(potentialNewIndex, sessions.length - 1)
            : Math.max(potentialNewIndex, 0);

        const newSessionId = sessions[newIndex]?.id;
        if (newSessionId) {
            handleRowClick(newSessionId, undefined, undefined, true, !!playAllRef?.current); // Pass skipTracking=true
        }
    };

    const showContinueWatching = useCallback(
        (passedSessionId: string) => passedSessionId === sessionid && sessionid !== secondarysessionid,
        [sessionid, secondarysessionid]
    );
    
    const goTo = useCallback((passedSession: Session) => {
        goToPage({
            page: payloadConfiguration.page,
            appId,
            sessionid: passedSession.sessionid,
            secondarysessionid,
            autoplay,
            segment: sessionSegment,
            parentType,
            notetab,
            eventid: null,
            starttime,
            expanded: false,
            dateSegment: null,
            uxcamuserid: null
        })
        mutateAIUserSession({
            appid: appId,
            uxcamuserid: passedSession?.userProperty?.uxcamuserid,
            recordedon: passedSession?.recordedon,
            session_per_page: 101,
            usersessionrun: passedSession?.userSessionRun,
            webApp: isWebApp
        })
    }, [payloadConfiguration.page, appId, secondarysessionid, autoplay, sessionSegment, parentType, notetab, starttime, mutateAIUserSession, isWebApp]);
    
    useEffect(() => {
        if (dataBody) {
            setActiveSessionList(dataBody) // * set fresh data
            
            // * Handle session selection based on context
            if (!sessions.some(session => session.id === sessionid)) {
                // * Default selection logic when sessionid isn't in the list
                if (payloadConfiguration.navigationType === 'next' && sessions.length > 0) {
                    // * For next page navigation, select the first session
                    const firstSessionId = sessions[0]?.id;
                    const sessionData =  dataWithSessionLocked?.data?.data?.body?.find((i:Session)=>i.sessionid === firstSessionId)
                    if (sessionData) {
                        setUtils(prev => ({ ...prev, activePlaylist: PLAYLIST_STATUS.SESSION_PLAYLIST }));
                        goTo(sessionData);
                    }
                } else if (payloadConfiguration.navigationType === 'prev' && sessions.length > 0) {
                    // * For prev page navigation, select the last session
                    const lastSessionId = sessions[sessions.length - 1]?.id;
                    const sessionData =  dataWithSessionLocked?.data?.data?.body?.find((i:Session)=>i.sessionid === lastSessionId)
                    if (lastSessionId) {
                        setUtils(prev => ({ ...prev, activePlaylist: PLAYLIST_STATUS.SESSION_PLAYLIST }));
                        goTo(sessionData);
                    }
                } else {
                    // * Default to the first session in the list
                    const firstSessionId = sessions[0]?.id;
                    const sessionData =  dataWithSessionLocked?.data?.data?.body?.find((i:Session)=>i.sessionid === firstSessionId)
                    if (sessionData) {
                        setUtils(prev => ({ ...prev, activePlaylist: PLAYLIST_STATUS.INACTIVE }));
                        goTo(sessionData);
                    }
                }
            }
        }
    }, [dataBody]);

    const currentSessionIndex = useMemo(() => {
        const data = sessions.find(s => s.id === sessionid);
        return {
            count: data?.index,
            index: data?.dataIndex,
        }
    } , [sessions, sessionid]);

    const triggerLabel = useMemo(() => {
            if (totalSessionsCount && currentSessionIndex.count) {
                return `Session: ${currentSessionIndex.count} out of ${totalSessionsCount }`;
            }
            return 'Session';
    }, [currentSessionIndex, totalSessionsCount]);

    const hasPrevNext = useMemo(() => {
        if (!dataWithSessionLocked?.data?.data?.pagination) return { hasPrev: false, hasNext: false };
        const { pagination } = dataWithSessionLocked.data.data;
        return {
            hasPrev: currentSessionIndex.index === 0 ? pagination.current !== 1 : true,
            hasNext: currentSessionIndex.index === sessions.length - 1 ? pagination.current !== pagination.pages : true
        };
    }, [currentSessionIndex, dataWithSessionLocked?.data?.data, sessions.length]);

    const onVisibleChange = useCallback((visible: boolean) => {
       visible && dispatch(trackPlaylistDropdownClick({
            parentType,
            playlistType: PlaylistType.SESSION
        }))
    },[dispatch, parentType])
    // Set the video controls callback to use the dropdown's navigation
    useEffect(() => {
        const handleNextForPlayAll = () => handleNextPrevClick('next');
        nextSessionCallbackRef.current = handleNextForPlayAll;
        return () => {
            nextSessionCallbackRef.current = null;
        };
    }, [nextSessionCallbackRef, sessionid, playAllRef?.current ]);


    return (
        <BaseSessionDropdown
            sessions={sessions}
            currentSessionId={sessionid}
            isLoading={isFetching || isStatsDataLoading}
            isActive={utils.activePlaylist === PLAYLIST_STATUS.SESSION_PLAYLIST}
            onSessionClick={handleRowClick}
            onNextPrevClick={handleNextPrevClick}
            showContinueWatching={showContinueWatching}
            dropdownTitle={getDropdownTitle(showContinueWatching(sessionid))}
            styleConfig={{
                size: 'lg'
            }}
            triggerLabel={triggerLabel}
            hasPrev={hasPrevNext.hasPrev}
            hasNext={hasPrevNext.hasNext}
            onVisibleChange={onVisibleChange}
        />
    );
};

export default SessionListDropdown;