import React, { createContext, useContext, useMemo } from 'react'
import { IDocument } from '../AIAssistant/ChatTab'

interface IProps {
	children: React.ReactNode
}

interface IAIAssistantPopup {
	tempDocumentsMap: IDocument[] | null
	setTempDocumentsMap: ( tempDocumentsMap: IDocument[] | null ) => void
	sessionAliasMap: Record<string, string> | null
	setSessionAliasMap: ( sessionAliasMap: Record<string, string> | null ) => void
}

const AIAssistantContext = createContext<IAIAssistantPopup>( {
	tempDocumentsMap: null,
	setTempDocumentsMap: () => null,
	sessionAliasMap: null,
	setSessionAliasMap: () => null,
} )

const AIAssistantContextProvider: React.FC<IProps> = ( { children } ) => {
	const [ tempDocumentsMap, setTempDocumentsMap ] = React.useState<IDocument[] | null>( null )
	const [ sessionAliasMap, setSessionAliasMap ] = React.useState<Record<string, string> | null>( null )

	const value: IAIAssistantPopup = useMemo( () => ( {
		tempDocumentsMap,
		setTempDocumentsMap,
		sessionAliasMap,
		setSessionAliasMap,
	} ), [
		tempDocumentsMap,
		setTempDocumentsMap,
		sessionAliasMap,
		setSessionAliasMap,
	] )

	return (
		<AIAssistantContext.Provider value={ value }>
			{ children }
		</AIAssistantContext.Provider>
	)
}

const useAIAssistantContext = () => useContext( AIAssistantContext )

export {
	useAIAssistantContext,
	AIAssistantContextProvider
}