import React, { useEffect } from 'react'
import { UFCModal } from 'uxcam-frontend-components'
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'
import { useDispatch } from 'react-redux'
import styled from 'styled-components'
import { useRouter } from 'next/router'
import { trackTaraErrorNotification } from 'components/features/aiSessions/components/utils'
import { Footer, StyledButton, SubTitle, Title } from '../common'

const StyledTitle = styled( Title )`
	margin-bottom: 8px;
`

const SessionProcessingError = () => {
	const { setSessionProcessingErrorModalVisible, sessionProcessingErrorModalVisible} = useAISessionWatchlist()
	const router = useRouter()
	const dispatch = useDispatch()
	const { parentType } = router.query

	const handleClose = () => {
		setSessionProcessingErrorModalVisible( false )
	}

	const errorMessage = 'They may have already been analyzed, don’t include a video, or are longer than 20 minutes.'

	useEffect(() => {
		if (sessionProcessingErrorModalVisible) {
			dispatch(trackTaraErrorNotification({
				error: errorMessage,
				parentType: (parentType as string) || 'unknown'
			}))
		}
	}, [sessionProcessingErrorModalVisible, parentType, dispatch])

	const footer = (
		<Footer>
			<StyledButton
				type="button"
				variant="ghost"
				size="large"
				onClick={ handleClose }
			>
				Close
			</StyledButton>
		</Footer>
	)

	return (
		<UFCModal
			visible={ sessionProcessingErrorModalVisible }
			footer={ footer }
			closable={ false }
			className='duration-modal'
			style={{top: 0}}
		>
			<StyledTitle>
				We couldn’t process your sessions
			</StyledTitle>
			<SubTitle>
				{ errorMessage }
				<a href="https://help.uxcam.com/en/articles/13367270-what-is-tara" target='_blank' rel="noreferrer"> Learn more.</a>
			</SubTitle>
		</UFCModal>
	)
}

export default SessionProcessingError