import React from 'react';
import { Button, Modal } from 'antd';
import styled from 'styled-components';

const StyledModal = styled(Modal)`
  height: 210px;
  .ant-modal-footer {
    border-top: none;
    padding: 0;
  }
`;

const StyledDiv = styled.div`
  font-weight: 400;
  font-size: 18px;
  line-height: 21px;
  margin-bottom: 16px;
  padding: 16px;
`;

const StyledButton = styled(Button)`
  width: 100px;
  height: 42px;
  background: #5d97ff;
  border-radius: 4px;
  color: #ffffff;
  font-size: 16px;
`;
const StypedButtonDiv = styled.div`
  display: flex;
  justify-content: flex-end;
`;

const StylyedInfo = styled.p`
  color: #5b6d89;
  font-weight: 400;
  font-size: 14px;
  margin-bottom: 0;
`;
const StyledTitle = styled.p`
  font-size: 18px;
  color: #161e35;
  margin-bottom: 0;
`;

const ForbiddenModal = ({
  visibleForbiddenModal,
  setVisibleForbiddenModal,
}) => {
  const handleOk = () => {
    setVisibleForbiddenModal(false);
  };

  const handleCancel = () => {
    setVisibleForbiddenModal(false);
  };

  return (
    <StyledModal
        title=""
        visible={visibleForbiddenModal}
        onOk={handleOk}
        onCancel={handleCancel}
        destroyOnClose={handleCancel}
        width="415px"
        closable={false}
        footer={[]}
      >
        <StyledDiv>
          <StyledTitle>Insufficient Privilege</StyledTitle>
          <StylyedInfo>
            You do not have required privilege for this action.
          </StylyedInfo>
        </StyledDiv>

        <StypedButtonDiv>
          <StyledButton onClick={() => handleOk()} type="primary">
            Ok
          </StyledButton>
        </StypedButtonDiv>
      </StyledModal>
  );
};

export default ForbiddenModal;
