import React from 'react'
import styled, { createGlobalStyle } from 'styled-components'
import { Modal } from 'antd'
import { theme } from 'theme'

const GlobalStyles = createGlobalStyle`
	.share-chat-error-modal {
		.ant-modal-content {
			border-radius: 12px;
			box-shadow: 0px 8px 32px rgba(0, 0, 0, 0.12);
			.ant-modal-body {
				padding: 32px;
			}
		}
	}
`

const ContentWrapper = styled.div`
	display: flex;
	flex-direction: column;
	gap: 24px;
`

const TextSection = styled.div`
	display: flex;
	flex-direction: column;
	gap: 12px;
`

const TitleRow = styled.div`
	display: flex;
	align-items: center;
	gap: 8px;
`

const WarningIcon = () => (
	<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
		<circle cx="12" cy="12" r="10" fill="#FBBF24" />
		<path d="M12 8V13" stroke="white" strokeWidth="2" strokeLinecap="round" />
		<circle cx="12" cy="16" r="1" fill="white" />
	</svg>
)

const Title = styled.h2`
	font-family: Roboto;
	font-weight: 500;
	font-size: 18px;
	line-height: normal;
	color: ${theme.colors.surface500.toString()};
	margin: 0;
`

const Description = styled.p`
	font-family: Roboto;
	font-weight: 400;
	font-size: 13px;
	line-height: 22px;
	color: ${theme.colors.surface400.toString()};
	margin: 0;
`

const BoldText = styled.strong`
	font-weight: 500;
`

const Footer = styled.div`
	display: flex;
	justify-content: flex-end;
	gap: 12px;
`

const CloseButton = styled.button`
	padding: 8px 20px;
	border-radius: 6px;
	border: none;
	font-family: Roboto;
	font-size: 13px;
	font-weight: 500;
	cursor: pointer;
	color: ${theme.colors.primary500.toString()};
	background: transparent;

	&:hover {
		background: ${theme.colors.primary10.toString()};
	}
`

const PrimaryButton = styled.button`
	padding: 8px 20px;
	border-radius: 6px;
	border: none;
	font-family: Roboto;
	font-size: 13px;
	font-weight: 500;
	cursor: pointer;
	color: white;
	background: ${theme.colors.primary500.toString()};

	&:hover {
		background: ${theme.colors.primary600.toString()};
	}
`

export type ShareErrorType = 'expired' | 'no_permission' | 'ai_disabled' | null

interface IShareChatErrorModalProps {
	visible: boolean
	errorType: ShareErrorType
	onClose: () => void
	onSwitchAccount?: () => void
}

const ShareChatErrorModal: React.FC<IShareChatErrorModalProps> = ({
	visible,
	errorType,
	onClose,
	onSwitchAccount,
}) => {
	const renderContent = () => {
		switch (errorType) {
			case 'expired':
				return (
					<>
						<TextSection>
							<TitleRow>
								<WarningIcon />
								<Title>This link has expired</Title>
							</TitleRow>
							<Description>
								For security and data privacy, Tara AI shared links have a limited lifespan. To view this chat, please ask the sender to generate a new link.
							</Description>
						</TextSection>
						<Footer>
							<CloseButton onClick={onClose}>Close</CloseButton>
						</Footer>
					</>
				)

			case 'no_permission':
				return (
					<>
						<TextSection>
							<TitleRow>
								<WarningIcon />
								<Title>Can&apos;t open this chat</Title>
							</TitleRow>
							<Description>
								Your account doesn&apos;t have access to the app where this chat was shared. Try switching accounts, or contact the sender to request access.
							</Description>
						</TextSection>
						<Footer>
							<CloseButton onClick={onClose}>Continue on this account</CloseButton>
							<PrimaryButton onClick={onSwitchAccount}>Switch account</PrimaryButton>
						</Footer>
					</>
				)

			case 'ai_disabled':
				return (
					<>
						<TextSection>
							<TitleRow>
								<WarningIcon />
								<Title>Can&apos;t open this chat</Title>
							</TitleRow>
							<Description>
								AI has been disabled for this app. Go to <BoldText>Subscription settings &gt; Tara AI &gt; Turn On AI</BoldText> for this app and try again.
							</Description>
						</TextSection>
						<Footer>
							<CloseButton onClick={onClose}>Close</CloseButton>
						</Footer>
					</>
				)

			default:
				return null
		}
	}

	return (
		<>
			<GlobalStyles />
			<Modal
				visible={visible}
				closable={false}
				footer={null}
				className="share-chat-error-modal"
				centered
				width={470}
				destroyOnClose
			>
				<ContentWrapper>
					{renderContent()}
				</ContentWrapper>
			</Modal>
		</>
	)
}

export default ShareChatErrorModal
