import { axiosInstance } from './globalInstance'

class accessManagementApi {
  static async checkPlanStatus(orgId) {
    const res = await axiosInstance.get(
      `${process.env.SUBSCRIPTION_URL}/organization/${orgId}/check-plan-status`,
      {
        withCredentials: true,
        validateStatus (status) {
          return status >= 200 && status < 500 // default
        },
      }
    )
    return res.data
  }

  static async getApps(orgId) {
    const res = await axiosInstance.get(
      `${process.env.SUBSCRIPTION_URL}/organization/${orgId}/get-apps`,
      {
        withCredentials: true,
        validateStatus (status) {
          return status >= 200 && status < 500 // default
        },
      }
    )
    return res.data
  }

  static async getUsers(orgId) {
    const res = await axiosInstance.get(
      `${process.env.SUBSCRIPTION_URL}/organization/${orgId}/get-users`,
      {
        withCredentials: true,
        validateStatus (status) {
          return status >= 200 && status < 500 // default
        },
      }
    )
    return res.data
  }

  static async manageAppAccess(data) {
    const res = await axiosInstance.post(
      `${process.env.SUBSCRIPTION_URL}/organization/${data.organizationId}/manage-app-access`,
      data,
      {
        withCredentials: true,
        validateStatus (status) {
          return status >= 200 && status < 500 // default
        },
      }
    )
    return res.data
  }

  static async manageUserAccess(data) {
    const res = await axiosInstance.post(
      `${process.env.SUBSCRIPTION_URL}/organization/${data.organizationId}/manage-user-access`,
      data,
      {
        withCredentials: true,
        validateStatus (status) {
          return status >= 200 && status < 500 // default
        },
      }
    )
    return res.data
  }
}

export default accessManagementApi
