import React, { useMemo } from 'react'
import styled from 'styled-components'
import { theme } from 'theme'
import { UFCTooltip } from 'uxcam-frontend-components'
import PopupIcon from 'public/static/icon-popup-externa-open-square.svg'
import Link from 'next/link'
import { useSelector } from 'react-redux'
import { IReduxState } from 'types/reduxStateTypes'

const Container = styled.div`
	display: flex;
	align-items: center;
	gap: 4px;
	font-family: Roboto;
	font-weight: 400;
	font-size: 12px;
	line-height: 100%;
	margin: 0;
`

const Badge = styled.div`
	display: inline-block;
	padding: 2px 4px;
	background: ${theme.colors.surface05.toString()};
	border-radius: 4px;
	margin-left: 3px;
	span {
		font-weight: 500;
		color: ${theme.colors.surface500.toString()};
	}
`

const TooltipContentWrapper = styled.div`
	display: flex;
	align-items: center;
	gap: 4px;
`

type TProps = {
	creditsLeft: number
	totalCredits: number
}

const CreditsLeft = ( { creditsLeft, totalCredits }: TProps ) => {
	const { 
		currentOrgReducer: {
			orgId: orgID
		},
		currentAppReducer: {
			_id: appID
		}
	} = useSelector( ( state: IReduxState ) => state )
	const tooltipContent = useMemo( () => (
		<TooltipContentWrapper>
			Check
			<Link
				href={{
					pathname: '/integration',
					query: {
						setting: 'org_setting',
						org: orgID,
						org_tab: 'tara-ai',
						parentType: 'settings',
					},
				}}
				target="_blank"
				as={`/settings/org/${orgID}/${appID}/tara-ai`}
				rel="noopener noreferrer"
			>
				usage breakdown
			</Link>
			<PopupIcon />
		</TooltipContentWrapper>
	), [ orgID, appID ] )

	return (
		<Container>
			Credits left:
			<UFCTooltip title={ tooltipContent } placement='bottom'>
				<Badge>
					{ Math.ceil( creditsLeft ) } of
					<span> { Math.ceil( totalCredits ) }</span>
				</Badge>
			</UFCTooltip>
		</Container>
	)
}

export default CreditsLeft