export const getUseCaseById = (id: string): UseCase | undefined => {
	return PROMPT_LIBRARY_DATA.find(useCase => useCase.id === id)
}

export const getPlaceholderPosition = (text: string, placeholder: string): number => {
	const match = text.match(new RegExp(`\\{${placeholder}\\}`))
	if (match && match.index !== undefined) {
		return match.index
	}
	return text.length
}
