import React from 'react'
import { UFCModal } from 'uxcam-frontend-components'
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'
import ErrorIcon from 'public/static/icon-error-circle.svg'
import styled, { createGlobalStyle } from 'styled-components'
import { Footer, StyledButton, SubTitle, Title } from '../common'

const TitleWrapper = styled.div`
	margin-bottom: 8px;
	display: flex;
	align-items: center;
	gap: 8px;
`

const GlobalStyles = createGlobalStyle`
	.duration-modal {
		.ufc-modal-container {
			padding: 32px;
			.ufc-modal-footer {
				margin-top: 36px;
			}
		}
	}
`

const SessionUpgradeError = () => {
	const { upgradeErrorModalVisible, setUpgradeErrorModalVisible, setUpgradeModalVisible } = useAISessionWatchlist()

	const handleClose = () => {
		setUpgradeErrorModalVisible( false )
	}

	const handleRetry = () => {
		setUpgradeErrorModalVisible( false )
		setUpgradeModalVisible( true )
	}

	const footer = (
		<Footer>
			<StyledButton
				type="button"
				variant="ghost"
				size="large"
				onClick={ handleClose }
			>
				Close
			</StyledButton>
			<StyledButton
				type="button"
				variant="primary"
				size="large"
				onClick={ handleRetry }
			>
				Try again
			</StyledButton>
		</Footer>
	)

	return (
		<>
			<GlobalStyles />
			<UFCModal
				visible={ upgradeErrorModalVisible }
				footer={ footer }
				closable={ false }
				className='duration-modal'
				style={{top: 0}}
			>
				<TitleWrapper>
					<ErrorIcon />
					<Title>
						We couldn&apos;t send your upgrade request
					</Title>
				</TitleWrapper>
				<SubTitle>
					Something went wrong. Please try again in a moment.
				</SubTitle>
			</UFCModal>
		</>
	)
}

export default SessionUpgradeError
