import { Modal } from 'antd'
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext'
import React from 'react'
import styled from "styled-components"
import { theme } from 'theme'
import IconClose from 'public/static/close-bold.svg'

const Wrapper = styled.div`
	position: relative;
`

const VideoContainer = styled.div`
	padding:56.25% 0 0 0;
	position:relative;
	background-color: #0B0F23;
	overflow: hidden;
`

const CloseBtn = styled.button`
	position: absolute;
	background: none;
	cursor: pointer;
	top: -30px;
	right: -30px;
	height: 30px;
	width: 30px;
	border: none;
	padding: 0;
	margin: 0;
	svg > path {
		stroke: ${ theme.colors.primarySnow.toString() };
	}
`

const TutorialOverlay: React.FC = () => {
	const { showNoCodeEventsTutorial, setShowNoCodeEventsTutorial } = useNoCodeEventsContext()

	const handleClose = React.useCallback( () => {
		setShowNoCodeEventsTutorial( false )
	}, [ setShowNoCodeEventsTutorial ] )

	return (
        <Modal
        width={ 800 }
        bodyStyle={{ padding: 0 }}
        destroyOnClose
        visible={showNoCodeEventsTutorial}
        onCancel={handleClose} 
        maskClosable 
        closable={false}
        footer={false} 
        centered>
            <Wrapper>
                <CloseBtn onClick={handleClose}>
                    <IconClose />
                </CloseBtn>
                <VideoContainer>
                    <iframe
                        src="https://player.vimeo.com/video/889855543?h=1558086bea&amp;badge=0&amp;autopause=0&amp;quality_selector=1&amp;player_id=0&amp;app_id=58479"
                        frameBorder="0"
                        allow="autoplay; fullscreen; picture-in-picture"
                        style={{
                            position: 'absolute', top: '0', left: '0', width: '100%', height: '100%',
                        }}
                        title="How to create smart events in UXCam"
                    />
                </VideoContainer>
            </Wrapper>
        </Modal>
	)
}

export default React.memo( TutorialOverlay )
