/* eslint-disable no-nested-ternary */
import React, { memo, useCallback, useMemo } from 'react';
import { Modal } from 'antd';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { createGlobalStyle } from 'styled-components';
import ButtonNew from 'components/common/ButtonNew';
import { useMutation, useQueryClient } from 'react-query';
import { deleteScreenEvent } from 'components/features/sessions/hooks/useNocodeEvents';
import useMessage from 'hooks/useMessage';
import { rollbar } from 'components/common/rollbar';
import Rollbar from 'rollbar';
import { useDispatch, useSelector } from 'react-redux';
import { IReduxState } from 'types/reduxStateTypes';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';
import { ISessionTimeline } from 'types/sessionTypes';
import { trackPageViews } from 'redux/actions/trackingReport';
import { InfoCircleOutlined } from '@ant-design/icons';
import { removeScreenEventFromSessionDetail } from '../helpers';
import { Buttons, Label, Title } from '../commonStyles';
import { StyledAlert } from '../../styles';

const GlobalStyles = createGlobalStyle`
	.ant-modal-delete-nocode-event-wrapper {
		display: flex;
		align-items: center;
	}
	.ant-modal-delete-nocode-event {
		top: 0;
		.ant-modal-content {
			border-radius: 8px;
			padding: 32px;
		}
		.ant-modal-body {
			padding: 0;
		}
	}
`;

const DeleteSmartEventPopup: React.FC = () => {
  const {
    deleteScreenEventPopupOpen,
    setDeleteScreenEventPopupOpen,
    currentAction,
    setCurrentAction,
    currentScreen,
  } = useNoCodeEventsContext();
  const {
    sessionDetail,
    setSessionDetail,
    setSessionNocodeEvents,
    sessionNocodeEvents,
  } = useSessionTimeLine() as unknown as ISessionTimeline;
  const { currentAppReducer } = useSelector((state: IReduxState) => state);
  const { _id: appId } = currentAppReducer;
  const { mutate: deleteEvent, isLoading } = useMutation(deleteScreenEvent);
  const { message } = useMessage();
  const dispatch = useDispatch();
  const queryClient = useQueryClient();

  const handleClose = useCallback(() => {
    if (!isLoading) {
      setDeleteScreenEventPopupOpen(false);
      setCurrentAction(undefined);
    }
  }, [isLoading, setDeleteScreenEventPopupOpen, setCurrentAction]);

  const handleDeleteEvent = useCallback(() => {
    if (currentAction?.props) {
      const { id: nceId } = currentAction;
      deleteEvent(
        {
          appId,
          nceId: nceId as unknown as number,
        },
        {
          onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['manage-nocode-list'] });
            queryClient.invalidateQueries({ queryKey: ['nocodeEventList'] });
            dispatch(
              trackPageViews(null, {
                eventName: 'wa_remove_nocode_event',
                track_type: 'event',
                eventProperty: {
                  event_id: nceId,
                  screen_name: currentScreen?.activityName,
                  event_name: currentAction?.name,
                  type_of_event: 'screenvisit',
                },
              })
            );
            if (nceId && sessionDetail && currentScreen && currentAction) {
              const updatedSessionDetail = removeScreenEventFromSessionDetail(
                sessionDetail,
                currentScreen,
                nceId as unknown as number
              );
              setSessionDetail(updatedSessionDetail);
            }
            if (setSessionNocodeEvents && sessionNocodeEvents) {
              setSessionNocodeEvents(
                sessionNocodeEvents.filter(
                  (event) => event.event_name !== currentAction?.name
                )
              );
            }
            message({
              content: 'Smart event has been deleted successfully.',
              type: 'success',
            });
            handleClose();
          },
          onError: (error) => {
            message({
              content:
                'Something went wrong while deleting an event. Please try again.',
              type: 'error',
            });
            rollbar.error(
              error as Rollbar.LogArgument[],
              'Error while creating an event'
            );
          },
        }
      );
    }
  }, [
    currentAction,
    deleteEvent,
    appId,
    queryClient,
    dispatch,
    currentScreen,
    sessionDetail,
    setSessionNocodeEvents,
    sessionNocodeEvents,
    message,
    handleClose,
    setSessionDetail,
  ]);

  const displayScreenName = useMemo(
    () => currentScreen?.activityName || currentAction?.props?.activityName,
    [currentAction?.props?.activityName, currentScreen?.activityName]
  );

  return (
    <>
      <GlobalStyles />
      <Modal
        visible={deleteScreenEventPopupOpen}
        footer={null}
        onCancel={handleClose}
        closable={false}
        className="ant-modal-delete-nocode-event"
        wrapClassName="ant-modal-delete-nocode-event-wrapper"
        width={570}
      >
        <Title>
          Delete screen event <i>{currentAction?.name}</i> ?
        </Title>
        <StyledAlert
          showIcon
          icon={<InfoCircleOutlined />}
          rotate={ 180 }
          message={ <><b>Caution:</b> Deleting this event will impact the reports, funnels, and segments containing the event.</> }
        />
        <Label>
          You can recreate this event. The original interaction
          {' '}
          {displayScreenName ? (
            <>
              (<b>{displayScreenName}</b>)
            </>
          ) : (
            ''
          )}{' '}
          will remain in the sessions and continue to be captured.
        </Label>
        <Buttons>
          <ButtonNew
            width="medium"
            variant="ghost"
            onClick={handleClose}
            disabled={isLoading}
          >
            Cancel
          </ButtonNew>
          <ButtonNew
            width="medium"
            onClick={handleDeleteEvent}
            loading={isLoading}
          >
            Delete event
          </ButtonNew>
        </Buttons>
      </Modal>
    </>
  );
};

export default memo(DeleteSmartEventPopup);
