import React, { memo, useEffect, useLayoutEffect, useState } from 'react';
import { Tooltip } from 'antd';
import { RootStateOrAny, useDispatch, useSelector } from 'react-redux';
import { planhatPortalAccess, sidebarCollapse } from 'redux/actions/common';
import dynamic from 'next/dynamic';
import { RightExpandIcon } from 'public/static/redesign/sidebar';
import useSidebarUtils from '../hooks/useSidebarUtils';
import NewSideBarMenu from './NewSideBarMenu';
import BottomMenu from './BottomMenu';
import UpperMenu from './UpperMenu';
import {
  LeftCircleOutlinedWrapper,
  MiddleSection,
  SideBarWrapper,
} from './styles';
import { IntegrateMessage } from './variables';
import { ParentSideBarMenuProps } from './types';

const CreateAppModal = dynamic(import('components/common/createApp'), {
  loading: () => <div />,
});

const ParentSideBarMenu: React.FC<ParentSideBarMenuProps> = (props) => {
  const { collapsedMenu } = props;
  const dispatch = useDispatch();
  const sidebarScrollableDivRef = React.useRef<HTMLDivElement>(null);
  const [sidebarScrolled, setSidebarScrolled] = useState(0);
  // const [tooltipPosition, setTooltipPosition] = useState({ top: 0, left: 0 });

  useLayoutEffect(() => {
    const scrollableContainer = sidebarScrollableDivRef.current;
    if (scrollableContainer) {
      scrollableContainer.addEventListener('scroll', () => {
        if (scrollableContainer.scrollTop > 0) {
          setSidebarScrolled(scrollableContainer.scrollTop);
        } else {
          setSidebarScrolled(scrollableContainer.scrollTop);
        }
      });
    }
  }, []);

  const {
    showCreateApp,
    organizationIndex,
    urlRoutePageName,
    showAppList,
    displayAppListPopover,
    navigateToPath,
    navigateToAppTeam,
    showCreateAppBox,
    navigateToTeam,
    navigateToSubscription,
    navigateToAccountSetting,
    dispatchPortalLink,
    logout,
    setPortalData,
    portalData,
  } = useSidebarUtils();

  const {
    profileReducer: { email },
    currentAppReducer: { orgId, isIntegrated },
  } = useSelector((state: RootStateOrAny) => state);

  useEffect(() => {
    async function callPlanHatPortalAccessApi() {
      const portalAccessData = await dispatch(planhatPortalAccess(orgId, email));
      setPortalData(portalAccessData);
    }
    callPlanHatPortalAccessApi();
  }, [dispatch, orgId, email, setPortalData]); 

  // const handleMouseMove = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
  //   // Update the tooltip position based on mouse cursor movement
  //   setTooltipPosition({ top: e.clientY + 10, left: e.clientX + 10 });
  // }, []);

  return (
    <SideBarWrapper collapsedMenu={collapsedMenu}>
      <LeftCircleOutlinedWrapper
        collapsed={collapsedMenu}
        onClick={() => dispatch(sidebarCollapse(!collapsedMenu))}
      >
        <RightExpandIcon />
      </LeftCircleOutlinedWrapper>
      <div id="top">
        <UpperMenu
          organizationIndex={organizationIndex}
          urlRoutePageName={urlRoutePageName}
          showAppList={showAppList}
          displayAppListPopover={displayAppListPopover}
          navigateToPath={navigateToPath}
          navigateToAppTeam={navigateToAppTeam}
          collapsedMenu={collapsedMenu}
        />
      </div>
      <MiddleSection
        ref={sidebarScrollableDivRef}
        id="middle"
        isScrolled={sidebarScrolled > 0}
        // onMouseMove={(e: React.MouseEvent<HTMLDivElement>) => handleMouseMove(e)}
      >
        <Tooltip
          overlayClassName="is-integrated-message"
          // style={{ top: tooltipPosition.top, left: tooltipPosition.left }}
          title={ !isIntegrated ? IntegrateMessage : null }
          placement="rightTop"
          getPopupContainer={(triggerNode: HTMLElement) =>
            triggerNode.parentNode as HTMLElement
          }
        >
          <NewSideBarMenu collapsedMenu={collapsedMenu} />
          {/* empty span placed for tooltip display */}
          <span />
        </Tooltip>
      </MiddleSection>
      <div id="bottom">
        <BottomMenu
          organizationIndex={organizationIndex}
          navigateToTeam={navigateToTeam}
          navigateToAccountSetting={navigateToAccountSetting}
          navigateToSubscription={navigateToSubscription}
          urlRoutePageName={urlRoutePageName}
          dispatchPortalLink={dispatchPortalLink}
          collapsed={collapsedMenu}
          planHatPortalAccessData={portalData}
          logout={logout}
        />
      </div>
      {Boolean(showCreateApp) && (
        <CreateAppModal
          showCreateApp={showCreateApp}
          cancelCreateApp={showCreateAppBox}
          pageCalled="sidebar"
        />
      )}
    </SideBarWrapper>
  );
};

export default memo(ParentSideBarMenu);
