/* eslint-disable no-nested-ternary */
import React, { memo, useCallback, useMemo } from 'react';
import { Modal } from 'antd';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { createGlobalStyle } from 'styled-components';
import ButtonNew from 'components/common/ButtonNew';
import { useMutation, useQueryClient } from 'react-query';
import { deleteNocodeEvent } from 'components/features/sessions/hooks/useNocodeEvents';
import useMessage from 'hooks/useMessage';
import { rollbar } from 'components/common/rollbar';
import Rollbar from 'rollbar';
import { useDispatch, useSelector } from 'react-redux';
import { IReduxState } from 'types/reduxStateTypes';
import { gestureGenerateName } from 'components/shared/Sessions/DetailSideBar/Gestures/helpers';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';
import { ISessionTimeline } from 'types/sessionTypes';
import { trackPageViews } from 'redux/actions/trackingReport';
import { getFilterPropertyRemoteData } from 'redux/actions/filter';
import { InfoCircleOutlined } from '@ant-design/icons';
import {
  checkForAnyValue,
  removeNocodeEventFromSessionDetail,
} from '../helpers';
import { Buttons, Label, Title } from '../commonStyles';
import { StyledAlert } from '../../styles';

const GlobalStyles = createGlobalStyle`
	.ant-modal-delete-nocode-event-wrapper {
		display: flex;
		align-items: center;
	}
	.ant-modal-delete-nocode-event {
		top: 0;
		.ant-modal-content {
			border-radius: 8px;
			padding: 32px;
		}
		.ant-modal-body {
			padding: 0;
		}
	}
`;

const DeleteNoCodeEventPopup: React.FC = () => {
  const {
    deletePopupOpen,
    setDeletePopupOpen,
    currentAction,
    setCurrentAction,
    currentScreen,
    noCodeEventsFeatureFlag,
  } = useNoCodeEventsContext();
  const {
    sessionDetail,
    setSessionDetail,
    setSessionNocodeEvents,
    sessionNocodeEvents,
  } = useSessionTimeLine() as unknown as ISessionTimeline;
  const {
    currentAppReducer,
    appFilter: { dateSegment },
  } = useSelector((state: IReduxState) => state);
  const { _id: appId } = currentAppReducer;
  const { mutate: deleteEvent, isLoading } = useMutation(deleteNocodeEvent);
  const { message } = useMessage();
  const dispatch = useDispatch();
  const queryClient = useQueryClient();

  const getPayload = useCallback(
    () => ({
      attribute: 'nce_name',
      filter: [],
      search: '',
      dropdownLimit: 501,
      date_range: dateSegment,
    }),
    [dateSegment]
  );

  const gestureTypeStr = useMemo(
    () => currentAction?.props?.gestureType || 'not defined',
    [currentAction?.props?.gestureType]
  );
  const name = currentAction?.props?.viewName || currentAction?.props?.viewName;
  const viewType = currentAction?.props?.viewType || '';
  const generatedName = useMemo(
    () =>
      noCodeEventsFeatureFlag &&
      gestureGenerateName(
        gestureTypeStr,
        viewType,
        noCodeEventsFeatureFlag,
        name
      ),
    [viewType, name, noCodeEventsFeatureFlag, gestureTypeStr]
  );

  const handleClose = useCallback(() => {
    if (!isLoading) {
      setDeletePopupOpen(false);
      setCurrentAction(undefined);
    }
  }, [isLoading, setDeletePopupOpen, setCurrentAction]);

  const handleDeleteEvent = useCallback(() => {
	if (currentAction?.props) {
	  const { id: nceId } = currentAction;
	  deleteEvent(
		 {
			appId,
			nceId: nceId as unknown as number,
		 },
		 {
			onSuccess: () => {
			  queryClient.invalidateQueries({ queryKey: ['manage-nocode-list'] });
			  queryClient.invalidateQueries({ queryKey: ['nocodeEventList'] });
			  dispatch(getFilterPropertyRemoteData(getPayload(), false, true));
			  dispatch(
				 trackPageViews(null, {
					eventName: 'wa_remove_nocode_event',
					track_type: 'event',
					eventProperty: {
					  event_id: nceId,
					  screen_name: checkForAnyValue(
						 'activityName',
						 currentScreen?.activityName ||
							currentAction?.screenName ||
							'undefined'
					  ).value,
					  view_name: checkForAnyValue(
						 'viewName',
						 currentAction?.props?.viewName || 'undefined'
					  ).value,
					  view_type: currentAction?.props?.viewType || '',
					  element_id: checkForAnyValue(
						 'idString',
						 currentAction?.props?.idString || 'undefined'
					  ).value,
					  gesture_type: currentAction?.props?.viewTypeId,
					  gesture_name: gestureTypeStr,
					  event_name: currentAction?.name,
					  type_of_event: 'gesture',
					},
				 })
			  );
			  if (nceId && sessionDetail && currentScreen && currentAction) {
				 setSessionDetail(
					removeNocodeEventFromSessionDetail(
					  sessionDetail,
					  currentScreen,
					  nceId as unknown as number
					)
				 );
			  }
			  if (setSessionNocodeEvents && sessionNocodeEvents) {
				 setSessionNocodeEvents(
					sessionNocodeEvents.filter(
					  (event) => event.event_name !== currentAction?.name
					)
				 );
			  }
			  message({
				 content: 'Smart event has been deleted succesfully.',
				 type: 'success',
			  });
			  handleClose();
			},
			onError: (error) => {
			  message({
				 content:
					'Something went wrong while deleting an event. Please try again.',
				 type: 'error',
			  });
			  rollbar.error(
				 error as Rollbar.LogArgument[],
				 'Error while creating an event'
			  );
			},
		 }
	  );
	}
 }, [
	currentAction,
	deleteEvent,
	appId,
	queryClient,
	dispatch,
	getPayload,
	currentScreen,
	gestureTypeStr,
	sessionDetail,
	setSessionNocodeEvents,
	sessionNocodeEvents,
	message,
	handleClose,
	setSessionDetail,
 ]);

	return (
		<>
			<GlobalStyles />
			<Modal
				visible={ deletePopupOpen }
				footer={ null }
				onCancel={ handleClose }
				closable={ false }
				className='ant-modal-delete-nocode-event'
				wrapClassName='ant-modal-delete-nocode-event-wrapper'
				width={ 570 }
			>
				<Title>
					Delete smart event <i>{ currentAction?.name }</i> ?
				</Title>
				<StyledAlert 
					showIcon
					icon={<InfoCircleOutlined />}
					rotate={ 180 }
					message={ <><b>Caution:</b> Deleting this event will impact the reports, funnels, and segments containing the event.</> }
				/>
				<Label>
				 	You can recreate this event. The original interaction 
					{ generatedName ? (
						<>
							{ ' ' }
								(<b>{ generatedName }</b>)
							{ ' ' }
						</>
					) : ' ' }
					will remain in the sessions and continue to be captured.
				</Label>
				<Buttons>
					<ButtonNew 
						width='medium'
						variant='ghost'
						onClick={ handleClose }
						disabled={ isLoading }
					>
						Cancel
					</ButtonNew>
					<ButtonNew
						width='medium'
						onClick={ handleDeleteEvent }
						loading={ isLoading }
					>
						Delete event
					</ButtonNew>
				</Buttons>
			</Modal>
		</>
	)
}

export default memo(DeleteNoCodeEventPopup);
