import React, { useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux';
import { findIndex, isEmpty } from 'lodash'
import { addSessionId, addUserId } from 'redux/actions/common'
import AppFilterV2 from 'components/shared/GlobalFilter';
import useSegmentAPI from 'components/shared/GlobalFilter/components/SegmentMenu/hooks/useSegmentAPI';

const TopMenu = () => {
  const dispatch = useDispatch()
  const {
    currentOrgReducer: currentOrg,
    urlReducer: { parentType, },
    currentAppReducer: currentApp,
    applicationReducer: orgList,
  } = useSelector(state => state)
  const remainingTrial = !isEmpty(currentOrg.remainingTrial) && currentOrg.remainingTrial
  const orgIndex = findIndex(orgList, { orgId: currentApp.orgId })
  const isAccessGranted = React.useMemo(() => (orgList[orgIndex].dashboardAccess && (remainingTrial ? remainingTrial['hours'] + remainingTrial['days'] !== 0 : true)) || currentOrg['isLoggedFromAdminDashboard'], [orgList, orgIndex, remainingTrial, currentOrg])
  
  useSegmentAPI();

  useEffect(() => {
    dispatch(addSessionId([]))
    dispatch(addUserId([]))
  }, [parentType])
  
  if (isAccessGranted && currentApp.isIntegrated) return <AppFilterV2 key={parentType + currentApp['_id']} />
  return null;
}

export default TopMenu;
