import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import Router from 'next/router';
import mixpanel from 'mixpanel-browser';
import { useCallback, useMemo, useState } from 'react';
import { RootStateOrAny, useDispatch, useSelector } from 'react-redux';
import { planhatPortalAccess, planhatPortalLink } from 'redux/actions/common';
import { appSettingPage, entityPages } from '../menuBar/variables';

declare global {
  interface Window {
    Intercom: any;
  }
}

const useSidebarUtils = () => {

  const dispatch = useDispatch();

  const [showAppList, setShowAppList] = useState(false);
  const [showCreateApp, setShowCreateApp] = useState(false);
  const [portalData, setPortalData] = useState({});

  const {
    currentAppReducer: currentApp,
    applicationReducer: orgList,
    urlReducer: {
      parentType,
      funnelId,
      eventid,
    },
    appFilter,
    accessManagement: { planStatus },
  } = useSelector((state: RootStateOrAny) => state);

  const { _id: appId, orgId } = currentApp;

  const baseUrl = useMemo(() => `/app/${appId}`, [appId]);

  const sessionSegment = appFilter.session.segment;
  const userSegment = appFilter.user.segment;
  const eventSegment = appFilter.event.segment;
  const screenSegment = appFilter.screen.segment;
  const issueSegment = appFilter.issue.segment;
  const screenFlowSegment = appFilter.screenFlow.segment;
  const heatmapSegment = appFilter.heatmap.segment;
  const planDowngradeActive =
    planStatus?.selectAppAction || planStatus?.selectUserAction;

  const organizationIndex = useMemo(() => {
    if (currentApp?.error) {
      return 0;
    }
    return orgList?.findIndex((org: any) => org.orgId === currentApp.orgId);
  }, [currentApp, orgList]);

  const urlRoutePageName = useMemo(() => {
    const isLayoutSettingPages = appSettingPage.indexOf(parentType) > -1;
    if (!isLayoutSettingPages) {
      return entityPages[parentType as keyof typeof entityPages] || 'overview';
    }
    return 'overview';
  }, [parentType]);

  const displayAppListPopover = (value: boolean) => {
    setShowAppList(value);
  };

  const navigateToPath = () => {
    let url;
    let params;

    displayAppListPopover(false);

    if (appId) {
      url = `/settings/app/${orgId}/${appId}/video_recording_setting`;
      params = `/integration?parentType=settings&setting=app_setting&org=${orgId}&app=${appId}&app_tab=video_recording_setting`;
    } else if (orgList.length === 0) {
      url = `/settings/app`;
      params = `/integration?parentType=settings&setting=app_setting`;
    } else {
      url = `/settings/app/${orgList[0]['orgId']}`;
      params = `/integration?parentType=settings&setting=app_setting&org=${orgList[0]['orgId']}`;
    }
    Router.push(params, url);
  };

  const navigateToAppTeam = () => {
    let url;
    let params;

    displayAppListPopover(false);

    if (appId) {
      url = `/settings/app/${orgId}/${appId}/team`;
      params = `/integration?parentType=settings&setting=app_setting&org=${orgId}&app=${appId}&app_tab=team`;
    } else if (orgList.length === 0) {
      url = `/settings/app`;
      params = `/integration?parentType=settings&setting=app_setting`;
    } else if (orgList[0].apps.length) {
      url = `/settings/app/${orgList[0].apps[0].orgId}/${orgList[0].apps[0]['_id']}/team`;
      params = `/integration?parentType=settings&setting=app_setting&org=${orgList[0].orgId}&app=${orgList[0].apps[0]['_id']}&app_tab=team`;
    } else {
      url = `/settings/app/${orgList[0].orgId}`;
      params = `/integration?parentType=settings&setting=app_setting&org=${orgList[0].orgId}`;
    }
    Router.push(params, url);
  };

  const navigateToTeam = () => {
    let url;
    let params;

    displayAppListPopover(false);

    if (orgId) {
      url = `/settings/org/${orgId}/team`;
      params = `/integration?parentType=settings&setting=org_setting&org=${orgId}&org_tab=team`;
    } else if (orgList.length === 0) {
      url = `/settings/org}`;
      params = `/integration?parentType=settings&setting=org_setting}`;
    } else {
      url = `/settings/org/${orgList[0]['orgId']}/team`;
      params = `/integration?parentType=settings&setting=org_setting&org=${orgList[0]['orgId']}&org_tab=team`;
    }
    Router.push(params, url);
  };

  const navigateToSubscription = () => {
    let url;
    let params;

    displayAppListPopover(false);

    if (orgId) {
      url = `/settings/org/${orgId}/plan`;
      params = `/integration?parentType=settings&setting=org_setting&org=${orgId}&org_tab=plan`;
    } else if (orgList.length === 0) {
      url = `/settings/org}`;
      params = `/integration?parentType=settings&setting=org_setting}`;
    } else {
      url = `/settings/org/${orgList[0]['orgId']}/plan`;
      params = `/integration?parentType=settings&setting=org_setting&org=${orgList[0]['orgId']}&org_tab=plan`;
    }
    Router.push(params, url);
  };

  const navigateToAccountSetting = (e: MouseEvent) => {
    e.preventDefault();

    displayAppListPopover(false);

    const url = `/settings/profile`;
    const params = `/integration?parentType=settings&setting=profile_setting`;
    Router.push(params, url);
  };

  const dispatchPortalLink = (id: string) => {
    dispatch(planhatPortalLink(id))
  }

  const dispatchPlanHatPortalAccessData = (data: object) => {
    setPortalData(data)
  }

  const showCreateAppBox = () => {
    setShowCreateApp((prevShowCreateApp) => !prevShowCreateApp);
  };

  const getRouteUrl = useCallback(
    (value: string) => {
      let pageUrl;
      let segment;
      switch (value) {
        case 'overview':
          pageUrl = `${baseUrl}/overview`;
          break;
        case 'customDashboard':
          pageUrl = `${baseUrl}/customDashboard`;
          break;
        case 'sessionsList':
        case 'aiSessionsList':
          pageUrl = `${baseUrl}/aisessions/list/1/`;
          segment = sessionSegment;
          break;
        case 'sessionStatistics':
        case 'aiSessionStatistics':
          pageUrl = `${baseUrl}/aisessions/analytics`;
          segment = sessionSegment;
          break;
        case 'usersList':
          pageUrl = `${baseUrl}/users/list/1/`;
          segment = userSegment;
          break;
        case 'screensList':
          pageUrl = `${baseUrl}/heatmaps/list/1/`;
          segment = screenSegment;
          break;
        case 'heatmapsList':
          pageUrl = `${baseUrl}/screens/list`;
          segment = heatmapSegment;
          break;
        case 'webHeatmaps':
          pageUrl = `${baseUrl}/web-heatmap`;
          segment = heatmapSegment;
          break;
        case 'screenFlow':
          pageUrl = `${baseUrl}/screenflow`;
          segment = screenFlowSegment;
          break;
        case 'screenBurst':
          pageUrl = `${baseUrl}/screenburst`;
          segment = screenFlowSegment;
          break;
        case 'funnels':
          pageUrl = `${baseUrl}/funnels${funnelId ? `/${funnelId}` : ''}`;
          break;
        case 'eventsList':
          pageUrl = `${baseUrl}/events/list/1/${
            eventid && eventid !== 'undefined' ? eventid : ''
            }`;
          segment = eventSegment;
          break;
        case 'nocodeEventsList':
          pageUrl = `${baseUrl}/smart-events/list/1/${
            eventid && eventid !== 'undefined' ? eventid : ''
            }`;
          segment = eventSegment;
          break;
        case 'statistics': {
          pageUrl = `${baseUrl}/events/analytics`;
          const isSegmentNocode = !!eventSegment.find(
            (obj: { table: string }) => obj.table === 'no_code_event'
          );
          segment = isSegmentNocode ? [] : eventSegment;
          break;
        }
        case 'crashes':
          pageUrl = `${baseUrl}/issues/crashes`;
          segment = issueSegment;
          break;
        case 'freezes':
          pageUrl = `${baseUrl}/issues/freezes`;
          segment = issueSegment;
          break;
        case 'exceptions':
          pageUrl = `${baseUrl}/issues/exceptions`;
          segment = issueSegment;
          break;
        case 'insights':
          pageUrl = `${baseUrl}/insights`;
          break;
        case 'retention':
          pageUrl = `${baseUrl}/retention`;
          break;
        case 'guide':
          pageUrl = `${baseUrl}/guide`;
          break;
        default:
          break;
      }
      if (segment && segment.length) {
        pageUrl = urlSegmentEncoder(pageUrl, segment);
      }
      return planDowngradeActive ? '/plan-downgrade' : pageUrl;
    },
    [
      baseUrl,
      eventSegment,
      eventid,
      funnelId,
      heatmapSegment,
      issueSegment,
      planDowngradeActive,
      screenFlowSegment,
      screenSegment,
      sessionSegment,
      userSegment,
    ]
  );

  const getRouteQuery = useCallback(
    (pType: string, issue?: string) => {
      const newParentType = planDowngradeActive ? 'plan-downgrade' : pType;
      return `/integration?parentType=${ newParentType }&appId=${appId}&issueType=${issue}`;
    },
    [appId, planDowngradeActive]
  );

  const handleIntercom = async () => {
    typeof window !== 'undefined' && window.Intercom && window.Intercom('show');
  };

  const logout = () => {
    displayAppListPopover(false);
    let signupApp: string | null = ''
    try {
      signupApp = localStorage.getItem('signupApp')
      localStorage.clear();
      if (signupApp) {
        localStorage.setItem('signupApp', signupApp)
      }
      sessionStorage.clear();
    } catch (err) {
      // silent fail
    }
    typeof window !== 'undefined' &&
      window.Intercom &&
      window.Intercom('shutdown');
    mixpanel?.persistence?.clear();
    // *Clear Caches from Cache Storage
    if (typeof window !== 'undefined') {
      caches.delete('search-attribute-cache');
    }
    window.location.href = `${process.env.REDIRECT_URL}/logout`;
  };

  return {
    organizationIndex,
    urlRoutePageName,
    showAppList,
    showCreateApp,
    portalData,
    displayAppListPopover,
    navigateToPath,
    navigateToAppTeam,
    showCreateAppBox,
    getRouteUrl,
    getRouteQuery,
    navigateToTeam,
    navigateToSubscription,
    navigateToAccountSetting,
    dispatchPortalLink,
    dispatchPlanHatPortalAccessData,
    handleIntercom,
    logout,
    setPortalData,
  };
};

export default useSidebarUtils;
