import React, { useState } from 'react';
import styled from 'styled-components';
import { Tooltip } from 'antd';
import { Spinner } from 'uxcam-frontend-components';
import { theme } from 'theme';
import InfoIcon from 'public/static/icon-info.svg'
import { IMessage } from '../../..';
import { useCostDetails } from './useCostDetails';

interface ViewResponseInfoProps {
  message: IMessage;
  appId: string;
}

const InfoButton = styled.button`
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 6px !important;
  background-color: ${ theme.colors.surface05.toString() } !important;
  border: 1px solid ${ theme.colors.surface10.toString() } !important;
  border-radius: 30px !important;
  font-size: 12px;
  line-height: 20px;
  color: ${ theme.colors.surface400.toString() } !important;
  cursor: pointer;
  margin-top: 8px;
  transition: all 0.2s;

  &:hover {
    background-color: #E6E8EB !important;
    border-color: #BFBFBF !important;
  }

  svg {
    width: 16px;
    height: 16px;
  }
`;

const TooltipContent = styled.div`
  padding: 4px 0;
`;

const TooltipRow = styled.div`
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 13px;
  line-height: 20px;
  color: #fff;

  strong {
    font-weight: 600;
  }
`;

const LoadingWrapper = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
`;

const SpinnerContainer = styled.div`
  position: relative;
  width: 16px;
  height: 16px;
`;

const ViewResponseInfo: React.FC<ViewResponseInfoProps> = ({ message, appId }) => {
  const [isHovered, setIsHovered] = useState(false);
  const { invocation_id: invocationId } = message;

  const { data: costData, isLoading } = useCostDetails({
    invocationId,
    appId,
    enabled: isHovered,
  });

  const renderTooltipContent = () => {
    if (isLoading) {
      return (
        <LoadingWrapper>
          <SpinnerContainer>
            <Spinner data-size="xs" />
          </SpinnerContainer>
        </LoadingWrapper>
      );
    }

    if (!costData || !costData.cost_breakdown || costData.cost_breakdown.length === 0) {
      return <TooltipContent>No cost data available</TooltipContent>;
    }
    const breakdown = costData.cost_breakdown[0];

    const totalTokens = costData.total_tokens || 0;
    const totalCost = costData.total_cost || 0;
    const models = costData.models || [];
    const taraVersion = costData.tara_version || '';
    const provider = breakdown.provider || '';

    return (
      <TooltipContent>
        <TooltipRow>
          <strong>Tara version:</strong>
          <span>{taraVersion || breakdown?.tara_version}</span>
        </TooltipRow>
        <TooltipRow>
          <strong>Total tokens:</strong>
          <span>{totalTokens.toLocaleString()}</span>
        </TooltipRow>
        <TooltipRow>
          <strong>Total cost:</strong>
          <span>${totalCost.toFixed(4)}</span>
        </TooltipRow>
        <TooltipRow>
          <strong>Models:</strong>
          {
            models?.length > 0 ? (
              <span>{models.join(', ')}</span>
            ) : (
              <span>{provider} {breakdown.model || 'Default'}</span>
            )
          }
        </TooltipRow>
      </TooltipContent>
    );
  };

  return (
    <Tooltip
      title={renderTooltipContent()}
      placement="top"
      overlayStyle={{ maxWidth: 400 }}
      color="#1F1F1F"
    >
      <InfoButton
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        <InfoIcon />
        View response info
      </InfoButton>
    </Tooltip>
  );
};

export default ViewResponseInfo;
