import React, { memo, useCallback, useMemo } from 'react';
import { Form, Modal, Tooltip } from 'antd';
import Rollbar from 'rollbar';
import axios from 'axios';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { createGlobalStyle } from 'styled-components';
import ButtonNew from 'components/common/ButtonNew';
import { useMutation, useQueryClient } from 'react-query';
import { createNocodeEvent, createScreenSmartEvent } from 'components/features/sessions/hooks/useNocodeEvents';
import useMessage from 'hooks/useMessage';
import { rollbar } from 'components/common/rollbar';
import { useDispatch, useSelector } from 'react-redux';
import { IReduxState } from 'types/reduxStateTypes';
import IconDuplicate from 'public/static/icon-duplicate.svg';
import { TGestureName } from 'types/sessionTypes';
import { trackPageViews } from 'redux/actions/trackingReport';
import { gesturesTypesWithValue, gesturesViewTypeStringToInt } from 'components/features/heatmaps/constants';
import { ICreateNocodeResponse } from 'types/nocodeEvents';
import { checkForAnyValue, showTooltip } from '../helpers';
import { Buttons, Label, Title } from '../commonStyles';
import { EventWrapper, InputArea, InputLabel, InputText, LabelRight, LabelWrapper, ResponseWrapper, SubTitle } from '../../styles';
import AppSelector from './AppSelector';

interface IDuplicateFormProps {
    destination_app: string;
    event_name: string;
    event_description?: string;
}

const GlobalStyles = createGlobalStyle`
	.ant-modal-duplicate-nocode-event-wrapper {
		display: flex;
		align-items: center;
	}
	.ant-modal-duplicate-nocode-event {
		top: 0;
		.ant-modal-content {
			border-radius: 8px;
			padding: 32px;
		}
		.ant-modal-body {
			padding: 0;
		}
        input{
            margin-bottom: 0;
        }
        .ant-form-item-explain-error{
            font-size: 12px;
        }
        form#duplicate-smart-event{
            margin-top: 16px;
        }
	}
    .app-selector-dropdown{
        > div{
            width: 100%;
            max-width: 100%;
        }
        .ufc-dropdown-menu{
            max-width: 100%;
        }
    }
`;

const DuplicateSmartEventPopup: React.FC = () => {
    const {
        duplicateEventModalOpen,
        setDuplicateEventModalOpen,
        currentAction,
        setCurrentAction,
        currentScreen,
    } = useNoCodeEventsContext();

    const { currentAppReducer, applicationReducer, currentOrgReducer, screenRenamedList } = useSelector((state: IReduxState) => state);
    const [apiResponseMessage, setApiResponseMessage] = React.useState<{
        title: React.ReactNode | string;
        description: React.ReactNode | string;
    }>({
        title: null,
        description: null,
    });

    const orgId = currentOrgReducer?.orgId;
    const applicationList = useMemo(() => {
        if (!applicationReducer || !Array.isArray(applicationReducer)) {
            return []
        }

        return applicationReducer.find((app) => app.orgId === orgId)?.apps || []
    }, [applicationReducer, orgId]);
    const { _id: appId } = currentAppReducer;

    const appOptions = useMemo(
        () =>
            applicationList.map((app) => ({
                // eslint-disable-next-line no-underscore-dangle
                value: app._id,
                label: appId === app['_id'] ? `${app.name} (Current app)` : app.name,
                icon: app?.image || undefined
            })).sort((a, b) => {
                if (appId === a.value) {
                    return -1;
                } if (appId === b.value) {
                    return 1;
                }
                return 0;

            }),
        [appId, applicationList]
    );


    const { mutate: createEvent, isLoading: createIsLoading } = useMutation(createNocodeEvent);
    const { mutate: createScreenEvent, isLoading: createIsScreenLoading } = useMutation(createScreenSmartEvent);
    const { message } = useMessage();
    const dispatch = useDispatch();
    const queryClient = useQueryClient();
    const [form] = Form.useForm();

    const { setFieldsValue, getFieldValue, resetFields, setFields } = form

    const isScreenEvent = useMemo(() => currentAction?.eventType === 'Screen', [currentAction?.eventType]);

    const handleClose = useCallback(() => {
        if (!createIsLoading || !createIsScreenLoading) {
            setDuplicateEventModalOpen(false);
            setCurrentAction(undefined);
            setApiResponseMessage({
                title: null,
                description: null,
            });
            resetFields()
        }
    }, [createIsLoading, createIsScreenLoading, setDuplicateEventModalOpen, setCurrentAction, resetFields]);

    const triggerEvent = useCallback((nceId:number, destinationAppLabel: string) => {
        dispatch(
            trackPageViews(null, {
                eventName: 'wa_duplicate_nocode_event',
                track_type: 'event',
                eventProperty: {
                    screen_name: checkForAnyValue(
                        'activityName',
                        currentScreen?.activityName ||
                          currentAction?.screenName ||
                          'undefined'
                      ).value,
                    element_id: checkForAnyValue(
                      'idString',
                      currentAction?.props?.idString || 'undefined'
                    ).value,
                    gesture_name: currentAction?.props?.viewName || 'undefined',
                    gesture_type:
                      currentAction?.props?.gestureType || currentAction?.name,
                    event_id: nceId,
                    event_name: getFieldValue('event_name'),
                    type_of_event: isScreenEvent ? 'screenvisit' : 'gesture',
                    destination_app_name: destinationAppLabel,
                    destination_appid: getFieldValue('destination_app'),
                }
            })
        )
    }, [currentAction, currentScreen, dispatch, getFieldValue, isScreenEvent])
    
    const triggerError = useCallback((error: unknown) => {
        if (axios.isAxiosError(error)) {
            const errorObj =
                error?.request?.response &&
                JSON.parse(error.request.response)['error'];
            if (
                errorObj?.status === 409 &&
                errorObj?.message === 'Duplicate name.'
            ) {
                setFields([
                    {
                        name: 'event_name',
                        errors: ['Smart event with that name already exists in the selected app.'],
                    },
                ]);
                return;
            }
        }
        setApiResponseMessage({
            title: 'Event duplication failed',
            description: 'Something went wrong when trying to duplicate the smart event. Please try again later.',
        })
        rollbar.error(
            error as Rollbar.LogArgument[],
            'Error while duplicating an event'
        );
    }, [setFields])

    const handleCreateScreenEvent = useCallback((values: IDuplicateFormProps) => {
        const appLabel = appOptions.find((app) => app.value === values.destination_app)?.label;
        const filterdDestinationApp = appLabel?.replace(/\s*\(Current app\)$/, '');
        createScreenEvent(
            {
                name: values?.event_name?.trim(),
                description: values?.event_description,
                appid: values?.destination_app,
                orgid: orgId as string,
                platform: null,
                screen_name: [currentAction?.props?.activityName || ''],
                sdk_version: '',
                category: ['nocode'],
                previous_screen_name: [],
                next_screen_name: [],
                custom_property: {
                    access: "Yes"
                }
            },
            {
                onSuccess: (res) => {
                    const nceId = (res as ICreateNocodeResponse)?.data?.data?.nceId;
                    if (appId === values.destination_app) {
                        queryClient.invalidateQueries({ queryKey: ['manage-nocode-list'] });
                    }
                    setApiResponseMessage({
                        title: 'Event duplicated',
                        description: <> Your smart event <strong>&rsquo;{values.event_name}&rsquo;</strong> has been duplicated successfully. You can now find the event in {filterdDestinationApp}. </>
                    })
                    if( nceId && filterdDestinationApp ) triggerEvent(nceId, filterdDestinationApp)
                    },
                onError: (error) => {
                    triggerError(error)
                },
            }
        );
    }, [appId, appOptions, createScreenEvent, currentAction?.props?.activityName, orgId, queryClient, triggerError, triggerEvent])

    const handleCreateEvent = useCallback((values: IDuplicateFormProps) => {
        const appLabel = appOptions.find((app) => app.value === values.destination_app)?.label;
        const filterdDestinationApp = appLabel?.replace(/\s*\(Current app\)$/, '');        
        createEvent({
            name: values.event_name.trim(),
            description: values.event_description,
            appid: values.destination_app,
            element_id: [currentAction?.props?.idString] || [null],
            gesture_type: [gesturesTypesWithValue[currentAction?.props?.gestureType as TGestureName]],
            orgid: orgId,
            platform: null,
            sdk_version: '',
            screen_name: [currentAction?.screenName || ''],
            view_name: [currentAction?.props?.viewName] || [null],
            view_type: [gesturesViewTypeStringToInt[currentAction?.props?.viewType as keyof typeof gesturesViewTypeStringToInt]],
            category: ['nocoode'],
        }, {
            onSuccess: (res) => {
                const nceId = (res as ICreateNocodeResponse)?.data?.data?.nceId;
                if (appId === values.destination_app) {
                    queryClient.invalidateQueries({ queryKey: ['manage-nocode-list'] });
                }
                setApiResponseMessage({
                    title: 'Event duplicated',
                    description: <> Your smart event <strong>&rsquo;{values.event_name}&rsquo;</strong> has been duplicated successfully. You can now find the event in {filterdDestinationApp}. </>
                })
                if( nceId && filterdDestinationApp ) triggerEvent(nceId, filterdDestinationApp)
            },
            onError: (error) => {
                triggerError(error)
            },
        })
    }, [appId, appOptions, createEvent, currentAction?.props?.gestureType, currentAction?.props?.idString, currentAction?.props?.viewName, currentAction?.props?.viewType, currentAction?.screenName, orgId, queryClient, triggerError, triggerEvent])

    const handleDuplicateEvent = useCallback((values: IDuplicateFormProps) => {
        if (values && orgId && currentAction) {
            if (!isScreenEvent) {
                handleCreateEvent(values)
            } else {
                handleCreateScreenEvent(values)
            }
        } else {
            message({
                content: 'Something went wrong while creating an event',
                type: 'error',
            });
            rollbar.error(
                [
                    appId &&
                    currentAction?.name &&
                    orgId &&
                    //   device?.platform &&
                    //   device?.sdkVersion &&
                    currentAction?.props?.viewType,
                ],
                'Error with values when creating event'
            );
            message({
                content: 'Something went wrong while creating an event',
                type: 'error',
            });
        }
    }, [appId, currentAction, handleCreateEvent, handleCreateScreenEvent, isScreenEvent, message, orgId]);

    const displayScreenName = useMemo(
        () => currentScreen?.activityName || currentAction?.props?.activityName || currentAction?.screenName,
        [currentAction?.props?.activityName, currentAction?.screenName, currentScreen?.activityName]
    );

    const gestureTypeStr = useMemo(() => {
        if (currentAction?.type === 'gesture') {
            return currentAction?.name || 'Undefined';
        }

        return currentAction?.props?.gestureType || 'Undefined';
    }, [
        currentAction?.name,
        currentAction?.props?.gestureType,
        currentAction?.type,
    ]);

    const smartRule = useMemo(
        () => currentAction?.props?.rule,
        [currentAction?.props?.rule]
    );

    const renamedScreenName = useMemo(() => screenRenamedList[displayScreenName || ''] || displayScreenName, [displayScreenName, screenRenamedList]);

    React.useEffect(() => {
        resetFields();
        if (currentAction?.name) {
            setFieldsValue({
                'event_name': `Copy of ${currentAction?.name}`,
            });
        }
    }, [currentAction, resetFields, setFieldsValue]);

    return (
        <>
            <GlobalStyles />
            <Modal
                visible={duplicateEventModalOpen}
                footer={null}
                onCancel={handleClose}
                closable={false}
                className="ant-modal-duplicate-nocode-event"
                wrapClassName="ant-modal-duplicate-nocode-event-wrapper"
                width={570}
            >
                {
                    apiResponseMessage?.title && apiResponseMessage.description ? (
                        <ResponseWrapper>
                            <Title>
                                {apiResponseMessage.title}
                            </Title>
                            <SubTitle>
                                {apiResponseMessage.description}
                            </SubTitle>
                            <ButtonNew
                                onClick={handleClose}
                                width="medium"
                                type='button'
                            >
                                Ok
                            </ButtonNew>
                        </ResponseWrapper>
                    ) : (
                        <>
                            <Title>
                                <IconDuplicate /> Duplicate smart event
                            </Title>
                            <EventWrapper isEditable>
                                <LabelWrapper>
                                    <Label>
                                        <b>Screen name:</b>
                                    </Label>
                                    <LabelRight isUneditable>
                                        <span>{checkForAnyValue('activityName',renamedScreenName as string).jsx}</span>
                                    </LabelRight>
                                </LabelWrapper>
                                {
                                    isScreenEvent ? (
                                        <>
                                            <LabelWrapper>
                                                <Label>
                                                    <b>Original screen name:</b>
                                                </Label>
                                                <LabelRight isUneditable>
                                                    <span>{displayScreenName || <i>Undefined</i>}</span>
                                                </LabelRight>
                                            </LabelWrapper>
                                            <LabelWrapper>
                                                <Label>
                                                    <b>Event type:</b>
                                                </Label>
                                                <LabelRight isUneditable>
                                                    <span>{currentAction?.eventType || <i>Undefined</i>}</span>
                                                </LabelRight>
                                            </LabelWrapper>
                                        </>
                                    ) : (
                                        <>
                                            <LabelWrapper>
                                                <Label>
                                                    <b>Gesture type:</b>
                                                </Label>
                                                <LabelRight isUneditable>
                                                    <span>{gestureTypeStr}</span>
                                                </LabelRight>
                                            </LabelWrapper>
                                            <LabelWrapper>
                                                <Label>
                                                    <b>UI element type:</b>
                                                </Label>
                                                <LabelRight isUneditable>
                                                    <span>
                                                        {currentAction?.props?.viewType || <i>Undefined</i>}
                                                    </span>
                                                </LabelRight>
                                            </LabelWrapper>
                                            <LabelWrapper>
                                                <Label>
                                                    <b>UI element name:</b>
                                                </Label>
                                                <LabelRight isUneditable>
                                                    <span>
                                                        <Tooltip
                                                            overlay={
                                                                showTooltip(currentAction?.props?.viewName) &&
                                                                currentAction?.props?.viewName
                                                            }
                                                            placement="top"
                                                        >
                                                            {
                                                                checkForAnyValue(
                                                                    'viewName',
                                                                    currentAction?.props?.viewName || 'undefined',
                                                                    smartRule
                                                                ).jsx
                                                            }
                                                        </Tooltip>
                                                    </span>
                                                </LabelRight>
                                            </LabelWrapper>
                                            <LabelWrapper>
                                                <Label>
                                                    <b>UI element ID:</b>
                                                </Label>
                                                <LabelRight isUneditable>
                                                    <span>
                                                        <Tooltip
                                                            overlay={
                                                                showTooltip(currentAction?.props?.idString) &&
                                                                currentAction?.props?.idString
                                                            }
                                                            placement="top"
                                                        >
                                                            {
                                                                checkForAnyValue(
                                                                    'idString',
                                                                    currentAction?.props?.idString || 'undefined',
                                                                    smartRule
                                                                ).jsx
                                                            }
                                                        </Tooltip>
                                                    </span>
                                                </LabelRight>
                                            </LabelWrapper>
                                        </>
                                    )
                                }
                            </EventWrapper>
                            <Form
                                form={form}
                                name='duplicate-smart-event'
                                onFinish={handleDuplicateEvent}
                            >
                                <InputLabel>
                                    <b>Destination app</b>
                                </InputLabel>
                                <Form.Item
                                    name="destination_app"
                                    rules={[{ required: true, message: 'Please provide a destination app' }]}
                                    shouldUpdate
                                >
                                    <AppSelector
                                        appList={appOptions}
                                        getFieldValue={getFieldValue}
                                        setFieldsValue={setFieldsValue}
                                    />
                                </Form.Item>
                                <InputLabel>
                                    <b>Event name</b>
                                </InputLabel>
                                <Form.Item
                                    name="event_name"
                                    rules={[
                                        { required: true, message: 'Please provide an event name' },
                                        {
                                            max: 50,
                                            message:
                                                'The event name is too long. Please make it shorter.',
                                        },
                                    ]}
                                    shouldUpdate
                                >
                                    <InputText placeholder="Add event name" disabled={createIsLoading || createIsScreenLoading} />
                                </Form.Item>
                                <InputLabel>
                                    <b>Description</b>
                                </InputLabel>
                                <Form.Item
                                    name="event_description"
                                    className="text-area"
                                    rules={[
                                        {
                                            max: 500,
                                            message:
                                                'The description is too long. Please make it shorter.',
                                        },
                                    ]}
                                >
                                    <InputArea placeholder="Add description" disabled={createIsLoading || createIsScreenLoading} />
                                </Form.Item>
                                <Buttons>
                                    <ButtonNew
                                        width="medium"
                                        variant="ghost"
                                        onClick={handleClose}
                                        disabled={createIsLoading || createIsScreenLoading}
                                    >
                                        Cancel
                                    </ButtonNew>
                                    <ButtonNew
                                        width="medium"
                                        type='submit'
                                        loading={createIsLoading || createIsScreenLoading}
                                    >
                                        Duplicate
                                    </ButtonNew>
                                </Buttons>
                            </Form>
                        </>
                    )
                }

            </Modal>
        </>
    );
};

export default memo(DuplicateSmartEventPopup);
