const SessionWatchStatusModal = () => {
	const {
		batchModalVisible,
		state,
		selected,
		remainingCredits,
		isFreeCustomer,
		setItems,
		setBatchModalVisible,
		setErrorModalVisible,
		setPopupVisibility,
		triggerManualCheck,
		setSessionProcessingErrorModalVisible,
		orgId,
		creditsConversion,
		totalCredits,
	} = useAISessionWatchlist()
	const { close } = useFloatingToolbarContext()
	const dispatch = useDispatch()
	const {
		currentAppReducer: { _id: appID },
		appFilter: {
			dateSegment,
			session: {
				segment: sessionSegments,
			},
		},
		profileReducer: { name }
	 } = useSelector( ( rState: IReduxState ) => rState)
	const [form] = Form.useForm()
	const [creditsSelected, setCreditsSelected] = useState<TMaxProcessingCreditsBatch>(30)
	const queryClient = useQueryClient()
	const { isLoggedInAsAdminAdmin } = useIsLoggedInAdmin()
	const router = useRouter()
	const { parentType } = router.query

	// Helper function to optimistically update AI usage data
	const updateAIUsageOptimistically = useCallback((scheduledCredits: number) => {
		if (!orgId) return

		const queryKey = `ai_usage_overview_${orgId}`
		const currentData = queryClient.getQueryData<TAIUsageOverview>(queryKey)

		if (currentData) {
			// Optimistically update scheduled minutes
			queryClient.setQueryData(queryKey, {
				...currentData,
				scheduled_tara_credit: ( currentData.scheduled_tara_credit || 0 ) + scheduledCredits
			} )
		}

		// Refetch to get actual values from server
		queryClient.refetchQueries(queryKey)
	}, [orgId, queryClient])

	const handleClose = useCallback(() => {
		setTimeout( () => {
			form.resetFields()
		}, 300)
		setBatchModalVisible( false )
	}, [ setBatchModalVisible, form ])

	const { isLoading: isLoadingSelected, mutateAsync: mutateAsyncSelected } = useMutation( {
		mutationFn: processSelectedSessions,
		retry: false,
		onError: () => {
			setBatchModalVisible( false )
			setErrorModalVisible( true )
		},
		onSuccess: ( responseData, vars ) => {
			const data = responseData as { success?: boolean; data?: { status?: string } }
			if ( data?.data?.status === 'no_sessions_found' ) {
				handleClose()
				setSessionProcessingErrorModalVisible( true )
				return
			}

			const { batch_name, session_ids } = vars
			const date = new Date().toISOString()
			const totalTime = selected.reduce( ( acc, curr ) => acc + Math.ceil( curr.sessionDuration ), 0 )
			const totalRequestedCredits = Math.ceil( totalTime / 60 ) * (creditsConversion.tara_credits / creditsConversion.video_minutes)

			setItems( prev => [
				{
					id: date,
					createdAt: date,
					analyzedCount: session_ids.length,
					name: batch_name,
					requestedCredits: totalRequestedCredits,
					scheduledByName: name,
					analyzedCredits: 0,
					completedStatus: false,
					source: 'session',
				},
				...prev
			] )

			// Optimistically update AI usage data
			updateAIUsageOptimistically(totalRequestedCredits)

			// Refresh data from server to ensure we have the latest batch info
			triggerManualCheck()

			handleClose()
			setPopupVisibility( true )
			// Don't enforce popup for newly added items - only enforce when items complete
			close()
		}
	} )
	
	const { isLoading: isLoadingBatch, mutateAsync: mutateAsyncBatch } = useMutation( {
		mutationFn: processBatchSessions,
		retry: false,
		onError: () => {
			setBatchModalVisible( false )
			setErrorModalVisible( true )
		},
		onSuccess: ( responseData, vars ) => {
			const { batch_name, max_processing_time_minutes } = vars
			const date = new Date().toISOString()
			const totalRequestedCredits = Math.ceil( max_processing_time_minutes || 0 ) * (creditsConversion.tara_credits / creditsConversion.video_minutes)

			const data = responseData as { success?: boolean; data?: { status?: string } }
			if ( data?.data?.status === 'no_sessions_found' ) {
				handleClose()
				setSessionProcessingErrorModalVisible( true )
				return
			}

			setItems( prev => [
				{
					id: date,
					createdAt: date,
					name: batch_name,
					requestedCredits: totalRequestedCredits || 0,
					scheduledByName: name,
					analyzedCredits: 0,
					completedStatus: false,
					source: 'batch',
				},
				...prev
			] )

			// Optimistically update AI usage data
			updateAIUsageOptimistically(totalRequestedCredits)

			// Refresh data from server to ensure we have the latest batch info
			triggerManualCheck()

			handleClose()
			setPopupVisibility( true )
			// Don't enforce popup for newly added items - only enforce when items complete
		}
	} )

	const handleCreditsChange = useCallback( (newCredits: number) => {
		if ( ![ 15, 30, 60, 90 ].includes( newCredits ) ) {
			throw new Error( 'Credits can be only 30 60 or 90 mins')
		}

		setCreditsSelected(newCredits as TMaxProcessingCreditsBatch)
	}, [] )

	const estimatedSessions = useMemo(() => {
		if (!creditsConversion) return 0

		const taraCredits = Number(creditsConversion.tara_credits)
		const videoMinutes = Number(creditsConversion.video_minutes)

		if (!taraCredits || !videoMinutes || taraCredits === 0 || videoMinutes === 0 || Number.isNaN(taraCredits) || Number.isNaN(videoMinutes)) {
			return 0
		}

		// Use the lesser of creditsSelected or remainingCredits
		const creditsToUse = Math.min(creditsSelected, remainingCredits)

		// Convert credits to minutes using conversion ratio
		const totalMinutes = creditsToUse * (videoMinutes / taraCredits)

		// Divide by average session length (1.5 minutes)
		const result = Math.round(totalMinutes / 1.5)

		return Number.isNaN(result) ? 0 : result
	}, [creditsSelected, remainingCredits, creditsConversion])

	const handleSubmit = useCallback( async () => {
		const values = await form.validateFields()
		const sessionIds = selected?.map( el => el.sessionid )
		const isSelected = !!selected?.length

		const approximateSessions = isSelected
			? selected.length
			: estimatedSessions

		const creditsUsed = isSelected
			? Math.ceil( selected.reduce( ( acc, curr ) => acc + Math.ceil( curr.sessionDuration ), 0 ) / 60 ) * (creditsConversion.tara_credits / creditsConversion.video_minutes)
			: creditsSelected

		dispatch(trackSubmitBatchRequest({
			batchName: values.batchName,
			approximateSessions,
			creditsUsed,
			creditsRemaining: remainingCredits,
			filtersApplied: sessionSegments,
			parentType: (parentType as string) || 'unknown',
			type: isSelected ? 'session' : 'batch'
		}))

		const payload: TBatchPayload | TSelectedPayload = {
			// eslint-disable-next-line @typescript-eslint/no-non-null-assertion
			"appid": appID!,
			"date_range": dateSegment,
			"batch_name": values.batchName,
			"filters": sessionSegments || [],
			...( !isSelected ? { "requested_credits_usage": creditsSelected } : {} ),
			...( isSelected ? { "session_ids": sessionIds } : {} ),
		}

		if ( isSelected ) {
			await mutateAsyncSelected( payload as TSelectedPayload )
		} else {
			await mutateAsyncBatch( payload )
		}
	}, [ form, selected, appID, dateSegment, creditsSelected, mutateAsyncSelected, mutateAsyncBatch, sessionSegments, estimatedSessions, creditsConversion, remainingCredits, parentType ] )

	const isLoading = isLoadingSelected || isLoadingBatch

	const footer = useMemo( () => {
		const label = isLoading ? <Spin indicator={<LoadingOutlined style={{ fontSize: 16, color: 'white' }} spin />} /> : 'Let Tara Watch'

		return (
			<Footer>
				<StyledButton
					type="button"
					variant="ghost"
					size="large"
					disabled={ isLoading }
					onClick={handleClose}
				>
					Cancel
				</StyledButton>
				<StyledButton
					type="button"
					variant="primary"
					size="large"
					disabled={ isLoading || remainingCredits === 0 }
					onClick={ handleSubmit }
				>
					{ label }
				</StyledButton>
			</Footer>
		)
	}, [ handleClose, handleSubmit, isLoading, remainingCredits ] )

	const subTitle = useMemo( () => {
		switch( state ) {
			case 'filtered':
				return 'Tara will watch sessions that match your filters to better answer  your questions'
			case 'selected':
			case 'selectedFiltered':
				return 'Tara will focus on the selected sessions to better answer your questions'
			default:
				return 'Tara will watch more sessions from the selected date range to better answer your questions'
		}
	}, [ state ] )

	const isSelected = state === 'selectedFiltered' || state === 'selected'
	const boxSubTitle = isSelected ? 'Tara will attempt to watch' : 'Tara will watch'
	const boxTitle = isSelected ? `${ selected?.length } session${ getS( selected ) }` : `~${ estimatedSessions } session${ getS( estimatedSessions ) }`

	const maxUsageValue = useMemo(() => {
		if ( state !== 'selected' && state !== 'selectedFiltered' ) {
			return creditsSelected
		}

		if (!creditsConversion) {
			return remainingCredits
		}

		const taraCredits = Number(creditsConversion.tara_credits)
		const videoMinutes = Number(creditsConversion.video_minutes)

		if (!taraCredits || !videoMinutes || taraCredits === 0 || videoMinutes === 0 || Number.isNaN(taraCredits) || Number.isNaN(videoMinutes)) {
			return remainingCredits
		}

		const durationSumOfSelectedSec = Math.round( selected?.reduce( ( prev, curr ) => prev + curr.sessionDuration, 0 ) || 0 )
		const processingTimeLeftSec = ( remainingCredits * (videoMinutes / taraCredits) ) * 60

		if ( durationSumOfSelectedSec < processingTimeLeftSec ) {
			return Math.ceil( durationSumOfSelectedSec / 60 )
		}
		return remainingCredits
	}, [ creditsSelected, state, selected, remainingCredits, creditsConversion ])
	const showLowLimit = !isFreeCustomer && remainingCredits < 50
	
	return (
		<>
			<GlobalStyles />
			<UFCModal
				visible={ batchModalVisible }
				footer={ footer }
				closable={ false }
				className='duration-modal'
				style={{top: 0}}
			>
				<Titles>
					<Title>
						Have Tara watch more sessions
					</Title>
					<SubTitle>
						{ subTitle }
					</SubTitle>
				</Titles>
				{ showLowLimit && !isSelected && <LowLimitBox /> }
				<Box>
					<BoxSubTitle>
						{ boxSubTitle }
					</BoxSubTitle>
					<BoxTitle>
						{ boxTitle }
					</BoxTitle>
					<BoxDesc>
						Using up to
						<span>{ Math.ceil( maxUsageValue ) } credit{ getS( Math.ceil( maxUsageValue ) ) }</span>
						from your plan
					</BoxDesc>
					{ !isSelected && (
						<BoxFooter>
							Estimated count based on an average session length (~1.5 min)
						</BoxFooter>
					) }
				</Box>
				{ !isSelected && (
					<SliderSection>
						<WatchCreditsSlider
							onChange={handleCreditsChange}
							creditsLeft={ remainingCredits }
							totalCredits={ totalCredits }
							isAdmin={ isLoggedInAsAdminAdmin }
						/>
					</SliderSection>
				) }
				<Form form={form} layout="vertical">
					<InputSection>
						<InputLabelContainer>
							<InputLabel>
								Batch name
							</InputLabel>
							{ isSelected && (
								<CreditsLeft
									creditsLeft={ remainingCredits }
									totalCredits={ totalCredits }
								/>
							) }
						</InputLabelContainer>
						<Form.Item
							name="batchName"
							rules={[
								{ required: true, message: 'Name your batch to continue' },
								{ min: 1, message: 'Batch name must be at least 1 character' },
								{ max: 50, message: 'Batch name must be less than 50 characters' }
							]}
							validateTrigger={['onBlur', 'onChange']}
							style={{ margin: 0 }}
						>
							<Input
								type="text"
								placeholder="Create a name for this batch"
								disabled={ isLoading || remainingCredits === 0 }
							/>
						</Form.Item>
					</InputSection>
				</Form>
	
				<InforBox>
					<span>Note: </span>
					Tara automatically excludes sessions longer than 20 minutes or without a video.
				</InforBox>
			</UFCModal>
		</>
	)
}

export default SessionWatchStatusModal