import React, { useState, useCallback, useEffect, memo } from 'react';
import styled from 'styled-components';
import { Tooltip } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';
import { IReduxState } from 'types/reduxStateTypes';
import IconThumbsUp from 'public/static/ai/icon-thumbs-up.svg';
import IconThumbsUpHover from 'public/static/ai/icon-thumbs-up-hover.svg';
import IconThumbsUpActive from 'public/static/ai/icon-thumbs-up-active.svg';
import IconThumbsDown from 'public/static/ai/icon-thumbs-down.svg';
import IconThumbsDownHover from 'public/static/ai/icon-thumbs-down-hover.svg';
import IconThumbsDownActive from 'public/static/ai/icon-thumbs-down-active.svg';
import { FeedbackType, submitFeedback } from 'services/feedbackApi';
import { useFeedbackModal } from 'components/common/Contexts/FeedbackModalContext';
import { useTaraAPIVersion } from 'components/common/Contexts/APIVersionContext';
import { buildCometLink } from 'components/common/AIAssistant/utils';

interface IFeedbackButtons {
  messageId: string;
  invocationId: string;
  sessionId: string;
  initialFeedback?: null | 'positive' | 'negative';
}

const FeedbackContainer = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
`;

const FeedbackButton = styled.button`
  background: transparent !important;
  border: none !important;
  cursor: pointer !important;
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: relative !important;
  width: 16px !important;
  height: 16px !important;

  &:disabled {
    cursor: not-allowed !important;
    opacity: 0.5 !important;
  }
`;

const FeedbackButtons: React.FC<IFeedbackButtons> = ({
  messageId,
  invocationId,
  sessionId,
  initialFeedback,
}) => {
  const dispatch = useDispatch();
  const { currentAppReducer: { _id: appId } } = useSelector((state: IReduxState) => state);
  const { openModal, isSubmitting, submittedMessageId, setSubmittedMessageId } = useFeedbackModal();
  const { currentVersion } = useTaraAPIVersion();

  const [feedback, setFeedback] = useState<FeedbackType>(initialFeedback ?? null);
  const [hoveredButton, setHoveredButton] = useState<'up' | 'down' | null>(null);
  const [isSubmittingPositive, setIsSubmittingPositive] = useState(false);

  const [thumbsUpTooltipOpen, setThumbsUpTooltipOpen] = useState(false);
  const [thumbsDownTooltipOpen, setThumbsDownTooltipOpen] = useState(false);

  // Listen for successful negative feedback submission from the modal
  useEffect(() => {
    if (submittedMessageId === messageId) {
      setFeedback('negative');
      // Clear the submitted message ID after handling
      setSubmittedMessageId(null);
    }
  }, [submittedMessageId, messageId, setSubmittedMessageId]);

  const handlePositiveFeedback = useCallback(async () => {
    // Force close tooltip immediately to prevent it sticking after layout shift
    setThumbsUpTooltipOpen(false);

    if (isSubmittingPositive || isSubmitting) return;

    // Toggle off if already positive, otherwise set to positive
    const newFeedback = feedback === 'positive' ? null : 'positive';
    const previousFeedback = feedback;
    setFeedback(newFeedback);

    setIsSubmittingPositive(true);
    try {
      await submitFeedback({
        feedback_type: newFeedback,
        why_bad_response: null,
        improvement_suggestion: null,
        app_id: appId || '',
        session_id: sessionId,
        invocation_id: invocationId,
      }, currentVersion);

      if (newFeedback === 'positive') {
        dispatch(
          trackPageViews(null, {
            eventName: 'wa_ai_submit_feedback',
            track_type: 'event',
            eventProperty: {
              feedback: 'thumbs_up',
              link: buildCometLink(invocationId),
            },
          })
        );
      } else {
        dispatch(
          trackPageViews(null, {
            eventName: 'wa_ai_remove_feedback',
            track_type: 'event',
            eventProperty: {
              feedback: 'thumbs_up',
            },
          })
        );
      }
    } catch (error) {
      console.error('Failed to submit positive feedback:', error);
      // Revert on error
      setFeedback(previousFeedback);
    } finally {
      setIsSubmittingPositive(false);
    }
  }, [feedback, messageId, invocationId, sessionId, appId, dispatch, isSubmittingPositive, isSubmitting, currentVersion]);

  const handleNegativeFeedback = useCallback(async () => {
    // Force close tooltip immediately to prevent it sticking after layout shift
    setThumbsDownTooltipOpen(false);

    if (isSubmittingPositive || isSubmitting) return;

    // Toggle off if already negative - send API call to clear
    if (feedback === 'negative') {
      const previousFeedback = feedback;
      setFeedback(null);

      setIsSubmittingPositive(true);
      try {
        await submitFeedback({
          feedback_type: null,
          why_bad_response: null,
          improvement_suggestion: null,
          app_id: appId || '',
          session_id: sessionId,
          invocation_id: invocationId,
        }, currentVersion);

        dispatch(
          trackPageViews(null, {
            eventName: 'wa_ai_remove_feedback',
            track_type: 'event',
            eventProperty: {
              feedback: 'thumbs_down',
            },
          })
        );
      } catch (error) {
        console.error('Failed to clear negative feedback:', error);
        // Revert on error
        setFeedback(previousFeedback);
      } finally {
        setIsSubmittingPositive(false);
      }
      return;
    }

    // Open the shared modal via context
    openModal(messageId, invocationId, sessionId);
  }, [feedback, isSubmittingPositive, isSubmitting, openModal, messageId, invocationId, sessionId, appId, dispatch, currentVersion]);

  // Listen for feedback submission from modal (via custom event or callback)
  // For now, we'll set the feedback state when the modal closes successfully
  // This will be handled by the parent component that manages the modal

  const renderThumbsUpIcon = () => {
    if (feedback === 'positive') {
      return <IconThumbsUpActive />;
    }
    if (hoveredButton === 'up') {
      return <IconThumbsUpHover />;
    }
    return <IconThumbsUp />;
  };

  const renderThumbsDownIcon = () => {
    if (feedback === 'negative') {
      return <IconThumbsDownActive />;
    }
    if (hoveredButton === 'down') {
      return <IconThumbsDownHover />;
    }
    return <IconThumbsDown />;
  };

  const getThumbsUpTooltip = () => {
    if (feedback === 'positive') {
      return 'You responded positively';
    }
    return 'Positive response';
  };

  const getThumbsDownTooltip = () => {
    if (feedback === 'negative') {
      return 'You responded negatively';
    }
    return 'Negative response';
  };

  // Only show the active button when feedback is given
  // User must click the active button to deactivate it before switching
  const showThumbsDown = feedback !== 'positive';
  const showThumbsUp = feedback !== 'negative';

  return (
    <FeedbackContainer>
      {showThumbsDown && (
        <Tooltip
          title={getThumbsDownTooltip()}
          visible={thumbsDownTooltipOpen}
          onVisibleChange={setThumbsDownTooltipOpen}
        >
          <FeedbackButton
            onClick={handleNegativeFeedback}
            onMouseEnter={() => setHoveredButton('down')}
            onMouseLeave={() => setHoveredButton(null)}
            disabled={isSubmittingPositive || isSubmitting}
            aria-label={getThumbsDownTooltip()}
          >
            {renderThumbsDownIcon()}
          </FeedbackButton>
        </Tooltip>
      )}
      {showThumbsUp && (
        <Tooltip
          title={getThumbsUpTooltip()}
          visible={thumbsUpTooltipOpen}
          onVisibleChange={setThumbsUpTooltipOpen}
        >
          <FeedbackButton
            onClick={handlePositiveFeedback}
            onMouseEnter={() => setHoveredButton('up')}
            onMouseLeave={() => setHoveredButton(null)}
            disabled={isSubmittingPositive || isSubmitting}
            aria-label={getThumbsUpTooltip()}
          >
            {renderThumbsUpIcon()}
          </FeedbackButton>
        </Tooltip>
      )}
    </FeedbackContainer>
  );
};

export default memo(FeedbackButtons);
