/* eslint-disable no-param-reassign */
import React from 'react'
import styled from 'styled-components'

interface IProps {
	dateRef: React.MutableRefObject<string | null>
	timestamp: string | undefined
}

const DividerWrapper = styled.div`
	width: 100%;
	display: flex;
	justify-content: center;
	position: relative;
	z-index: 1;
	&:not(:first-of-type) {
		margin-top: 40px; // was 72 px before
	}
	&:first-of-type {
		margin-top: 13px;
	}
	&::after {
		content: '';
		position: absolute;
		top: calc(50% - 1px);
		left: 20px;
		right: 20px;
		height: 1px;
		background-color: #F3F4F5;
	}
`

const Divider = styled.div`
	padding: 0px 9px;
	border: 1px solid #F3F4F5;
	border-radius: 4px;
	font-size: 10px;
	line-height: 20px;
	color: #737886;
	background-color: #ffffff;
	z-index: 2;
	position: relative;
	&::before {
		content: '';
		position: absolute;
		top: 0;
		left: -9px;
		width: 8px;
		height: 100%;
		background-color: #ffffff;
	}
	&::after {
		content: '';
		position: absolute;
		top: 0;
		right: -9px;
		width: 8px;
		height: 100%;
		background-color: #ffffff;
	}
`

const formatTimestamp = (timestamp: string) => {
	const date = new Date(timestamp)
	const day = date.getDate()
	const month = date.toLocaleString('en-GB', { month: 'short' })
	const weekday = date.toLocaleString('en-GB', { weekday: 'long' })
	return `${day} ${month}, ${weekday}`
}

const isDifferentDate = (ts1: string, ts2: string) => {
	const d1 = new Date(ts1);
	const d2 = new Date(ts2);
	return (
		d1.getFullYear() !== d2.getFullYear() ||
		d1.getMonth() !== d2.getMonth() ||
		d1.getDate() !== d2.getDate()
	);
}

const DateDivider = ({ dateRef, timestamp }: IProps) => {
	const [showDivider, setShowDivider] = React.useState(false);

	React.useEffect(() => {
		if (!timestamp) return;

		if (!dateRef.current) {
			dateRef.current = timestamp;
			setShowDivider(true);
		} else if (isDifferentDate(dateRef.current, timestamp)) {
			dateRef.current = timestamp;
			setShowDivider(true);
		} else {
			setShowDivider(false);
		}
	}, [timestamp, dateRef]);

	if (!timestamp || !showDivider) {
		return null;
	}

	const formattedDate = formatTimestamp(timestamp);

	return (
		<DividerWrapper>
			<Divider>
				{formattedDate}
			</Divider>
		</DividerWrapper>
	);
}

export default DateDivider