interface INegativeFeedbackModalProps {
  onFeedbackSubmitted?: (messageId: string) => void;
}

const NegativeFeedbackModal: React.FC<INegativeFeedbackModalProps> = ({
  onFeedbackSubmitted,
}) => {
  const dispatch = useDispatch();
  const { currentAppReducer: { _id: appId } } = useSelector((state: IReduxState) => state);
  const { modalState, closeModal, isSubmitting, setIsSubmitting, setSubmittedMessageId } = useFeedbackModal();
  const { currentVersion } = useTaraAPIVersion();

  const [selectedReasons, setSelectedReasons] = useState<string[]>([]);
  const [additionalFeedback, setAdditionalFeedback] = useState('');

  const handleReasonChange = useCallback((value: unknown) => {
    setSelectedReasons(value as string[]);
  }, []);

  const handleFeedbackChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setAdditionalFeedback(e.target.value);
    },
    []
  );

  const handleSubmit = useCallback(async () => {
    if (isSubmitting) return;

    setIsSubmitting(true);
    try {
      await submitFeedback({
        feedback_type: 'negative',
        why_bad_response: selectedReasons.length > 0 ? selectedReasons.join(', ') : null,
        improvement_suggestion: additionalFeedback || null,
        app_id: appId || '',
        session_id: modalState.sessionId,
        invocation_id: modalState.invocationId,
      }, currentVersion);

      dispatch(
        trackPageViews(null, {
          eventName: 'wa_ai_submit_feedback',
          track_type: 'event',
          eventProperty: {
            feedback: 'thumbs_down',
            reason: selectedReasons.length > 0 ? selectedReasons.join(', ') : undefined,
            link: buildCometLink(modalState.invocationId),
          },
        })
      );

      // Notify FeedbackButtons that this message received negative feedback
      setSubmittedMessageId(modalState.messageId);

      if (onFeedbackSubmitted) {
        onFeedbackSubmitted(modalState.messageId);
      }

      closeModal();
    } catch (error) {
      console.error('Failed to submit negative feedback:', error);
    } finally {
      setIsSubmitting(false);
    }
  }, [
    isSubmitting,
    setIsSubmitting,
    modalState,
    appId,
    selectedReasons,
    additionalFeedback,
    dispatch,
    onFeedbackSubmitted,
    closeModal,
    setSubmittedMessageId,
    currentVersion,
  ]);

  const handleCancel = useCallback(() => {
    setSelectedReasons([]);
    setAdditionalFeedback('');
    closeModal();
  }, [closeModal]);

  const handleAfterClose = useCallback(() => {
    setSelectedReasons([]);
    setAdditionalFeedback('');
  }, []);

  return (
    <StyledModal
      title="Help us improve Tara"
      visible={modalState.isOpen}
      onCancel={handleCancel}
      afterClose={handleAfterClose}
      footer={null}
      width={570}
      centered
      destroyOnClose
    >
      <ModalContent>
        <Description>
          Please be as specific as possible when sharing feedback, the more details you share, the better we can help.
        </Description>

        <FieldWrapper>
          <FieldLabel>Why was it a bad response?</FieldLabel>
          <StyledSelect
            placeholder="Select one or more reasons"
            mode="multiple"
            maxTagCount="responsive"
            value={selectedReasons}
            onChange={handleReasonChange}
            options={NEGATIVE_FEEDBACK_REASONS.map((reason) => ({
              value: reason.id,
              label: (
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <Checkbox checked={selectedReasons.includes(reason.id)} />
                  <span>{reason.label}</span>
                </div>
              ),
              tagLabel: reason.label,
            }))}
            optionLabelProp="tagLabel"
            getPopupContainer={(triggerNode) => triggerNode.parentElement || document.body}
          />
        </FieldWrapper>

        <FieldWrapper>
          <FieldLabel>How can we improve? <OptionalMark>(optional)</OptionalMark></FieldLabel>
          <StyledTextArea
            placeholder="Help us understand what happened so we can improve."
            value={additionalFeedback}
            onChange={handleFeedbackChange}
            rows={3}
            maxLength={500}
          />
        </FieldWrapper>
      </ModalContent>

      <FooterWrapper>
        <CancelButton onClick={handleCancel} disabled={isSubmitting}>
          Cancel
        </CancelButton>
        <SubmitButton onClick={handleSubmit} disabled={isSubmitting || selectedReasons.length === 0}>
          {isSubmitting ? 'Submitting...' : 'Submit feedback'}
        </SubmitButton>
      </FooterWrapper>
    </StyledModal>
  );
};

export default NegativeFeedbackModal;
