import React, { useCallback } from 'react'
import styled from 'styled-components'
import IconWarning from 'public/static/ai/icon-warning.svg'
import { theme } from 'theme'
import { useRouter } from 'next/router'
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'
import { trackClickUpgrade } from 'components/features/aiSessions/components/utils'
import { useDispatch } from 'react-redux'

const Container = styled.div`
	background-color: ${ theme.colors.primary05.toString() };
	padding: 13px 12px;
	border-radius: 6px;
	display: flex;
	justify-content: space-between;
	align-items: center;
	flex-direction: column;
	gap: 10px;
	background-color: rgba(254, 214, 77, 0.25);
	border: 1px solid rgba(254, 214, 77, 0.25);
	margin-bottom: 24px;
	flex-direction: row;
	align-items: flex-start;
`

const LowLimitBoxLeft = styled.div`
	display: flex;
	gap: 6px;
`

const TaraButtonStyled = styled.button`
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 7px 5px 6px;
  background-color: white;
  background-clip: padding-box;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
  position: relative;
  justify-content: center;
	font-size: 12px;
	white-space: nowrap;
	align-self: center;
  &::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 6px;
    padding: 1px;
    background: linear-gradient(195deg, #ee5edd, #49c5ff);
    -webkit-mask: linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask-composite: exclude;
    pointer-events: none;
  }
`

const LowLimitText = styled.div`
	display: flex;
	flex-direction: column;
	font-family: Roboto;
	font-weight: 400;
	font-style: Regular;
	font-size: 12px;
	line-height: 19px;
	letter-spacing: 0%;
	color: ${ theme.colors.primary1000.toString()};
	strong {
		font-size: 700;
	}
`

const LowLimitBox = () => {
	const { setUpgradeModalVisible, setBatchModalVisible } = useAISessionWatchlist()
	const router = useRouter()
	const dispatch = useDispatch()
	const { parentType } = router.query

	const handleClick = useCallback( () => {
		dispatch(trackClickUpgrade({
			taraProduct: 'low_credits',
			parentType: (parentType as string) || 'unknown',
			source: 'batch_modal_button'
		}))

		setUpgradeModalVisible( true )
		setBatchModalVisible( false )
	}, [ setUpgradeModalVisible, setBatchModalVisible, parentType, dispatch ] )

	return (
		<Container>
			<LowLimitBoxLeft>
				<IconWarning />
				<LowLimitText>
					<strong>Less than 50 credits remaining</strong>
					Add more to keep uncovering insights.
				</LowLimitText>
			</LowLimitBoxLeft>
			<TaraButtonStyled onClick={ handleClick }>
				Upgrade plan
			</TaraButtonStyled>
		</Container>
	)
}

export default LowLimitBox