import { useEffect, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';
import { isEmpty } from 'lodash';
import { IReduxState } from 'types/reduxStateTypes';
import { useQueryClient } from 'react-query';


interface AIMetaData {
  descriptions?: string[];
  [key: string]: any;
}

export const useSessionScreenVisitTrackEvent = () => {
  const dispatch = useDispatch();
  const profile = useSelector((state: IReduxState) => state.profileReducer);
  const parentType = useSelector((state: IReduxState) => state.urlReducer.parentType);
  const queryClient = useQueryClient();
  const queries = queryClient.getQueriesData<AIMetaData>(['ai-session-meta']);
  const aiMeta = queries.length > 0 ? queries[0][1] : undefined;
  const aiMetaRef = useRef(aiMeta);

  useEffect(() => {
    if (aiMetaRef.current !== aiMeta) {
      aiMetaRef.current = aiMeta;
    }
  }, [aiMeta]);

  useEffect(() => {
    if (typeof window !== 'undefined' && !isEmpty(profile)) {
      if (parentType === 'aiSessionsList') {
        dispatch(trackPageViews(null, {
          eventName: 'screenvisit_sessions',
          track_type: 'event',
          eventProperty: {
            context_length: aiMetaRef?.current?.descriptions?.length
          }
        }));
      }
    }
  }, [dispatch, parentType, profile, aiMeta?.descriptions?.length]);
}; 