import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme'
import PromptArrowIcon from 'public/static/ai/icon-prompt-arrow.svg'
import { PromptTemplate } from './promptLibraryData'

const Item = styled.button`
	display: flex;
	align-items: flex-start;
	gap: 2px;
	padding: 8px;
	background: #EFF5FFB2;
	border-radius: 4px;
	border: none;
	cursor: pointer;
	width: 100%;
	text-align: left;
	transition: background-color 0.15s ease;

	&:hover {
		background: #DFEAFF99;
	}
`

const IconWrapper = styled.div`
	flex-shrink: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 24px;
	height: 24px;
`

const TextWrapper = styled.div`
	display: inline;
`

const TextSpan = styled.span`
	font-family: 'Roboto', sans-serif;
	font-weight: 400;
	font-size: 12px;
	line-height: 20px;
	color: #454B5D;
`

const Placeholder = styled.span`
	display: inline-flex;
	align-items: center;
	justify-content: center;
	padding: 2px 3px;
	background: ${theme.colors.primary100.toString()};
	border-radius: 2px;
	font-family: 'Roboto', sans-serif;
	font-weight: 400;
	font-size: 12px;
	line-height: 20px;
	color: ${theme.colors.primary700.toString()};
`

interface PromptItemProps {
	prompt: PromptTemplate
	onClick: (prompt: PromptTemplate) => void
}

const PromptItem = ({ prompt, onClick }: PromptItemProps) => {
	const handleClick = () => {
		onClick(prompt)
	}

	const renderPromptText = () => {
		const { text } = prompt

		// Match all {placeholder} patterns in the text
		const regex = /\{([^}]+)\}/g
		const parts: React.ReactNode[] = []
		let lastIndex = 0
		let match = regex.exec(text)
		let keyIndex = 0

		while (match !== null) {
			// Add text before the match
			if (match.index > lastIndex) {
				parts.push(<TextSpan key={`text-${keyIndex}`}>{text.slice(lastIndex, match.index)}</TextSpan>)
				keyIndex += 1
			}

			// Add the placeholder
			parts.push(<Placeholder key={`placeholder-${keyIndex}`}>{match[1]}</Placeholder>)
			keyIndex += 1

			lastIndex = regex.lastIndex
			match = regex.exec(text)
		}

		// Add remaining text after last match
		if (lastIndex < text.length) {
			parts.push(<TextSpan key={`text-${keyIndex}`}>{text.slice(lastIndex)}</TextSpan>)
		}

		return parts.length > 0 ? parts : <TextSpan>{text}</TextSpan>
	}

	return (
		<Item onClick={handleClick}>
			<IconWrapper>
				<PromptArrowIcon />
			</IconWrapper>
			<TextWrapper>
				{renderPromptText()}
			</TextWrapper>
		</Item>
	)
}

export default PromptItem
