import React from 'react'
import DropoffIcon from 'public/static/ai/icon-case-1.svg'
import FrictionIcon from 'public/static/ai/icon-case-2.svg'
import FeatureIcon from 'public/static/ai/icon-case-3.svg'
import DiscoveryIcon from 'public/static/ai/icon-case-4.svg'

export type UseCaseIconType = 'dropoff' | 'friction' | 'feature' | 'discovery'

interface UseCaseIconProps {
	type: UseCaseIconType
}

export const UseCaseIcon = ({ type }: UseCaseIconProps) => {
	switch (type) {
		case 'dropoff':
			return <DropoffIcon />
		case 'friction':
			return <FrictionIcon />
		case 'feature':
			return <FeatureIcon />
		case 'discovery':
			return <DiscoveryIcon />
		default:
			return null
	}
}
