import React, { useState, useEffect, memo, useCallback, useRef } from 'react'
import { useSelector, useDispatch, useStore } from 'react-redux'
import {
  isEmpty,
  isArray,
  indexOf,
  find,
  findIndex,
} from 'lodash'
import Router, { useRouter } from 'next/router'
import Cookies from 'universal-cookie'
import mixpanel from 'mixpanel-browser'
import { v4 } from 'uuid'
import Source from 'components/common/referrerSource'
import { valueByKeyEvent } from 'redux/actions/event'
import {
  getAppCheckList,
  gotCurrentApp,
  getAppDropdown,
  getCurrentApp,
} from 'redux/actions/appdropdown'
import { getScreenNameList } from 'redux/actions/screenFilter'
import {
  setError,
  sessionProcessingStatus,
  getRecordingStatusBanner,
  updateOrgChangeEvent,
  getHashKey
} from 'redux/actions/common'
import { getUser } from 'redux/actions/profile'
import { getActiveSubscription } from 'redux/actions/subscription'
import { isProd, isLocal } from 'Utils/constants/variables'
import {
  loadGoogleTagManager,
  initializeIntercom,
  initializeHotjar,
} from 'Utils/helpers/initializePlugins'
import { trackEvent } from 'services/globalInstance'
import { checkPlanStatus } from 'redux/actions/accessManagement'
import { trackPageViews } from 'redux/actions/trackingReport'
import { getCountryRegion } from 'Utils/helpers/commonUtils'
import { rollbar } from 'components/common/rollbar'
import { resetSidebarDropdownStates } from 'redux/actions/video'
import { getDateSegment } from 'redux/actions/megaFilter'
import useEventLimitStatus from 'hooks/useEventLimitAPI'
import { hotjar } from 'react-hotjar'
import { currentTimeZone } from 'Utils/DateConversion/dateConversionUtils'
import { useGetCustomLabelsQuery } from 'hooks/useCustomLabels';
import sortBy from 'lodash/sortBy'
import { activityFilterSelector } from 'components/shared/GlobalFilter/components/FilterDisplayBar/ActivityFilter/constants'
import { useSessionScreenVisitTrackEvent } from 'hooks/useSessionScreenVisitTrackEvent'
import HotjarBlockedOrg from '../../../Utils/constants/HotjarExclusion.json'
import { useRestrictionContext } from '../layout/context/restrictionContext'

const browserCookies = new Cookies()
const cookieFromAdmin = browserCookies.get('loggedInFromAdminDashboard')
const isProdAndNotAdminLogin = Boolean(!isLocal && typeof window !== 'undefined' && (cookieFromAdmin === null || cookieFromAdmin === undefined))

const onBoradingComponents = [
  'welcome_firstVisit',
  'integration',
  'dashboard',
  'plan-downgrade',
]

const MainHoc = (WrappedComponent) => {
  const HocComponent = (props) => {
    const {
      urlReducer: urlParam,
      profileReducer: profile,
      currentAppReducer: currentApp,
      applicationReducer: organizationList,
      tokenReducer,
      eventTable,
      errorReducer,
      appFilter: {
        dateSegmentIsInitial,
      },
      sidebarReducer: {
        collapse: sidebarStateCollapsed,
      }
    } = useSelector((state) => state)

    const dispatch = useDispatch()
    const store = useStore()
    const router = useRouter()
    const [orgForm, setOrgForm] = useState(false)
    const [appForm, setAppForm] = useState(false)
    const [dashboardAccessView, setDashboardAccessView] = useState(false)
    const [reasonNoDashboardAccess, setReasonNoDashboardAccess] = useState()
    const { aiSessionFeatureAllowed: isAISession } = useRestrictionContext() || {}

    // const sessionDateRange = appFilter.
    const { parentType, appId: appIdFromURL, app: appid } = urlParam
    let orgId = currentApp?.orgId || urlParam?.org
    const urlAsPath = urlParam?.url || ''
    const appId = appIdFromURL || appid
    const [isAISessionState, setIsAISessionState] = useState(false)
    // source_id for user source tracking on initial load
    const getSourceId = () => {
      if (typeof window !== 'undefined') {
        const url = new URL(window.location.href)
        const sourceId = url.searchParams.get('tsource_id')
        return sourceId
      }
      return null
    }

    const sourceId = getSourceId();

    const accessHotjar = !HotjarBlockedOrg.includes(orgId);
    useGetCustomLabelsQuery(appId)
    

    useEventLimitStatus();
    const resetStatus = () => {
      setAppForm(false)
      setOrgForm(false)
    }
    const changeAppStatus = () => {
      setAppForm(true)
      setOrgForm(false)
    }
    const intercomBooted = useRef(false)
    const isAISessionRef = React.useRef(isAISession)
    isAISessionRef.current = isAISession
    const loadIntercom = async (profileData, currentOrgData) => {
      const intercomKy = await dispatch(getHashKey())
      await initializeIntercom()
      if (window.Intercom && (cookieFromAdmin === null || cookieFromAdmin === undefined) && !intercomBooted.current) {
        const currentIsAISession = !!isAISessionRef.current
        const aiHorizontalPadding = sidebarStateCollapsed ? 89 : 209
        const horizontalPadding = !currentIsAISession ? 0 : aiHorizontalPadding;
        const hideDefaultLauncher = currentIsAISession
        window.Intercom('boot', {
          app_id: process.env.INTERCOM_APP_KEY,
          name: profileData?.name,
          api_base: "https://api-iam.intercom.io",
          user_hash: intercomKy?.data,
          email: profileData?.email,
          user_id: profileData?.['_id'],
          organizationID: currentOrgData?.orgId,
          organizationName: currentOrgData?.organizationName,
          applicationId: currentApp?.['_id'],
          // firstPaidSubscriptionStartDate:currentOrgData?.firstPaidSubscriptionStartDate,
          subscriptionStatus: currentOrgData?.subscriptionStatus,
          hubspotLink: currentOrgData?.hubspotLink,
          adminPanelLink: currentOrgData?.adminPanelLink,
          planName: currentOrgData?.planName,
          url: urlParam?.url,
          alignment: currentIsAISession ? 'left' : 'right',
          horizontal_padding: horizontalPadding,
          hide_default_launcher: hideDefaultLauncher,
        })
        intercomBooted.current = true;
      }
    }

    const loadMixpanel = () => {
      if (!mixpanel['__loaded']) {
        mixpanel.init(process.env.MIXPANEL)
        mixpanel.identify(profile['_id'])
        mixpanel.track('Page Visited', {
          pageName: urlParam.url,
          pageURL: window.location.href,
        })
        mixpanel.register({
          source: Source(),
        })
        mixpanel.people.set({
          source: Source(),
        })
      }
    }

    const updateIntercom = async (query, user) => {
      window.Intercom &&  window.Intercom("update", {
        name: user?.name,
        email: user?.email,
        url: query.url,
        applicationId: query?.appId,
      })
    }

    const loadHotjar = async () => {
      initializeHotjar();
      typeof window !== 'undefined' && hotjar.identify(profile['_id'], {
        'email': profile.email,
      });
    }

    const valueByKeyEventDispatcher = (key, val) => dispatch(valueByKeyEvent(key, val))

    // https://uxcamcom.atlassian.net/browse/CX-832
    // function updateTimeParams() {
    //   const currentDate = new Date();
    //   const currentTime = currentDate.toISOString().split('T')[1]; // Extract time part
    //   const segmentDate = appFilter?.dateSegment;

    //   if(!segmentDate.labelId) return;
    
    //   const updatedValue = {
    //     lower: `${new Date(segmentDate?.value?.lower).toISOString().split('T')[0]}T${currentTime}`,
    //     upper: `${new Date(segmentDate?.value?.upper).toISOString().split('T')[0]}T${currentTime}`
    //   };

    //   if(urlAsPath) {
    //     const includesDateRange = urlAsPath.includes('upload_time') || urlAsPath.includes('device_time') || urlAsPath.includes('date_range')
    //     if(!includesDateRange) {
    //       dispatch(
    //         getDateSegment({
    //           ...segmentDate,
    //           value: updatedValue
    //         })
    //       );
    //     };
    //   }
    // } 
    const getDateLatest = async () => {
      const defaultAttribute = [ 'aiSessionsList', 'aiSessionStatistics' ].includes( parentType ) ? 'device_time' : 'upload_time'
      dispatch(
        getDateSegment({
          attribute: defaultAttribute,
          operator: 'between_dates',
          value: {
            lower: new Date( new Date( new Date().setDate( new Date().getDate() - 30 ) ) ),
            upper: new Date( new Date() ),
          },
          tz: currentTimeZone,
          labelId: 'absolute_last30d',
          initial: true,
        })
      );
    };
    const changeDateRangeToCurrentUTC = () => {
      if(urlAsPath) {
        const attributesToAvoid = ['upload_time', 'device_time', 'date_range'];
        const urlAttributes= [];
        // * Extracting Top level attributes from the URL 
        urlAsPath?.replace(/([^?=&]+)=([^&]+)/g, (_, attribute) => {
            urlAttributes.push(attribute)
        })
        const ActivityFilterAttributes = Object.keys(activityFilterSelector)
        const includesDateRange = urlAttributes?.some((attribute) => attributesToAvoid.includes(attribute))
        const onlyActivityFilters = urlAttributes?.every(attrs=>ActivityFilterAttributes.includes(attrs))
     
        if(!includesDateRange || onlyActivityFilters) getDateLatest();
        
      }
    };
    const checkPlanStatusDispatcher = (org, app) => {
      dispatch(checkPlanStatus(org))
        .then((planStatus) => {
          const isPlanActionNeeded = planStatus?.selectAppAction || planStatus?.selectUserAction
          if (isPlanActionNeeded)
            Router.push(
              `/integration?parentType=plan-downgrade&appId=${appId || app}${org ? `&orgId=${org}` : ''}`,
              `/plan-downgrade?appId=${appId || app}${org ? `?orgId=${org}` : ''}`
            );
        })
        .catch((err) => err)
    }
    const getFirstOrg = async (orgListArgs, priorityOrgId) => {
      const newOrgList = orgListArgs || organizationList
      const orgApps = find(newOrgList, (og) => priorityOrgId ? og.orgId === priorityOrgId : og.apps.length > 0)
      const newOrgId = priorityOrgId || newOrgList?.[0]?.orgId;
      if (newOrgList?.length && newOrgList?.length === 1){
        try {
          localStorage.setItem('orgId', newOrgId)
        } catch (err) {
          // silent fail
        }
        orgId = newOrgId
      }
       
      if (orgApps) {
        const lastIndex = findIndex(orgApps.apps, { isLastVisitedApp: true })
        const priorityOrgIndex = findIndex(newOrgList, { 'orgId': priorityOrgId });
        const useIndex = priorityOrgId ? priorityOrgIndex : lastIndex;
        const app = dispatch(
          getCurrentApp(
            useIndex > -1 && orgApps.apps[useIndex].hasAccess
              ? orgApps.apps[useIndex]['_id']
              : orgApps.apps[0]['_id']
          )
        )
        if(app) checkPlanStatusDispatcher(orgId, orgApps.apps[0]?.['_id'])
        try {
          localStorage.setItem('appId', app['_id'])
        } catch (err) {
          // silent fail
        }
      } else {
        dispatch(gotCurrentApp({}))
        // const signupApp = localStorage.getItem('signupApp')
        // localStorage.clear();
        // if (signupApp) {
        //   localStorage.setItem('signupApp', signupApp)
        // }
      }
    }
    const callOrgFirstApp = async (orgListArgs) => {
      const newOrgList = orgListArgs || organizationList
      let appIdFromLocalStorage = ''
      try {
        appIdFromLocalStorage = localStorage.getItem('appId')
      } catch (err) {
        // silent fail
      }
      if (appId && appId !== 'undefined') {
        const app = dispatch(getCurrentApp(appId, newOrgList))
        if(app) checkPlanStatusDispatcher(app.orgId, app['_id'])
      } else if (appIdFromLocalStorage !== 'undefined') {
        const appList = []
          .concat(...newOrgList.map((o) => o.apps))
          .filter((d) => d['_id'])
          .map((d) => d['_id'])
        if (appList.length && appIdFromLocalStorage) {
          const idExist = indexOf(appList, appIdFromLocalStorage)
          if (idExist >= 0 && appIdFromLocalStorage) {
            const app = dispatch(getCurrentApp(appIdFromLocalStorage))
            if(app) checkPlanStatusDispatcher(app.orgId, app['_id'])
          } else getFirstOrg(newOrgList)
        } else getFirstOrg(newOrgList)
      } else getFirstOrg(newOrgList)
    }

    const checkOrgAppPage = async (orgListArgs, priorityOrgId, localProfile) => {
      const newOrgList = orgListArgs || organizationList
      sortBy(newOrgList, (o) => o?.orgId !== priorityOrgId);
      let reassignedApp; let reassignedAppId; let orgDashboardAccess = true;

      // Read parentType fresh from store to avoid stale closure on initial mount
      const freshUrlReducer = store.getState().urlReducer
      const currentParentType = freshUrlReducer?.parentType || parentType

      try {
        if (onBoradingComponents.includes(currentParentType)) {
          if (newOrgList.length === 0) {
            setOrgForm(true)
          } else if (newOrgList.length > 0) {
            if (appId) {
              newOrgList.forEach((org) => {
                org.apps.forEach((app) => {
                  if (app['_id'] === appId) {
                    reassignedApp = app;
                    orgDashboardAccess = typeof org.dashboardAccess === 'boolean'
                      ? org.dashboardAccess
                      : true;
                  }
                });
              });
            } else {
            newOrgList.map((org) => {
              if (reassignedApp === undefined) {
                if (org.apps.length > 0) {
                  const lastIndex = findIndex(org.apps, { isLastVisitedApp: true })
                  const priorityOrdIndex = findIndex(newOrgList, { 'orgId': priorityOrgId })
                  const useIndex = priorityOrgId ? priorityOrdIndex : lastIndex; 
                  reassignedApp =
                    useIndex > -1 && org.apps[useIndex]['hasAccess']
                      ? org.apps[useIndex]
                      : org.apps[0]
                  orgDashboardAccess =
                    typeof org.dashboardAccess === 'boolean'
                      ? org.dashboardAccess
                      : true
                  
                } else {
                  orgDashboardAccess =
                    typeof org.dashboardAccess === 'boolean'
                      ? org.dashboardAccess
                      : true
                }
              }
            })
          }
          
          if (reassignedApp && orgDashboardAccess) {
            // hasAccess = reassignedApp.hasAccess
            reassignedAppId = reassignedApp['_id']
            // Carry over shareError param so the error modal shows after redirect
            const shareErrorParam = typeof window !== 'undefined' ? new URL(window.location.href).searchParams.get('shareError') : null
            const shareErrorSuffix = shareErrorParam ? `&shareError=${shareErrorParam}` : ''
            const asURL = reassignedApp.isIntegrated
              ? `/app/${reassignedAppId}/overview${shareErrorParam ? `?shareError=${shareErrorParam}` : ''}`
              : `/integration?appId=${reassignedAppId}`
            Router.push(
              `/integration?appId=${reassignedAppId}&parentType=${
                reassignedApp.isIntegrated ? 'overview' : `integration`
              }${shareErrorSuffix}`,
              asURL
            )
          } else if (orgDashboardAccess) {
            const hasPassword = localProfile?.hasPassword
            if (hasPassword) {
              setAppForm(true)
              Router.push( `/dashboard?parentType=welcome_firstVisit`, `/welcome/first_visit` )
            }else{
              Router.push(
                `/setup?parentType=setup_password`,
                `/signup/password`
              );
            }
          } else {
            setDashboardAccessView(true)
            setReasonNoDashboardAccess(newOrgList[0].reasonNoDashboardAccess)
          }
        } else {
          reassignedAppId = currentApp['_id']
          const asURL = currentApp.isIntegrated ? `/app/${reassignedAppId}/overview` : `integration?appId=${reassignedAppId}`
          Router.push( `/integration?appId=${reassignedAppId}&parentType=${ currentApp.isIntegrated ? 'overview' : `integration` }`, asURL )
        }
      } else if (parentType === 'settings') {
        const url = new URL(window.location.href);
        if (url.searchParams.has('referer')) {
          const currentOrg = newOrgList.find((org) => org.orgId === orgId);
          if (!currentOrg) {
            Router.push('/error?errorStatus=406');
            return;
          }
          getFirstOrg(newOrgList, orgId);
        }
      }
      } catch (error) { return error }
    }

    const appLevelApiCalls = () => {
      const currentAppOrgId = orgId || currentApp?.orgId
      const currentAppId = appId || currentApp['_id']
      const orgIndex = findIndex(organizationList, { orgId: currentAppOrgId })
      if (orgIndex >= 0 && organizationList[orgIndex].dashboardAccess && currentAppId !== 'undefined') {
        dispatch(updateOrgChangeEvent(orgId))
        dispatch(getRecordingStatusBanner(currentAppOrgId, currentAppId))
        if (
          !onBoradingComponents.includes(parentType) && currentAppId
        ) {
          dispatch(getAppCheckList(currentAppId))
          dispatch(getScreenNameList(currentAppId))
        }
      }
    }
    const initialApis = async () => {
      let localProfile;
      if(isEmpty(profile)) {
        localProfile = await dispatch(getUser())
      }
      if (!organizationList) {
        const resByDropdown = dispatch(getAppDropdown(tokenReducer, false))
        resByDropdown
          .then(async (res) => {
            if (res && isArray(res)) {
              await callOrgFirstApp(res)
              checkOrgAppPage(res, undefined, localProfile)
            }
          })
          .catch((err) => err)
      } else {
        if(organizationList.length) await callOrgFirstApp()
        checkOrgAppPage(undefined, undefined, localProfile)
      }
    }
    const initialCallings = () => {
      try {
        localStorage.setItem('bottomBarClassFlag', undefined)
        if (sourceId) sessionStorage.setItem('source_id', sourceId)
        if(!localStorage.getItem('appId')) localStorage.setItem('appId', appId)
      } catch (err) {
        // silent fail
      }
      dispatch(setError({}))
      initialApis()
    }

    const trackLoginEvent  = useCallback(() => {
      let loginState = false;
      try {
        loginState = localStorage.getItem('loginState');
        if (loginState === 'true') {
          dispatch(trackPageViews(null, { eventName: 'wa_log_in' }))
          localStorage.setItem('loginState', false)
        }
      } catch (err) {
        // silent fail
      }
    }, [dispatch])

    const shouldTrackEvent = parentType !== 'aiSessionsList' && parentType !== 'setup_password' && parentType !== 'welcome_firstVisit'
    const appEssentials = async () => {
      dispatch(getActiveSubscription(orgId)).then((response) => {
        const responseData = response?.data
        shouldTrackEvent && dispatch(trackPageViews(profile))
        if (responseData) {
          try {
            localStorage.setItem('currentPlan', responseData['name'])
            localStorage.setItem('orgId', responseData['orgId'])
            localStorage.setItem('organizationName', responseData['organizationName'])
          } catch (err) {
            // silent fail
          }
        }
        trackLoginEvent()
        if (
          responseData &&
          currentApp
        ) {
            loadIntercom(profile, responseData)
            loadMixpanel()
            accessHotjar && loadHotjar()
            loadGoogleTagManager(responseData, profile)             
            rollbar.configure({
              payload: {
                user: {
                  name: profile.name,
                  email: profile.email,
                  app: currentApp.name,
                  appId: currentApp['_id'],
                },
              },
            })
        }
      }).catch((error) => error)
      let tokenResponse = ''
      let tokenCallGetTime = ''
      try {
        tokenResponse = localStorage.getItem('tokenResponse')
        tokenCallGetTime = localStorage.getItem('tokenCallGetTime')
      } catch (err) {
        // silent fail
      }
      if (tokenResponse && tokenResponse !== 'false' && tokenCallGetTime) {
        tokenResponse = JSON.parse(tokenResponse)
        await trackEvent(tokenResponse, tokenCallGetTime)
        try {
          localStorage.setItem('tokenResponse', 'false')
          localStorage.setItem('tokenCallGetTime', 'false')
        } catch (err) {
          // silent fail
        }
      }
      dispatch(sessionProcessingStatus())
    }
    const trackProps = async () => {
      const ipAddress = await getCountryRegion()
      try {
        localStorage.setItem('internetIdentity', ipAddress?.ip || 'Could not track IP')
        if(!localStorage.getItem('usersSessionSId')) localStorage.setItem('usersSessionId', v4() )
      } catch (err) {
        // silent fail
      }
    }

    // Dynamic AppID/OrgID in URL - we can use id/orgid as placehodler instead of real value
    useEffect(() => {
      const asPath = router?.asPath
    
      const appIDFromUrl = urlParam?.appId || urlParam?.app
      const orgIDFromUrl = urlParam?.orgId || urlParam?.org 

      let appIDFromLocalStorage = null
      let orgIDFromLocalStorage = null
      
      try {
        appIDFromLocalStorage = localStorage.getItem( 'appId' )
        orgIDFromLocalStorage = localStorage.getItem( 'orgId' )
      } catch (err) {
        // silent fail
      }

      const shouldReplaceAppID = appIDFromUrl === 'id'
      const shouldReplaceOrgID = orgIDFromUrl === 'orgid'

      let newPath = asPath
      let shouldPush = false

      if ( shouldReplaceAppID && !appIDFromLocalStorage || shouldReplaceOrgID && !orgIDFromLocalStorage ) {
        return undefined
      }

      if ( shouldReplaceAppID && appIDFromLocalStorage ) {
        if ( newPath.includes( '?appId=id' ) ) {
          newPath = newPath.replace( '?appId=id', `?appId=${ appIDFromLocalStorage }` )
        } else {
          newPath = newPath.replace( '/id/', `/${ appIDFromLocalStorage }/` )
        }
        shouldPush = true
      }
      
      if ( shouldReplaceOrgID && orgIDFromLocalStorage ) {
        newPath = newPath.replace( '/orgid/', `/${ orgIDFromLocalStorage }/` )
        shouldPush = true
      }

      if ( shouldPush ) {
        window.location.href = newPath
      }
      return undefined
    }, [ urlParam, parentType, router ] )

    useEffect(() => {
     // if(isProdAndNotAdminLogin) trackProps()
      trackProps()
      initialCallings()
    }, [])

    const orgIDRef = React.useRef(orgId)
    const appIDRef = React.useRef(appId)
    useEffect(() => {
      if ((orgIDRef.current !== orgId || appIDRef.current !== appId) && window.Intercom) {
        window.Intercom('shutdown')
        intercomBooted.current = false
      }
      orgIDRef.current = orgId
      appIDRef.current = appId

      if (!isEmpty(profile)) {
        if (orgId) appEssentials()
        else if (isProdAndNotAdminLogin) {
          loadIntercom(profile)
        }
      }
    }, [orgId, appId, profile, isAISessionState])

    const timerRef = React.useRef(null)
    useEffect( () => {
      timerRef.current = setTimeout( () => {
        setIsAISessionState( isAISession )
      }, 1000)

      return () => {
        if (timerRef.current) {
          clearTimeout(timerRef.current)
        }
      }
    }, [ isAISession ] )

    useEffect(() => {
      if (!isAISession) return undefined
      const updateIntercomVisibility = () => {
        if (window.Intercom) {
          window.Intercom('update', { hide_default_launcher: true })
          const aiHorizontalPadding = sidebarStateCollapsed ? 89 : 209
          window.Intercom('update', {
            hide_default_launcher: true,
            alignment: 'left',
            horizontal_padding: aiHorizontalPadding,
          })
          return intercomBooted.current
        }
        return false
      }
      if (updateIntercomVisibility()) return undefined
      const interval = setInterval(() => {
        if (updateIntercomVisibility()) clearInterval(interval)
      }, 500)
      return () => clearInterval(interval)
    }, [isAISession, sidebarStateCollapsed])

    useEffect(() => {
      if (orgId) appLevelApiCalls()
    }, [currentApp?.orgId, appId ])

    const initializedDate = React.useRef( false )
    const prevParentType = React.useRef()
    const shouldUpdateDate = [ 'aiSessionsList', 'aiSessionStatistics', 'sessionsList', 'sessionStatistics' ].includes( parentType ) || [ 'aiSessionsList', 'aiSessionStatistics', 'sessionsList', 'sessionStatistics' ].includes( prevParentType.current )


    useEffect(() => {
      if ( prevParentType.current !== parentType ) {
        prevParentType.current = parentType
      }
      if ( appId && organizationList && initializedDate.current && dateSegmentIsInitial && shouldUpdateDate ) {
        getDateLatest()
      }
    }, [appId, organizationList, parentType, dateSegmentIsInitial])

    useEffect(() => {
      if (appId) dispatch(resetSidebarDropdownStates())
      if (appId && organizationList) {
        dispatch(getCurrentApp(appId))
        changeDateRangeToCurrentUTC()
        initializedDate.current = true
      }
    }, [appId, organizationList])

    // useEffect(() => {
    //   if(appId && organizationList) {
    //     updateTimeParams()
    //   }
    // }, [parentType])

    useEffect(() => {
      if (urlAsPath) {
        if(eventTable.isSessionEventTab) valueByKeyEventDispatcher('isSessionEventTab', null)
        if(isProd) loadMixpanel()
      }
      profile && updateIntercom(urlParam, profile)
    }, [urlParam, profile])

    const _ = useSessionScreenVisitTrackEvent();
    useEffect(() => {
    //* dont trigger for some pages; it has its own track event
      if(typeof window !== 'undefined' && !isEmpty(profile) && shouldTrackEvent) { 
          dispatch(trackPageViews())
      }
    }, [urlParam, parentType])

    // useScreenList()

    return (
        <WrappedComponent
          orgForm={orgForm}
          appForm={appForm}
          dashboardAccessView={dashboardAccessView}
          reasonNoDashboardAccess={reasonNoDashboardAccess}
          valueByKeyEvent={valueByKeyEventDispatcher}
          resetStatus={resetStatus}
          errorReducer={errorReducer}
          changeAppStatus={changeAppStatus}
          {...props}
        />
    )
  }
  return memo(HocComponent)
}
export default MainHoc
