const CHAR_RELEASE_INTERVAL = 8;

const useBufferedStream = (rawContent: string, isActive: boolean) => {
  const [displayedContent, setDisplayedContent] = React.useState('');
  const bufferRef = React.useRef('');
  const lastProcessedRef = React.useRef(0);
  const intervalRef = React.useRef<ReturnType<typeof setInterval> | null>(null);

  React.useEffect(() => {
    if (!isActive) {
      setDisplayedContent('');
      bufferRef.current = '';
      lastProcessedRef.current = 0;
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      return;
    }

    const newContent = rawContent.slice(lastProcessedRef.current);
    if (newContent) {
      bufferRef.current += newContent;
      lastProcessedRef.current = rawContent.length;
    }

    if (!intervalRef.current && bufferRef.current.length > 0) {
      intervalRef.current = setInterval(() => {
        if (bufferRef.current.length > 0) {
          const nextChar = bufferRef.current[0];
          bufferRef.current = bufferRef.current.slice(1);
          setDisplayedContent(prev => prev + nextChar);
        } else if (intervalRef.current) {
          clearInterval(intervalRef.current);
          intervalRef.current = null;
        }
      }, CHAR_RELEASE_INTERVAL);
    }
  }, [rawContent, isActive]);

  React.useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  return displayedContent;
};

const formatTimestamp = (timestamp: string) => {
	const date = new Date(timestamp);
	return date.toLocaleString('en-GB', {
		hour: '2-digit',
		minute: '2-digit',
	});
};

const ChatBubble = ({ isLoading, message, dateRef, customCopyContent, showCopyButton = true, chatSessionId }: IChatBubble) => {
	const { content, timestamp, role, readable_filters: readableFilters, sessions_analyzed_by_ai: sessionsAnalyzedByAI, tool, invocation_id: invocationId, isError, id: chatID, feedback_type: feedbackType } = message;
	const { debugMode } = useAISidebarContext();
	const { aiSessionFeatureAllowed: isTaraEnabled } = useRestrictionContext() as unknown as { aiSessionFeatureAllowed: boolean }
	const isStreaming = message.id === 'streaming';
	const displayedContent = useBufferedStream(content || '', isStreaming);
	const {
		urlReducer: urlQuery,
		appFilter: { session: { segment: sessionSegment } },
	} = useSelector((state: IReduxState) => state);
	const formattedTimestamp = React.useMemo(
		() => formatTimestamp(timestamp as string),
		[timestamp]
	);
	const { tempDocumentsMap, sessionAliasMap } = useAIAssistantContext();
	const { onItemSetActive, buildSessionUrl } = useSessionTableHelper({ expanded: false });
	const isUser = role === 'user';
	const dispatch = useDispatch();
	const { setUtils } = useAISessionUtils();
	const isAISessionDetailsPage = urlQuery?.sessionid
	const { mutate: mutateAIUserSession } = useAIUserSessions()
	const queryClient = useQueryClient();
	const [currentSessionId, setCurrentSessionId] = React.useState<string>('');
	// Map of invocationId -> sessionId[] to track watched sessions per chat
	const [watchedSessionsMap, setWatchedSessionsMap] = React.useState<Record<string, string[]>>({});
	const [isCopied, setIsCopied] = React.useState(false);
	const [isHovered, setIsHovered] = React.useState(false);

	// Reference counter for old hex-ID format only (BE alias format uses its own S-number)
	const referenceCounterRef = React.useRef(1);
	const referenceMapRef = React.useRef<Map<string, number>>(new Map());

	React.useEffect(() => {
		referenceCounterRef.current = 1;
		referenceMapRef.current = new Map();
	}, [message.id]);

	useEffect(() => {
		const stored = localStorage.getItem('watched_sessions_by_invocation');
		if (stored) {
			try {
				setWatchedSessionsMap(JSON.parse(stored));
			} catch (e) {
				console.error('Failed to parse watched sessions map', e);
			}
		}
	}, []);

	const markAsWatched = React.useCallback((sessionId: string, invocationIdParam: string) => {
		setWatchedSessionsMap((prev) => {
			const currentInvocationSessions = prev[invocationIdParam] || [];
			if (currentInvocationSessions.includes(sessionId)) return prev;

			const newMap = {
				...prev,
				[invocationIdParam]: [...currentInvocationSessions, sessionId]
			};

			try {
				localStorage.setItem('watched_sessions_by_invocation', JSON.stringify(newMap));
			} catch (e) {
				console.error('Failed to save watched sessions map', e);
			}
			return newMap;
		});
	}, []);

	const handleCopy = React.useCallback(() => {
		const contentToCopy = customCopyContent || content;
		if (typeof contentToCopy === 'string') {
			const plainText = stripMarkdown(contentToCopy, urlQuery.appId || '', sessionAliasMap);
			navigator.clipboard.writeText(plainText);
			setIsCopied(true);
			setTimeout(() => setIsCopied(false), 3000);

			dispatch(
				trackPageViews(null, {
					eventName: 'wa_ai_copy_response',
					track_type: 'event',
				})
			);
		}
	}, [content, customCopyContent, urlQuery.appId, dispatch]);

	const onLinkClick = React.useCallback((url: string) => {
		dispatch(
			trackPageViews(null, {
				eventName: 'wa_sessions_tara_click_link',
				track_type: 'event',
				eventProperty: {
					url_link: url,
				},
			})
		)
	}, [dispatch])

	const getAIDetailsQueryKey = useMemo(() => getAIDetailsKey(currentSessionId), [currentSessionId]);
	const getDetailsQueryState = queryClient.getQueryState(getAIDetailsQueryKey) as any
	const isWebApp = useIsAppType('web');

	useEffect(() => {
		if (!currentSessionId || getDetailsQueryState?.isFetching || !getDetailsQueryState?.data) {
			return;
		}
		mutateAIUserSession({
			appid: urlQuery.appId || '',
			recordedon: getDetailsQueryState?.data?.time?.sessionRecordedDateTime,
			session_per_page: 101,
			usersessionrun: getDetailsQueryState?.data?.sessionNumber,
			uxcamuserid: getDetailsQueryState?.data?.userProperty?.uxcamuserid,
			webApp: isWebApp
		}, {
			onSettled: () => {
				setCurrentSessionId('')
			},
			onSuccess: (data) => {
				const passedSession = (data as UserSessionData).data.data.body;
				const sessionData = passedSession.find((session) => session.sessionid === currentSessionId);
				if (!sessionData) return;
				dispatch(trackAISessionSelect({
					sessionId: sessionData.sessionid,
					aiAnalyzed: sessionData.sessionanalyzedbyai,
					containsVideo: sessionData.video,
					duration: sessionData.sessionDuration,
					gestureCount: sessionData?.totalGesture,
					parentType: urlQuery.parentType || '',
					sessionSelectedFrom: 'tara',
					filtersApplied: sessionSegment,
					isRageTap: sessionData.isRageTap,
					isUiFreeze: sessionData.isuifreeze,
					isCrashed: sessionData.crashed,
				}))
			}
		})
	}, [currentSessionId, dispatch, getDetailsQueryState, isWebApp, mutateAIUserSession, sessionSegment, urlQuery.appId, urlQuery.parentType])

	const parseContent = React.useCallback(
		(contentProps: string) => {
			// Normalize raw UXCam session URLs into {{session:id}} format
			const normalizedContent = contentProps.replace(
				/https?:\/\/(?:app\.)?uxcam\.com\/app\/sessions\/([a-f0-9]{24})\b[^\s)"]*/gi,
				'{{session:$1}}'
			);

			const documentLinkMatch = normalizedContent.match(/\(\((\d?)\)\)/);
			if (documentLinkMatch) {
				const documentIndex = Number(documentLinkMatch[1]);
				const document =
					tempDocumentsMap?.[documentIndex] ||
					message?.document_map?.[documentIndex];
				const prefix = normalizedContent.startsWith(':') ? ': ' : '';

				if (document) {
					return [
						prefix,
						<a
							key={document.url}
							href={document.url}
							target="_blank"
							rel="noopener noreferrer"
							onClick={() => onLinkClick(document.url)}
						>
							{document.title}
						</a>,
					];
				}
			}

			const regex = /\[\[(.*?)\]\]/g;
			if (normalizedContent.match(regex)) {
				const parts = [];
				let lastIndex = 0;
				let match;

				// eslint-disable-next-line no-cond-assign
				while ((match = regex.exec(normalizedContent)) !== null) {
					if (match.index > lastIndex) {
						parts.push(normalizedContent.substring(lastIndex, match.index));
					}

					const id = match[1];
					const currentInvocationWatchedSessions = (invocationId || chatID) ? (watchedSessionsMap[invocationId || chatID] || []) : [];
					const sessionIdForUrl = isAISessionDetailsPage || id;
					const sessionButtonUrl = buildSessionUrl(sessionIdForUrl,  id, 0, false);

					parts.push(
						<SessionButton
							key={`session-${id}-${match.index}`}
							href={sessionButtonUrl}
							data-session-watched={currentInvocationWatchedSessions.includes(id)}
							onClick={(e: React.MouseEvent<HTMLAnchorElement>) => {
								e.preventDefault();
								const sessionId = isAISessionDetailsPage || id;
								const secondarySessionId = id;
								setCurrentSessionId(secondarySessionId)
								const url = onItemSetActive(sessionId, false, false, secondarySessionId);
								setUtils(prev => ({ ...prev, activePlaylist: PLAYLIST_STATUS.INACTIVE }));
								onLinkClick(url)
								if (invocationId || chatID) markAsWatched(id, invocationId || chatID);
							}}
						>
							{id}
						</SessionButton>
					);

					lastIndex = match.index + match[0].length;
				}

				if (lastIndex < normalizedContent.length) {
					parts.push(normalizedContent.substring(lastIndex));
				}
				// eslint-disable-next-line react/jsx-no-useless-fragment
				return <>{parts}</>;
			}

			// Check for session/screenvisit in {{session:...}} or {{screenvisit:...,timestamp,screenName}} format
			// Supports both aliases (S3) and hex IDs (24-char)
			const combinedCheckRegex = /\{\{(session|screenvisit):([^}]+)\}\}/gi;
			const hasSessionOrScreenVisit = normalizedContent.match(combinedCheckRegex);
			const currentInvocationWatchedSessions = (invocationId || chatID) ? (watchedSessionsMap[invocationId || chatID] || []) : [];

			if (hasSessionOrScreenVisit) {
				const parts = [];

				const combinedRegex = /\{\{(session|screenvisit):([^}]+)\}\}/gi;
				let lastIndex = 0;
				let match;

				// eslint-disable-next-line no-cond-assign
				while ((match = combinedRegex.exec(normalizedContent)) !== null) {
					if (match.index > lastIndex) {
						parts.push(normalizedContent.substring(lastIndex, match.index));
					}

					const type = match[1].toLowerCase() as 'session' | 'screenvisit';
					const data = match[2];

					let rawId: string;
					let startTime: number | undefined;
					let screenName: string | undefined;

					if (type === 'session') {
						rawId = data;
					} else {
						const screenVisitParts = data.split(',');
						[rawId] = screenVisitParts;
						const rawTime = screenVisitParts[1];
						if (rawTime && rawTime.includes(':')) {
							const timeParts = rawTime.split(':').map(Number);
							startTime = timeParts.length === 3
								? timeParts[0] * 3600 + timeParts[1] * 60 + timeParts[2]
								: timeParts[0] * 60 + timeParts[1];
						} else {
							startTime = parseFloat(rawTime);
						}
						screenName = screenVisitParts.slice(2).join(',');
					}

					// Resolve alias (S3) to real session ID, or use hex ID directly
					const isAlias = /^S\d+$/i.test(rawId);
					const sessionId = isAlias ? (sessionAliasMap?.[rawId] || null) : rawId;

					// Assign frontend reference number (sequential per message, deduplicated by session ID)
					const occurrenceKey = rawId;
					let refNumber = referenceMapRef.current.get(occurrenceKey);
					if (refNumber === undefined) {
						refNumber = referenceCounterRef.current;
						referenceMapRef.current.set(occurrenceKey, refNumber);
						referenceCounterRef.current += 1;
					}

					// If alias can't be resolved yet (streaming), show non-clickable badge
					if (!sessionId) {
						parts.push(
							<ReferenceNumber
								key={`ref-${refNumber}-${match.index}`}
								as="span"
								style={{ cursor: 'default' }}
							>
								{refNumber}
							</ReferenceNumber>
						);
						lastIndex = match.index + match[0].length;
						// eslint-disable-next-line no-continue
						continue;
					}

					const sessionIdToUse = isAISessionDetailsPage || sessionId;
					const secondarySessionId = sessionId;
					const sessionUrl = buildSessionUrl(sessionIdToUse, secondarySessionId, startTime || 0, false);

					const tooltipContent = type === 'session'
						? <span style={{ whiteSpace: 'nowrap' }}>Watch session <strong>{sessionId}</strong></span>
						: <span style={{ whiteSpace: 'nowrap' }}>Watch screen <strong>{screenName}</strong></span>;

					parts.push(
						<Tooltip key={`ref-${refNumber}-${match.index}`} title={tooltipContent} placement='bottomLeft' overlayStyle={{ maxWidth: 'none' }}>
							<ReferenceNumber
								href={sessionUrl}
								data-session-watched={currentInvocationWatchedSessions.includes(sessionId)}
								onClick={(e: React.MouseEvent<HTMLAnchorElement>) => {
									e.preventDefault();
									setCurrentSessionId(secondarySessionId);
									const url = onItemSetActive(sessionIdToUse, false, false, secondarySessionId, startTime || 0);
									setUtils(prev => ({ ...prev, activePlaylist: PLAYLIST_STATUS.INACTIVE }));
									onLinkClick(url);
									if (invocationId || chatID) markAsWatched(sessionId, invocationId || chatID);
								}}
							>
								{refNumber}
							</ReferenceNumber>
						</Tooltip>
					);

					lastIndex = match.index + match[0].length;
				}

				if (lastIndex < normalizedContent.length) {
					parts.push(normalizedContent.substring(lastIndex));
				}

				// eslint-disable-next-line react/jsx-no-useless-fragment
				return <>{parts}</>;
			}

			if (normalizedContent.includes('<br>')) {
				return normalizedContent.split('<br>').map((part, idx, arr) =>
					idx < arr.length - 1
						// eslint-disable-next-line react/no-array-index-key
						? [part, <br key={idx} />]
						: part
				);
			}

			return normalizedContent;
		},
		[message, onItemSetActive, buildSessionUrl, tempDocumentsMap, sessionAliasMap, onLinkClick, isAISessionDetailsPage, setUtils, watchedSessionsMap, markAsWatched, invocationId, chatID]
	);

	const recursiveParseContentChildren = React.useCallback(
		(children: React.ReactNode): React.ReactNode => {
			if (typeof children === 'string') {
				return parseContent(children);
			}

			if (Array.isArray(children)) {
				return children.map((child) => recursiveParseContentChildren(child));
			}

			if (React.isValidElement(children)) {
				// Prevent processing children of SessionButton to avoid nested buttons
				if (children.type === SessionButton) {
					return children;
				}

				return React.cloneElement(children, {
					...children.props,
					children: recursiveParseContentChildren(children.props.children),
				});
			}

			return children;
		},
		[parseContent]
	);

	const generateComponent = React.useCallback(
		(props: React.ClassAttributes<HTMLSpanElement> & React.HTMLAttributes<HTMLSpanElement> & ExtraProps) => {
			const { children, node, ...rest } = props;
			const type = node?.tagName as keyof JSX.IntrinsicElements
			const processedChildren = recursiveParseContentChildren(children);
			const newElement = React.createElement(type, rest, processedChildren);

			switch( type ) {
				case 'table':
					return (
						<TableWrapper>
							{ newElement }
						</TableWrapper>
					)
				default:
					return newElement
			}
		},
		[recursiveParseContentChildren]
	);

	const generateAnchorComponent = React.useCallback(
		(props: React.ClassAttributes<HTMLAnchorElement> & React.AnchorHTMLAttributes<HTMLAnchorElement> & ExtraProps) => {
			const { children, href, ...rest } = props;
			const processedChildren = recursiveParseContentChildren(children);

			// If the href is a UXCam session URL, the children will have been converted
			// to a ReferenceNumber/SessionButton link by parseContent — skip the outer <a> to avoid nesting
			if (href && /uxcam\.com\/app\/sessions\/[a-f0-9]{24}/i.test(href)) {
				// eslint-disable-next-line react/jsx-no-useless-fragment
				return <>{processedChildren}</>;
			}

			// Return JSX instead of React.createElement to match existing pattern
			return (
				<a
					{...rest}
					href={href}
					target="_blank"
					rel="noopener noreferrer"
					onClick={href ? () => onLinkClick(href) : undefined}
				>
					{processedChildren}
				</a>
			);
		},
		[recursiveParseContentChildren, onLinkClick]
	);

	const tooltipContent = React.useMemo(() => generateTooltipContent({
		total_sessions: sessionsAnalyzedByAI || 0,
		descriptions: readableFilters || [],
	}), [readableFilters, sessionsAnalyzedByAI]);

	const renderCopyIcon = () => {
		if (isCopied) {
			return <IconComplete />;
		}
		if (isHovered) {
			return <IconCopyHover />;
		}
		return <IconCopy />;
	};

	const renderContent = React.useMemo(() => {
		// Handle stopped indicator - both legacy isStoppedByUser flag and new user_stopped role
		if (message.isStoppedByUser || role === 'user_stopped') {
			const displayText = (!content || content === 'null' || content === 'User stopped') ? 'Response stopped by user' : content;
			return (
				<StoppedIndicator>
					<InfoIcon />
					{displayText}
				</StoppedIndicator>
			);
		}

		if (isLoading) {
			return (
				<LoadingWrapper>
					<SpinnerWrapper>
						<Spinner data-size="xs" />
					</SpinnerWrapper>
					{content}
				</LoadingWrapper>
			);
		}

		// Handle debug mode function calls and responses
		if (debugMode && tool && (content === 'function_call' || content === 'function_response')) {
			return (
				<DebugAccordion
					type={content as 'function_call' | 'function_response'}
					tool={tool}
					timestamp={timestamp}
				/>
			);
		}

		const markdownComponents = {
			h1: generateComponent,
			h2: generateComponent,
			h3: generateComponent,
			h4: generateComponent,
			h5: generateComponent,
			h6: generateComponent,
			b: generateComponent,
			blockquote: generateComponent,
			strong: generateComponent,
			em: generateComponent,
			a: generateAnchorComponent,
			li: generateComponent,
			p: generateComponent,
			span: generateComponent,
			table: generateComponent,
			thead: generateComponent,
			tbody: generateComponent,
			tr: generateComponent,
			th: generateComponent,
			td: generateComponent,
		};

		if (isStreaming && displayedContent) {
			return (
				<Markdown remarkPlugins={[remarkGfm]} components={markdownComponents}>
					{displayedContent}
				</Markdown>
			);
		}

		return (
			<>
				<Markdown remarkPlugins={[remarkGfm]} components={markdownComponents}>
					{content}
				</Markdown>
				{debugMode && invocationId && urlQuery.appId && !isUser && (
					<ViewResponseInfo message={message} appId={urlQuery.appId} />
				)}
			</>
		);
	}, [isLoading, content, generateComponent, generateAnchorComponent, debugMode, tool, timestamp, invocationId, urlQuery.appId, message, isUser, isStreaming, displayedContent]);

	return (
		<>
			{dateRef && <DateDivider dateRef={dateRef} timestamp={timestamp} />}
			<ChatBubbleContainer role={role}>
				<ChatBubbleContent role={role}>
					{timestamp && isUser && (
						<ChatBubbleTop>{formattedTimestamp}</ChatBubbleTop>
					)}
					{renderContent}
					{isUser && !isTaraEnabled && !!readableFilters?.length && (
						<CountIndicatorContainer>
							<CountIndicator
								count={sessionsAnalyzedByAI || 0}
								loading={false}
								tooltip={tooltipContent}
								background="rgba(255,255,255,0.7)"
							/>
						</CountIndicatorContainer>
					)}
					{!isUser && !isLoading && !isError && showCopyButton && !!invocationId && role !== 'user_stopped' && (
						<ActionButtonsContainer>
							<Tooltip title={isCopied ? "Response copied!" : "Copy response"}>
								<CopyButton
									onClick={handleCopy}
									onMouseEnter={() => setIsHovered(true)}
									onMouseLeave={() => setIsHovered(false)}
								>
									{renderCopyIcon()}
								</CopyButton>
							</Tooltip>
							<FeedbackButtons
								messageId={chatID || ''}
								invocationId={invocationId || ''}
								sessionId={chatSessionId || ''}
								initialFeedback={feedbackType}
							/>
						</ActionButtonsContainer>
					)}
				</ChatBubbleContent>
			</ChatBubbleContainer>
		</>
	);
};

export default ChatBubble;
