import { Button, Layout, Tooltip } from 'antd';
import Router from 'next/router';
import React from 'react'
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder'
import ChevronLeftArrow from 'public/static/chevron-left-arrow-icon.svg';
import SessionDropdown from 'components/features/aiSessions/components/SessionListDropdown';
import { AIChatToggleLeftWrapper, AIChatToggleRightWrapper } from 'components/shared/GlobalFilter/components/index'
import Calendar2Icon from 'public/static/customisable-dashboard/calendar-2.svg'
import AIChatToggle from 'components/common/AIAssistant/ChatTab/AIChatToggle';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { trackPageViews } from 'redux/actions/trackingReport';
import FilterCountButton from '../FilterCountButton';
import CalendarDateRangePicker from '../CalendarDateRangePicker';

const { Header } = Layout;

const Wrapper = styled.div`
    display: flex;
    align-items: center;
    gap: 8px;  
    width: 100%;
    justify-content: space-between;
    .left {
        display: flex;
        align-items: center;
        gap: 8px;
    }
    .right {
        display: flex;
        align-items: center;
    }
`

const GoBack = styled.button`
    background: #fff;
    border: 1px solid #F3F4F5;
    border-radius: 5px;
    padding: 0 8px;
    height: 32px;
    font-size: 13px;
    font-weight: 500;
    line-height: 32px;
    color: #161E35;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 9px;
    &:hover {
        color: #5D97FF;
        fill: #5D97FF;
        transition: all 0.3s ease-in-out;
    }
`

const ButtonWrap = styled(Button)`
  border: 1px solid #F3F4F5 !important;
  display: flex;
  border-radius: 6px;
  gap: 8px;
  span{
    line-height: 13px;
  }
  svg{
    position: relative;
    top: -1px;
  }
  padding: 8px 12px;
  &:disabled{
    background-color: #fff ;
    color: #A2A5AE;
    font-weight: 400 !important;
    border-color: red;
  }
`

function AISessionFilter() {
    const {
        urlReducer: {
            sessionpage = 1,
            appId,
            autoplay,
        },
        appFilter: {
            session: { segment: sessionSegment },
        },
    } = useSelector((state) => state);
    const dispatch = useDispatch();
    const { aiSessionFeatureAllowed: isTaraEnabled } = useRestrictionContext() || {}
    const { aiSessionFeatureAllowed } = useRestrictionContext() || {}
    
    const handleSessionClick = () => {
        const segment = sessionSegment;
        const autoPlayPart = `&autoplay=${autoplay ? '1' : ' 0'}`;
        const url = urlSegmentEncoder(
            `/app/${appId}/aisessions/list/${sessionpage || 1}?`,
            segment
        );
        const query = `appId=${appId}&parentType=aiSessionsList&sessionpage=${sessionpage || 1
            }&starttime=0${autoPlayPart}`;

         dispatch(trackPageViews(null, {
           eventName: 'go_back_to_session_list',
           track_type: 'event',
           eventProperty: {}
         }))
        Router.push(`/integration?${query}`, url);
    };



    return (
        <Header className="global-menu">
            <div className="global-menu-container" >
                <Wrapper className='global-left-wrapper'>
                    <div className='left'>
                        <GoBack type='button' onClick={handleSessionClick}>
                            <ChevronLeftArrow />
                            <span>
                                Session list
                            </span>
                        </GoBack>
                        <SessionDropdown />
                        <FilterCountButton isAlternativeStyle />
                    </div>
                    <div className='right'>
                        { !isTaraEnabled && aiSessionFeatureAllowed && (
                            <AIChatToggleLeftWrapper>
                                <AIChatToggle />
                            </AIChatToggleLeftWrapper>
                        ) }
                        <CalendarDateRangePicker disabled>
                            {
                                ({ btnLabel }) =>
                                    <Tooltip title="This filter can only be changed outside the player. Please navigate back to adjust." placement="bottomRight">
                                        <ButtonWrap className='date-picker-trigger' disabled><Calendar2Icon /><span>{btnLabel}</span></ButtonWrap>
                                    </Tooltip>
                            }
                        </CalendarDateRangePicker>
                        { isTaraEnabled && aiSessionFeatureAllowed && (
                            <AIChatToggleRightWrapper>
                                <AIChatToggle />
                            </AIChatToggleRightWrapper>
                        ) }
                    </div>
                </Wrapper>
            </div>
        </Header>
    )
}

export default AISessionFilter

