import React, { useCallback } from 'react'
import styled from 'styled-components'
import IconWarning from 'public/static/ai/icon-warning.svg'
import IconTaraLiteInfo from 'public/static/ai/icon-tara-lite-info.svg'
import IconClose from 'public/static/close-banner.svg'
import { TaraButton } from 'components/common/AIAssistant/SessionWatchStatus'
import { useTopBannerContext } from 'components/IntegratePages/layout/TopBanners/TopBanner/context'
import Link from 'next/link'
import { useRouter } from 'next/router'
import { useDispatch, useSelector } from 'react-redux'
import { IReduxState } from 'types/reduxStateTypes'
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'
import { trackClickUpgrade } from 'components/features/aiSessions/components/utils'

const Container = styled.div<{ $variant: 'lowCredits' | 'taraLite' }>`
	position: relative;
	background: ${({ $variant }) => $variant === 'taraLite' ? '#fdecff' : 'rgba(254, 214, 77, 0.25)'};
	border: 1px solid ${({ $variant }) => $variant === 'taraLite' ? '#fdecff' : 'rgba(254, 214, 77, 0.25)'};
	border-radius: 4px;
	padding: 9px 20px;
	display: flex;
	justify-content: center;
	align-items: center;
	gap: 4px;
	color: rgba(37, 60, 102, 1);
	font-size: 14px;
	a {
		margin-left: 4px;
		margin-right: 4px;
		color: rgba(37, 60, 102, 1);
		font-weight: 700;
		text-decoration: underline;
	}
	svg {
		margin-right: 4px;
	}
	button {
		background: ${({ $variant }) => $variant === 'taraLite' ? 'rgba(255, 255, 255, 0.8)' : 'rgba(255, 255, 255, 0.45)'};
		font-size: 13px;
		line-height: 13px;
		padding: 5px 10px;
		margin-left: 8px;
		${({ $variant }) => $variant === 'taraLite' && `
			border: 1.5px solid rgba(238, 94, 221, 0.5);
		`}
	}
`

const CloseButton = styled.button`
	position: absolute;
	top: 50%;
	transform: translateY(-50%);
	right: 10px;
	margin: 0 !important;
	padding: 0 !important;
	border: none !important;
	background: transparent !important;
	height: 16px;
	width: 16px;
	cursor: pointer;
`

const TextContent = styled.span`
	display: flex;
	align-items: center;
	gap: 4px;
	span {
		font-weight: 500;
	}
`

type TopBannerContentLimitsProps = {
	variant: 'lowCredits' | 'taraLite'
}

const TopBannerContentLimits = ({ variant }: TopBannerContentLimitsProps) => {
	const { setTaraBacthLimitOpen } = useTopBannerContext()
	const { setUpgradeModalVisible } = useAISessionWatchlist()
	const router = useRouter()
	const dispatch = useDispatch()
	const { parentType } = router.query
	const {
		currentOrgReducer: {
			orgId
		}
	} = useSelector( ( state: IReduxState ) => state )

	const handleClose = useCallback( () => {
		setTaraBacthLimitOpen( false )
	}, [ setTaraBacthLimitOpen ] )

	const handleUpgradeClick = useCallback( () => {
		dispatch(trackClickUpgrade({
			taraProduct: variant === 'taraLite' ? 'upgrade_request' : 'all_credits_used',
			parentType: (parentType as string) || 'unknown',
			source: 'banner'
		}))

		setUpgradeModalVisible( true )
	}, [ setUpgradeModalVisible, parentType, dispatch, variant ] )
	if (variant === 'taraLite') {
		return (
			<Container $variant="taraLite">
				<TextContent>
					<IconTaraLiteInfo />
					<span>Showing limited sample with Tara Lite.</span>
					Unlock deeper insights with Tara Pro
				</TextContent>
				<TaraButton onClick={ handleUpgradeClick }>
					Unlock Tara Pro
				</TaraButton>
				<CloseButton onClick={ handleClose }>
					<IconClose />
				</CloseButton>
			</Container>
		)
	}

	return (
		<Container $variant="lowCredits">
			<IconWarning />
			You&apos;ve used all your
			<Link
				href={{
					pathname: '/integration',
					query: {
						setting: 'org_setting',
						org: orgId,
						org_tab: 'tara-ai',
						parentType: 'settings',
					},
				}}
				target="_blank"
				as={`/settings/org/${orgId}/tara-ai`}
				rel="noopener noreferrer"
			>
				monthly credits.
			</Link>
			<TaraButton onClick={ handleUpgradeClick }>
				Upgrade plan
			</TaraButton>
			<CloseButton onClick={ handleClose }>
				<IconClose />
			</CloseButton>
		</Container>
	)
}

export default TopBannerContentLimits