import React from 'react'
import styled, { createGlobalStyle } from 'styled-components'
import { Button } from 'uxcam-frontend-components'
import { theme } from 'theme'
import { Modal } from 'antd'

const GlobalStyles = createGlobalStyle`
	.delete-chat-modal {
		.ant-modal-content {
			border-radius: 8px;
			box-shadow: none;
			.ant-modal-body {
				padding: 32px;
			}
		}
	}
`

const TextSection = styled.div`
	display: flex;
	flex-direction: column;
	gap: 12px;
`

const Title = styled.h2`
	font-family: Roboto;
	font-weight: 500;
	font-size: 18px;
	line-height: normal;
	color: ${theme.colors.surface500.toString()};
	margin: 0;
`

const Description = styled.p`
	font-family: Roboto;
	font-weight: 400;
	font-size: 12px;
	line-height: 24px;
	color: ${theme.colors.surface400.toString()};
	margin: 0;
`

const Footer = styled.div`
	display: flex;
	justify-content: flex-end;
	gap: 16px;
	margin-top: 32px;
`

const CancelButton = styled(Button)`
	background: ${theme.colors.primarySnow.toString()} !important;
	color: ${theme.colors.primary500.toString()} !important;
	border: none !important;
	min-width: 100px !important;

	&:hover:not(:disabled) {
		background: #E6F2FF !important;
		color: ${theme.colors.primary600.toString()} !important;
	}
`

const DeleteButton = styled(Button)`
	background: #FEEEED !important;
	color: #F4584C !important;
	border: none !important;
	min-width: 130px !important;

	&:hover:not(:disabled) {
		background: #FDD9D6 !important;
		color: #E34238 !important;
	}

	&:disabled {
		opacity: 0.6;
	}
`

interface IDeleteChatModalProps {
	visible: boolean
	chatName: string
	onCancel: () => void
	onConfirm: () => void
	isDeleting: boolean
}

const DeleteChatModal: React.FC<IDeleteChatModalProps> = ({ visible, chatName, onCancel, onConfirm, isDeleting }) => {
	return (
		<>
			<GlobalStyles />
			<Modal
				visible={visible}
				closable={false}
				footer={null}
				className='delete-chat-modal'
				centered
				width={570}
			>
				<TextSection>
					<Title>Delete &ldquo;{chatName}&rdquo;?</Title>
					<Description>
						This action cannot be undone and all messages will be permanently deleted.
					</Description>
				</TextSection>
				<Footer>
					<CancelButton
						type="button"
						variant="ghost"
						size="large"
						onClick={onCancel}
						disabled={isDeleting}
					>
						Cancel
					</CancelButton>
					<DeleteButton
						type="button"
						variant="primary"
						size="large"
						onClick={onConfirm}
						disabled={isDeleting}
					>
						Delete
					</DeleteButton>
				</Footer>
			</Modal>
		</>
	)
}

export default DeleteChatModal
