import React, { useMemo } from 'react';
import { Progress } from 'antd';
import { useSelector } from 'react-redux';
import styled from 'styled-components';

import { useFetchCheckListById } from '../OnboradingChecklist';

const StyledProgress = styled(Progress)`
  // .ant-progress-text {
  //   .anticon-check {
  //     width: 100% !important;
  //     height: 100% !important;
  //     text-align: center;
  //     display: flex;
  //     justify-content: center;
  //     align-items: center;
  //     svg {
  //       width: 11px;
  //       height: 11px;
  //     }
  //   }
  // }
`;

const CheckListPercentage = () => {
  const { currentAppReducer: currentApp } = useSelector((state) => state);
  const { _id: appId } = currentApp;

  const { data: checkList } = useFetchCheckListById(appId);

  const completedChecklistPercent = useMemo(() => {
    if (checkList) {
      const calculatePercent = Object.values(checkList).filter(
        (val) => val === true
      );
      const totalCriteria = Object.keys(checkList).length;
      const result = (calculatePercent.length / totalCriteria) * 100;
      return parseInt(result, 10);
    }
    return 0;
  }, [checkList]);

  return (
    <StyledProgress
      type="circle"
      width={25}
      percent={completedChecklistPercent}
    />
  );
};

export default CheckListPercentage;
