import React, { useState, useRef } from 'react';
import styled from 'styled-components';
import { Tooltip } from 'antd';

const ChildText = styled.p`
  white-space: pre;
  overflow: hidden;
  text-overflow: ellipsis;
  width: ${({widthValue})=> widthValue ? `${widthValue}px` : undefined};
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  margin: 0;
  padding: 0;
`;

const EllipsisTooltip =  ({
  children,
  title,
  width
}) => {
  const [visible, setVisible] = useState(false);
  const container = useRef(null);

  const handleVisibleChange = (updatedVisible) => {
    if (container.current.clientWidth < container.current.scrollWidth) {
      setVisible(updatedVisible);
    }
  };

  return (
    <Tooltip
      visible={ visible }
      onVisibleChange={ handleVisibleChange }
      title={ title }
      overlayStyle={ { whiteSpace: 'pre' } }
    >
      <ChildText
        ref={ container }
        widthValue={width}
        className='ellipse-tooltip-text'
      >
        { children }
      </ChildText>
    </Tooltip>
  );
}

const TruncateField = ({ value, width }) => (
  <EllipsisTooltip title={value} width={width}>
    {value}
  </EllipsisTooltip>
);

export default TruncateField;
