import React, { useMemo } from 'react'
import { useSelector } from 'react-redux'
import type { IReduxState } from 'types/reduxStateTypes'
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'
import TopBanner from "../TopBanner"
import TopBannerContentLimits from './TopBannerContentLimits'
import { useTopBannerContext } from '../TopBanner/context'

type TopBannerTaraBatchLimitProps = {
	isBatchFlag: boolean
}

const TopBannerTaraBatchLimit = ({ isBatchFlag }: TopBannerTaraBatchLimitProps) => {
	const { taraBatchLimitOpen } = useTopBannerContext()
	const { currentOrgReducer } = useSelector( ( state: IReduxState ) => state )
	const isTaraProPackage = currentOrgReducer?.isTaraProPackage ?? false
	const { remainingCredits, creditsUsageISLoading } = useAISessionWatchlist()

	const variant = useMemo(() => {
		// Low credits banner only shows when batch flag is enabled
		if (isBatchFlag && remainingCredits <= 0 && !creditsUsageISLoading) {
			return 'lowCredits'
		}
		// Tara Lite banner shows regardless of batch flag
		if (!isTaraProPackage) {
			return 'taraLite'
		}
		return null
	}, [isBatchFlag, remainingCredits, creditsUsageISLoading, isTaraProPackage])
	if (!variant) {
		return null
	}

	return (
		<TopBanner open={ taraBatchLimitOpen }>
			<TopBannerContentLimits variant={ variant } />
		</TopBanner>
	)
}

export default TopBannerTaraBatchLimit