import { TARA_API_VERSION } from 'components/common/AIAssistant/utils';
import { axiosInstance } from './globalInstance';

export interface CostBreakdown {
  model: string;
  persona: string;
  provider: string;
  total_prompt_tokens: number;
  total_completion_tokens: number;
  total_tokens: number;
  total_cached_tokens: number;
  total_cost: number;
  cost_source: string;
  tara_version: string;
  created_at: string;
}

export interface DebugCostResponse {
  invocation_id: string;
  app_id: string;
  cost_breakdown: CostBreakdown[];
  total_records: number;
  total_cost: number;
  total_tokens: number;
  models: string[];
  tara_version: string;
}

const VERSION_TO_PROXY: Record<TARA_API_VERSION, { proxy: string; env: string }> = {
  [TARA_API_VERSION.PROD]: { proxy: '/_tara_prod', env: process.env.TARA_PROD_API || '' },
  [TARA_API_VERSION.UAT]: { proxy: '/_tara_uat', env: process.env.TARA_UAT_API || '' },
  [TARA_API_VERSION.STAGING]: { proxy: '/_tara_staging', env: process.env.TARA_STAGING_API || '' },
  [TARA_API_VERSION.EXPERIENCE]: { proxy: '/_tara_experience', env: process.env.TARA_EXPERIENCE_API || '' },
  [TARA_API_VERSION.CX]: { proxy: '/_tara_cx', env: process.env.TARA_CX_API || '' },
  [TARA_API_VERSION.BIZOPS]: { proxy: '/_tara_bizops', env: process.env.TARA_BIZOPS_API || '' },
  [TARA_API_VERSION.RESEARCH]: { proxy: '/_tara_research', env: process.env.TARA_RESEARCH_API || '' },
};

class DebugApi {
  private static getBaseURL(version: TARA_API_VERSION, useProxy: boolean): string {
    const config = VERSION_TO_PROXY[version] || VERSION_TO_PROXY[TARA_API_VERSION.PROD];
    return useProxy ? config.proxy : config.env;
  }

  static async getCostDetails(
    invocationId: string,
    appId: string,
    version: TARA_API_VERSION = TARA_API_VERSION.PROD
  ): Promise<DebugCostResponse> {
    const useProxy = process.env.USE_PROXY === 'true';

    const baseURL = DebugApi.getBaseURL(version, useProxy);

    const response = await axiosInstance.get(
      `${baseURL}/debug/cost`,
      {
        params: {
          invocation_id: invocationId,
          app_id: appId,
        },
        withCredentials: true,
      }
    );
    return response.data;
  }

  static async clearChat(
    appId: string,
    sessionId: string,
    version: TARA_API_VERSION = TARA_API_VERSION.PROD,
    persona = 'assistant'
  ): Promise<{ success: boolean; message: string; deleted_count: number }> {
    const useProxy = process.env.USE_PROXY === 'true';

    const baseURL = DebugApi.getBaseURL(version, useProxy);

    const response = await axiosInstance.post(
      `${baseURL}/remove/chat`,
      {
        app_id: appId,
        persona,
        session_id: sessionId,
      },
      {
        withCredentials: true,
      }
    );
    return response.data;
  }
}

export default DebugApi;
