const StyledStrong = styled.strong`
	white-space: nowrap;
`

const boldQuotedAndSessions = (text: string) => {
  if (text.startsWith("Sessions from the ")) {
    const prefix = "Sessions from the ";
    const after = text.slice(prefix.length);
    return (
      <>
        {prefix}
        <b>{after}</b>
      </>
    );
  }

  const match = text.match(/'(.*?)'/);
  if (!match) return text;

  const [fullMatch, innerText] = match;
  const [before, after] = text.split(fullMatch);

  return (
    <>
      {before}
      <b>{`'${innerText}'`}</b>
      {after}
    </>
  );
}

export const generateTooltipContent = ( data?: TSessionMetaResponse ) => {
	if (!data) return '';

	const { total_sessions: totalSessions, descriptions } = data;

	if (!descriptions?.length) return '';

	return (
		<>
			The assistant will respond based on <StyledStrong>{`${totalSessions} session${ totalSessions === 1 ? '' : 's' }`} </StyledStrong> filtered with the following criteria:
			<ul>
				{descriptions?.map((desc) => (
					<li key={desc}>{boldQuotedAndSessions(desc)}</li>
				))}
			</ul>
		</>
	);
}

const TopButton = ( { loading, onStop, onSend, disabled }: Pick<IProps, 'loading' | 'onStop' | 'onSend' | 'disabled' > ) => {
	if ( loading ) {
		return (
			<StopButton onClick={onStop}>
				<StopIcon />
			</StopButton>
		)
	}

	return (
		<SendButton onClick={onSend} disabled={disabled}>
			<Icon />
		</SendButton>
	)
}

const ChatInput = ({
	value,
	onChange,
	onKeyDown,
	disabled,
	onSend,
	loading = false,
	onStop,
	onSuggestionsClick,
	showSuggestionsButton = false,
	suggestionsActive = false,
	cursorToFirstToken = false,
	onCursorPlaced,
	secondaryPlaceholder,
}: IProps) => {
	const { aiSessionFeatureAllowed: isTaraEnabled } = useRestrictionContext() as unknown as { aiSessionFeatureAllowed: boolean }
	const { debugMode } = useAISidebarContext()
	const {
		creditsUsageISLoading,
		remainingCredits,
		setUpgradeModalVisible,
	} = useAISessionWatchlist()
	const dispatch = useDispatch()
	const router = useRouter()
	const { parentType } = router.query
	const {
		currentOrgReducer: {
			status: orgStatus,
		},
	} = useSelector( ( state: IReduxState ) => state)

	const { sessionMeta, sessionMetaIsFetching } = useSessionMeta( 'AI STREAM - error getting ai chat messages', undefined, true )

	const tooltipContent = React.useMemo(() => generateTooltipContent(sessionMeta), [sessionMeta]);

	const handleUpgradeClick = useCallback( () => {
		dispatch(trackClickUpgrade({
			taraProduct: 'chat',
			parentType: (parentType as string) || 'unknown',
			source: 'chat'
		}))

		setUpgradeModalVisible( true )
	}, [ setUpgradeModalVisible, parentType, dispatch ] )

	const shouldShowYellowBannerRef = useRef(false);

	useEffect(() => {
		if (!creditsUsageISLoading) {
			shouldShowYellowBannerRef.current = Math.ceil(remainingCredits) <= 50 || orgStatus === 'Canceled';
		}
	}, [creditsUsageISLoading, remainingCredits, orgStatus]);

	const yellowBanner = useMemo(() => {
		if ( !isTaraEnabled ) return false

		if (creditsUsageISLoading) {
			return shouldShowYellowBannerRef.current;
		}
		return Math.ceil(remainingCredits) <= 50 || orgStatus === 'Canceled';
	}, [remainingCredits, creditsUsageISLoading, isTaraEnabled, orgStatus])

	const chatCredits = useMemo( () => {
		if ( typeof remainingCredits !== 'number' && !remainingCredits || creditsUsageISLoading ) {
			return '-/- credits left'
		}

		const roundedRemaining = Math.max(0, Math.ceil( remainingCredits ))

		return `${ roundedRemaining.toLocaleString() } credit${ roundedRemaining !== 1 ? 's' : '' } left`
	}, [ remainingCredits, creditsUsageISLoading ] )

	const chatIcon = useMemo( () => {
		if ( yellowBanner && Math.max(0, Math.ceil( remainingCredits )) === 0 ) {
			return <IconWarning />
		}
		return <IconCoin />
	}, [ yellowBanner, remainingCredits ] )

	const { isLoggedInAsAdminAdmin } = useIsLoggedInAdmin()
	const shouldIgnoreLimits = isLoggedInAsAdminAdmin
	const creditLimitReached = useMemo( () => {
		if ( shouldIgnoreLimits ) return false

		return ( !creditsUsageISLoading && Math.ceil( remainingCredits ) <= 0 ) || orgStatus === 'Canceled'
	}, [ shouldIgnoreLimits, creditsUsageISLoading, remainingCredits, orgStatus ] )

	return (
		<Wrapper>
			<ChatInputContainer>
				<TopWrapper $noBottomBorder={ !isTaraEnabled }>
					<InputRow>
						<TokenizedInput
							placeholder={loading ? "Tara is thinking..." : "Ask Tara anything..."}
							value={value}
							onChange={onChange}
							onKeyDown={onKeyDown}
							disabled={disabled || ( isTaraEnabled ? creditLimitReached : false )}
							cursorToFirstToken={cursorToFirstToken}
							onCursorPlaced={onCursorPlaced}
							secondaryPlaceholder={secondaryPlaceholder}
						/>
						{ isTaraEnabled && !showSuggestionsButton && (
							<TopButton
								disabled={ disabled || ( isTaraEnabled ? creditLimitReached : false ) }
								onSend={ onSend }
								onStop={ onStop }
								loading={ loading }
							/>
						) }
					</InputRow>
					{ showSuggestionsButton && (
						<TopInner>
							{ onSuggestionsClick && (
								<PromptSuggestionButton
									onClick={onSuggestionsClick}
									isActive={suggestionsActive}
									disabled={loading}
								/>
							)}
							{ isTaraEnabled && (
								<TopButton
									disabled={ disabled || ( isTaraEnabled ? creditLimitReached : false ) }
									onSend={ onSend }
									onStop={ onStop }
									loading={ loading }
								/>
							) }
						</TopInner>
					) }
				</TopWrapper>
				<BottomBar $isTaraEnabled={ isTaraEnabled } $yellow={ yellowBanner }>
					<BottomBarLeft>
						{ isTaraEnabled ? (
							<>
								{ chatIcon }
								{ chatCredits }
							</>
						) : (
							<CountIndicator
								loading={sessionMetaIsFetching}
								tooltip={tooltipContent}
								count={sessionMeta?.total_sessions || 0}
							/>
						) }
					</BottomBarLeft>
					{ yellowBanner && !debugMode && (
						<TaraButton onClick={ handleUpgradeClick }>
							<WatchMoreText>
								Upgrade plan
							</WatchMoreText>
						</TaraButton>
					) }
					{ !isTaraEnabled && (
						<SendButton onClick={onSend} disabled={disabled} $large={ !isTaraEnabled }>
							<Icon />
						</SendButton>
					) }
				</BottomBar>
			</ChatInputContainer>
			<Info>
				I do my best, but I can make mistakes. Please verify key info.
			</Info>
		</Wrapper>
	);
};

export default ChatInput;
