import React, { useCallback } from 'react'
import { message as messageAntd } from 'antd'
import { MessageType } from 'antd/lib/message'
import SuccessIcon from 'public/static/icon-checkmark-green-circle.svg'
import ErrorIcon from 'public/static/icon-error-circle.svg'
import ExplanationMarkIcon from 'public/static/icon-explanation-mark-circle.svg'

interface IMessageProps {
	content: string;
	type: 'success' | 'error' | 'info';
}

const useMessage = (): {
	message: ( { content, type }: IMessageProps ) => MessageType,
} => {

	const getIcon = useCallback( ( type: IMessageProps[ 'type' ] ) => {
		switch( type ) {
			case 'error':
				return <ErrorIcon />
			case 'info':
				return <ExplanationMarkIcon />
			default:
				return <SuccessIcon />
		}
	}, [] )

	const message = useCallback( ( { content, type }: IMessageProps ) => (
		messageAntd.open( { 
			content,
			type,
			icon: getIcon( type ),
			className: "new-message",
			duration: 5,
		} )
	), [ getIcon ] )

	return {
		message,
	}
}

export default useMessage