import React from 'react'
import { UFCModal } from 'uxcam-frontend-components'
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'
import CheckIcon from 'public/static/icon-checkmark-green-circle.svg'
import styled, { createGlobalStyle } from 'styled-components'
import { Footer, StyledButton, SubTitle, Title } from '../common'

const TitleWrapper = styled.div`
	margin-bottom: 8px;
	display: flex;
	align-items: center;
	gap: 8px;
`

const GlobalStyles = createGlobalStyle`
	.duration-modal {
		.ufc-modal-container {
			padding: 32px;
		}
	}
`

const SessionUpgradeSuccess = () => {
	const { successModalVisible, setSuccessModalVisible } = useAISessionWatchlist()

	const handleClose = () => {
		setSuccessModalVisible( false )
	}

	const footer = (
		<Footer>
			<StyledButton
				type="button"
				variant="ghost"
				size="large"
				onClick={ handleClose }
			>
				Close
			</StyledButton>
		</Footer>
	)

	return (
		<>
			<GlobalStyles />
			<UFCModal
				visible={ successModalVisible }
				footer={ footer }
				closable={ false }
				className='duration-modal'
				style={{top: 0}}
			>
				<TitleWrapper>
					<CheckIcon />
					<Title>
						Request received
					</Title>
				</TitleWrapper>
				<SubTitle>
					We’ve received your request to upgrade Tara’s plan. Our team will contact you via email shortly.
				</SubTitle>
			</UFCModal>
		</>
	)
}

export default SessionUpgradeSuccess