import React, { useEffect, useState } from 'react';
import styled from 'styled-components';
import { redirectToTaraDashboard } from 'Utils/helpers/taraDashboard';

const REDIRECT_AFTER_SECONDS = 8;

const Screen = styled.div`
  display: flex;
  min-height: 100vh;
  align-items: center;
  justify-content: center;
  background: #f5f6fa;
  padding: 24px;
`;

const Card = styled.div`
  width: 100%;
  max-width: 440px;
  border: 1px solid #e4e7ef;
  border-radius: 8px;
  background: #fff;
  padding: 32px;
  text-align: center;

  h1 {
    margin: 0;
    font-size: 18px;
    font-weight: 600;
    color: #2f3345;
  }

  .redirect-countdown {
    margin: 16px 0 0;
    font-size: 12px;
    color: #6b7188;
  }
`;

/**
 * Full-screen interstitial for authenticated users whose organization signed
 * up through Tara (organization.signupSurface === 'tara'). Shows a brief
 * redirect notice, then auto-redirects to the new dashboard (shared `.uxcam.com`
 * cookies keep them signed in). Exact mirror of Tara's
 * NewDashboardAccessGateScreen, pointing the opposite way.
 */
const TaraDashboardGateScreen = () => {
  const [secondsLeft, setSecondsLeft] = useState(REDIRECT_AFTER_SECONDS);

  useEffect(() => {
    const intervalId = window.setInterval(() => {
      // Clamp at zero so the redirect effect below fires exactly once — an
      // ever-decreasing counter would re-trigger it every second while the
      // navigation is still in flight.
      setSecondsLeft((seconds) => (seconds <= 0 ? 0 : seconds - 1));
    }, 1000);
    return () => window.clearInterval(intervalId);
  }, []);

  useEffect(() => {
    if (secondsLeft === 0) redirectToTaraDashboard();
  }, [secondsLeft]);

  return (
    <Screen>
      <Card>
        <h1>Redirecting to your UXCam dashboard</h1>
        <p className="redirect-countdown" aria-live="polite">
          Redirecting in {Math.max(secondsLeft, 0)}s…
        </p>
      </Card>
    </Screen>
  );
};

export default TaraDashboardGateScreen;
