/* eslint-disable no-nested-ternary */
import React from 'react'
import dynamic from 'next/dynamic'
import styled from 'styled-components'
import { useDispatch } from "react-redux"
import { getOrgList } from 'redux/actions/common'
import ReactLoader from '../../common/reactLoading'

const CreateAppNew = dynamic(import('./CreateAppNew'), {
  loading: () => <ReactLoader />
})

export const ModalWrapper = styled.div`
  > button {
    position: absolute;
    top: 16px;
    right: 16px;
    cursor: pointer;
    z-index: 10;
    border: none;
    background: transparent;
    box-shadow: none;
  }
`

const WelcomeMessage = ( { resetStatus } ) => {
  const dispatch = useDispatch()

  React.useEffect(() => {
    dispatch(getOrgList())
  }, [dispatch])
  
  return <CreateAppNew resetStatus={ resetStatus }/>
};

export default React.memo( WelcomeMessage )