import React, { createContext, useContext, useState, useCallback, useMemo } from 'react';

interface FeedbackModalState {
  isOpen: boolean;
  messageId: string;
  invocationId: string;
  sessionId: string;
}

interface FeedbackModalContextValue {
  modalState: FeedbackModalState;
  openModal: (messageId: string, invocationId: string, sessionId: string) => void;
  closeModal: () => void;
  isSubmitting: boolean;
  setIsSubmitting: (value: boolean) => void;
  submittedMessageId: string | null;
  setSubmittedMessageId: (messageId: string | null) => void;
}

const initialState: FeedbackModalState = {
  isOpen: false,
  messageId: '',
  invocationId: '',
  sessionId: '',
};

const FeedbackModalContext = createContext<FeedbackModalContextValue | null>(null);

export const useFeedbackModal = () => {
  const context = useContext(FeedbackModalContext);
  if (!context) {
    throw new Error('useFeedbackModal must be used within a FeedbackModalProvider');
  }
  return context;
};

interface FeedbackModalProviderProps {
  children: React.ReactNode;
}

export const FeedbackModalProvider: React.FC<FeedbackModalProviderProps> = ({ children }) => {
  const [modalState, setModalState] = useState<FeedbackModalState>(initialState);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submittedMessageId, setSubmittedMessageId] = useState<string | null>(null);

  const openModal = useCallback((messageId: string, invocationId: string, sessionId: string) => {
    setModalState({
      isOpen: true,
      messageId,
      invocationId,
      sessionId,
    });
  }, []);

  const closeModal = useCallback(() => {
    setModalState(initialState);
  }, []);

  const value = useMemo(
    () => ({
      modalState,
      openModal,
      closeModal,
      isSubmitting,
      setIsSubmitting,
      submittedMessageId,
      setSubmittedMessageId,
    }),
    [modalState, openModal, closeModal, isSubmitting, submittedMessageId]
  );

  return (
    <FeedbackModalContext.Provider value={value}>
      {children}
    </FeedbackModalContext.Provider>
  );
};
