/* eslint-disable react/jsx-no-useless-fragment */
import React, { memo, useMemo } from 'react'
import { useSelector } from 'react-redux'
import dynamic from 'next/dynamic'

import MegaFilter from 'components/shared/GlobalFilter/components';
import { megaFilterIncludedPageList } from 'Utils/constants/index';
import AISessionFilter from './components/aiSessionFilter';

const FilterDisplayBar = dynamic( import('components/shared/GlobalFilter/components/FilterDisplayBar'), { loading: () => <></> } );

const GlobalFilter = ({ isFilterDisplayBar }) => {
  const { parentType, sessionid } = useSelector(state => state.urlReducer)
  
  const shouldRenderAISessionFilter = useMemo(() => 
    parentType === 'aiSessionsList' && sessionid,
    [parentType, sessionid]
  );

  if(megaFilterIncludedPageList.indexOf(parentType) === -1) return <></>
  
  if(shouldRenderAISessionFilter) {
    return <AISessionFilter />
  }
  return (
    isFilterDisplayBar ?  <FilterDisplayBar /> : <MegaFilter />
  )
}

export default memo(GlobalFilter);