const AISideChatRenderer = ({ showAISideChat, showTopMenuBar, urlParam, topLevelFilterBar, children }) => {
  const sidebarContext = useAISidebarContext()
  const actuallyShowSideChat = showAISideChat && sidebarContext.isVisible

  return (
    <SplitContainer split={ actuallyShowSideChat }>
      <SplitMainWrapper>
        <TopBanners />
        <SplitMain>
          { showTopMenuBar && (
            <TopMenu query={urlParam} />
          ) }
          <SplitMainScrollable id="main-scrollable-container">
            {topLevelFilterBar}
            {cloneElement(children)}
          </SplitMainScrollable>
        </SplitMain>
      </SplitMainWrapper>
      { actuallyShowSideChat && (
        <SplitRight isExpanded={sidebarContext.isExpanded}>
          <AIAssistantContextProvider>
            <AIAssistant />
          </AIAssistantContextProvider>
        </SplitRight>
      ) }
    </SplitContainer>
  )
}

const RenderSplitContainer = ( { parentType, currentApp, orgId, orgList, objIncludesFeature, planFeatures, featureKeyObj, urlParam, topLevelFilterBar, children } ) => {
  const { pageIsLocked, aiSessionFeatureAllowed } = useRestrictionContext()
  const showTopMenuBar = useMemo( () => {
    if (megaFilterIncludedPageList.indexOf(parentType) > -1 && currentApp.isIntegrated && !pageIsLocked) {
      const indexBy = orgId && orgList.length && findLastIndex(orgList, { orgId });
      const hasAccessOrg = indexBy > -1 && orgList[indexBy].hasAccess;
      const isFeatureEnabled = hasAccessOrg && objIncludesFeature ? planFeatures?.[featureKeyObj[parentType]] : true
      if ( isFeatureEnabled ) {
        return true
      }
    }

    return false
  }, [ currentApp, featureKeyObj, objIncludesFeature, orgId, orgList, pageIsLocked, parentType, planFeatures ] )
  const showAISideChat = useMemo( () => parentType === 'aiSessionsList' && showTopMenuBar && aiSessionFeatureAllowed, [ parentType, showTopMenuBar, aiSessionFeatureAllowed ] )

  return (
    <AISidebarContextProvider appId={urlParam?.appId}>
      <AISideChatRenderer
        showAISideChat={showAISideChat}
        showTopMenuBar={showTopMenuBar}
        urlParam={urlParam}
        topLevelFilterBar={topLevelFilterBar}
      >
        { children }
      </AISideChatRenderer>
    </AISidebarContextProvider>
  )
}

const SetReduxFeatureFlags = React.memo( () => {
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext();

  const dispatch = useDispatch()

  React.useEffect( () => {
    dispatch(setNoCodeFlag(noCodeEventsFeatureFlag))
  }, [noCodeEventsFeatureFlag, dispatch] )

  return null
} )

const CloseToolbarOnParentTypeChange = React.memo( ( { parentType } ) => {
  const { setOpen, setContent } = useFloatingToolbarContext()

  useEffect( () => {
    setOpen( false )
    setContent( null )
  }, [ parentType, setOpen, setContent ] )

  return null
} )
const ScreenListPrefetchWrapper = React.memo(() => {
  useScreenListPrefetch();
  return null;
});

const ShareErrorHandler = React.memo(() => {
  const [shareError, setShareError] = useState(null);
  const dispatch = useDispatch();

  useEffect(() => {
    const url = new URL(window.location.href);
    const error = url.searchParams.get('shareError');
    if (error) {
      setShareError(error);
      if (error === 'expired') {
        dispatch(trackPageViews(null, { eventName: 'wa_tara_share_expired', track_type: 'event' }))
      } else if (error === 'no_permission') {
        dispatch(trackPageViews(null, { eventName: 'wa_tara_share_chat_blocked', track_type: 'event' }))
      }
      url.searchParams.delete('shareError');
      window.history.replaceState({}, '', url.toString());
    }
  }, []);

  const handleClose = () => setShareError(null);

  if (shareError === 'chat_limit') {
    return (
      <ChatLimitModal
        visible
        onClose={handleClose}
        title="Chat limit reached"
        description="You've reached the maximum number of chats allowed. To start a new conversation, please delete an existing chat from your sidebar."
      />
    );
  }

  return (
    <ShareChatErrorModal
      visible={!!shareError}
      errorType={shareError}
      onClose={handleClose}
      onSwitchAccount={() => {
        window.location.href = `/logout?redirect=${window.location.pathname}`;
      }}
    />
  );
});

const ComponentLayout = ({ children, query: urlParam }) => {
  const {
    commonReducer,
    currentOrgReducer: currentOrgSubscription,
    sidebarReducer,
    profileReducer: profile,
    currentAppReducer: currentApp,
    recordingStatusBanner,
    applicationReducer: orgList,
    selectedSessionReducer: selectedSession,
    selectedUserReducer: selectedUser,
    megaFilterReducer,
    organizationReducer: organizationList,
    appFilter
  } = useSelector((state) => state);

  const dispatch = useDispatch();
  const { filterBarVisible } = megaFilterReducer;
  const currentOrg = currentOrgSubscription;
  const parentType = urlParam?.parentType;
  const { bottomBarClassFlag, isVisible_custom_popup:isVisibleCustomPopup } = commonReducer;
  const sidebarCollapseStatus = sidebarReducer.collapse;
  const { isAIEnabled } = currentApp;
  const planFeatureTara = currentOrg?.planFeature?.tara;
  const isToolbarEnabled = !!(planFeatureTara && isAIEnabled);
  const orgId = currentOrg?.orgId;
  const planType = currentOrg?.planType;
  const [expirePlanMsg, setExpirePlanMsg] = useState(false);
  const [ paymentStatus, setPaymentStatus ] = useState(null);
  const [ remainingTrial, setRemainingTrial ] = useState(null);

  const [isOpened, setIsOpened] = useState(false);
  const [orgCsrf, setOrgCsrf] = useState('');
  const isEventOrStatistics = parentType === 'eventsList' || parentType === 'statistics';
  const planFeatures = currentOrg?.planFeature;
  const isPlanPaid = useMemo(() => Array.isArray(orgList) && orgList?.find((org) => org.orgId === orgId)?.subscription?.type === 'paid', [orgId, orgList])

  const showPaymentBanner = useCallback(() => { 
    if( ( window && typeof window === 'undefined' ) || !paymentStatus) return false
    let paymentBannerCloseDate = ''
    try {
      paymentBannerCloseDate = window.localStorage.getItem('paymentBannerCloseDate')
    } catch (err) {
      // silent fail
    }
    const hasBeen24Hrs = paymentBannerCloseDate && new Date(paymentBannerCloseDate).getTime() + 24 * 60 * 60 * 1000 < new Date().getTime();

    if( hasBeen24Hrs === null ) return paymentStatus?.data?.show_banner

    return paymentStatus?.data?.show_banner && !!hasBeen24Hrs
  }, [paymentStatus])

  const isWebApp = useIsAppType( 'web' );
  // eslint-disable-next-line no-underscore-dangle
  const filterOrg = useMemo(()=> organizationList?.length ? organizationList.find((org) => org._id === currentOrgSubscription?.orgId) : {}, [currentOrgSubscription, organizationList] ) ;
  const hasTaraTrialNotExpired = useMemo(() => {
    if (!currentOrg?.taraTrialExpiryDate) return false;
    const expiryDate = new Date(currentOrg.taraTrialExpiryDate);
    const now = new Date();
    return expiryDate.getTime() > now.getTime();
  }, [currentOrg?.taraTrialExpiryDate]);
  
  const trialFlag = useMemo(()=> bottomBarClassFlag && (filterOrg?.selfServeCheckout || currentOrg?.onTrial || currentOrg?.planType === "free" || showPaymentBanner() || hasTaraTrialNotExpired) , [bottomBarClassFlag, filterOrg?.selfServeCheckout, currentOrg?.onTrial, currentOrg?.planType, showPaymentBanner, hasTaraTrialNotExpired] )

  const featureKeyObj = useMemo(
    () => ({
      eventsList: 'eventAnalysis',
      statistics: 'eventAnalysis',
      screenFlow: 'screenFlow',
      issues: 'issueAnalytics',
      funnels: 'funnelFeature',
      [urlParam.screenname ? 'screensList' : '']: 'screenAnalysis',
    }),
    [urlParam.screenname]
  );
  const objIncludesFeature = Object.keys(featureKeyObj).indexOf(parentType) > -1;

  const getPlanStatus = useCallback(async () => {
    if( !orgId ) return
    await CommonApi.getPaymentStatus(orgId).then((res) => {
      if (res.status === 200) {
        setPaymentStatus(res.data);
      }
    }).catch((error) => {
      rollbar.error('Error in fetching payment status', error);
    });
  }, [orgId]);

  const getRemainingTrial = useCallback(async () => {
    if( !orgId || planType !== 'trial' ) return
    await CommonApi.getRemainingTrial(orgId).then((res) => {
      if (res.status === 200) {
        setRemainingTrial(res?.data?.data?.remainingTrial);
      }
    }).catch((error) => {
      rollbar.error('Error in fetching remaining trial', error);
    });
  }, [orgId, planType]);

  const setTrialFlagDispatcher = useCallback(async () => {
    if (currentOrg?.orgId) {
      const { onTrial } = currentOrg;

      const bannerFlag = !expirePlanMsg
        ? ((onTrial &&
          remainingTrial &&
          remainingTrial.days + remainingTrial.hours > 0) || planType === "free" || (filterOrg?.selfServeCheckout && onTrial) || showPaymentBanner() || hasTaraTrialNotExpired)
        : false;

      dispatch(setTrialFlag(bannerFlag));
    }
  }, [currentOrg, dispatch, expirePlanMsg, filterOrg?.selfServeCheckout, planType, remainingTrial, showPaymentBanner, hasTaraTrialNotExpired]);
  const handleCsrfAndQuoteModelVisible = async (e) => {
    e.preventDefault();
    const csrfOfOrg = await dispatch(getOrgCsrf());
    if (csrfOfOrg) await setOrgCsrf(csrfOfOrg);
  };
  const hideChatBox = () => setIsOpened(!isOpened);
  const checkZendesk = () => {
    if (window.zE) {
      window.zE(() => {
        window.zE.hide();
        setIsOpened(true);
      });
    }
  };
  
  const ctxClassName = !profile.error
    ? cs({
        'heatmap-hide-scroll': parentType === 'heatmapsList' && urlParam.screenname && !filterBarVisible,
        'wrapper-contracts': !sidebarCollapseStatus,
        'wrapper-expands': sidebarCollapseStatus,
        'feature-unavailable-page':
          objIncludesFeature &&
          planFeatures &&
          !planFeatures[featureKeyObj[parentType]],
        'filter-display-event-wrapper': isEventOrStatistics && filterBarVisible,
      })
    : '';

  const getDataFromUrl = async () => {
    const urlD = await dispatch(decodeUrlV2(urlParam.url, isWebApp))
    if(pageFilterMap[parentType]) await dispatch(addSegmentV2(urlD, pageFilterMap[parentType]))
    // * CX-1876: SYNC ACTIVITY FILTER STATE FROM URL  
    if(pageFilterMap[parentType] === pageFilterMap.usersList) {
        await dispatch(decodeActivityFilterUrl(urlParam.url))
    }
  }

  useEffect(() => {
    getDataFromUrl()
  }, [isWebApp])

  useEffect(() => {
    if(tableValueMap[parentType]) dispatch(setFilterPageTable(tableValueMap[parentType]))
  }, [parentType, dispatch])
  

  useEffect(() => {
    if(urlParam.appId) dispatch(clearStatsData());
  }, [urlParam.appId])

  useEffect(() => {
    checkZendesk();
  }, []);

  useEffect(() => {
    setTrialFlagDispatcher();
  }, [ setTrialFlagDispatcher ]);

  useEffect(() => {
    if( ( window && typeof window === 'undefined' )) return

    let paymentBannerCloseDate = ''
    try {
      paymentBannerCloseDate = window.localStorage.getItem('paymentBannerCloseDate')
    } catch (err) {
      // silent fail
    }
    const hasBeen24Hrs = paymentBannerCloseDate && new Date(paymentBannerCloseDate).getTime() + 24 * 60 * 60 * 1000 < new Date().getTime();

    if( hasBeen24Hrs === null ) getPlanStatus()

    if (isPlanPaid && !!hasBeen24Hrs) {
      getPlanStatus()
    }
  }, [getPlanStatus, isPlanPaid])

  useEffect(() => {
    if( !orgId || planType !== 'trial' ) return
    getRemainingTrial()
  }, [orgId, planType, getRemainingTrial])

  const topLevelFilterBar = useMemo(() => {
    let component = <></>
    const isAccessible = Boolean(megaFilterIncludedPageList.includes(parentType) && selectedSession.length === 0 && selectedUser.length === 0 && currentApp.isIntegrated)
    if (isAccessible) component = <AppFilterV2 key={parentType + currentApp['_id']} isFilterDisplayBar />
    return component
  }, [parentType, selectedSession.length, selectedUser.length, currentApp])
  const selfServeChargebee = useMemo(() => filterOrg?.selfServeCheckout && (planType === "free" || planType === "trial"),[filterOrg?.selfServeCheckout, planType])
  const isAppliedFilterViewOnly = useMemo(() => {
    return (parentType === 'aiSessionsList') && urlParam?.sessionid
    }
    , [parentType, urlParam?.sessionid])
  /**
   * Context data that will be appended to all events tracked by the EventTrackingProvider
   */
  const eventTrackingContextData = useMemo(() => ({
    applicationId: urlParam?.appId,
    organizationId: orgId,
    subscriptionPlan: planType,
    userId: profile?.userId,
    userEmail: profile?.email,
  }), [urlParam?.appId, orgId, planType, profile?.userId, profile?.email])

  const eventTrackingHeaders = useMemo(() => {
    let token

    try {
      const browserCookies = new Cookies();
      token = browserCookies.get('token');
    }
    catch (error) {
      token = ''
    }

    return {
      'Authorization': `Bearer ${token}`,
    }
  }, [] )

  // Orgs that signed up through Tara live on the new dashboard — the exact
  // mirror of Tara's classic-org gate. Blocked only when the active
  // subscription explicitly reports signupSurface === 'tara'; admin-panel
  // logins bypass and an unresolved subscription fails open.
  if (resolveTaraDashboardGate(currentOrgSubscription).blocked) {
    return <TaraDashboardGateScreen />
  }

  return (
    <ConfigProvider direction={{ locale: eng }}>
      <EventTraackingProvider
        contextData={ eventTrackingContextData }
        eventEndpoint={ EventTrackingUrl }
        extraHeaders={ eventTrackingHeaders }
      >
      <SetReduxFeatureFlags />
      <QueryClientProvider client={queryClient}>
        <ScreenListPrefetchWrapper />
        <UserCohortsProvider>
          <StylesProvider>
          <RestrictionContextProvider>
            <ModalProvider>
              <SessionVideoProviderV2 appId={ urlParam?.appId } sessionId={ urlParam?.sessionid }>
                <AISessionUtilsProvider>
                  <FloatingToolbarContextProvider>
                    <TopBannerContextProvider>
                      <AISessionWatchlistContextProvider>
                        <SessionUpgrade />
                        <SessionWatchStatusModals />
                        <AppliedFilterContextProvider viewOnly={isAppliedFilterViewOnly}>
                          <>
                            <HandleLockedFeatures />
                            <NoCodeEventsPopups />
                            <div
                              className="theme-light internal-main-wrapper"
                              id="uxcam-main-layout"
                            >
                              <MainHead
                                brainTreeScript={ parentType === 'settings' ? 'https://js.braintreegateway.com/web/dropin/1.32.0/js/dropin.min.js' : '' }
                                chargebeeScript={ parentType === 'settings' || selfServeChargebee ? 'https://js.chargebee.com/v2/chargebee.js' : '' }
                                trialFlag={trialFlag}
                              />
                              <Layout hasSider>
                                {isEmpty(currentOrgSubscription) ? (
                                  <></>
                                ) : (
                                  <ParentSiderWrapper
                                    trigger={null}
                                    collapsible
                                    collapsed={sidebarCollapseStatus}
                                  >
                                    <ParentSideBarMenu collapsedMenu={sidebarCollapseStatus} />
                                  </ParentSiderWrapper>
                                )}
                                <Content className={ctxClassName} id="main-content-container">
                                  {isToolbarEnabled && (
                                    <>
                                    <StylesProvider>
                                      <FloatingToolbar />
                                    </StylesProvider>
                                      <CloseToolbarOnParentTypeChange parentType={parentType} />
                                    </>
                                  )}
                                  <RenderSplitContainer
                                    parentType={ parentType }
                                    currentApp={ currentApp }
                                    orgId={ orgId }
                                    orgList={ orgList }
                                    objIncludesFeature={ objIncludesFeature } 
                                    planFeatures={ planFeatures }
                                    featureKeyObj={ featureKeyObj }
                                    urlParam={ urlParam }
                                    topLevelFilterBar={ topLevelFilterBar }
                                  >
                                    {children}
                                  </RenderSplitContainer>
                                  {currentApp.isIntegrated &&
                                    parentType &&
                                    recordingStatusBanner.status &&
                                    recordingStatusBanner.message &&
                                    !isWebApp && (
                                      <BannerHtml recordingStatusBanner={recordingStatusBanner} />
                                    ) }
                                  {trialFlag && (
                                    <BannerForTrial
                                      currentOrgSubscription={currentOrgSubscription}
                                      expirePlanMsg={expirePlanMsg}
                                      setTrialFlag={setTrialFlag}
                                      isIntegrated={currentApp.isIntegrated}
                                      handleCsrfAndQuoteModelVisible={
                                        handleCsrfAndQuoteModelVisible
                                      }
                                      paymentStatus={ paymentStatus }
                                      remainingTrial={remainingTrial}
                                      taraTrialExpiryDate={currentOrg?.taraTrialExpiryDate}
                                    />
                                  )}
                                </Content>
                                {isOpened && (
                                  <div className="feedback-btn">
                                    <Button
                                      type="close-chat"
                                      icon={<CloseOutlined />}
                                      onClick={hideChatBox}
                                    />
                                    <Button
                                      type="zen-chat"
                                      onClick={() => window.zE.activate({ hideOnClose: true })}
                                    >
                                      <FaComments />
                                    </Button>
                                  </div>
                                )}
                              </Layout>
                              <InsufficientPrivilege />
                              <CustomPopup
                                isVisible_custom_popup={isVisibleCustomPopup}
                                handleCsrfAndQuoteModelVisible={handleCsrfAndQuoteModelVisible}
                              />
                              {profile?.email && profile?.showUpdateUserProfileModal &&
                              <RoleBasedCustomPopup
                                showUpdateUserProfileModal={profile?.showUpdateUserProfileModal}
                              />
                              }
                              <PlanBasedPricingPopup />
                              <ShareErrorHandler />
                            </div>
                          </>
                        </AppliedFilterContextProvider>
                      </AISessionWatchlistContextProvider>
                    </TopBannerContextProvider>
                  </FloatingToolbarContextProvider>
                </AISessionUtilsProvider>
              </SessionVideoProviderV2>
            </ModalProvider>
          </RestrictionContextProvider>
          </StylesProvider>
        </UserCohortsProvider>
        <ReactQueryDevtools initialIsOpen={false} position='bottom-right' />
      </QueryClientProvider>
      </EventTraackingProvider>
    </ConfigProvider>
  );
}
const BannerHtml = ({ recordingStatusBanner }) => {
  const dispatch = useDispatch();

  useEffect(() => {
    const openIntercomPopupEl = document.getElementById('open-intercom-popup');

    const handleClick = (e) => {
      e.preventDefault();
      showIntercom();
    };

    openIntercomPopupEl?.addEventListener('click', handleClick);

    return () => {
      openIntercomPopupEl?.removeEventListener('click', handleClick);
    };
  }, []);

  return (
    <div className="global-message-bar">
      <img
        alt=''
        src="/static/no-video.svg"
        style={{ width: '20px', marginRight: '10px' }}
      />
      <p>{ReactHtmlParser(recordingStatusBanner.message)}</p>
      <Button
        icon={<CloseOutlined />}
        style={{ fontSize: '12px' }}
        onClick={(e) => dispatch(hideRecordingStatusBanner(e))}
      />
    </div>
  );
};
export default ComponentLayout;
