import React from 'react'
import { useSelector } from "react-redux"
import { IReduxState } from "types/reduxStateTypes"
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import TopBannerTaraBatchLimit from './TopBannerTaraBatchLimit'

const TopBanners = () => {
	const {
		urlReducer: {
			parentType
		}
	} = useSelector( ( state: IReduxState ) => state )
	const { aiSessionFeatureAllowed } = useRestrictionContext() as unknown as { aiSessionFeatureAllowed: boolean }

	const isOnAISessionPage = parentType === 'aiSessionsList' || parentType === 'aiSessionStatistics'

	if ( !isOnAISessionPage || !aiSessionFeatureAllowed ) {
		return null
	}

	return (
		// eslint-disable-next-line react/jsx-no-useless-fragment
		<>
			<TopBannerTaraBatchLimit isBatchFlag={ aiSessionFeatureAllowed } />
		</>
	)
}

export default TopBanners