import React, { useMemo } from 'react';
import { useSelector } from 'react-redux';
import { useQuery } from 'react-query';
import { IEventPropertyFilter, IReduxState } from 'types/reduxStateTypes';
import { AI_SESSIONS_PER_PAGE } from 'components/features/aiSessions';
import { rollbar } from 'components/common/rollbar';
import { LogArgument } from 'rollbar';
import { getSessionMeta, TSessionMetaPayload } from '../queries';

export const useSessionMeta = ( errorMessage?: string, customFilters?: IEventPropertyFilter[], refetchOnMetaChange?: boolean ) => {
	const {
		currentAppReducer: {
			_id: appID
		},
		appFilter: {
			session: {
				segment: appFilterSegment,
			},
			dateSegment,
		},
		urlReducer: {
			sessionpage,
			// sessionid,
		},
	} = useSelector((reduxState: IReduxState) => reduxState);

	const combinedAppFilterSegment = useMemo(() => {
		const filters = [...(appFilterSegment || [])];
		// if (sessionid) {
		// 	filters.push({
		// 		attribute: 'session_id',
		// 		operator: 'in',
		// 		value: [sessionid],
		// 		table: 'session',
		// 	});
		// }
		return filters;
	}, [appFilterSegment]);

	const metaPayload = useMemo(() => ({
		appid: appID as string,
		filters: customFilters || combinedAppFilterSegment,
		date_range: dateSegment,
		page: sessionpage || 1,
		session_per_page: AI_SESSIONS_PER_PAGE,
	}), [appID, combinedAppFilterSegment, dateSegment, sessionpage, customFilters]);

	const { data: sessionMeta, isFetching: sessionMetaIsFetching, refetch: refetchSessionMeta } = useQuery({
		queryKey: ['ai-session-meta', metaPayload],
		queryFn: () => getSessionMeta(metaPayload as TSessionMetaPayload),
		onError: (err: unknown) => {
			if ( errorMessage ) {
				rollbar.error(errorMessage, err as LogArgument);
			}
			rollbar.error(err as LogArgument);
		}
	});

	React.useEffect(() => {
		if ( refetchOnMetaChange ) {
			refetchSessionMeta()
		}
	}, [refetchSessionMeta, metaPayload, refetchOnMetaChange])

	return {
		sessionMeta,
		sessionMetaIsFetching,
		refetchSessionMeta,
	};
};
