import React from "react"
import styled from "styled-components"
import { UFCTooltip, Spinner } from "uxcam-frontend-components"
import FiltersIcon from "public/static/sessions/filters-count-ai.svg"

interface ICountIndicatorProps {
  loading: boolean
  tooltip: string | React.ReactNode
  count: number
  background?: string
}

const Wrapper = styled.div<Pick<ICountIndicatorProps, 'background'>>`
  padding: 6px 8px 6px 6px;
  border-radius: 30px;
  background-color: ${ ( { background } ) => background || '#F5F7FA' };
  font-size: 13px;
  line-height: 16px;
  color: #161E35;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  transition: background-color 0.1s ease;
  cursor: default;
  user-select: none;
  &:hover {
    background-color: ${ ( { background } ) => background || '#DFEAFF' };
  }
`

const IconWrapper = styled.div`
  height: 20px;
  width: 20px;
  background: #FFFFFF;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
`

const SpinnerWrapper = styled.div`
  position: relative;
  height: 20px;
  width: 20px;
`

export const CountIndicator = ( { loading, tooltip, count, background }: ICountIndicatorProps ) => {
	return (
		<UFCTooltip 
				title={ !loading && tooltip && tooltip }
				align={ { offset: [ 0, -10 ] } }
				overlayStyle={ { maxWidth: '285px' } }
			>
			<Wrapper background={ background }>
				<IconWrapper>
					<FiltersIcon />
				</IconWrapper>
					{ loading && (
						<SpinnerWrapper>
							<Spinner data-size="xs" />
						</SpinnerWrapper>
					) }
				{ !loading && (
          <>{count} Session{count === 1 ? '' : 's'}</>
        ) }
			</Wrapper>
		</UFCTooltip>
	)
}