import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import {
  CheckCircleFilled,
  CopyOutlined,
  InfoCircleOutlined,
} from '@ant-design/icons';
import {
  Row,
  Col,
  Avatar,
  Button,
  message,
  Tooltip,
  Collapse,
  Alert,
} from 'antd';
import styled from 'styled-components';
import { useQuery, useMutation, useQueryClient } from 'react-query';

import { CopyToClipboard } from 'react-copy-to-clipboard';

import {
  sensitiveDataBlock,
  integrateOtherAnalyticTool,
  watchCrashSession,
  watchSlippingAwayUserSession,
  handleChecklistCompleted,
  fetchAppCheckList,
} from 'redux/actions/appdropdown';

import InviteButtonField from './InviteButtonField';
import Question from './question';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';

const { Panel } = Collapse;

const StyledLinkButton = styled(Button)`
  color: #5d97ff;
  span {
    text-decoration: underline;
  }
  &:hover {
    border: none;
  }
`;

const StyleDoneButton = styled(Button)`
  height: 34px;
  margin-right: 10px;
`;

const StyledIntegrateWrapper = styled.div``;

const StyledParagraph = styled.p`
  margin-buttom: 10px;
`;

const StyledH2 = styled.h2`
  font-size: 18px !important;
`;

const checkMark = (value) => (
  <CheckCircleFilled
    style={{ opacity: value ? '' : '.2' }}
    onClick={(event) => {
      event.stopPropagation();
    }}
  />
);

const checkListActive = {
  isEnvironmentsCreated: '1',
  isSDKIntegrated: '2',
  isAppScreensTagged: '3',
  isDataCleaned: '4',
  isSensitiveDataBlocked: '5',
  isCustomEventTracked: '6',
  isUserPropertiesUploaded: '7',
  isHandledExceptionsReported: '8',
  isAppAnalyticsToolIntegrated: '9',
  isCrashSessionsWatched: '10',
  isFirstSessionSegmentCreated: '11',
  isSlippingWayUserSessionWatched: '12',
  isMemberInvited: '13',
  isAppScreenRenamed: '14',
};

export const useFetchCheckListById = (appId) =>
  useQuery(['checkList', appId], () => fetchAppCheckList(appId), {});

const Checklist = () => {
  const [hookState, setState] = useState({
    loading: false,
    emailAddress: '',
    doItMyself: false,
    checkIntegrateDone: false,
    visible: false,
    emails: [],
    inviteRole: 1,
    privateMessage: '',
    successVisible: false,
    btnLoadingSensitive: false,
    btnLoading: false,
  });
  const [questionPage, setQuestionPage] = useState(false);
  const [keyValue, setKeyValue] = useState('0');
  const queryClient = useQueryClient();

  const dispatch = useDispatch();
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()
  const { currentAppReducer: currentApp, urlReducer: urlQuery } = useSelector(
    (state) => state
  );

  const { _id: appId } = currentApp;

  const { data: checkList } = useFetchCheckListById(urlQuery?.appId);

  const handleCompleted = (data) => handleChecklistCompleted(data, appId);
  const toogleQuestionPage = (open) => {
    if (open) {
      setQuestionPage(true);
    } else {
      setQuestionPage(false);
    }
  };

  const queryKey = useMemo(() => ['checkList', appId], [appId]);

  const { mutate } = useMutation(handleCompleted, {
    onSuccess: (data) => {
      queryClient.setQueryData(queryKey, (oldData) => {
        const newData = { ...oldData, ...data?.app };
        return newData;
      });
      message.success(data?.message);
    },
    onError: (error) => {
      message.error(error?.data?.error?.message);
    },
  });

  const showModal = () => {};

  const copy = (e) => {
    e.stopPropagation();
    e.preventDefault();
    message.success('copied');
  };

  const handleBlockSensitive = () => {
    setState({
      ...hookState,
      ...{
        btnLoadingSensitive: true,
      },
    });
    dispatch(
      sensitiveDataBlock(appId, {
        sensitiveDataBlocked: true,
      })
    ).then(async (res) => {
      if (res) {
        setState({
          ...hookState,
          ...{
            btnLoadingSensitive: false,
          },
        });
        queryClient.invalidateQueries(queryKey);
      } else {
        // Todo
      }
    });
  };

  const handleAnalyticsTool = () => {
    setState({
      ...hookState,
      ...{
        btnLoading: true,
      },
    });
    dispatch(
      integrateOtherAnalyticTool(appId, { appIntegrateAnalyticTool: true })
    ).then(async (res) => {
      if (res) {
        setState({
          ...hookState,
          ...{
            btnLoading: false,
          },
        });
        queryClient.invalidateQueries(queryKey);
      } else {
        // Todo
      }
    });
  };

  const handleCrashedSessionWatched = async () => {
    if (!checkList?.isCrashSessionsWatched) {
      await dispatch(
        watchCrashSession(appId, { crashSessionWatched: true })
      ).then(async (res) => {
        if (res) queryClient.invalidateQueries(queryKey);
      }).catch(err => err);
    }
    checkList?.isCrashSessionsWatched &&
      window.open(
        `${process.env.REDIRECT_URL}/app/${appId}/sessions/list/1?session_crashed={"o":"equal","v":"True","tb":"session"}`,
        '_blank'
      );
  };

  const handleSlippingWayUserSession = async () => {
    if (!checkList?.isSlippingWayUserSessionWatched) {
      await dispatch(
        watchSlippingAwayUserSession(appId, {
          slippingWayUserSessionWatched: true,
        })
      ).then(async (res) => {
        if (res) {
          queryClient.invalidateQueries(queryKey);
        } else {
          // Todo
        }
      });
    }
    checkList.isSlippingWayUserSessionWatched &&
      window.open(
        `${process.env.REDIRECT_URL}/app/${appId}/users/list/1?user_session_count={"o":"greater","v":"10","tb":"appuser"}&user_session_duration={"o":"greater","v":"1800","tb":"appuser"}&user_last_seen_on={"o":"before","v":"2020-04-15","tb":"appuser"}`,
        '_blank'
      );
  };

  const defaultActive = useMemo(() => {
    let count;
    checkList &&
      Object.keys(checkListActive).map((key) => {
        if (!checkList[key] && count === undefined) {
          count = checkListActive[key];
        }
        return count;
      });
    return count;
  }, [checkList]);

  const handleCollapsed = (key) => {
    setKeyValue(key);
  };

  const WelcomePage = (
    <Col lg={20} className="height-full">
      <StyledIntegrateWrapper className="integrate-wrapper height-full">
        <StyledH2>Getting started guide</StyledH2>
        <div className="accordion-wrapper">
          <h3>Technical setup checklist</h3>
          <Collapse
            accordion
            activeKey={keyValue === '0' ? checkList && defaultActive : keyValue}
            onChange={handleCollapsed}
          >
            <Panel
              header="Create your environments"
              key="1"
              extra={checkMark(checkList?.isEnvironmentsCreated)} // need to update the key
              expandIconPosition="right"
            >
              <StyledParagraph>
                Create separate instances for your test/internal data and your
                production data.
              </StyledParagraph>

              {!checkList?.isEnvironmentsCreated && (
                <StyleDoneButton
                  onClick={() =>
                    checkList?.isSDKIntegrated
                      ? mutate({ step: 'environmentsCreated' })
                      : message.info(
                          'You need to complete the SDK integration at first.'
                        )
                  }
                  // loading={btnLoadingSensitive}
                >
                  Done
                </StyleDoneButton>
              )}

              <a
                href="https://developer.uxcam.com/docs/so-what-does-uxcam-do#your-app-key-"
                target="_blank"
                className="ant-btn ant-btn-primary"
                rel="noreferrer"
              >
                View steps
              </a>
            </Panel>
            <Panel
              header="SDK Integration"
              key="2"
              extra={checkMark(checkList?.isSDKIntegrated)}
              expandIconPosition="right"
            >
              <Row type="flex" justify="center">
                <Col
                  span={12}
                  style={{
                    borderRight: '1px solid #C0CAD9',
                    padding: '10px 30px 10px 0',
                    margin: '-16px 0',
                  }}
                >
                  <div
                    className="demo-video-box"
                    style={{ boxShadow: '0 0 0 transparent' }}
                  >
                    <span>
                      <img
                        src="/static/features_session_recordings.png"
                        style={{ opacity: '1', width: '250px' }}
                        alt=""
                      />
                    </span>
                  </div>
                  <p>
                    Our SDK connects your app with UXCam to import all of your
                    app’s data such as your users' sessions.
                  </p>
                </Col>
                <Col span={12}>
                  <div className="integrate-welcome">
                    <h2>
                      Setting up UXCam in "{currentApp?.name}" is easy and only
                      takes a few minutes.
                    </h2>
                    <h2>
                      Ready to get started by adding two lines of code to your
                      app?
                    </h2>
                    <div className="integrate-button-wrapper">
                      <a
                        href="https://developer.uxcam.com/docs"
                        target="_blank"
                        rel="noreferrer"
                        className="ant-btn ant-btn-primary integrate-button"
                      >
                        View steps
                      </a>

                      <InviteButtonField
                        labelName="Invite a developer"
                        showModal={showModal}
                      />
                    </div>

                    <p style={{ margin: '20px 0 30px' }}>
                      <strong>
                        UXCam app key :{' '}
                        <span style={{ fontFamily: 'monospace' }}>
                          {currentApp?.key}
                        </span>
                      </strong>
                      <CopyToClipboard text={currentApp?.key} onCopy={() => {}}>
                        <Tooltip
                          placement="topLeft"
                          title="Copy"
                          arrowPointAtCenter
                        >
                          <Button
                            onClick={(e) => copy(e)}
                            size="small"
                            style={{
                              borderRadius: '50%',
                              height: 20,
                              width: 20,
                              textAlign: 'center',
                              background: '#dde3f3',
                              color: '#413eff',
                              border: '#dde3f3',
                              marginLeft: 10,
                              padding: 0,
                            }}
                          >
                            <CopyOutlined style={{ fontSize: '12px' }} />
                          </Button>
                        </Tooltip>
                      </CopyToClipboard>
                    </p>
                    <Alert
                      message=""
                      description="Remember that if you want to see your sessions on the dashboard, your app has to go to the background."
                      type="info"
                      showIcon
                    />
                  </div>
                </Col>
              </Row>
            </Panel>
            <Panel
              header="Tag your app screens"
              key="3"
              extra={checkMark(checkList?.isAppScreensTagged)} // need to update the key
              expandIconPosition="right"
            >
              <p style={{ marginBottom: '10px' }}>
                Tag all the screens in your app to enrich the usage of heatmaps,
                filters, and other features within UXCam. This is helpful to
                decide where each screen starts and ends within your app.
              </p>

              {!checkList?.isAppScreensTagged && ( // need to add later condition
                <StyleDoneButton
                  onClick={() =>
                    checkList?.isSDKIntegrated
                      ? mutate({ step: 'appScreensTagged' })
                      : message.info(
                          'You need to complete the SDK integration at first.'
                        )
                  }
                  // loading={hookState?.btnLoadingSensitive}
                >
                  Done
                </StyleDoneButton>
              )}

              <a
                href="https://uxcam-documentation.readme.io/docs/tag-of-screens"
                target="_blank"
                className="ant-btn ant-btn-primary"
                rel="noreferrer"
              >
                View steps
              </a>
            </Panel>
            <Panel
              header="Clean your data"
              key="4"
              extra={checkMark(checkList?.isDataCleaned)} // need to update the key
              expandIconPosition="right"
            >
              <StyledParagraph>
                Utilize our APIs to remove your internal testers or users who
                opt-out of tracking from your production data.
              </StyledParagraph>

              {!checkList?.isDataCleaned && (
                <StyleDoneButton
                  onClick={() =>
                    checkList?.isSDKIntegrated
                      ? mutate({ step: 'dataCleaned' })
                      : message.info(
                          'You need to complete the SDK integration at first.'
                        )
                  }
                  // loading={hookState?.btnLoadingSensitive}
                >
                  Done
                </StyleDoneButton>
              )}

              <a
                href="https://uxcam-documentation.readme.io/docs/opt-in-opt-out"
                target="_blank"
                className="ant-btn ant-btn-primary"
                rel="noreferrer"
              >
                View steps
              </a>
            </Panel>

            <Panel
              header="Hide end-user personal data"
              key="5"
              extra={checkMark(checkList && checkList.isSensitiveDataBlocked)}
              expandIconPosition="right"
            >
              <p>
                Before recording any sessions and/or videos, please use UXCam
                API to hide any personal data that you would like to hide/
                occlude from UXCam App so neither you nor UXCam will store
                personal data in UXCam app. <br />
                <br />
                Remember that personal data means any information which are
                related to an identified or identifiable natural person.
                Examples of the above are: name, email address, password, home
                address, telephone, IP address, cookies, location, user ID that
                linked to other elements can identify someone. <br />
                <br />
                If you need more information on how to hide this information,
                please click the following{' '}
                <a
                  href="https://help.uxcam.com/en/articles/10426206-ensuring-data-protection-how-to-protect-sensitive-customer-data-with-uxcam"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  link
                </a>{' '}
                and/or please contact support to explain to you how to do so.{' '}
                <br />
                <br />
                <i>
                  Important: UXCam app does not hide personal information by
                  default. Customer is the main responsible for using the UXCam
                  API to hide this information.
                </i>
              </p>
              {checkList && !checkList.isSensitiveDataBlocked && (
                <StyleDoneButton
                  onClick={() =>
                    checkList?.isSDKIntegrated
                      ? handleBlockSensitive()
                      : message.info(
                          'You need to complete the SDK integration at first.'
                        )
                  }
                  loading={hookState?.btnLoadingSensitive}
                >
                  Done
                </StyleDoneButton>
              )}
              <a
                href="https://uxcam-documentation.readme.io/docs/screen-blurring"
                target="_blank"
                className="ant-btn ant-btn-primary"
                rel="noreferrer"
              >
                View steps
              </a>
            </Panel>

            <Panel
              header={ `Track ${ noCodeEventsFeatureFlag ? 'coded' : 'custom' } events` }
              key="6"
              extra={checkMark(checkList?.isCustomEventTracked)}
              expandIconPosition="right"
            >
              <StyledParagraph>
              { noCodeEventsFeatureFlag ? 'Coded' : 'Custom' } events enable detailed analysis.{' '}
              </StyledParagraph>
              <p>
                Upload { noCodeEventsFeatureFlag ? 'coded' : 'custom' } events from your app to analyze the behavior of
                users who triggered certain events, e.g. a product purchase.
              </p>
              <a
                href="https://uxcam-documentation.readme.io/docs/send-events"
                target="_blank"
                className="ant-btn ant-btn-primary"
                rel="noreferrer"
              >
                View steps
              </a>
            </Panel>
            <Panel
              header="Upload user properties"
              key="7"
              extra={checkMark(checkList && checkList.isUserPropertiesUploaded)}
              expandIconPosition="right"
            >
              <StyledParagraph>
                User properties make it easy to find specific users.
              </StyledParagraph>
              <p>
                By default, we generate random aliases for your users based on
                their country of origin. If you want to easily identify your
                users in UXCam, you can upload e.g. the unique user id from your
                app to our dashboard. Additionally, you can send us other data
                that will allow you to segment users in a way that works best
                for you.
              </p>
              <a
                href="https://uxcam-documentation.readme.io/docs/send-user-properties"
                target="_blank"
                className="ant-btn ant-btn-primary"
                rel="noreferrer"
              >
                View steps
              </a>
            </Panel>
            <Panel
              header="Report Handled Exceptions"
              key="8"
              extra={checkMark(checkList?.isHandledExceptionsReported)} // need to update the key
              expandIconPosition="right"
            >
              <StyledParagraph>
                Available for native iOS and Android only. Non-fatal or caught
                exceptions are those that are manually handled by developers
                that do not result in application flow breaking. Once your
                application reaches a code block that raises an exception, you
                can catch the exception and send it to UXCam using the
                reportExceptionEvent API.
              </StyledParagraph>

              {!checkList?.isHandledExceptionsReported && (
                <StyleDoneButton
                  onClick={() =>
                    checkList?.isSDKIntegrated
                      ? mutate({ step: 'handledExceptionsReported' })
                      : message.info(
                          'You need to complete the SDK integration at first.'
                        )
                  }
                  // loading={hookState?.btnLoadingSensitive}
                >
                  Done
                </StyleDoneButton>
              )}

              <a
                href="https://uxcam-documentation.readme.io/docs/report-handled-exceptions"
                target="_blank"
                className="ant-btn ant-btn-primary"
                rel="noreferrer"
              >
                View steps
              </a>
            </Panel>

            <Panel
              header="Integrate UXCam with other Analytics tools"
              key="9"
              extra={checkMark(
                checkList && checkList.isAppAnalyticsToolIntegrated
              )}
              expandIconPosition="right"
            >
              <StyledParagraph>Enrich your existing data.</StyledParagraph>
              <p>
                If you use any other analytics tools like Firebase, you can
                easily integrate them with UXCam. This will let you track
                specific events and attach session URLs to external tools, which
                lets you dig deeper into the event's analysis.
              </p>
              {checkList && !checkList.isAppAnalyticsToolIntegrated && (
                <StyleDoneButton
                  loading={hookState?.btnLoading}
                  onClick={() =>
                    checkList.isSDKIntegrated
                      ? handleAnalyticsTool()
                      : message.info(
                          'You need to complete the SDK integration at first.'
                        )
                  }
                >
                  Done
                </StyleDoneButton>
              )}
              <a
                href="https://uxcam-documentation.readme.io/docs/other-3rd-party-integrations"
                target="_blank"
                className="ant-btn ant-btn-primary"
                rel="noreferrer"
              >
                View steps
              </a>
            </Panel>
          </Collapse>
        </div>

        <div className="accordion-wrapper">
          <h3>
            Onboarding checklist{' '}
            <small>
              ( <InfoCircleOutlined /> It is recommended to complete the
              technical setup checklist at first.)
            </small>
          </h3>
          <Collapse
            accordion
            activeKey={keyValue === '0' ? checkList && defaultActive : keyValue}
            onChange={handleCollapsed}
          >
            <Panel
              header="Watch crashed sessions"
              key="10"
              extra={checkMark(checkList?.isCrashSessionsWatched)}
              expandIconPosition="right"
            >
              <StyledParagraph>
                Session segments allow you to uncover issues quickly.
              </StyledParagraph>
              <p>
                With our default "crashed sessions" segment, you can easily
                watch all crashed session recordings to understand when and why
                they happened. This will speed up the process of troubleshooting
                bugs and issues and minimize confusing and frustrating
                conversations with customers.
              </p>
              <Button
                className="ant-btn-primary"
                onClick={() =>
                  checkList?.isSDKIntegrated
                    ? handleCrashedSessionWatched()
                    : message.info(
                        'You need to complete the SDK integration at first.'
                      )
                }
              >
                {' '}
                Watch crashed session
              </Button>
            </Panel>
            <Panel
              header="Create your first saved session segment"
              key="11"
              extra={checkMark(checkList?.isFirstSessionSegmentCreated)}
              expandIconPosition="right"
            >
              <StyledParagraph>
                Save time through custom segments.
              </StyledParagraph>
              <p>
                {`Once you've determined which session properties are most
                valuable, you can save these segments so that you don't need to
                add filters manually`}
              </p>
              <a
                href="https://help.uxcam.com/en/articles/10222530-filters-segments"
                target="_blank"
                rel="noreferrer"
                className="ant-btn ant-btn-primary"
              >
                View steps
              </a>
            </Panel>
            <Panel
              header="Watch sessions of users who are slipping away"
              key="12"
              extra={checkMark(checkList?.isSlippingWayUserSessionWatched)}
              expandIconPosition="right"
            >
              <StyledParagraph>
                Find out which users are abandoning your app and discover why it
                may be happening.{' '}
              </StyledParagraph>
              <p>Thanks to this, you avoid losing users in the future!</p>
              <Button
                className="ant-btn-primary"
                onClick={() =>
                  checkList?.isSDKIntegrated
                    ? handleSlippingWayUserSession()
                    : message.info(
                        'You need to complete the SDK integration at first.'
                      )
                }
              >
                {' '}
                Find users who are slipping away{' '}
              </Button>
            </Panel>
            <Panel
              header="Invite your team members"
              key="13"
              extra={checkMark(checkList && checkList?.isMemberInvited)}
              expandIconPosition="right"
            >
              <p>Work with your team - two heads are always better than one.</p>

              <InviteButtonField labelName="Invite" showModal={showModal} />
            </Panel>
            <Panel
              header="Rename your screens"
              key="14"
              extra={checkList && checkMark(checkList?.isAppScreenRenamed)}
              expandIconPosition="right"
            >
              <StyledParagraph>
                Improve the usability of your UXCam dashboard!
              </StyledParagraph>
              <p>
                Go through the automatically detected screens and adjust their
                names to ones that make sense to you.
              </p>
              <a
                href="https://help.uxcam.com/hc/en-us/articles/360036091852-Screen-list"
                target="_blank"
                rel="noreferrer"
                className="ant-btn ant-btn-primary"
              >
                View steps
              </a>
            </Panel>
          </Collapse>
        </div>
      </StyledIntegrateWrapper>
    </Col>
  );

  useEffect(() => {
    setKeyValue('0');
  }, [urlQuery?.appId]);

  return (
    <div className="checklist-integrate-body">
      <Row className="height-full">
        {!questionPage && WelcomePage}

        {questionPage && <Question toogleQuestionPage={toogleQuestionPage} />}

        <Col lg={4} className="height-full" style={{ marginLeft: 'auto' }}>
          <div className="display-table">
            <div className="integrate-sidebar">
              <div className="testimonial">
                <a href="mailto:team@uxcam.com">
                  <Avatar src="/static/susan-uxcam.jpg" size="large" />
                  <div className="person">
                    <p>
                      <strong>Susan Ostojska</strong>
                      <br />
                      <small>Head of Customer Success</small>
                    </p>
                  </div>
                </a>
              </div>
              {!questionPage && (
                <StyledLinkButton
                  type="link"
                  href="https://help.uxcam.com/en/collections/11057211-faq"
                  target="_blank"
                >
                  Still have questions?
                </StyledLinkButton>
              )}
            </div>
          </div>
        </Col>
      </Row>
    </div>
  );
};

export default Checklist;
